UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ვარდისფერი ღრუბლის სმუზი'), description_ka = COALESCE(description_ka, 'რძე და სეზამი ძვლებსა და კბილებს იცავს'), category_ka = COALESCE(category_ka, 'ჯანსაღი_სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["რძე - 1 ჭიქა","მარწყვი - 6 ცალი","ბანანი - ნახევარი","სეზამი - 1 ჩაის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბლენდერში დააბლენდერეთ","ცივად მიირთვით"]'::jsonb) WHERE id = 'ba869d0c-6059-4e21-8549-a6fc4dbae37c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დილის ფენები - იოგურტი და გრანოლა'), description_ka = COALESCE(description_ka, 'პრობიოტიკებით მდიდარი საუზმე, რომელიც საჭმლის მონელებას აადვილებს. კალციუმისა და ენერგიის წყარო.'), category_ka = COALESCE(category_ka, 'საუზმე'), ingredients_ka = COALESCE(ingredients_ka, '["იოგურტი: 1 ჯამი","შვრია: 3 სუფრის კოვზი","ნიგოზი: 1 მუჭა (დაქუცმაცებული)","თაფლი: 1 სუფრის კოვზი","ხილი (ბანანი, მარწყვი): სურვილისამებრ"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["შვრია მშრალ ტაფაზე მსუბუქად მოხალეთ","ნიგოზი დააქუცმაცეთ და შვრიას დაუმატეთ","დაამატეთ თაფლი და აურიეთ - ეს თქვენი გრანოლაა","ჯამში იოგურტი ჩაასხით და ზემოდან გრანოლა მოაყარეთ","დაამატეთ ახალი ხილის ნაჭრები"]'::jsonb) WHERE id = 'db39aaba-46b8-48c5-9ee2-718a433c813d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოკეანის ნიავის ბეიგელი - ორაგულის ტოსტი'), description_ka = COALESCE(description_ka, 'ომეგა-3-ის წყარო, რომელიც გონების დაბინდვას ამცირებს და კანს ბზინვარებას მატებს.

სარგებელი: ორაგული ქალებში ხელს უწყობს გულ-სისხლძარღვთა სისტემისა და ტვინის ჯანმრთელობას და ზრდის კანის ელასტიკურობას.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ჭვავის პური ან სრულმარცვლოვანი სიმითი (ბეიგელი): 1 ცალი","კრემ-ყველი (ლაბნე): 1 სუფრის კოვზი","დაჭრილი ორაგული (სომონი): 2-3 თხელი ნაჭერი","კიტრის ნაჭრები, კამა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["პურს კრემ-ყველი წაუსვით. ზემოდან კიტრისა და ორაგულის ნაჭრები დაალაგეთ. ახალი კამით მორთეთ და მიირთვით."]'::jsonb) WHERE id = 'eff41793-674f-452c-86c7-b28f4dd44a0f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'შაკშუკა'), description_ka = COALESCE(description_ka, 'ცხელი, უხვად პომიდვრიანი და სანელებლებით შეზავებული უქმეების კლასიკა.

სარგებელი: მომზადებულ პომიდორში შემავალი ლიკოპენი ძლიერი ანტიოქსიდანტია, რომელიც უჯრედებს ოქსიდაციური დაზიანებისგან იცავს.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხი: 2 ცალი","პომიდორი: 2 ცალი (დაჭრილი)","ფერადი ბულგარული წიწაკა: ნახევარი (დაჭრილი)","ხახვი: ნახევარი","ზეითუნის ზეთი, დაფქული ძირა (კუმინი), მარილი, პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ტაფაზე ხახვი და წიწაკა ზეითუნის ზეთში მოშუშეთ. დაამატეთ პომიდორი და სანელებლები და მოამზადეთ, სანამ სოუსის კონსისტენციას არ მიიღებს. სოუსში ჩაღრმავებები გააკეთეთ, შიგნით კვერცხები ჩაახალეთ, თავსახური დააფარეთ და სასურველ კონსისტენციამდე მოამზადეთ."]'::jsonb) WHERE id = '29bb0ce4-9bdc-4fac-b1c7-e5b836d8f1d0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოკეანის საჩუქარი - ორაგული'), description_ka = COALESCE(description_ka, 'ომეგა-3-ით მდიდარი კერძი, რომელიც იდეალურია მეძუძური დედისთვის. ხელს უწყობს ბავშვის ტვინის განვითარებას.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['მშობიარობის შემდგომი პერიოდი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ორაგული (სალმონი): 150 qr","სატაცური ან მწვანე ლობიო: 100 qr","ლიმონი: ნახევარი","კამა: 1 კონა","ზეითუნის ზეთი: 1 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თევზს მოაყარეთ მარილი და ლიმონის წვენში დაამარინადეთ (10 dəq)","გვერდით ბოსტნეული დაალაგეთ","წაუსვით ზეითუნის ზეთი და ფოლგაში გაახვიეთ","ღუმელში 180°C-ზე 20 წუთის განმავლობაში მოამზადეთ","ზემოდან უხვად მოაყარეთ ახალი კამა — ის ტრადიციულად ლაქტაციის ხელშემწყობად მიიჩნევა"]'::jsonb) WHERE id = 'fe3cad51-3e25-4969-b2ba-dbb221d883b9';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ზურმუხტისფერი ხავერდი - ისპანახის წვნიანი'), description_ka = COALESCE(description_ka, 'რკინითა და ფოლიუმის მჟავით მდიდარი მწვანე ენერგია, რომელიც დაღლილობის შემცირებაში გეხმარებათ.'), category_ka = COALESCE(category_ka, 'ვახშამი'), ingredients_ka = COALESCE(ingredients_ka, '["ისპანახი: 1 დიდი კონა","კარტოფილი: 1 ცალი","ხახვი: 1 ცალი","ნაღები (ან რძე): ნახევარი ჭიქა","მარილი, პილპილი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბოსტნეული დაჭერით და წყალში მოხარშეთ","როცა დარბილდება, ბლენდერით პიურედ აქციეთ","ბოლოს ნაღები დაამატეთ და ერთხელ წამოადუღეთ","დაამატეთ მარილი და პილპილი","მიირთვით ცხლად — რკინის საჭიროების დასაკმაყოფილებლად კარგი არჩევანია"]'::jsonb) WHERE id = '7b50a305-3e3e-47ca-8cb4-e9cc2bf8695d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ლალისფერი რაგუ — ჭარხლითა და ხორცით'), description_ka = COALESCE(description_ka, 'სისხლწარმოქმნისა და რძის გამომუშავების ხელშემწყობი შესანიშნავი დუეტი. რკინისა და ცილის წყარო.'), category_ka = COALESCE(category_ka, 'სადილის_კერძი'), tags_ka = COALESCE(tags_ka, ARRAY['მშობიარობის_შემდგომი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["საქონლის ხორცი: 200 qr (კუბებად დაჭრილი)","ჭარხალი: 1 ცალი (დიდი)","სტაფილო: 1 ცალი","ბულიონი: 2 ჭიქა","მარილი, პილპილი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხორცი პატარა კუბებად დაჭერით და დარბილებამდე მოხარშეთ","ჭარხალი და სტაფილო გაფცქვენით და დაჭერით","ხორცს დაუმატეთ და დაბალ ცეცხლზე 30-40 წუთის განმავლობაში მოამზადეთ","დაუმატეთ მარილი და პილპილი","მიირთვით ცხლად — ხელს უწყობს სისხლწარმოქმნასა და რძის გამომუშავებას"]'::jsonb) WHERE id = '7bcfa70e-7c6a-42b0-84fa-c8b8642dc2e8';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ვანილის მარცვლებიანი მაკიატო'), description_ka = COALESCE(description_ka, 'ნამდვილი იტალიური გემო, რომელშიც ხელოვნური სიროფის ნაცვლად ვანილის ბუნებრივი მარცვლებია გამოყენებული.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ფინჯანი ესპრესო, მეოთხედი ჭიქა ცხელი და აქაფებული რძე, ვანილის ბუნებრივი ჩხირის მარცვლები (ან ორგანული ვანილის ექსტრაქტი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["რძე ვანილთან ერთად გააცხელეთ და კარგად ააქაფეთ. ცხელი ესპრესოს ზედაპირზე კოვზით მხოლოდ ვანილიანი ქაფი მოათავსეთ."]'::jsonb) WHERE id = 'fa71b0aa-2b84-4b46-9f5a-66cd2a1a924c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროსფერი ქინოას ფაფა'), description_ka = COALESCE(description_ka, 'ენერგიისა და მცენარეული რკინის დადასტურებული წყარო.

სარგებელი: ქინოა უგლუტენო, სრულფასოვანი მარცვლეულია, რომელიც ყველა შეუცვლელ ამინომჟავას შეიცავს და სისხლში შაქრის დონის რეგულირებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'საუზმე'), ingredients_ka = COALESCE(ingredients_ka, '["ქინოა: ნახევარი ჭიქა (კარგად გარეცხილი)","ნუშის რძე: 1 ჭიქა","დაფქული კურკუმა: ნახევარი ჩაის კოვზი (ანთების საწინააღმდეგო)","ნუშის გული, ქიშმიში ან შავი ქლიავის ჩირი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქინოა რძესთან ერთად ქვაბში მოათავსეთ, დაუმატეთ კურკუმა და დაბალ ცეცხლზე სითხის შეწოვამდე მოხარშეთ. გადმოდგით ცეცხლიდან და ზემოდან ნუში და ქიშმიში მოაყარეთ."]'::jsonb) WHERE id = 'a8e7b2fb-a93b-4062-b10e-3ec92ab8f15b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ხრაშუნა სეზამის პასტილა'), description_ka = COALESCE(description_ka, 'უძველესი ენერგეტიკული ბატონი: მხოლოდ თაფლი და სეზამი. მდიდარია კალციუმით და ამცირებს ტკბილეულის სურვილს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი_ტკბილეული'), ingredients_ka = COALESCE(ingredients_ka, '["სეზამი: 1 ჭიქა","თაფლი: ნახევარი ჭიქა"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სეზამი მშრალ ტაფაზე მსუბუქად მოხალეთ (ოქროსფერი შეფერილობის მიღებამდე)","თაფლი ცალკე ტაფაზე გააცხელეთ, სანამ აქაფდება","მოხალული სეზამი თაფლს დაუმატეთ და სწრაფად აურიეთ","საცხობ ქაღალდზე 1 sm სისქეზე გადაანაწილეთ","გაგრილების შემდეგ რომბის ფორმის ნაჭრებად დაჭერით"]'::jsonb) WHERE id = '5ea647ef-3b19-4587-8829-05b5dcb6c41c';
