UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოკეანის მარგალიტი — ორაგული და სატაცური'), description_ka = COALESCE(description_ka, 'კლასიკური წყვილი, რომელიც კანს შიგნიდან ატენიანებს და შეშუპების შემცირებას უწყობს ხელს.

სარგებელი: ორაგულში შემავალი ომეგა-3 თმასა და კანს ბზინვარებას მატებს, სატაცური კი ბუნებრივი შარდმდენია (ხელს უწყობს ორგანიზმიდან ზედმეტი სითხის გამოდევნას და შეშუპების შემცირებას).'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ორაგულის (სალმონის) ფილე: 150 qr","სატაცური (ასპარაგუსი): 6-8 ცალი","ლიმონი: ნახევარი","ზეითუნის ზეთი, ზღვის მარილი, შავი პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სატაცურს მაგარი ბოლოები მოაჭერით. თევზი და სატაცური ღუმელის ლანგარზე დაალაგეთ. მოასხით ზეითუნის ზეთი და ლიმონის წვენი, მოაყარეთ მარილი და პილპილი, შემდეგ 180 გრადუსზე 15-20 წუთის განმავლობაში გამოაცხვეთ."]'::jsonb) WHERE id = '07319d7d-c920-4693-bc34-502061f38b1b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღუმელში გამომცხვარი ფალაფელი'), description_ka = COALESCE(description_ka, 'ღუმელში გამომცხვარი, ბოჭკოვანი და ხრაშუნა აღმოსავლური კერძი მათთვის, ვინც შემწვარ საკვებს თავს არიდებს.

სარგებელი: მუხუდო ქალის ორგანიზმში ესტროგენის დონის ბუნებრივად შენარჩუნებას უწყობს ხელს, ბოჭკოვანი შემადგენლობა კი შეკრულობის თავიდან აცილებაში ეხმარება.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მუხუდო: 1 ჭიქა (წინა საღამოს დამბალი, უმი)","ახალი ოხრახუში და ქინძი: ნახევარი კონა","ხახვი, ნიორი, ძირა (დაფქული)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში ისე დააქუცმაცეთ, რომ ზედმეტად არ დაიფქვას. ხელით პატარა ბურთულები გააკეთეთ, საცხობ ქაღალდზე დაალაგეთ და 180 გრადუსზე 25 წუთის განმავლობაში გამოაცხვეთ. მიირთვით იოგურტთან ან ტაჰინის სოუსთან ერთად."]'::jsonb) WHERE id = 'fff5b4d4-5ba2-4e96-98ea-a65ef476ad64';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბროკოლის (ყვავილოვანი კომბოსტოს) გრატენი'), description_ka = COALESCE(description_ka, 'კალციუმისა და C ვიტამინის წყარო — ალტერნატივა იმ დღეებისთვის, როცა ხორცი არ გსურთ'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ორსულობა']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყვავილოვანი კომბოსტო ან ბროკოლი - 300 გრ","კვერცხი - 2 ცალი","იოგურტი - 2 სუფრის კოვზი","ფქვილი - 1 სუფრის კოვზი","ყველი - 30 გრ"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყვავილოვანი კომბოსტო ან ბროკოლი მოხარშეთ","კვერცხი, იოგურტი და ფქვილი ათქვიფეთ","მიღებული ნარევი ბოსტნეულს გადაასხით","ყველი მოაყარეთ და ღუმელში გამოაცხვეთ"]'::jsonb) WHERE id = '0af2c4bf-6712-4fe8-994f-bb2c520b2caf';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'შოკოლადის მუსი ავოკადოთი'), description_ka = COALESCE(description_ka, 'ავოკადო მდიდარია ფოლიუმის მჟავითა და მაგნიუმით, კაკაო კი ბედნიერების ჰორმონის გამოყოფას უწყობს ხელს'), category_ka = COALESCE(category_ka, 'ჯანსაღი_სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ავოკადო - 1 ცალი","კაკაო - 2 სუფრის კოვზი","თაფლი - 3 სუფრის კოვზი","ვანილი","ნუშის რძე - 3 კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში მოათავსეთ","ურიეთ კრემისებრი მასის მიღებამდე","მაცივარში 30 წუთით გააჩერეთ","მიირთვით მარწყვთან ერთად"]'::jsonb) WHERE id = 'c7535dc2-4407-4715-bc23-3a8242531319';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მწვანე სასწაული - ხორცის ბურთულები კამით'), description_ka = COALESCE(description_ka, 'აზერბაიჯანული სამზარეულოს ყველაზე ცნობილი საიდუმლო რძის გამომუშავების გასაზრდელად: ბევრი კამა! ის რძის სადინარების გახსნას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'სადილი'), ingredients_ka = COALESCE(ingredients_ka, '["ფარში (საქონლის ან ქათმის): 300 გრ","ბრინჯი: ნახევარი ჭიქა","კამა: 2 დიდი კონა","კარტოფილი: 2 ცალი","ხახვი: 1 ცალი","მარილი, პილპილი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ფარში, გარეცხილი ბრინჯი და წვრილად დაჭრილი კამის ნახევარი ერთმანეთში აურიეთ","მარილი და პილპილი დაუმატეთ და ხორცის ბურთულები გააკეთეთ","ადუღებულ წყალში დაჭრილი კარტოფილი და ხახვი ჩაყარეთ","5 წთ-ის შემდეგ ხორცის ბურთულები დაუმატეთ და დაბალ ცეცხლზე 25-30 წთ ხარშეთ","მომზადების დასრულებამდე ცოტა ხნით ადრე დარჩენილი კამა უხვად დაჭერით და სუპში ჩაყარეთ"]'::jsonb) WHERE id = 'b8788575-43f0-4748-a08b-a02e6044caa7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქარვის ნაკადი — ულუმბოს ჩაი'), description_ka = COALESCE(description_ka, 'მსოფლიოში რძის გამომუშავების ერთ-ერთი ყველაზე ძლიერი მცენარეული სტიმულატორი: ულუმბო (Fenugreek). ასტიმულირებს ჰორმონ პროლაქტინის გამომუშავებას.'), category_ka = COALESCE(category_ka, 'ჯანსაღი_სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ულუმბოს თესლი (Fenugreek): 1 ჩაის კოვზი","წყალი: 2 ჭიქა","თაფლი: 1 ჩაის კოვზი (სურვილისამებრ)","ლიმონი: რამდენიმე წვეთი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ულუმბოს თესლი მშრალ ტაფაზე 1-2 წუთის განმავლობაში მსუბუქად მოხალეთ (არ დაწვათ)","დაამატეთ მდუღარე წყალში","10 წუთით დააყენეთ, შემდეგ გადაწურეთ","სურვილისამებრ დაამატეთ თაფლი და ლიმონი","დალიეთ დღეში 2-3 ფინჯანი — რძის მატება 24-48 საათში იგრძნობა"]'::jsonb) WHERE id = '52d3741b-ea80-45a2-99fd-beda7e7b6c4a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დილის მატჩას ბოული'), description_ka = COALESCE(description_ka, 'მათთვის, ვისაც კოფეინის გარეშე გამოფხიზლება სურს — ანტიოქსიდანტებით მდიდარი და ნივთიერებათა ცვლის დამაჩქარებელი.

სარგებელი: მატჩას ჩაი აჩქარებს მეტაბოლიზმს და წმენდს კანს. ყავის მსგავსად ენერგიის უეცარ მოზღვავებასა და შემდგომ დაღლას არ იწვევს; მთელი დღის განმავლობაში ენერგიის დაბალანსებულ დონეს ინარჩუნებს'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["გაყინული ბანანი: 1 ცალი","მატჩას ფხვნილი: 1 ჩაის კოვზი","ისპანახი: 1 პატარა მუჭა","ნუშის რძე: ნახევარი ჭიქა","მოსართავად: ქოქოსის ფანტელი, ნუშის გული, კივის ნაჭრები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბანანი, მატჩა, ისპანახი და რძე ბლენდერში სქელი სმუზის მიღებამდე ათქვიფეთ. ჩაასხით ჯამში და ზემოდან თხილეულითა და კივით მორთეთ."]'::jsonb) WHERE id = '8c4792f6-0abc-4597-99d1-ff981dc2a340';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტკბილი სიზმრების შოტი'), description_ka = COALESCE(description_ka, 'კუნთების კრუნჩხვებისა და დაძაბულობის შესამცირებლად'), category_ka = COALESCE(category_ka, 'ჯანსაღი_სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ნუში — 5 ცალი (დალბობილი)","ბანანი — მეოთხედი","კაკაო — ნახევარი ჩაის კოვზი","წყალი — 2 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ნუში გაასუფთავეთ","ყველაფერი ბლენდერში თხევადი მასის მიღებამდე ათქვიფეთ"]'::jsonb) WHERE id = '13b7591b-479c-457d-ab27-09785681c532';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კრემოვანი გონება - ავოკადო და ბანანი'), description_ka = COALESCE(description_ka, 'ტვინის განვითარებისთვის ომეგა-3-ის ნამდვილი ბომბი, მომზადებას არ საჭიროებს (7 თვე+)'), category_ka = COALESCE(category_ka, 'baby_food'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food', 'vitamin_rich']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ავოკადო - ნახევარი","ბანანი - ნახევარი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ორივე ჩანგლით დაჭყლიტეთ","დატოვეთ მცირე ნაჭრებით"]'::jsonb) WHERE id = '2b374b35-8810-48b4-a990-d7b6c19bcd99';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'პატარა პროტეინი - ქათამი და ბოსტნეული'), description_ka = COALESCE(description_ka, 'ბავშვის პირველი გამოცდილება ხორცთან (7-8 თვე)'), category_ka = COALESCE(category_ka, 'baby_food'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ფილე - 40 qr","ბროკოლი - 3 ყვავილედი","ზეითუნის ზეთი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხორცი მოხარშეთ და პირველი ნახარში გადაღვარეთ","დაამატეთ ბოსტნეული და მოხარშეთ","ყველაფერი ერთად დააბლენდერეთ"]'::jsonb) WHERE id = 'f7f4a9f1-a670-4aa2-bc79-2ba16bd08e45';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოკეანის სინაზე - თეთრი თევზი და ბოსტნეული'), description_ka = COALESCE(description_ka, 'ფოსფორისა და იოდის წყარო (9-10 თვე)'), category_ka = COALESCE(category_ka, 'baby_food'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["თეთრი თევზი - 40 qr","სტაფილო - ნახევარი","ხახვი - ცოტა"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თევზი ბოსტნეულთან ერთად ორთქლზე მოამზადეთ","ყურადღებით შეამოწმეთ, რომ ფხები არ დარჩეს","ჩანგლით დააქუცმაცეთ"]'::jsonb) WHERE id = 'b455efa4-2b34-4269-90be-921a5749ae99';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყვავილოვანი კომბოსტოს პიცა'), description_ka = COALESCE(description_ka, 'იმისთვის, რომ პიცით გლუტენისა და ცომის გარეშე, სინდისის ქენჯნის გარეშე ისიამოვნოთ.

სარგებელი: კომბოსტო მდიდარია ფიტონუტრიენტებით და ხელს უწყობს ღვიძლის გაწმენდას. ეს პიცა საერთოდ არ იწვევს შებერილობასა და გულძმარვას.'), category_ka = COALESCE(category_ka, 'ვახშამი'), ingredients_ka = COALESCE(ingredients_ka, '["ყვავილოვანი კომბოსტო: ნახევარი თავი (გახეხილი და ბოლომდე გაწურული)","კვერცხი: 1 ცალი","ყველი (გახეხილი): 3 სუფრის კოვზი (ცომისთვის)","ზემოდან მოსაყრელად: ტომატის პასტა, პომიდვრის ნაჭრები, ყველი, ბაზილიკი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["გახეხილი ყვავილოვანი კომბოსტო კვერცხსა და ყველთან ერთად მოზილეთ და საცხობ ლანგარზე პიცის ცომივით გაანაწილეთ. 200 გრადუსზე 15 წუთის განმავლობაში (შებრაწვამდე) გამოაცხვეთ. შემდეგ გამოიღეთ, ზემოდან სოუსი და სხვა ინგრედიენტები მოათავსეთ და კიდევ 5 წუთი, ყველის გადნობამდე, გამოაცხვეთ."]'::jsonb) WHERE id = 'e3dad099-6f8a-4e3c-8dfa-2922158c70b6';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'თბილი სოკოსა და ისპანახის სალათი'), description_ka = COALESCE(description_ka, 'მიწის არომატის მქონე, თბილი და ნოყიერი სალათი იმ საღამოებისთვის, როცა ხორცის ჭამა არ გსურთ.

სარგებელი: ისპანახში შემავალი მაგნიუმი კუნთებს ადუნებს, სოკო კი მდიდარია იმუნიტეტის გასაძლიერებლად მნიშვნელოვანი D ვიტამინითა და B ჯგუფის ვიტამინებით.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქამა ან ხის სოკო: 150 გრ (დაჭრილი)","ახალგაზრდა ისპანახი: 2-3 მუჭა (უმი)","ნიგოზი: 1 მუჭა","ბალზამიკური ძმარი, ზეითუნის ზეთი, ნიორი (ცოტაოდენი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სოკო ერთ კბილ ნიორთან ერთად მცირე რაოდენობის ზეთში შებრაწვამდე მოშუშეთ. ისპანახი ჯამში მოათავსეთ. ცხელი სოკო ისპანახს დააყარეთ (სითბო ისპანახს ოდნავ დაარბილებს). მოაყარეთ ნიგოზი და მოასხით ბალზამიკური ძმარი."]'::jsonb) WHERE id = 'cc18259a-201a-4dd4-83bd-d60fc14dccba';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოსპიანი ყაბაყის სპაგეტი'), description_ka = COALESCE(description_ka, 'მცენარეული ცილით მდიდარი, პასტის ჯანსაღი ალტერნატივა, რომელიც სპაგეტის მონატრებას დაგავიწყებთ.

სარგებელი: ყაბაყის წყალობით ნახშირწყლებს თითქმის არ იღებთ, ოსპი კი მცენარეული წარმოშობის რკინითა და ბოჭკოთი უზრუნველყოფთ და საჭმლის მონელებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყაბაყი: 2 ცალი (სპაგეტის ფორმაზე დაჭრილი)","წითელი ოსპი: ნახევარი ჭიქა (მოხარშული)","პომიდორი, ხახვი, ნიორი (სოუსისთვის)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხახვითა და პომიდვრით „ბოლონეზეს“ სტილის სოუსი მოამზადეთ და მოხარშული ოსპი შეურიეთ. ყაბაყი ტაფაზე 2 წუთის განმავლობაში მოშუშეთ და თეფშზე გადაიტანეთ, ზემოდან კი უხვად მოასხით ოსპიანი სოუსი."]'::jsonb) WHERE id = 'a5b41661-394b-4403-8c11-ef8c670867ac';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ლალისფერი ჰიბისკუსის მოჰიტო'), description_ka = COALESCE(description_ka, 'ახალგაზრდობის ელექსირი და არტერიული წნევის დამარეგულირებელი წითელი სიამოვნება.

სარგებელი: ჰიბისკუსი C ვიტამინისა და ანტიოქსიდანტების წყაროა, აჩქარებს მეტაბოლიზმს და იცავს გულ-სისხლძარღვთა სისტემას.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ჰიბისკუსის ჩაი (მაგრად დაყენებული და გაცივებული): ნახევარი ჭიქა","პიტნის ფოთლები: 5-6 ცალი","ლაიმი: ნახევარი (დაჭრილი)","გაზიანი წყალი (მინერალური წყალი) და ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჭიქის ძირში პიტნის ფოთლები და ლაიმის ნაჭრები ხის სანაყით დაჭყლიტეთ. დაუმატეთ ბევრი ყინული. ჩაასხით ცივი ჰიბისკუსის ჩაი და მინერალური წყალი, შემდეგ მოურიეთ."]'::jsonb) WHERE id = 'd9f4e457-b6da-4ebb-92a8-543b9465b164';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ციტრუსის ნაპერწკალი'), description_ka = COALESCE(description_ka, 'დილის კოქტეილი, რომელიც ნივთიერებათა ცვლას ააქტიურებს და ცხიმის წვას უწყობს ხელს.

სარგებელი: გრეიპფრუტი ინსულინის დონეს აბალანსებს, როზმარინი კი მეხსიერებასა და კონცენტრაციას აძლიერებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["გრეიპფრუტის წვენი (ახლად გამოწურული): ნახევარი ჭიქა","ახალი როზმარინი: 1 ტოტი","გაზიანი წყალი: ნახევარი ჭიქა","ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["როზმარინის ტოტი ხელით მსუბუქად დასრისეთ (არომატის გამოსაყოფად) და ჭიქაში მოათავსეთ. დაუმატეთ ყინული, გრეიპფრუტის წვენი და მინერალური წყალი."]'::jsonb) WHERE id = 'd407408a-9e13-47c0-b565-ec699f31591e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ცივი კაკაოს პროტეინის შეიკი'), description_ka = COALESCE(description_ka, 'იდეალურია ვარჯიშის შემდეგ კუნთების აღსადგენად და დანაყრების შეგრძნებისთვის.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["1 სუფრის კოვზი კაკაო, 1 გაყინული ბანანი, 1 სუფრის კოვზი არაქისის კარაქი, 1 ჭიქა ცივი რძე, ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში ათქვიფეთ, სანამ სქელ შეიკს არ მიიღებთ."]'::jsonb) WHERE id = 'fff46867-aa41-4bc9-8647-1346ba044359';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ცისარტყელას შამფურები (3 წლის ასაკიდან)'), description_ka = COALESCE(description_ka, 'ფერადი და უსაფრთხო შამფურები, რომლებიც ხილის ჭამას სახალისო თამაშად აქცევს.

სარგებელი: სხვადასხვა ფერის ხილი სხვადასხვა ვიტამინსა და სასარგებლო ნივთიერებას (C, K, ანტიოქსიდანტებს) შეიცავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მარწყვი (წითელი), მანდარინი (ნარინჯისფერი), ბანანი (ყვითელი), კივი (მწვანე), მოცვი (ლურჯი/იისფერი).","ბავშვებისთვის უსაფრთხო პლასტმასის ან ხის შამფურები (ჩხირები) ბლაგვი წვერით."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხილი ბავშვისთვის ადვილად შესაჭმელ პატარა კუბებად დაჭერით. შამფურებზე ცისარტყელას ფერების თანმიმდევრობით ააცვით."]'::jsonb) WHERE id = '0b4a6a47-3a40-4940-a2d5-e0a7260449ef';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კრევეტები ნიორითა და ყაბაყით'), description_ka = COALESCE(description_ka, 'კაფეს ან რესტორნის ხარისხის ზღვის პროდუქტების კერძი, რომელიც თითქმის არ შეიცავს კალორიებს.

