UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ლავანდის რძე'), description_ka = COALESCE(description_ka, 'ჯადოსნური სასმელი, რომელიც დაძაბული დღის შემდეგ სტრესს მოგიხსნით და ბავშვივით ტკბილად დაგაძინებთ.

