სარგებელი: მოცვი ძლიერი ანტიოქსიდანტია, რომელიც ტვინის მუშაობას ასტიმულირებს. უშაქრო, ფქვილის გარეშე მომზადებული რბილი ფენქეიქი.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბანანი: 1 ცალი (მწიფე, დაჭყლეტილი)","კვერცხის გული: 1 ცალი (ცილა 1 წლამდე არ შეიძლება)","მოცვი: 6-7 ცალი (შუაზე გაჭრილი)","შვრიის ფქვილი: 1 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბანანი დაჭყლიტეთ და კვერცხის გულსა და ფქვილს შეურიეთ. დაამატეთ დაჭრილი მოცვი. უცხიმო ტაფაზე კოვზით პატარა წრეები მოათავსეთ და ორივე მხრიდან გამოაცხვეთ."]'::jsonb) WHERE id = 'e4dcec61-d668-42ad-9158-cfc7b2b1485d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დარიჩინიანი შვრიის ფლეთ უაითი'), description_ka = COALESCE(description_ka, 'მსუბუქი და არომატული ყავა, რომელიც სისხლში შაქრის (ინსულინის) დონეს მკვეთრად არ ზრდის.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general', 'milk_boost']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ფინჯანი (shot) ესპრესო, ნახევარი ჭიქა აქაფებული შვრიის რძე, 1 ჩაის კოვზი დაფქული დარიჩინი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ესპრესოს ცხელი, სქლად აქაფებული შვრიის რძე დაუმატეთ და უხვად მოაყარეთ დარიჩინი."]'::jsonb) WHERE id = 'a3480015-30ca-4f9a-b8de-a642fd9a639c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქინოასა და შოკოლადის ხრაშუნა ლუკმები'), description_ka = COALESCE(description_ka, 'PMS-ის (მენსტრუაციის წინა) პერიოდში შოკოლადის ძლიერი სურვილის დასაკმაყოფილებლად ყველაზე ხრაშუნა და ჯანსაღი არჩევანი.

სარგებელი: შავი შოკოლადი მდიდარია მაგნიუმით (ამცირებს სპაზმებსა და დაძაბულობას), გაფუებული ქინოა კი ორგანიზმს ცილით ამარაგებს და სისხლში შაქრის დონეს სტაბილურად ინარჩუნებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["შავი შოკოლადი (მინიმუმ 70% კაკაო): 100 qr","გაფუებული ქინოა (ან შვრია): 1 ჭიქა","ზღვის მარილი: ძალიან მცირე რაოდენობით (ზემოდან მოსაყრელად)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["შოკოლადი ორთქლზე (წყლის აბაზანის მეთოდით) გაადნეთ. დაუმატეთ ქინოა და კარგად აურიეთ. კოვზით საცხობ ქაღალდზე პატარა გროვებად მოათავსეთ. ზემოდან ზღვის მარილი მოაყარეთ და მაცივარში 20 წუთით გააჩერეთ."]'::jsonb) WHERE id = 'b3153614-fcee-47f5-887f-a9f21df0723d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კაკაოსა და ავოკადოს ტარტი'), description_ka = COALESCE(description_ka, 'შოკოლადის ტარტის წარმოუდგენლად ჯანსაღი ვერსია, რომელსაც გამოცხობა არ სჭირდება.

სარგებელი: ავოკადოში შემავალი ჯანსაღი ცხიმები აუცილებელია ქალის ჰორმონების სინთეზისთვის. კაკაო კი ზრდის ენდორფინების (ბედნიერების ჰორმონების) გამოყოფას.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), ingredients_ka = COALESCE(ingredients_ka, '["ძირისთვის: 1 ჭიქა ნიგოზი, 10 ცალი ფინიკი.","კრემისთვის: 2 ცალი მწიფე ავოკადო, ნახევარი ჭიქა უშაქრო კაკაო, 4 სუფრის კოვზი თაფლი ან ბადაგი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ნიგოზი და ფინიკი ბლენდერში დააქუცმაცეთ და ტარტის ფორმის ძირზე გადაანაწილეთ. კრემისთვის ავოკადო, კაკაო და თაფლი ბლენდერში აბრეშუმივით გლუვი მასის მიღებამდე ათქვიფეთ. კრემი ძირს ზემოდან გადაანაწილეთ და მაცივარში 2 საათით გააჩერეთ."]'::jsonb) WHERE id = '1b665124-a619-4ee4-9dce-a48ced0f8106';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'არაქისის კარაქით სავსე ფინიკი'), description_ka = COALESCE(description_ka, 'ენერგიის სწრაფად აღმდგენი „სნექი“, რომელიც ნამდვილი კარამელიანი შოკოლადის გემოს შეგიქმნით.

სარგებელი: სრულად აქრობს რაფინირებული შაქრის ძლიერ სურვილს. არაქისის კარაქი ცილებისა და ჯანსაღი ცხიმების წყალობით დანაყრების შეგრძნებას აძლიერებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["Medjool-ის ფინიკი (დიდი, რბილი): 5-6 ცალი","უშაქრო არაქისის კარაქი: 2 სუფრის კოვზი","შავი შოკოლადი (გამდნარი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ფინიკები სიგრძეზე გაჭერით და კურკები ამოიღეთ. შიგნით არაქისის კარაქი ჩაუდეთ. ფინიკები ნახევრამდე ჩააწეთ გამდნარ შავ შოკოლადში და გასამაგრებლად მაცივარში მოათავსეთ."]'::jsonb) WHERE id = '23124658-0378-42aa-b696-d264cdef885d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მარწყვისა და კეშიუს ჩიზქეიქი'), description_ka = COALESCE(description_ka, 'შესანიშნავი „Raw Vegan“ ჩიზქეიქი, რომელიც რძის პროდუქტების, ფქვილისა და შაქრის გარეშე მზადდება.

სარგებელი: კეშიუ ხელს უწყობს არტერიული წნევის რეგულირებას, მარწყვი კი მდიდარია დაბერების საწინააღმდეგო მოქმედების მქონე C ვიტამინით.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ძირისთვის: ნუში, ფინიკი (ბლენდერში დაქუცმაცებული).","კრემისთვის: 1.5 ჭიქა კეშიუ (ღამით დამბალი), 1 ჭიქა მარწყვი, 3 სუფრის კოვზი გამდნარი ქოქოსის ზეთი, აგავის სიროფი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ძირის ნარევი ფორმის ძირზე მჭიდროდ დატკეპნეთ. წყლისგან გადაწურული კეშიუ მარწყვთან, ზეთსა და სიროფთან ერთად ბლენდერში ათქვიფეთ სრულიად ერთგვაროვანი კრემის მიღებამდე. დაასხით ძირს და საყინულეში 4 საათით მოათავსეთ."]'::jsonb) WHERE id = '64191934-b404-495f-b229-388b63914389';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტკბილი კარტოფილისა და ვაშლის პიურე (6 თვიდან)'), description_ka = COALESCE(description_ka, 'თუ გავითვალისწინებთ, რომ ბავშვებს ტკბილი გემო უყვართ, ეს მათი ერთ-ერთი საყვარელი პირველი კერძი გახდება.

სარგებელი: ტკბილი კარტოფილი (ბატატი) მდიდარია A ვიტამინითა და ბოჭკოებით, ვაშლი კი ხელს უწყობს საჭმლის მონელებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი: 1 პატარა ცალი (გაფცქვნილი, კუბებად დაჭრილი)","ტკბილი ვაშლი: ნახევარი (გაფცქვნილი)","დედის რძე ან რძის ნარევი (გასათხელებლად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ტკბილი კარტოფილი და ვაშლი ორთქლზე ან ძალიან მცირე რაოდენობის წყალში სრულ დარბილებამდე მოამზადეთ. ჩანგლით დასრისეთ ან პიურედ აქციეთ. სანამ თბილია, ცოტაოდენი დედის რძე დაამატეთ და სასურველ სისქემდე გაათხელეთ."]'::jsonb) WHERE id = '27feef17-d812-4444-aa98-c2116d7d5049';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სტაფილოსა და ოსპის წვნიანი
(8 თვიდან)'), description_ka = COALESCE(description_ka, 'უგემრიელესი, ნარინჯისფერი და გაზების გამომწვევი ეფექტის არმქონე წვნიანი, რომელიც ბავშვს რკინით მდიდარ საკვებს გააცნობს.

სარგებელი: წითელი ოსპი მცენარეული ცილისა და რკინის წყაროა. სტაფილო კი მდიდარია ბეტა-კაროტინით, რომელიც თვალების განვითარებისთვის მნიშვნელოვანია.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["წითელი ოსპი: 2 სუფრის კოვზი (კარგად გარეცხილი)","სტაფილო: 1 პატარა ცალი (გახეხილი)","ზეითუნის ზეთი: 1 ჩაის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სტაფილო და ოსპი პატარა ქვაბში მოათავსეთ, იმდენი წყალი დაასხით, რომ დაიფაროს, და სრულ დარბილებამდე მოხარშეთ. ბლენდერში დააბლენდერეთ და ზემოდან 1 ჩაის კოვზი ექსტრა ვირჯინ ზეითუნის ზეთი მოასხით."]'::jsonb) WHERE id = '10778f55-a6f7-4dea-b6b5-e285d45babb5';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ცისარტყელას რიზოტო (1 წლის+)'), description_ka = COALESCE(description_ka, 'ნოყიერი სადილი, რომელიც ფერადი მარცვლებითაა სავსე და ღეჭვის უნარის განვითარებას უწყობს ხელს.

სარგებელი: ეს ერთ ქვაბში მომზადებული, ნახშირწყლებით, ცილებითა და ვიტამინებით მდიდარი, იდეალურად დაბალანსებული კერძია.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მრგვალი ბრინჯი: 2 სუფრის კოვზი (კარგად გარეცხილი)","სტაფილო, მწვანე ბარდა, სიმინდი: თითოეული 1 სუფრის კოვზი (ძალიან წვრილად დაჭრილი)","ძვლის ან ქათმის ბულიონი: 1 ჭიქა","კარაქი: ძალიან ცოტა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბოსტნეული და ბრინჯი ბულიონში დაბალ ცეცხლზე ხარშეთ, სანამ მთლიანად დარბილდება, სითხეს შეიწოვს და ფაფისებრ (რიზოტოს) კონსისტენციას მიიღებს. ბოლოს დაუმატეთ კარაქი და მოურიეთ."]'::jsonb) WHERE id = 'ec6cb7d9-6570-4500-be81-64329c0e4a07';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'Coco-Espresso Chill'), description_ka = COALESCE(description_ka, 'გამაგრილებელი, უშაქრო შედევრი ტროპიკული გემოების მოყვარულთათვის.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ფინჯანი (შოტი) ესპრესო, 1 ჭიქა ნატურალური ქოქოსის წყალი (coconut water), ბევრი ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჭიქა ყინულით შეავსეთ და ქოქოსის წყალი ჩაასხით. ბოლოს ნელა დაუმატეთ ესპრესო, რათა ორი განსხვავებული ფერის ფენა წარმოიქმნას. მოურიეთ და მიირთვით."]'::jsonb) WHERE id = '269778e2-5f1d-4cd3-b820-0a1898c7e6ea';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყაბაყის კატლეტები (2 წლის+)'), description_ka = COALESCE(description_ka, 'ბოსტნეულის ბლინების/კატლეტების სახით მომზადებული გემრიელი კერძი, რომელიც ბავშვის ყურადღებას მიიპყრობს.

სარგებელი: ყაბაყი და მწვანილი უჯრედისითაა მდიდარი და ნაწლავების მუშაობას აწესრიგებს. ძალიან რბილი ტექსტურის გამო მისი დაღეჭვა მარტივია.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყაბაყი: 1 ცალი (გახეხილი და სითხისგან მთლიანად გაწურული)","კვერცხი: 1 ცალი","თეთრი ყველი ან ხაჭო: 1 სუფრის კოვზი","მთლიანი ხორბლის ფქვილი: 1-2 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სითხისგან გაწურული ყაბაყი კვერცხს, ყველსა და ფქვილს შეურიეთ, რათა სქელი ცომისებრი მასა მიიღოთ.","ცხიმწასმულ ცხელ ტაფაზე კოვზით პატარა მრგვალი ულუფები მოათავსეთ.","ორივე მხრიდან ოქროსფერ-მომწვანო შეფერილობის მიღებამდე შეწვით."]'::jsonb) WHERE id = 'b53735ed-6abe-4b68-b652-4d5d294d5553';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოსა და კვერცხის პიურე
(8 თვე+)'), description_ka = COALESCE(description_ka, 'ბუნებრივი ენერგიის კომბინაცია, რომელიც მომზადებას არ საჭიროებს (კვერცხის გარდა) და დილაობით დედებს ცხოვრებას უმარტივებს.

სარგებელი: ორი შესანიშნავი „სუპერფუდი“ ერთად. ავოკადოში შემავალი ომეგა ცხიმოვანი მჟავები და კვერცხის გულში არსებული ქოლინი პირდაპირ უწყობს ხელს ინტელექტისა და მეხსიერების განვითარებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მაგრად მოხარშული კვერცხის გული: 1 ცალი","ავოკადო: მეოთხედი (ძალიან რბილი და მწიფე)","დედის რძე ან ფორმულა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ავოკადო და მოხარშული კვერცხის გული ჯამში ჩანგლით კარგად დასრისეთ. თუ მასა ძალიან სქელია, რამდენიმე წვეთი დედის რძით ან თბილი წყლით გაათხელეთ."]'::jsonb) WHERE id = 'e39c8f3d-f865-4de6-8f5d-d3f60a5624c8';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ვარდისფერი პანტერას პასტა(1 წელი+)'), description_ka = COALESCE(description_ka, 'ყველისა და ჭარხლის მხიარული პასტა, რომელიც ბავშვებს თავისი ფერით ხიბლავს.

სარგებელი: ჭარხალი ხელს უწყობს სისხლის მიმოქცევას, ყველი კი ძვლების განვითარებისთვის საჭირო კალციუმის მდიდარი წყაროა.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["საბავშვო მაკარონი (პატარა ზომის): 3-4 სუფრის კოვზი","ჭარხლის პიურე (მოხარშული და დაჭყლეტილი): 1 სუფრის კოვზი","ხაჭო (მარილიანი) ან კრემყველი: 1 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მაკარონი წყალში სრულ დარბილებამდე მოხარშეთ და გადაწურეთ. ცხელ მაკარონს ჭარხლის პიურე და ყველი დაუმატეთ და კარგად აურიეთ. მაკარონი მაშინვე კაშკაშა ვარდისფერს მიიღებს."]'::jsonb) WHERE id = 'dc9362af-ecb7-4bac-9ddf-d84bf1aa2f2d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჯანსაღი ნაგეთსები(1 წელი+)'), description_ka = COALESCE(description_ka, 'მაღაზიაში შეძენილი ნაგეთსების ჯანსაღი, ღუმელში გამომცხვარი და იოგურტის გარეშე მომზადებული ალტერნატივა.

სარგებელი: ქათმის სუფთა ცილისა და შვრიის ბოჭკოვანი საფარის წყალობით, ენერგიის სრულფასოვანი წყაროა.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ხორცი: 100 გრ (ბლენდერში დაქუცმაცებული ან ძალიან წვრილად დაჭრილი)","შვრიის ფქვილი (ან დაქუცმაცებული შვრიის ფანტელი): ამოსავლებად","კვერცხი: 1 ცალი (ათქვეფილი)","ტკბილი წითელი დაფქული წიწაკა (პაპრიკა - არა ცხარე)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქათმის ხორცს ძალიან ცოტა პაპრიკა დაუმატეთ და მოზილეთ. პატარა ნაწილებად დაყავით, ჯერ კვერცხში, შემდეგ კი შვრიის ფქვილში ამოავლეთ. საცხობ ქაღალდზე, ღუმელში 180 გრადუსზე 20 წუთის განმავლობაში გამოაცხვეთ."]'::jsonb) WHERE id = '732a8d20-182d-45bb-9171-f30bbd4cd142';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჟოლოს დათუნიას ბოული (2 წლის ზემოთ)'), description_ka = COALESCE(description_ka, 'სახალისო სმუზის ბოული, რომელიც ნაყინის ეფექტს ქმნის და იდეალურია წასახემსებლად ან საუზმეზე.

სარგებელი: გაწურული იოგურტი პრობიოტიკების წყაროა (აძლიერებს იმუნიტეტს), კენკრა კი ანტიოქსიდანტებითაა მდიდარი.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["გაწურული იოგურტი: 3 სუფრის კოვზი","გაყინული ჟოლო ან მარწყვი: 1 მუჭა","ბანანი: ნახევარი (იოგურტთან შესარევად)","გასაფორმებლად: ბანანის ნაჭრები, მოცვი (დათვის სახის გასაკეთებლად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["იოგურტი, ნახევარი ბანანი და გაყინული კენკრა დააბლენდერეთ, სანამ სრულიად ერთგვაროვან, სქელ კრემს არ მიიღებთ.","ჩაასხით ბოულში.","ბანანის ორი ნაჭრით დათვის ყურები გააკეთეთ, მოცვით კი თვალები და ცხვირი."]'::jsonb) WHERE id = 'b83ce14e-ac83-4541-a4e8-d4b8fa3d176e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჯანსაღი მუქი მოკა'), description_ka = COALESCE(description_ka, 'უსიროფო ალტერნატივა მათთვის, ვისაც ყავისა და შოკოლადის გემოთი ერთდროულად ტკბობა სურს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ფინჯანი ესპრესო, 1 ჩაის კოვზი სუფთა კაკაო, 1 ჩაის კოვზი თაფლი, 1 ჭიქა ცხელი ნუშის რძე."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ცხელ ესპრესოში გახსენით კაკაო და თაფლი. ზემოდან დაამატეთ ცხელი, აქაფებული ნუშის რძე."]'::jsonb) WHERE id = 'fdd5be2e-2d65-464b-84d3-084f637ea16e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მომღიმარი პიცები (2 წლის ზემოთ)'), description_ka = COALESCE(description_ka, 'სახალისო და ჯანსაღი პიცა, რომლის მომზადებაშიც 2 წლის ბავშვს შეუძლია დაგეხმაროთ.

სარგებელი: რადგან სახლში მზადდება, დანამატებს არ შეიცავს. ის ბავშვს საკვებთან ემოციური კავშირის ჩამოყალიბებაში ეხმარება (მომღიმარი სახის ფორმის მეშვეობით).'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მინი მთლიანი მარცვლეულის პიტა (ან პატარა ლავაში): 1 ცალი","ტომატის პასტა (სახლში მომზადებული, უშაქრო): 1 სუფრის კოვზი","მოცარელა: 2 სუფრის კოვზი, გახეხილი","შავი ზეთისხილის რგოლები (თვალებისთვის) და წითელი წიწაკის ზოლი (პირისთვის)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["პიტას ზედაპირზე ტომატის პასტა წაუსვით.","ზემოდან უხვად მოაყარეთ ყველი.","ზეთისხილითა და წიწაკით „მომღიმარი სახე“ გააკეთეთ. გამოაცხვეთ ღუმელში ყველის გადნობამდე (დაახლოებით 5-7 წუთი)."]'::jsonb) WHERE id = 'b7520537-fae1-481b-9bea-7a9cf32f15f7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კურდღლის ორცხობილა (2 წლის ზემოთ)'), description_ka = COALESCE(description_ka, 'უშაქრო, ხრაშუნა და ძალიან სასარგებლო შინ მომზადებული ორცხობილა, რომელიც ბისკვიტს შესანიშნავად ჩაანაცვლებს.

სარგებელი: ბოჭკოთი მდიდარი შვრია და ვიტამინებით სავსე სტაფილო ბავშვის საჭმლის მონელებას აუმჯობესებს. მაღაზიაში შეძენილი ბისკვიტების ყველაზე ჯანსაღი ალტერნატივაა.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["შვრიის ფანტელი: 1 ჭიქა","სტაფილო: 1 ცალი (გახეხილი)","ვაშლის პიურე: ნახევარი ჭიქა (ვაშლი მოხარშეთ და დაჭყლიტეთ — ის სიტკბოს შემატებს)","ქიშმიში (ძალიან წვრილად დაჭრილი): 1 სუფრის კოვზი","კარაქი: 1 სუფრის კოვზი (გამდნარი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ღრმა ჯამში კარგად მოზილეთ.","ხელით პატარა, ბრტყელი ორცხობილები გააკეთეთ (ან ცხოველის ფორმის საჭრელები გამოიყენეთ).","170 გრადუსზე გახურებულ ღუმელში 15-20 წუთის განმავლობაში, მსუბუქად შეწითლებამდე გამოაცხვეთ."]'::jsonb) WHERE id = '7cc7ac25-0798-468f-82c0-6764afc0cd4f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მინი ბურგერები (3 წლის ზემოთ)'), description_ka = COALESCE(description_ka, '100% შინ მომზადებული, ჯანსაღი მინი ბურგერები, რომლებიც სწრაფი კვების სურვილს ამცირებს.

სარგებელი: სახლში გატარებული სუფთა ხორცი ცილისა და რკინის, ხოლო სრულმარცვლოვანი პური B ვიტამინის წყაროა.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["სრულმარცვლოვანი ხორბლის ფქვილის მინი ბურგერის ფუნთუშები: 2 ცალი","საქონლის უცხიმო ფარში: 100 გრ","ჰოლანდიური ყველი: 1-2 თხელი ნაჭერი","პომიდორი და სალათის ფოთოლი","ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ფარშისგან ფუნთუშის ზომის თხელი და ბრტყელი კატლეტები გააკეთეთ და ტაფაზე მცირე რაოდენობის ზეთში შეწვით. ფუნთუშებს შორის კატლეტი, ყველი, პომიდორი და სალათის ფოთოლი მოათავსეთ და მინი ბურგერები ააწყვეთ."]'::jsonb) WHERE id = 'e6d245f4-3ec1-4650-92fc-b0b877ba16f0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღუმელში გამომცხვარი ბოსტნეულის ჩხირები (3 წლის ზემოთ)'), description_ka = COALESCE(description_ka, 'ფერადი და ხრაშუნა ბოსტნეულის ჩხირები, რომლებიც კლასიკურ კარტოფილ ფრის ჩაანაცვლებს.

სარგებელი: ტკბილი კარტოფილი და სტაფილო A ვიტამინის მდიდარი წყაროა. რადგან ზეთში არ იწვება, ტრანსცხიმებს არ შეიცავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი (ბატატი): 1 ცალი","სტაფილო: 1 დიდი ცალი","ზეითუნის ზეთი: 1 სუფრის კოვზი","ძალიან ცოტა მარილი და ტკბილი წითელი დაფქული წიწაკა (პაპრიკა)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბოსტნეული თანაბარი ზომის მოგრძო ჩხირებად (ფრის ფორმით) დაჭერით. ზეითუნის ზეთსა და სანელებლებს შეურიეთ და საცხობ ქაღალდზე დაალაგეთ. 200 გრადუსზე 20-25 წუთის განმავლობაში, კიდეების გახრაშუნებამდე გამოაცხვეთ."]'::jsonb) WHERE id = '705fa4d6-de4b-4c10-bc6c-46c0cc463f11';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დათუნია ტოსტი (3 წლის+)'), description_ka = COALESCE(description_ka, 'გემრიელი საუზმე, რომელიც ღიმილს მოგგვრით და მხოლოდ 2 წუთში მზადდება.

სარგებელი: არაქისის კარაქი ტვინისთვის სასარგებლო ცხიმებსა და ცილას შეიცავს. ბანანი კი ენერგიას მატებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვადრატული სრულმარცვლოვანი პური: 1 ნაჭერი (მოხალული)","არაქისის კარაქი: 1 სუფრის კოვზი","ბანანი: 3 მრგვალი ნაჭერი","მოცვი: 3 ცალი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მოხალულ პურზე არაქისის კარაქი წაუსვით. ბანანის ორი ნაჭერი ყურების მსგავსად ზედა კიდეებთან მოათავსეთ, ერთი კი — ცხვირის ადგილას. მოცვისგან თვალები და ცხვირის წვერი გააკეთეთ."]'::jsonb) WHERE id = '36867e84-3459-4059-a668-70f297e35576';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'საიდუმლო ბაღის მაფინები (3 წლის+)'), description_ka = COALESCE(description_ka, 'ყველისა და ბოსტნეულის მარილიანი მაფინები, რომელთა პარკში ან მოგზაურობაში წაღებაც ძალიან მოსახერხებელია.

სარგებელი: შაქარს არ შეიცავს. ბავშვი მას ადვილად დაიჭერს ხელში და სუფთად მიირთმევს, შემადგენლობა კი მდიდარია მინერალებითა და კალციუმით.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხი: 2 ცალი","იოგურტი: 2 სუფრის კოვზი","სტაფილო (გახეხილი) და ბროკოლი (ძალიან წვრილად დაჭრილი): ნახევარი ჭიქა","თეთრი ყველი: 2 სუფრის კოვზი (დაქუცმაცებული)","სრულმარცვლოვანი ფქვილი და საცხობი ფხვნილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თხევადი ინგრედიენტები ათქვიფეთ. დაამატეთ ბოსტნეული და ყველი. შეურიეთ ფქვილი და საცხობი ფხვნილი, რომ სქელი მაფინის ცომი მიიღოთ. მაფინის ფორმებში 180 გრადუსზე 20-25 წუთის განმავლობაში გამოაცხვეთ, სანამ აფუვდება და შეწითლდება."]'::jsonb) WHERE id = 'ecfe7439-ff4e-4167-ab7a-c45d91fa903c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'UFO პიცები (4 წლის+)'), description_ka = COALESCE(description_ka, 'სახალისო უგლუტენო მინი-პიცები, რომლებიც ცომის ნაცვლად სოკოს ქუდებისგან მზადდება.

სარგებელი: პორტობელო ან დიდი ქამა სოკო D ვიტამინით მდიდარია. ეს შესანიშნავი ხერხია, რომ ბავშვები სოკოს მიაჩვიოთ.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["დიდი ქამა სოკო: 4-5 ცალი (ფეხების გარეშე)","ტომატის პასტა: 2 სუფრის კოვზი","მოცარელა: 3 სუფრის კოვზი (გახეხილი)","სიმინდი ან ზეთისხილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სოკოს ქუდების შიგნით ტომატის პასტა წაუსვით. ზემოდან ყველი და სიმინდის მარცვლები მოაყარეთ. 180 გრადუსზე გახურებულ ღუმელში გამოაცხვეთ, სანამ ყველი არ გადნება და სოკო არ დარბილდება (დაახლოებით 15 წუთი)."]'::jsonb) WHERE id = '0a108d2a-2483-496b-8459-a35dba184122';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დილის ცისარტყელა (4 წლის+)'), description_ka = COALESCE(description_ka, 'მინი-ფანქეიქებისა და ხილის კომბინაცია — იდეალური საუზმეა ხელით საჭმელად.

სარგებელი: სხვადასხვა ხილი სხვადასხვა ვიტამინს შეიცავს. ჩხირები ხელს უწყობს ბავშვის მოტორული უნარებისა და საკვებისადმი ინტერესის განვითარებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მინი-ფანქეიქები: მონეტის ზომის, გამომცხვარი","მარწყვი, ბანანის რგოლები, კივის ნაჭრები.","ხის ჩხირები ბლაგვი წვერით."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჩხირებზე მონაცვლეობით ააწყვეთ: მინი-ფანქეიქი, მარწყვი, ბანანი, კვლავ ფანქეიქი და კივი. გვერდით დაუდგით პატარა ჯამი თაფლით ან ბექმეზით, ჩასაწობად."]'::jsonb) WHERE id = 'bb88a8d3-5c23-4d20-8927-32de71e35006';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'თევზის კატლეტები (4 წლის+)'), description_ka = COALESCE(description_ka, 'ომეგა-3-ის წყარო, რომელსაც თევზის მოყვარული ბავშვებიც კი მიმზიდველი ფორმის გამო სიამოვნებით მიირთმევენ.

სარგებელი: ორაგული ხელს უწყობს ტვინის მუშაობისა და მეხსიერების გაუმჯობესებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), ingredients_ka = COALESCE(ingredients_ka, '["ორაგულის (სალმონის) ფილე: 100 გრ (მოხარშული, დაქუცმაცებული)","კარტოფილი: 1 ცალი (მოხარშული და დაჭყლეტილი)","კამა: ძალიან ცოტა (დაჭრილი)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["დაჭყლეტილი კარტოფილი, თევზი და კამა კარგად მოზილეთ. მასა საცხობ ქაღალდზე გააბრტყელეთ და ვარსკვლავის ფორმის საჭრელით ამოჭერით. ტაფაზე ან ღუმელში მსუბუქად შეწითლებამდე მოამზადეთ."]'::jsonb) WHERE id = '94068d6c-ec4c-4f36-a84e-fdd44212d93d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'გალაქტიკური პასტა (5 წლის+)'), description_ka = COALESCE(description_ka, 'ვარსკვლავებისა და პეპლების მსგავსი ფორმის მაკარონით მომზადებული კრემ-ყველიანი კოსმოსური კერძი.

სარგებელი: სხვადასხვა ფერის ბოსტნეული (ბარდა, სიმინდი) კერძს ვიტამინებით ამდიდრებს, ხოლო უშაქრო იოგურტისა და ყველის სოუსი კუჭისთვის მსუბუქია.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["უგლუტენო პეპლის ფორმის მაკარონი (Farfalle) ან ფერადი მაკარონი: 1 ჭიქა","მწვანე ბარდა და სიმინდი: თითოეული 1 სუფრის კოვზი","ჩერი პომიდორი: 3-4 ცალი (შუაზე გაჭრილი)","კრემ-ყველი (ან გაწურული იოგურტი): 1 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მაკარონი სრულ დარბილებამდე მოხარშეთ და გადაწურეთ (ცოტაოდენი ნახარში შეინახეთ). ცხელ მაკარონს დაუმატეთ კრემ-ყველი, ბარდა, სიმინდი და პომიდორი, შემდეგ აურიეთ. ყველი გადნება და კრემისებრ სოუსს წარმოქმნის."]'::jsonb) WHERE id = 'f234c77f-4a04-4526-9394-c82a1bc713cf';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჯადოსნური ბაღის კექსები (4 წლის+)'), description_ka = COALESCE(description_ka, 'პარკში, ბაღში ან გზაში წასაღები მარილიანი კექსები, რომლებშიც ბევრი ყველი და ბოსტნეულია დამალული.

სარგებელი: უშაქროა. აერთიანებს კალციუმსა (ყველი) და ვიტამინებს (ბოსტნეული), თანაც ხელში ადვილად დასაჭერია.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხი: 2 ცალი","მაწონი: 2 სუფრის კოვზი","სტაფილო (გახეხილი) და ყაბაყი (გაწურული): ნახევარი ჭიქა","თეთრი ყველი: 2 სუფრის კოვზი","ფქვილი და გამაფხვიერებელი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თხევადი ინგრედიენტები და ყველი კარგად ათქვიფეთ. დაამატეთ ბოსტნეული. ბოლოს შეურიეთ ფქვილი და გამაფხვიერებელი, გადაანაწილეთ მაფინის ფორმებში და გამოაცხვეთ 180 გრადუსზე 20-25 წუთის განმავლობაში."]'::jsonb) WHERE id = '4232cb2b-2881-4a46-bce4-1d4070cda869';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჯადოსნური ელექსირი (5 წლის+)'), description_ka = COALESCE(description_ka, 'საუზმისთვის ან დესერტად განკუთვნილი, გამჭვირვალე ჭიქაში ფენა-ფენა მომზადებული თვალწარმტაცი ნუგბარი.

სარგებელი: პრობიოტიკური მაწონი ხელს უწყობს საჭმლის მონელებას, კენკრა კი იმუნურ სისტემას აძლიერებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მაწონი (სახლის ან გაწურული): 1 ჭიქა","ჟოლოს ან მარწყვის პიურე: 2 სუფრის კოვზი","უშაქრო გრანოლა ან შვრიისა და თხილეულის ნარევი: 2 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბავშვისთვის საყვარელ გამჭვირვალე ჭიქაში ფენა-ფენა მოათავსეთ ჯერ მაწონი, შემდეგ ხილის პიურე და ბოლოს გრანოლა. ზემოდან კვლავ მაწონის ფენა დაამატეთ და ახალი ხილით გააფორმეთ."]'::jsonb) WHERE id = 'aa773f2c-e3f1-47eb-9a0d-5723d6301a77';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ზენ ლიმონათი'), description_ka = COALESCE(description_ka, 'გაზიანი მატჩა, რომელიც ზაფხულის დღეებში მეტაბოლიზმს აჩქარებს და შებერილობას ამცირებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ჩაის კოვზი მატჩას ფხვნილი, ნახევარი ლიმონის წვენი, 1 ჩაის კოვზი აგავის სიროფი ან თაფლი, 1 ჭიქა მინერალური (გაზიანი) წყალი, პიტნის ფოთლები, ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მატჩა მცირე რაოდენობის წყალში თაფლთან და ლიმონთან ერთად ათქვიფეთ, სანამ არ გაიხსნება. ჭიქაში ჩაყარეთ ყინული და პიტნა, შემდეგ დაასხით მატჩას ნარევი და მინერალური წყალი."]'::jsonb) WHERE id = '2e2ead49-bcaf-4338-94ee-467ad791737c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ხრაშუნა თევზის ლუკმები (5 წლის+)'), description_ka = COALESCE(description_ka, 'ოქროსფერი და ხრაშუნა თევზის კუბები, რომლებიც თევზის ჭამისგან თავის ამრიდებელ 5 წლის ბავშვებსაც კი მოხიბლავს.

სარგებელი: თეთრი თევზი ფოსფორის, იოდისა და ადვილად ასათვისებელი ცილის წყაროა. შესანიშნავია გონებრივი განვითარებისთვის.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["თეთრი თევზის ფილე (მაგალითად, ვირთევზა, ზღვის ქორჭილა): 150 qr (კუბებად დაჭრილი და უფხო)","კვერცხი: 1 ცალი","უშაქრო სიმინდის ფანტელები (კორნფლექსი) ან პურის საფანელი: ამოსავლებად"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სიმინდის ფანტელები ხელით დააქუცმაცეთ. თევზის კუბები ჯერ ათქვეფილ კვერცხში, შემდეგ კი სიმინდის ნამცეცებში ამოავლეთ. საცხობ ქაღალდზე, ღუმელში 180 გრადუსზე 15-20 წუთის განმავლობაში გამოაცხვეთ."]'::jsonb) WHERE id = 'fe1e3f3e-8c82-4bdd-8cb3-2212d66df10f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ხრაშუნა ვაშლის სენდვიჩები (5 წლის+)'), description_ka = COALESCE(description_ka, 'პურის ნაცვლად ვაშლის ნაჭრებით მომზადებული, ენერგიით სავსე წასახემსებელი სკოლიდან ან საბავშვო ბაღიდან დაბრუნების შემდეგ.

სარგებელი: ვაშლში შემავალი პექტინის ბოჭკოები და მიწის თხილის კარაქის ცილა დანაყრების შეგრძნებას ახანგრძლივებს და ტკბილის მოთხოვნილებას ბუნებრივად აკმაყოფილებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["დიდი ვაშლი: 1 ცალი (გულგამოცლილი და რგოლებად დაჭრილი)","მიწის თხილის ან ნუშის კარაქი (უშაქრო): 2 სუფრის კოვზი","ქიშმიში ან შოკოლადის წვეთები (შუაში მოსათავსებლად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ვაშლის ერთ რგოლს მიწის თხილის კარაქი წაუსვით, ზემოდან ქიშმიში დააწყვეთ და მეორე რგოლი სენდვიჩივით დააფარეთ. ბავშვს ხელში დაჭერა რომ გაუადვილდეს, შეგიძლიათ შუაზე გაჭრათ."]'::jsonb) WHERE id = '2f4202ed-6015-4318-b0d0-ac257ccd10af';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კარდამონიანი Cold Brew'), description_ka = COALESCE(description_ka, 'გრილი, ძალიან დაბალი მჟავიანობის მქონე ყავა, რომელიც გულძმარვას არ იწვევს და საჭმლის მონელებას აადვილებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ჭიქა Cold Brew (ცივად დაყენებული ყავა), 1-2 ცალი კარდამონი (დაქუცმაცებული), ყინული, სურვილისამებრ ცოტაოდენი მცენარეული რძე."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყავის დაყენებისას (ან გაფილტვრისას) დაუმატეთ დაქუცმაცებული კარდამონის მარცვლები. მიირთვით უხვ ყინულთან ერთად. კარდამონი ყავას ძალიან \"cool\" და განსხვავებულ არომატს სძენს."]'::jsonb) WHERE id = '75bdd91d-7aed-40d8-9434-8c6ca0198e19';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქოქოსის მატჩა — ნეტარება'), description_ka = COALESCE(description_ka, 'ნაზი, ტროპიკული თბილი სასმელი, რომელიც კანს შიგნიდან ატენიანებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ჩაის კოვზი მატჩას ფხვნილი, 1 ჭიქა ქოქოსის რძე, 1 მწიკვი ვანილის ექსტრაქტი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქოქოსის რძე ქვაბში ორთქლის ამოსვლამდე გააცხელეთ (არ აადუღოთ). დაუმატეთ ვანილი და მატჩა, შემდეგ სპეციალური სათქვეფით (ან კაპუჩინატორით) ააქაფეთ."]'::jsonb) WHERE id = 'f005b3c3-1f74-4e4e-bab7-c8bc5e03c14a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'პიტნის მატჩა ფრაპე'), description_ka = COALESCE(description_ka, 'შაქრიანი „ფრაპუჩინოების“ 100%-ით ბუნებრივი და გამაგრილებელი ალტერნატივა.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ჩაის კოვზი მატჩა, 1 გაყინული ბანანი, 3-4 ახალი პიტნის ფოთოლი, ნახევარი ჭიქა შვრიის რძე."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში მაღალ სიჩქარეზე ათქვიფეთ, სანამ ნაყინის მსგავსი ტექსტურის ფრაპეს არ მიიღებთ."]'::jsonb) WHERE id = 'e8f085b1-b955-46e7-bd90-9c504005461c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სანელებლებიანი კაკაო'), description_ka = COALESCE(description_ka, 'უძველესი რეცეპტი, რომელიც ნივთიერებათა ცვლას ააქტიურებს და სისხლის მიმოქცევას აუმჯობესებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 სუფრის კოვზი სუფთა კაკაო, 1 მწიკვი დარიჩინი, ძალიან ცოტა (დანის წვერით) ცხარე წითელი წიწაკის ფხვნილი (კაიენი), 1 ჭიქა ცხელი თხილის რძე, თაფლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ცხელ რძეს კაკაო და სანელებლები დაუმატეთ და სრულ გახსნამდე ურიეთ. ცხარე და ტკბილი გემოების ბალანსი სასიამოვნოდ გაგათბობთ."]'::jsonb) WHERE id = '692f8fd9-2a1f-4e6e-90a2-3450b555119d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მაკა-კაკაოს ენერგეტიკული სასმელი'), description_ka = COALESCE(description_ka, 'ქალებისთვის სასარგებლო სასმელი, რომელიც ხელს უწყობს ჰორმონების დაბალანსებას და ზრდის ფიზიკურ გამძლეობას.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 სუფრის კოვზი კაკაო, 1 ჩაის კოვზი მაკას (maca) ფხვნილი, 1 ჭიქა შვრიის რძე, 1 ცალი ფინიკი (პიურეს სახით)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში თბილ ან ცივ რძესთან ერთად ერთგვაროვანი მასის მიღებამდე აურიეთ."]'::jsonb) WHERE id = 'da26b0d3-2e6e-4084-9b19-693dd01e5caa';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჯანსაღი Nutella-ს სასმელი'), description_ka = COALESCE(description_ka, 'თბილი და გემრიელი სასმელი, რომელიც ტკბილეულის სურვილს ამცირებს და საერთოდ არ შეიცავს შაქარს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 სუფრის კოვზი კაკაო, 1 სუფრის კოვზი ნატურალური თხილის პასტა (უშაქრო), 1 ჭიქა ცხელი რძე."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თხილის პასტა და კაკაო ცხელ რძეში ბლენდერით ან სათქვეფით სრულად გახსენით, ერთგვაროვანი მასის მიღებამდე."]'::jsonb) WHERE id = '1c2d3ae5-c16d-47ab-acbd-eff8a82af792';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მუხუდოთი გატენილი ბატატი'), description_ka = COALESCE(description_ka, 'რთული ნახშირწყლებით მდიდარი კლასიკური სადილი სპორტსმენებისა და ჯანსაღი კვების მიმდევრებისთვის, რომელიც ხანგრძლივად ანაყრებს.

სარგებელი: ბატატი მდიდარია კალიუმით, მუხუდო კი მცენარეული ცილებით. ეს ნამდვილი ენერგეტიკული ბომბია.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი (ბატატი): 2 ცალი (საშუალო ზომის)","მოხარშული მუხუდო (შეგიძლიათ კონსერვირებულიც გამოიყენოთ): 1 ჭიქა","ტაჰინი (სეზამის პასტა): 2 სუფრის კოვზი","ლიმონის წვენი, ზეითუნის ზეთი, ძირა (ცირა)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბატატები ჩანგლით რამდენიმე ადგილას დაჩხვლიტეთ და ღუმელში (200 გრადუსზე) სრულ დარბილებამდე გამოაცხვეთ (დაახლოებით 40 წუთი). გამოიღეთ, შუაზე გაჭერით და შიგთავსი ოდნავ ჩაჭყლიტეთ. ზემოდან სანელებლებით შეზავებული მუხუდო მოათავსეთ და ტაჰინისა და ლიმონის სოუსი მოასხით."]'::jsonb) WHERE id = '1eca4e78-4116-42f3-b2fa-fb5f13684582';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყვავილოვანი კომბოსტოს ფლავი'), description_ka = COALESCE(description_ka, 'კეტო და დაბალნახშირწყლოვანი დიეტების მეფე. რეცეპტი, რომელიც ბრინჯს 100%-ით ანაცვლებს და საერთოდ არ ასუქებს.

სარგებელი: ერთი ულუფა სულ 40-50 კალორიას შეიცავს. არ იწვევს სიმძიმისა და ძილიანობის შეგრძნებას, როგორც კლასიკური ბრინჯის ფლავი.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყვავილოვანი კომბოსტო: ნახევარი თავი","სტაფილო და მწვანე ბარდა: თითოეული 2 სუფრის კოვზი","ხახვი: 1 პატარა თავი","ზეითუნის ზეთი და კარაქი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყვავილოვანი კომბოსტო სახეხით ან ბლენდერით ბრინჯის მარცვლების ზომამდე დააქუცმაცეთ. ტაფაზე ხახვი, სტაფილო და ბარდა მცირე რაოდენობის ზეთში მოშუშეთ. დაუმატეთ კომბოსტოს „ბრინჯი“ და მორევით 5-6 წუთის განმავლობაში მოშუშეთ (ზედმეტად ნუ დაარბილებთ)."]'::jsonb) WHERE id = '836bc22f-3cef-4e15-bfd2-c877bc04f782';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ნაღების ბროკოლისა და ჩედარის სუპი'), description_ka = COALESCE(description_ka, 'მსოფლიოში ერთ-ერთი უგემრიელესი ზამთრის სუპი, რომელიც ამერიკული რესტორნების ქსელმა „Panera Bread“ გააცნო ფართო საზოგადოებას.

სარგებელი: სახლში მომზადებისას კალციუმითა და უჯრედისით მდიდარ, ძვლების გასამაგრებელ სუპად იქცევა.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბროკოლი: 300 qr (ძალიან წვრილად დაჭრილი)","სტაფილო: 1 ცალი (გახეხილი)","ჩედარის (Cheddar) ყველი: 1 ჭიქა (გახეხილი)","ქათმის ან ბოსტნეულის ბულიონი: 3 ჭიქა","ნაღები ან რძე: ნახევარი ჭიქა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სტაფილო და ბროკოლი ბულიონში დარბილებამდე მოხარშეთ (ბლენდერით ნაწილობრივ დააბლენდერეთ ისე, რომ მცირე ნაჭრები დარჩეს). დაუმატეთ რძე/ნაღები. გადმოდგით ცეცხლიდან, ცხელ სუპში გახეხილი ჩედარის ყველი ჩაყარეთ და გადნობამდე ურიეთ."]'::jsonb) WHERE id = 'c8f59b0c-497f-493b-9f85-c45a2583194f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მექსიკური კინოას სალათი'), description_ka = COALESCE(description_ka, 'დასავლურ სამყაროში „Meal Prep“ (წინასწარ მომზადებული საკვები) კულტურის ერთ-ერთი ყველაზე პოპულარული წარმომადგენელი.

სარგებელი: ფერადი, ნოყიერი და დიდი რაოდენობით მცენარეული ცილით მდიდარია. მაცივარში 3 დღე ინარჩუნებს სიახლეს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კინოა (მოხარშული): 1 ჭიქა","შავი ლობიო (კონსერვირებული): ნახევარი ჭიქა","სიმინდი: ნახევარი ჭიქა","ჩერი პომიდორი და წითელი ხახვი (დაჭრილი)","ახალი ქინძი, ლაიმის წვენი, ზეითუნის ზეთი, ხალაპენიოს წიწაკა (სურვილისამებრ)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი დიდ ჯამში აურიეთ. მოასხით ზეითუნის ზეთის, ლაიმის წვენისა და ქინძისგან მომზადებული სოუსი და კარგად შეურიეთ."]'::jsonb) WHERE id = 'a5af4229-e447-48cc-a6f1-6146ae4643a0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოს ბრაუნი'), description_ka = COALESCE(description_ka, 'ლეგენდარული „უშაქრო ბრაუნი“, რომელშიც კარაქის ნაცვლად ავოკადო, ხოლო ხორბლის ფქვილის ნაცვლად ნუშის ფქვილი გამოიყენება.

სარგებელი: არ შეიცავს ხორბლის ფქვილსა და რაფინირებულ შაქარს. ავოკადო დესერტს საოცარ სინოტივესა და ხავერდოვან ტექსტურას სძენს, მისი გემო კი საერთოდ არ იგრძნობა.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ავოკადო: 1 დიდი ცალი (სრულად დამწიფებული, პიურედ ქცეული)","ნუშის ფქვილი: ნახევარი ჭიქა","ნატურალური კაკაო (უშაქრო): ნახევარი ჭიქა","კვერცხი: 2 ცალი","თაფლი ან ნეკერჩხლის სიროფი: ჭიქის მესამედი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი დააბლენდერეთ, სანამ სრულიად ერთგვაროვან შოკოლადის კრემს არ მიიღებთ. ჩაასხით საცხობი ქაღალდით დაფენილ კვადრატულ ფორმაში და აცხვეთ 175 გრადუსზე 25-30 წუთის განმავლობაში. დაჭერით თბილ მდგომარეობაში."]'::jsonb) WHERE id = '64fd534a-ee42-4741-ad1d-2c83048a4d5e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოსა და კვერცხის ნავები'), description_ka = COALESCE(description_ka, 'მაიონეზის გარეშე მომზადებული, კეტოგენური და ცილებით მდიდარი გემრიელობა.

სარგებელი: კვერცხის ცილა და ავოკადოში შემავალი ომეგა ცხიმოვანი მჟავები გონებრივ ნისლს გაფანტავს და ენერგიას აღადგენს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მაგრად მოხარშული კვერცხი: 3 ცალი","ავოკადო: ნახევარი (მწიფე)","სელის ან ჩიას თესლი: ძალიან ცოტა (მოსაყრელად)","ლიმონის წვენი, მარილი, შავი პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კვერცხები სიგრძეზე შუაზე გაჭერით. გულები ამოიღეთ და ავოკადოსთან, ლიმონის წვენსა და სანელებლებთან ერთად სრულად კრემოვანი მასის მიღებამდე დასრისეთ. მიღებული მწვანე კრემი კვლავ კვერცხის ცილებში მოათავსეთ. ზემოდან სელის თესლი მოაყარეთ."]'::jsonb) WHERE id = 'c93f159c-1f03-4766-a5e7-3350ed9505bf';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ნუშის, სელისა და ჩიას ბურთულები'), description_ka = COALESCE(description_ka, 'ცხობის გარეშე მომზადებული ხრაშუნა ენერგეტიკული ბურთულები, რომლებიც იდეალურია ვარჯიშის წინ ან ყავასთან მისაყოლებლად.

სარგებელი: აერთიანებს სამი სუპერპროდუქტის (ნუში, სელი, ჩია) ძალას. სწრაფი ენერგიის წყარო და ბოჭკოსა და მინერალების ნამდვილი საბადოა.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ნუშის კარაქი (უშაქრო): ნახევარი ჭიქა","სელის თესლი (დაფქული): 2 სუფრის კოვზი","ჩიას თესლი: 1 სუფრის კოვზი","შვრია: ნახევარი ჭიქა","თაფლი ან აგავის სიროფი: 2 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ჯამში მოზილეთ, სანამ წებოვან მასას არ მიიღებთ. ხელით კაკლის ზომის ბურთულები გააკეთეთ და მაცივარში გააჩერეთ გასამაგრებლად. იდეალურია ჯიბით ან ჩანთით სატარებლად."]'::jsonb) WHERE id = '0160a14d-2320-433d-b86d-228b4fe1defc';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ნუშის კეტო კექსი'), description_ka = COALESCE(description_ka, 'ნახშირწყლების გარეშე მომზადებული კექსი მათთვის, ვისაც სურს თავი მსუბუქად, თითქოს ღრუბლებზე იგრძნოს.

სარგებელი: არ შეიცავს გლუტენს, ხორბლის ფქვილსა და შაქარს. განსაკუთრებით დიეტის დროს, ტკბილეულის სურვილის უსაფრთხოდ დაკმაყოფილებაში გეხმარებათ.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ნუშის ფქვილი: 1.5 ჭიქა","კვერცხი: 3 ცალი","ნუშის რძე: ჭიქის მეოთხედი","გახეხილი ლიმონის ცედრა ან ვანილი.","სტევია ან ძალიან ცოტა თაფლი (დასატკბობად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თხევადი ინგრედიენტები ათქვიფეთ, დაუმატეთ ნუშის ფქვილი და აურიეთ. ჩაასხით კექსის (მაფინის) ფორმებში და გამოაცხვეთ 175 გრადუსზე 20 წუთის განმავლობაში, შეწითლებამდე."]'::jsonb) WHERE id = '9ef68860-bc8e-4727-a11e-6e5469f057ef';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბერძნული სუვლაკი და ძაძიკი'), description_ka = COALESCE(description_ka, 'ხმელთაშუაზღვისპირული კვების მეფე: სუფთა ცილა, პრობიოტიკები და სასარგებლო ცხიმები.

სარგებელი: ძაძიკი (იოგურტისა და კიტრის სოუსი) ნაწლავის მიკროფლორას იცავს. ქათმის ხორცი კი ორგანიზმს ცილებით ამარაგებს და ნივთიერებათა ცვლას აჩქარებს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ფილე: 200 qr (კუბებად დაჭრილი, ლიმონსა და ბეგქონდარაში დამარინადებული)","გაწურული იოგურტი (ბერძნული იოგურტი): 4 სუფრის კოვზი","კიტრი: 1 ცალი (გახეხილი და სითხისგან კარგად გაწურული)","ახალი პიტნა, ნიორი, ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქათმის ნაჭრები ხის შამფურებზე ააცვით და ტაფაზე ან გრილზე შეწვით. ძაძიკის სოუსისთვის აურიეთ იოგურტი, სითხისგან გაწურული კიტრი, ნიორი, პიტნა და ზეითუნის ზეთი. ქათმის შამფურები ამ გრილ სოუსში ჩააწეთ და მიირთვით."]'::jsonb) WHERE id = 'e067e84f-8a22-4eb0-b5fa-1ae3ae37b95f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ფრანგული რატატუი'), description_ka = COALESCE(description_ka, 'სამხრეთ საფრანგეთის ფერადი, სრულიად ვეგანური და ვიზუალურად უნაკლო ბოსტნეულის კერძი.

სარგებელი: მინიმალური კალორია, მაქსიმალური ბოჭკო და ვიტამინები. ყველა ბოსტნეულის საკუთარ წვენში ნელ-ნელა მომზადება მათ კვებით ღირებულებას უნარჩუნებს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყაბაყი, ბადრიჯანი, პომიდორი: თითოეული 2 ცალი (ერთნაირი ზომის, ძალიან თხელ რგოლებად დაჭრილი)","ტომატის პასტა და ნიორი (ქვედა ფენის სოუსისთვის).","პროვანსული მწვანილები (ბეგქონდარა, როზმარინი), ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მრგვალი საცხობი ფორმის ძირზე პომიდვრის სოუსი გაანაწილეთ. დაჭრილი ბოსტნეული ფერების თანმიმდევრობით (ბადრიჯანი, პომიდორი, ყაბაყი) ფორმის კიდიდან ცენტრისკენ სპირალურად დაალაგეთ. მოაყარეთ მწვანილები, მოასხით ზეთი, დააფარეთ და გამოაცხვეთ 190 გრადუსზე 45 წუთის განმავლობაში."]'::jsonb) WHERE id = '3a7875bd-9bf1-4570-9e1d-e51c83452192';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'იაპონური მისოს სუპი'), description_ka = COALESCE(description_ka, 'მსუბუქი, ფერმენტირებული სუპი, რომელსაც დილით ან საღამოს მიირთმევენ და იაპონელთა დღეგრძელობის ერთ-ერთ საიდუმლოდ მიიჩნევენ.

სარგებელი: მისოს პასტა (ფერმენტირებული სოია) ნაწლავების ჯანმრთელობისთვის ერთ-ერთი ყველაზე ძლიერი პრობიოტიკია. ხელს უწყობს მონელების მოწესრიგებას.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მისოს პასტა: 2 სუფრის კოვზი (იყიდება აზიურ მაღაზიებში)","ტოფუ: 100 qr (დაჭრილი პატარა კუბებად)","მწვანე ხახვი: 2 ღერი (დაჭრილი)","თბილი წყალი ან ბოსტნეულის ბულიონი: 2 ჭიქა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["წყალი მიიყვანეთ ადუღებამდე და გადმოდგით ცეცხლიდან (მისო არ უნდა ადუღდეს, წინააღმდეგ შემთხვევაში პრობიოტიკები განადგურდება). მისოს პასტა წყალში გახსენით. დაუმატეთ ტოფუს კუბები და მწვანე ხახვი და მაშინვე, თბილად მიირთვით."]'::jsonb) WHERE id = '35ab7142-651b-45ae-b7e5-7c6acf7f3691';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ორაგული და კარტოფილი (1 წლიდან)'), description_ka = COALESCE(description_ka, 'რბილი თევზის კატლეტები, რომლებსაც თევზის მოყვარული ბავშვებიც კი სიამოვნებით მიირთმევენ.

სარგებელი: ორაგული შეიცავს ომეგა-3 ცხიმოვან მჟავებს, რომლებიც ხელს უწყობს ტვინისა და მხედველობის განვითარებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი', 'ბავშვის კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ორაგულის ფილე: 50 qr (ორთქლზე მომზადებული და დაქუცმაცებული)","კარტოფილი: 1 ცალი (მოხარშული და დაჭყლეტილი)","ახალი კამა: ძალიან ცოტა (დაჭრილი)","ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["დაჭყლეტილი კარტოფილი, დაქუცმაცებული უძვლო თევზი და კამა ერთმანეთში აურიეთ. გააკეთეთ პატარა კატლეტები და ტაფაზე, ძალიან მცირე რაოდენობის ზეითუნის ზეთში, ორივე მხრიდან მსუბუქად შეწვით."]'::jsonb) WHERE id = '34a3ec68-3237-4337-99bf-0423a1d5cd88';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'გაწურული იოგურტისა და ჩიას ბოული (1 წლიდან)'), description_ka = COALESCE(description_ka, 'პრობიოტიკებითა და კალციუმით მდიდარი წასახემსებელი ან მსუბუქი ვახშამი.

სარგებელი: იოგურტი ამდიდრებს ნაწლავის მიკროფლორას, ჩიას თესლი კი ომეგა-3-ს შეიცავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["გაწურული ან ბერძნული იოგურტი: 2-3 სუფრის კოვზი","ჩიას თესლი: ნახევარი ჩაის კოვზი (წინასწარ 1 კოვზ წყალში გაჟღენთილი)","ჟოლო ან მარწყვი: 2-3 ცალი (დაჭყლეტილი პიურეს სახით)","თაფლი: ჩაის კოვზის წვერით (უსაფრთხოა 1 წელზე უფროსი ასაკის ბავშვებისთვის)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["იოგურტი, გაჟღენთილი ჩიას თესლი, ხილის პიურე და ძალიან ცოტა თაფლი ჯამში აურიეთ. მიიღებთ გემრიელ დესერტს, რომელიც თქვენს ბავშვს თავისი ფერითაც დააინტერესებს."]'::jsonb) WHERE id = '90e2d20f-198b-4417-92bb-ccab337989e6';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მაკარონის სალათი (2 წლის ასაკიდან)'), description_ka = COALESCE(description_ka, 'სხვადასხვა ფერი და ტექსტურა 2 წლის ბავშვის მოტორულ უნარებსა და ინტერესს ავითარებს.

სარგებელი: ნოყიერი ნახშირწყლები და ბოსტნეულის ბოჭკოები ერთად. შესანიშნავი, გამაგრილებელი სადილია ზაფხულის ცხელი დღეებისთვის.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ფერადი ფუზილის მაკარონი (ბოსტნეულით): 1 ჭიქა (მოხარშული)","მწვანე ბარდა და სიმინდი: თითოეული 1 სუფრის კოვზი (მოხარშული)","სტაფილო: ნახევარი (ძალიან პატარა კუბებად დაჭრილი და მოხარშული)","მაწონი (სოუსისთვის): 1 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თბილი მაკარონი, ბარდა, სიმინდი და სტაფილო ერთ ჯამში აურიეთ.","ზემოდან მაწონი დაუმატეთ და კარგად აურიეთ, რომ გემოები შეერწყას.","დაუდგით ბავშვს, რათა საკუთარი ხელით მიირთვას."]'::jsonb) WHERE id = '78095524-c00e-403c-92d3-bbc3e2809be1';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტკბილი კარტოფილის ვაფლი (2 წლის ასაკიდან)'), description_ka = COALESCE(description_ka, 'ხრაშუნა და ხელით ადვილად დასაჭერი ვაფლი ბავშვებისთვის, რომლებსაც ფანქეიქები მობეზრდათ.

სარგებელი: ტკბილი კარტოფილი სისხლში შაქრის დონეს არეგულირებს და ბავშვს ხანგრძლივი ენერგიით უზრუნველყოფს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილის პიურე: ნახევარი ჭიქა","კვერცხი: 1 ცალი","ფქვილი (მთლიანი ხორბლის ან შვრიის): 2 სუფრის კოვზი","დარიჩინი: ძალიან ცოტა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ერთ თასში აურიეთ და ცომი მოამზადეთ.","ვაფლის აპარატს ოდნავ წაუსვით ზეთი და ცომი ჩაასხით.","აცხვეთ, სანამ ოქროსფერს არ მიიღებს და კიდეები არ გახრაშუნდება. (თუ ვაფლის აპარატი არ გაქვთ, შეგიძლიათ ტაფაზე ფანქეიქივითაც გამოაცხოთ)."]'::jsonb) WHERE id = '945b98d6-f61a-4b5b-a323-8398d17756d0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სახლში მომზადებული ნაგეთსები (4 წლის ასაკიდან)'), description_ka = COALESCE(description_ka, 'ღუმელში გამომცხვარი, 100% სახლში მომზადებული ხრაშუნა ნაგეთსები, რომლებიც სწრაფი კვების სურვილს ამცირებს.

სარგებელი: სუფთა ქათმის ცილა კუნთებს აძლიერებს, შვრიის საფარი კი საჭმლის მონელებას უწყობს ხელს და დანაყრების შეგრძნებას ხანგრძლივად ინარჩუნებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ხორცი: 150 qr (კუბებად დაჭრილი)","შვრიის ფქვილი ან დაფქული შვრია: ამოსავლებად","კვერცხი: 1 ცალი","ტკბილი წითელი დაფქული წიწაკა (პაპრიკა) და ცოტაოდენი მარილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქათმის კუბები ჯერ ათქვეფილ კვერცხში, შემდეგ კი სანელებლებიან შვრიის ფქვილში ამოავლეთ. საცხობ ქაღალდდაფენილ ლანგარზე დაალაგეთ და 190 გრადუსზე 20 წუთის განმავლობაში, შეწითლებამდე გამოაცხვეთ."]'::jsonb) WHERE id = '4660742b-6a15-4753-92bd-b4b19340e368';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ვაშლის დონატები(4 წლის+)'), description_ka = COALESCE(description_ka, 'ცომისა და შაქრის გარეშე მომზადებული დონატები, რომელთა მომზადებაც ბავშვებისთვის სახალისო თამაშად იქცევა.

სარგებელი: ვაშლში შემავალი ბოჭკო ხელს უწყობს საჭმლის მონელების რეგულირებას, არაქისის კარაქი კი დანაყრებისთვის საჭირო ცილას შეიცავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["დიდი ვაშლი: 1-2 ცალი (წითელი ან მწვანე)","არაქისის კარაქი ან შოკოლადისა და თხილის უშაქრო კრემი: 2 სუფრის კოვზი","შოკოლადის წვეთები, ქოქოსის ფანტელი, წვრილად დაჭრილი ნიგოზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ვაშლი რგოლებად დაჭერით და შუაში თესლებიანი ნაწილი წრიულად ამოჭერით (დონატის ფორმა რომ მიიღოთ). ზემოდან არაქისის კარაქი წაუსვით. მიეცით ბავშვს საშუალება, საკუთარი „ბორბლები“ შოკოლადის წვეთებითა და ქოქოსით მორთოს."]'::jsonb) WHERE id = 'a8a21b7d-5abe-40d9-9276-a772ffab8e70';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ისპანახის ვაფლები(5 წლის+)'), description_ka = COALESCE(description_ka, 'მწვანე ფერის ვაფლები, რომლებიც ბავშვების ყურადღებას იპყრობს და დილაობით მათ „დრაკონის ძალას“ აძლევს.

სარგებელი: ისპანახი მდიდარია რკინით, შვრია კი ბოჭკოთი. ბავშვი დიდხანს რჩება დანაყრებული და ეს ანემიის თავიდან აცილებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ახალგაზრდა ისპანახი: 1 დიდი მუჭა","კვერცხი: 1 ცალი","შვრიის ფქვილი (ან მთლიანი ხორბლის ფქვილი): 3-4 სუფრის კოვზი","რძე: ნახევარი ჭიქა","ზეითუნის ზეთი: 1 ჩაის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში ათქვიფეთ, სანამ სრულიად ერთგვაროვან, მკვეთრ მწვანე ცომს არ მიიღებთ. ვაფლის აპარატს (ან ტაფას) ზეთი წაუსვით, ჩაასხით ცომი და ხრაშუნა ტექსტურის მიღებამდე გამოაცხვეთ. ზემოდან შეგიძლიათ ცოტაოდენი თაფლი მოასხათ."]'::jsonb) WHERE id = 'cb924e7b-c487-4059-bef0-ff92f0b6b771';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროს საგანძურის კექსები(5 წლის+)'), description_ka = COALESCE(description_ka, 'ფერადი „საგანძურით“ სავსე კვერცხის კექსები, რომლებიც კვერცხის მოყვარულებად ყველაზე ჭირვეულ ბავშვებსაც კი აქცევს.

სარგებელი: კვერცხის გულში შემავალი ქოლინი მეხსიერებას აძლიერებს. კექსები ძალიან მსუბუქია, რადგან ფქვილსა და გლუტენს არ შეიცავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხი: 3 ცალი","ფერადი ბულგარული წიწაკა (წითელი და მწვანე): 2 სუფრის კოვზი (ძალიან წვრილად დაჭრილი)","ყველი (გახეხილი): 2 სუფრის კოვზი","მარილი და ცოტაოდენი რძე."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კვერცხი რძესა და მარილთან ერთად ათქვიფეთ. დაუმატეთ დაჭრილი წიწაკა და ყველი. კექსის (მაფინის) ფორმებს მსუბუქად წაუსვით ზეთი და ნარევი მათში გადაანაწილეთ. გამოაცხვეთ 180 გრადუსზე გახურებულ ღუმელში, სანამ არ ამოვა და არ დაიბრაწება (15-20 წუთი)."]'::jsonb) WHERE id = '37d5dece-84c4-4e64-b999-a935190306a7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქინოათი ფარშირებული ფერადი ბულგარული წიწაკა'), description_ka = COALESCE(description_ka, 'ხმელთაშუა ზღვის სამზარეულოს პოპულარული კერძის ცილებით მდიდარი ვერსია, რომელშიც ბრინჯის ნაცვლად ქინოა გამოიყენება.

სარგებელი: ფერადი ბულგარული წიწაკა C ვიტამინითაა მდიდარი. ღუმელში მომზადებისას ის იდეალურად ერწყმის ქინოას ტექსტურას.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბულგარული წიწაკა (წითელი, ყვითელი): 3-4 ცალი (შუაზე გაჭრილი და თესლებისგან გასუფთავებული)","ქინოა (მოხარშული): 1.5 ჭიქა","ფარში ან სოკო: 150 გრ (მოშუშული)","ტომატის პასტა, ყველი (ზემოდან მოსაყრელად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მოხარშული ქინოა მოშუშულ ფარშს/სოკოსა და ტომატის პასტას შეურიეთ. მიღებული მასით წიწაკები გაავსეთ. საცხობ ფორმაში დაალაგეთ და 180 გრადუსზე, წიწაკების დარბილებამდე გამოაცხვეთ. გამოღებამდე 5 წუთით ადრე ყველი მოაყარეთ."]'::jsonb) WHERE id = 'b1385dc4-14fe-4718-ab79-5558f3683c72';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოსა და ნუშის სმუზი'), description_ka = COALESCE(description_ka, 'განსაკუთრებით კრემოვანი სმუზი, რომელიც შეგიძლიათ მიირთვათ როგორც წასახემსებლად, ისე გემრიელი დესერტის ნაცვლად.

სარგებელი: ავოკადოს ცხიმებსა და ნუშში შემავალ E ვიტამინს უჯრედულ დონეზე გამაახალგაზრდავებელი ეფექტი აქვს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ავოკადო: ნახევარი (სრულად დამწიფებული და რბილი)","ნუშის რძე: 1 ჭიქა","ჩიას თესლი: 1 ჩაის კოვზი (ზემოდან მოსაყრელად)","თაფლი: 1 ჩაის კოვზი","ყინულის კუბები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ავოკადო, ნუშის რძე, ყინული და თაფლი ბლენდერში ათქვიფეთ, სანამ სრულიად ერთგვაროვან, „აბრეშუმივით“ გლუვ მასას არ მიიღებთ. ჭიქაში ჩაასხით და ზემოდან ჩიას თესლი მოაყარეთ."]'::jsonb) WHERE id = '14732b3b-b0ea-4f4d-834e-0f74c755ed69';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'Protein Cloud — ხაჭოს ფანქეიქი'), description_ka = COALESCE(description_ka, 'ფქვილის გარეშე მომზადებული, ცილებით მდიდარი ფანქეიქი, რომელიც ტკბილეულის სურვილს ჯანსაღად დაგიკმაყოფილებთ.

სარგებელი: ცილის მაღალი შემცველობა დიდხანს შეგინარჩუნებთ დანაყრების შეგრძნებას და ხელს უწყობს კუნთოვანი მასის შენარჩუნებას. ფქვილის არქონის გამო კი სისხლში შაქრის დონეს მკვეთრად არ ზრდის.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ხაჭო (ნაკლებცხიმიანი): 100 გრ","კვერცხი: 1 ცალი","შვრიის ფქვილი: 2 სუფრის კოვზი","ვანილი და დარიჩინი.","მისართმევად: იოგურტი ან თაფლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხაჭო კვერცხთან ერთად კარგად დასრისეთ. დაუმატეთ შვრიის ფქვილი და სანელებლები, შემდეგ ცომი მოამზადეთ. უცხიმო ტაფაზე პატარა წრეების სახით ორივე მხრიდან შეწვით."]'::jsonb) WHERE id = '29f853dc-e269-415a-b733-458329d3f202';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტკბილი კარტოფილის სოტე'), description_ka = COALESCE(description_ka, 'ბოჭკოთი და რთული ნახშირწყლებით მდიდარი, ნოყიერი კერძი განსხვავებული გემოთი.

სარგებელი: ტკბილ კარტოფილში შემავალი ბოჭკო და ვიტამინები ხელს უწყობს ინსულინრეზისტენტობის რეგულირებას და ამცირებს ტკბილეულის სურვილს.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი (ბატატი): 1 საშუალო ზომის (პატარა კუბებად დაჭრილი)","წითელი ხახვი: ნახევარი","ისპანახი: 1 მუჭა","ზეითუნის ზეთი, მარილი, შავი პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ტაფაზე გააცხელეთ ზეთი და მოშუშეთ ტკბილი კარტოფილი და ხახვი დარბილებამდე. სრულად მომზადების შემდეგ დაამატეთ ისპანახი და ურიეთ 1 წუთის განმავლობაში. შესანიშნავად ეხამება 1 ნაჭერ ყველს."]'::jsonb) WHERE id = '62b8e0b6-2240-42de-af0b-ccfb0617485b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბროკოლისა და ისპანახის წვნიანი'), description_ka = COALESCE(description_ka, 'შესანიშნავი „თხევადი“ ვახშამი, რათა დილით მსუბუქი და მშვიდი მუცლით გაიღვიძოთ.

სარგებელი: მწვანე დეტოქს-წვნიანი, რომელიც ხელს უწყობს ორგანიზმიდან ტოქსინების გამოდევნას და ღვიძლისა და ნაწლავების ნაზად გაწმენდას.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბროკოლი: 200 გრ","ისპანახი: 1 მუჭა","ხახვი, ნიორი (ცოტაოდენი).","ნუშის რძე ან ნაღები: 2 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბროკოლი და ხახვი მოხარშეთ წყალში დარბილებამდე. ცეცხლიდან გადმოდგმამდე 1 წუთით ადრე დაამატეთ ისპანახი. ყველაფერი დააბლენდერეთ, შემდეგ დაუმატეთ რძე/ნაღები და ურიეთ კრემისებრი კონსისტენციის მიღებამდე. მიირთვით მოხალულ გოგრის თესლთან ერთად."]'::jsonb) WHERE id = '94c6eeab-3fdb-44c0-af09-f90065cd1128';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ლიმონიანი ქათამი და სატაცური'), description_ka = COALESCE(description_ka, 'ერთ ტაფაზე მომზადებული დიეტური კერძი, რომელიც მარტივად ჟღერს, თუმცა ძალიან „მდიდრულად“ გამოიყურება.

სარგებელი: ქათმის მკერდი ცილის წყაროა, სატაცური კი სუპერპროდუქტია, რომელიც ხელს უწყობს თირკმლების მუშაობას და ორგანიზმიდან ჭარბი სითხის (შეშუპების) გამოდევნას.'), category_ka = COALESCE(category_ka, 'ვახშამი'), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდი: 150 გრ (თხლად დაბეგვილი ან დაჭრილი)","სატაცური (ასპარაგუსი): 1 კონა","ლიმონი: 1 ცალი (ნახევარი — წვენისთვის, ნახევარი — ნაჭრებად)","ზეითუნის ზეთი, ნივრის ფხვნილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ფართო ტაფაზე ქათამი ზეთში ორივე მხრიდან შეწვით. მომზადებამდე ცოტა ხნით ადრე ტაფაზე დაამატეთ სატაცური და ლიმონის ნაჭრები და ერთად მოშუშეთ 5-7 წუთის განმავლობაში. მოასხით ლიმონის წვენი და მიირთვით."]'::jsonb) WHERE id = '51c68a19-8648-4032-8605-7b8cccf441b0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბადრიჯნისა და ყველის ფენები'), description_ka = COALESCE(description_ka, 'მსუბუქი, დაბალნახშირწყლოვანი ალტერნატივა — ცრუ ლაზანია'), category_ka = COALESCE(category_ka, 'ვახშამი'), ingredients_ka = COALESCE(ingredients_ka, '["ბადრიჯანი - 2 ცალი","პომიდორი - 2 ცალი","თეთრი ყველი - 60 qr","რეჰანი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბადრიჯანი თხელ ნაჭრებად დაჭერით და ღუმელში ოდნავ მოარბილეთ","დაამატეთ ყველი, პომიდორი და რეჰანი","გამოაცხვეთ ღუმელში, სანამ ყველი არ გადნება"]'::jsonb) WHERE id = 'c940ec18-0208-46aa-8361-f2f2f659b141';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღუმელში გამომცხვარი ატამი დარიჩინით'), description_ka = COALESCE(description_ka, 'ძალიან მსუბუქი დესერტი, რომელიც ნაყინის ეფექტს ქმნის, თუმცა ძალიან ცოტა კალორიას შეიცავს.

სარგებელი: ატამი მდიდარია ბოჭკოებით, რაც ხელს უწყობს საჭმლის მონელებას, დარიჩინი კი შესაძლოა სისხლში შაქრის დონის რეგულირებას დაეხმაროს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), ingredients_ka = COALESCE(ingredients_ka, '["ატამი: 2 ცალი (შუაზე გაჭრილი, კურკის გარეშე)","დარიჩინი: 1 ჩაის კოვზი","ნიგოზი ან პეკანი: დაქუცმაცებული","გაწურული იოგურტი (მისართმევად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ატმის ნახევრები საცხობ ფორმაში დაალაგეთ, შუაგულში დარიჩინი და ნიგოზი მოაყარეთ. გამოაცხვეთ 180 გრადუსზე 15-20 წუთის განმავლობაში, სანამ არ დარბილდება. მიირთვით თბილი, შუაგულში ერთი კოვზი გაწურული იოგურტის დამატებით."]'::jsonb) WHERE id = 'e7b8a04c-a4fa-4769-bbd9-6735976b643a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'გოგრა და ქოქოსის რძე
(8 თვიდან)'), description_ka = COALESCE(description_ka, 'ბავშვის პირველი გაცნობა განსხვავებულ, ტროპიკულ გემოებთან. აქვს აბრეშუმივით ნაზი ტექსტურა.

სარგებელი: გოგრაში შემავალი A ვიტამინი ხელს უწყობს თვალის ჯანმრთელობას. ქოქოსის რძე კი ძროხის რძის მცენარეული ალტერნატივაა და სასარგებლო ცხიმებს შეიცავს. გაითვალისწინეთ, რომ ზოგიერთ ბავშვში მან შესაძლოა ალერგიული რეაქცია გამოიწვიოს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["გოგრა: 1 ნაჭერი (გაფცქვნილი, კუბებად დაჭრილი)","ქოქოსის რძე (არა მუყაოს შეფუთვაში ჩამოსხმული სასმელი, არამედ სქელი, კულინარიული სახეობა): 2 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["გოგრა ორთქლზე მოამზადეთ, სანამ არ დარბილდება. დაამატეთ ქოქოსის რძე და დააბლენდერეთ. მიიღებთ ძალიან ნოყიერ და გემრიელ სუპს."]'::jsonb) WHERE id = 'a8859019-9d72-40f8-8956-b03d1cfb1e34';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ინდაურისა და ქინოას ფარშირებული წიწაკა'), description_ka = COALESCE(description_ka, 'ჩვეულებრივი ტოლმის დაბალნახშირწყლოვანი, ვიტამინებით მდიდარი და ფერადი ვერსია.

სარგებელი: C ვიტამინისა (ფერადი წიწაკა) და ცილის (ინდაურის ხორცი) კომბინაცია ხელს უწყობს კანში კოლაგენის წარმოქმნას.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ფერადი ბულგარული წიწაკა: 2 ცალი (შუაზე გაჭრილი, ნავის ფორმის)","ინდაურის ფარში (ან უცხიმო საქონლის ხორცი): 150 გრ","ქინოა (მოხარშული): 2 სუფრის კოვზი","ტომატის სოუსი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ფარში ქინოასა და ტომატის სოუსთან ერთად ტაფაზე ნახევრად მოამზადეთ. მიღებული მასით შეავსეთ წიწაკის ნავები და გამოაცხვეთ ღუმელში, სანამ წიწაკა არ დარბილდება."]'::jsonb) WHERE id = 'b2be2ad1-ce46-48a9-9075-79f7864e5758';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მატჩას ლიმონათი'), description_ka = COALESCE(description_ka, 'ანტიოქსიდანტებით მდიდარი ორფეროვანი სასმელი, რომელიც ენერგიას უფრო თანაბრად მატებს.

სარგებელი: მატჩა შეიცავს კოფეინსა და L-თეანინს, ამიტომ ყავასთან შედარებით მისი მასტიმულირებელი ეფექტი შეიძლება უფრო თანაბრად იგრძნობოდეს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მატჩას ფხვნილი: 1 ჩაის კოვზი (თბილ წყალში აქაფებული)","ახლად გამოწურული ლიმონის წვენი: ჭიქის მესამედი","აგავის სიროფი ან თაფლი: 1 სუფრის კოვზი","წყალი და ბევრი ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჭიქაში ჩაყარეთ ყინული. ლიმონის წვენი, თაფლი და წყალი ერთმანეთში აურიეთ, გადაწურეთ და ყინულს დაასხით. ბოლოს ნელ-ნელა დაამატეთ აქაფებული მწვანე მატჩა (ასე სასმელი ჭიქაში ორფეროვანი იქნება — ქვემოთ ყვითელი, ზემოთ კი მწვანე)."]'::jsonb) WHERE id = 'cb10f111-6a9d-4baa-9dd6-af7ef8393f1e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღამით დაყენებული შვრია ნიგვზითა და ბანანით'), description_ka = COALESCE(description_ka, 'იდეალური, გრილი და მსუბუქი არჩევანი მათთვის, ვისაც დილით გულისრევა აწუხებს'), category_ka = COALESCE(category_ka, 'საუზმე'), ingredients_ka = COALESCE(ingredients_ka, '["შვრია - 4 სუფრის კოვზი","რძე - 1 ჭიქა","ბანანი - ნახევარი","ნიგოზი - 2 ცალი","თაფლი - 1 ჩაის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["საღამოს ერთმანეთში აურიეთ შვრია, რძე და თაფლი","შეინახეთ მაცივარში","დილით დაამატეთ ბანანი და ნიგოზი"]'::jsonb) WHERE id = 'ae635663-e33c-479a-970a-94bd85e39010';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბროკოლისა და ყველის ბურთულები (1 წლიდან+)'), description_ka = COALESCE(description_ka, 'ყველაზე ხრაშუნა და სახალისო გზა, რომ ბავშვს ბროკოლი შეაყვაროთ.

სარგებელი: ბროკოლი შეიცავს იმუნიტეტის გამაძლიერებელ C ვიტამინს, ხოლო ყველი და კვერცხი — ხარისხიან ცილას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბროკოლი: 4-5 ყვავილედი (ორთქლზე მომზადებული და ძალიან წვრილად დაჭრილი)","კვერცხი: 1 ცალი","ჰოლანდიური ყველი ან მოცარელა: 2 სუფრის კოვზი (გახეხილი)","მთლიანი ხორბლის ფქვილი ან დაფქული ორცხობილა: 1 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["დაჭრილი ბროკოლი კვერცხს, ყველსა და ფქვილს შეურიეთ. ხელით პატარა ცილინდრის (ან ჩხირის) ფორმა მიეცით. გამოაცხვეთ 180 გრადუსზე გახურებულ ღუმელში 15 წუთის განმავლობაში, სანამ არ შეწითლდება."]'::jsonb) WHERE id = 'a31f99ac-a31e-4008-9edc-552e80b3f2f2';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მზიანი გული — კვერცხი კარტოფილით'), description_ka = COALESCE(description_ka, 'კვერცხის გული მნიშვნელოვანია ტვინისა და მხედველობის განვითარებისთვის (8 თვიდან+)'), category_ka = COALESCE(category_ka, 'ბავშვის_საკვები'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხის გული - 1 ცალი","კარტოფილი - 1 პატარა ცალი","დედის რძე/ხელოვნური ნარევი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მოამზადეთ კარტოფილის პიურე","მოხარშული კვერცხის გული დაჭყლიტეთ და დაამატეთ","რძით გაათხელეთ"]'::jsonb) WHERE id = '0d1f8dc7-ed50-4792-a9b8-aaed4334e5c7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ირმის ნახტომის ორცხობილები'), description_ka = COALESCE(description_ka, 'მსოფლიოში ცნობილი ლაქტაციის ორცხობილების ჯანსაღი ვერსია. შვრია და სელის თესლი პროლაქტინის დონეს ზრდის.'), category_ka = COALESCE(category_ka, 'ჯანსაღი_ტკბილეული'), ingredients_ka = COALESCE(ingredients_ka, '["შვრია: 1.5 ჭიქა","კარაქი: 50 გრ","თაფლი: 3 სუფრის კოვზი","კვერცხი: 1 ცალი","სელის თესლი: 2 სუფრის კოვზი","შოკოლადის წვეთები: სურვილისამებრ"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კარაქი გაადნეთ და თაფლსა და კვერცხთან ერთად ათქვიფეთ","დაამატეთ შვრია და სელის თესლი, შემდეგ აურიეთ","სურვილისამებრ დაამატეთ შოკოლადის წვეთები","კოვზით საცხობ ქაღალდზე წრეები გააკეთეთ","გამოაცხვეთ 175°C-ზე 12-15 წუთის განმავლობაში — მიირთვით დღეში 2-3 ცალი"]'::jsonb) WHERE id = 'f09a3c1e-ec4c-4eb2-b2d1-b699bce46612';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადო სელის ლავაშში'), description_ka = COALESCE(description_ka, 'მხოლოდ 2 ინგრედიენტით მომზადებული, უფქვილო და უგლუტენო „ვეგანური ლავაში“.

სარგებელი: ნახშირწყლებს თითქმის არ შეიცავს. მხოლოდ ბოჭკოსა და წყლისგან შედგება და ნაწლავების ჯანმრთელობისთვის „ცოცხის“ როლს ასრულებს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["სელის თესლი (დაფქული): 1 ჭიქა","ადუღებული წყალი: 1 ჭიქა","შიგთავსისთვის: ავოკადოს ნაჭრები, ისპანახი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["დაფქულ სელის თესლს დაასხით ადუღებული წყალი და მოზილეთ ცომი (ჟელესებრი გახდება). ორ საცხობ ქაღალდს შორის ლავაშივით გააბრტყელეთ და ორივე მხრიდან მშრალ ტაფაზე გამოაცხვეთ. შიგნით მოათავსეთ ავოკადო და ისპანახი და რულეტივით (wrap) გადაახვიეთ."]'::jsonb) WHERE id = '47c56e28-7e74-45f9-b91a-7cf55a196ffc';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბანანის Nice Cream'), description_ka = COALESCE(description_ka, 'რძისა და შაქრის გარეშე მომზადებული, მხოლოდ ხილისგან შემდგარი ყველაზე ჯანსაღი ნაყინი'), category_ka = COALESCE(category_ka, 'ჯანსაღი_დესერტები'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბანანი - 2 ცალი (გაყინული)","კაკაო - 1 ჩაის კოვზი","მარწყვი - 3 ცალი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["გაყინული ბანანი ბლენდერში კრემისებრი მასის მიღებამდე დააბლენდერეთ","დაამატეთ კაკაო/მარწყვი","მაშინვე მიირთვით"]'::jsonb) WHERE id = 'ac0ef609-013d-4d24-9387-eb2cabfeb421';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბრუსკეტა ავოკადოთი და კვერცხით'), description_ka = COALESCE(description_ka, 'მდიდარია ფოლიუმის მჟავითა და ჯანსაღი ცხიმებით და ხელს უწყობს ნაყოფის ტვინის განვითარებას'), category_ka = COALESCE(category_ka, 'საუზმე'), ingredients_ka = COALESCE(ingredients_ka, '["მთლიანი ხორბლის პური - 2 ნაჭერი","ავოკადო - ნახევარი","კვერცხი - 1 ცალი","ლიმონის წვენი - 1 ჩაის კოვზი","სეზამი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ავოკადო დაჭყლიტეთ, დაამატეთ ლიმონის წვენი და მარილი","მოხალულ პურზე ავოკადო წაუსვით","მაგრად მოხარშული კვერცხი დაჭერით და ზემოდან დააწყვეთ","მოაყარეთ სეზამი"]'::jsonb) WHERE id = '2554217b-8b4f-4356-a70a-64c6a62b32e2';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დედოფლის ფაფა — დედოფლის დილა'), description_ka = COALESCE(description_ka, 'ფინიკისა და ნიგვზის ენერგიის შერწყმა შვრიის რძის გამომუშავების ხელშემწყობ თვისებასთან. პროლაქტინის სტიმულატორი.'), category_ka = COALESCE(category_ka, 'საუზმე'), ingredients_ka = COALESCE(ingredients_ka, '["შვრია: 3 სუფრის კოვზი","რძე: 1 ჭიქა","ფინიკი: 2-3 ცალი (კურკის გარეშე)","ნიგოზი: 1 მუჭა","დარიჩინი: ერთი მწიკვი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["რძე და შვრია ქვაბში საშუალო ცეცხლზე მორევით მოხარშეთ","განაგრძეთ მორევა შესქელებამდე (5-7 წთ)","გადმოდგით ცეცხლიდან და დაჭრილი ფინიკი დაამატეთ","მოაყარეთ ნიგოზი და დარიჩინი","მიირთვით ცხლად — რძის გამომუშავების ხელშესაწყობად საუკეთესო საუზმეა"]'::jsonb) WHERE id = 'e130e1c4-d49f-409f-844e-56265cb3eca7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მწვანე დეტოქს-ელექსირი'), description_ka = COALESCE(description_ka, 'სუპერ „მწვანე წვენი“, რომელიც ხელს უწყობს ღვიძლისა და კანის გაწმენდას და უჯრედების განახლებას.

სარგებელი: ნიახურის ღერო ხელს უწყობს აკნეს შემცირებასა და საჭმლის მონელების მოწესრიგებას. უზმოზე დალევისას შესანიშნავი დეტოქს-ეფექტი აქვს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ნიახურის ღერო: 2 ცალი","მწვანე ვაშლი: 1 ცალი","ახალი ჯანჯაფილი: ძალიან პატარა ნაჭერი","ლიმონის წვენი: ნახევარი ლიმონი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ნიახური, ვაშლი და ჯანჯაფილი წვენსაწურში გაატარეთ. დაუმატეთ გამოწურული ლიმონი და მაშინვე დალიეთ, სანამ ვიტამინები დაიკარგება."]'::jsonb) WHERE id = 'b862ae81-6647-4306-8478-b02653620beb';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მსხლისა და ქლიავის პიურე
(6 თვე+)'), description_ka = COALESCE(description_ka, 'დამატებით კვებაზე გადასვლისას ხშირად წარმოქმნილი შეკრულობის ბუნებრივი და გემრიელი გადაწყვეტა.

სარგებელი: ქლიავი და მსხალი ხელს უწყობს ნაწლავების მუშაობას, შვრია კი ბავშვს დიდხანს უნარჩუნებს დანაყრების შეგრძნებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბავშვის შვრიის ფქვილი (ან ბლენდერში დაფქული შვრია): 1-2 სუფრის კოვზი","მსხალი: ნახევარი","შავი ქლიავის ჩირი: 2 ცალი (წინასწარ დარბილებული ცხელ წყალში)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["შვრია წყალში მოხარშეთ ფაფის კონსისტენციამდე. მსხალი ორთქლზე დაარბილეთ. ქლიავი და მსხალი ბლენდერში დააბლენდერეთ და შვრიის ფაფას შეურიეთ."]'::jsonb) WHERE id = '869b95b1-b2fc-4999-9364-14adff9736c9';
