UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ცრუ ტოლმა ღუმელში'), description_ka = COALESCE(description_ka, 'რადგან შემწვარი არ არის, გულძმარვას არ იწვევს, ბოჭკოვანი ბოსტნეული კი საჭმლის მონელებას აადვილებს'), category_ka = COALESCE(category_ka, 'სადილი'), ingredients_ka = COALESCE(ingredients_ka, '["ყაბაყი - 2 ცალი","საქონლის ხორცის ფარში - 150 qr","ხახვი - 1 ცალი","პომიდორი - 1 ცალი","ყველი - 30 qr"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბოსტნეული შუაზე გაჭერით და გული ამოუღეთ","ხორცი ხახვსა და პომიდორთან ერთად მოამზადეთ","ბოსტნეული მომზადებული გულსართით შეავსეთ","180°C-ზე 25-30 წუთის განმავლობაში გამოაცხვეთ","მოაყარეთ ყველი"]'::jsonb) WHERE id = '2f2b9ad9-7480-4118-bad9-8cd23415bda5';
