UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბოსტნეულის მაფინ-ომლეტები'), description_ka = COALESCE(description_ka, 'ცილები და ვიტამინები ერთად. პრაქტიკული არჩევანია დასაქმებული ქალებისთვის'), category_ka = COALESCE(category_ka, 'საუზმე'), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხი - 3 ცალი","რძე - 2 სუფრის კოვზი","წითელი ბულგარული წიწაკა - ნახევარი","მწვანე ხახვი - რამდენიმე ღერი","თეთრი ყველი - 50 გრ"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კვერცხი რძესთან ერთად ათქვიფეთ","დაამატეთ წიწაკა, ხახვი და ყველი","ჩაასხით მაფინის ფორმებში","180°C-ზე 15-20 წუთის განმავლობაში გამოაცხვეთ"]'::jsonb) WHERE id = '04df0cb9-27f0-4232-a5c9-a3da1994f4f1';
