UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'თბილი სალათა მწვანე ოსპით'), description_ka = COALESCE(description_ka, 'ფოლიუმის მჟავისა და ბოჭკოს წყარო, მსუბუქი ვახშამი'), category_ka = COALESCE(category_ka, 'ვახშამი'), ingredients_ka = COALESCE(ingredients_ka, '["მწვანე ოსპი - ნახევარი ჭიქა","სტაფილო - 1 ცალი","ისპანახი - 1 მუჭა","ლიმონის წვენი","ზეითუნის ზეთი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ოსპი მოხარშეთ","დაამატეთ სტაფილო და ისპანახი","შეურიეთ ლიმონისა და ზეთის სოუსი"]'::jsonb) WHERE id = '9194dcd7-0593-42ea-be60-36f52bfc96b4';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღუმელში გამომცხვარი კომშის დესერტი'), description_ka = COALESCE(description_ka, 'კომში გულისრევის შემსუბუქების ერთ-ერთი ყველაზე ეფექტური ხილია'), category_ka = COALESCE(category_ka, 'ჯანსაღი_დესერტები'), ingredients_ka = COALESCE(ingredients_ka, '["კომში - 2 ცალი","ვაშლი - 1 ცალი","დარიჩინის ჩხირი - 1","მიხაკი - 3 ცალი","თაფლი, ნიგოზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კომში შუაზე გაჭერით და გახეხილი ვაშლით შეავსეთ","დაამატეთ დარიჩინი და მიხაკი","გამოაცხვეთ 180°C-ზე 50 წუთის განმავლობაში","მოასხით თაფლი"]'::jsonb) WHERE id = '71de5174-6da5-4ea3-85bb-14cde99315cd';
