UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'გულისრევის საწინააღმდეგო შოტი'), description_ka = COALESCE(description_ka, 'დილის გულისრევის შესამსუბუქებლად ერთ-ერთი ყველაზე ეფექტური საშუალება'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ჯანჯაფილის წვენი - 1 ჩაის კოვზი","ლიმონის წვენი - 1 სუფრის კოვზი","ვაშლის წვენი - 2 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["შეურიეთ პატარა ჭიქაში","დალიეთ დილით, უზმოზე"]'::jsonb) WHERE id = '880d9940-72c5-4091-be98-b624aa0ce63b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქინოასა და ბოსტნეულის ბოული'), description_ka = COALESCE(description_ka, 'ფერადი, ნოყიერი და მთლიანად მცენარეული ენერგიის წყარო.

სარგებელი: ქინოა რთული ნახშირწყალია, რომელიც სისხლში შაქრის დონეს მკვეთრად არ ზრდის, ხოლო მუხუდო მდიდარია მცენარეული ცილებითა და ფიტოესტროგენებით (ხელს უწყობს ქალის ჰორმონების რეგულირებას).'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქინოა: ნახევარი ჭიქა (მოხარშული)","ტკბილი კარტოფილი (ბატატი): 1 ცალი (კუბებად დაჭრილი და ღუმელში გამომცხვარი)","წითელი კომბოსტო: 1 მუჭა (თხლად დაჭრილი)","მუხუდო: 3 სუფრის კოვზი (მოხარშული)","სოუსისთვის: 1 სუფრის კოვზი ტაჰინი, ლიმონის წვენი, ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ღრმა ჯამში ერთმანეთის გვერდიგვერდ, ფერადად დაალაგეთ. მოასხით ტაჰინის სოუსი და მიირთვით."]'::jsonb) WHERE id = 'aef368fe-083d-4b68-9edb-d6de124b4d49';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბადრიჯნის გრატენი'), description_ka = COALESCE(description_ka, 'ცნობილი იტალიური კერძის, „პარმიჯანას“, დიეტური ვერსია შეწვის გარეშე.

სარგებელი: ბადრიჯნის კანში არსებული ანტიოქსიდანტი „ნასუნინი“ ტვინის უჯრედებს იცავს. კერძი ნოყიერია, თუმცა დაბალკალორიული.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბადრიჯანი: 2 ცალი (სიგრძეზე თხლად დაჭრილი)","პომიდვრის სოუსი: 1 ჭიქა","მოცარელა და ხაჭოს ტიპის ყველი: თანაბარი რაოდენობით შერეული","ახალი რეჰანი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბადრიჯნის ნაჭრები ღუმელში ზეთის გარეშე მსუბუქად გამოაცხვეთ. საცხობ ფორმაში ფენებად ჩააწყვეთ სოუსი, ბადრიჯანი, ყველი და რეჰანი (ლაზანიას მსგავსად). ზემოდან ყველის ფენა მოაყარეთ და ღუმელში მის შეწითლებამდე გამოაცხვეთ."]'::jsonb) WHERE id = 'c5e3e953-1def-4129-bf13-05450ac7ffc6';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღუმელში გამომცხვარი ვაშლის ჩიფსი დარიჩინით'), description_ka = COALESCE(description_ka, 'კანფეტის ნაცვლად ჯანსაღი წასახემსებელი'), category_ka = COALESCE(category_ka, 'ჯანსაღი_ტკბილეული'), ingredients_ka = COALESCE(ingredients_ka, '["ვაშლი - 2 ცალი","დარიჩინი - 1 ჩაის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ვაშლი თხელ ნაჭრებად დაჭერით","დარიჩინი მოაყარეთ","ღუმელში დაბალ ტემპერატურაზე გამოაშრეთ"]'::jsonb) WHERE id = '396d0e08-df24-45b2-bbc5-d0eb5bb97a61';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სტაფილოსა და ნიგვზის რბილი კექსი'), description_ka = COALESCE(description_ka, 'სტაფილოში შემავალი A ვიტამინი და ნიგოზში შემავალი ომეგა-3 სასარგებლოა თვალებისა და ტვინის განვითარებისთვის'), category_ka = COALESCE(category_ka, 'ჯანსაღი_ტკბილეული'), ingredients_ka = COALESCE(ingredients_ka, '["შვრიის ფქვილი - 1 ჭიქა","სტაფილო - 2 ცალი","კვერცხი - 2 ცალი","ნიგოზი - ნახევარი ჭიქა","თაფლი - 3 სუფრის კოვზი","დარიჩინი, გამაფხვიერებელი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კვერცხი თაფლთან ერთად ათქვიფეთ","დაამატეთ სტაფილო, ნიგოზი და დარიჩინი","შეურიეთ შვრიის ფქვილი და გამაფხვიერებელი","170°C-ზე 25 წუთის განმავლობაში გამოაცხვეთ"]'::jsonb) WHERE id = 'e1dfdbd8-e8bb-4c32-930c-c832c8f118d3';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მწვანე ქალღმერთის სმუზი'), description_ka = COALESCE(description_ka, 'ისპანახში შემავალი რკინა და C ვიტამინი ანემიის წინააღმდეგ სუპერძალაა'), category_ka = COALESCE(category_ka, 'ჯანსაღი_სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ისპანახი - 1 მუჭა","კივი - 1 ცალი","მწვანე ვაშლი - ნახევარი","ქოქოსის წყალი - ნახევარი ჭიქა","ლიმონის წვენი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში დააბლენდერეთ","მაშინვე დალიეთ"]'::jsonb) WHERE id = '6f156a10-e92e-4a17-a7af-3e68646cf53d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტაკოს ხრაშუნა ჯამები (3 წლის+)'), description_ka = COALESCE(description_ka, 'ლავაშისგან მომზადებულ ხრაშუნა ჯამებში მოთავსებული, ცილებით მდიდარი მექსიკური გემო.

სარგებელი: ლობიოში შემავალი ბოჭკო ხელს უწყობს მონელებას, ხოლო სიმინდი და ხორცი ბავშვს ზრდისთვის საჭირო ენერგიით უზრუნველყოფს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ლავაში (ან ტორტილია): 1 ცალი","წითელი ლობიო (მოხარშული): 2 სუფრის კოვზი","სიმინდი: 1 სუფრის კოვზი","ფარში ან დაქუცმაცებული ქათმის ხორცი: 2 სუფრის კოვზი","გახეხილი ყველი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ლავაში ჭიქის პირით წრიულად გამოჭერით. ეს წრეები მაფინის ფორმის ჩაღრმავებებში ჩააწყვეთ და დაჭერით, რომ \"ჯამის\" ფორმა მიიღოს. შიგნით მოათავსეთ ლობიო, სიმინდი, ხორცი, ზემოდან კი ყველი მოაყარეთ. გამოაცხვეთ ღუმელში, სანამ ყველი არ გადნება და ლავაში არ გახრაშუნდება (10 წუთი)."]'::jsonb) WHERE id = 'feb3870e-5bf3-4d4e-8622-e75280b05802';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოსპის ბომბა-სუპი'), description_ka = COALESCE(description_ka, 'ფოლიუმის მჟავის ნამდვილი საბადო — შეუცვლელი კერძი ორსულებისთვის'), category_ka = COALESCE(category_ka, 'სადილი'), ingredients_ka = COALESCE(ingredients_ka, '["წითელი ოსპი - 1 ჭიქა","სტაფილო - 1 ცალი","კარტოფილი - 1 ცალი","ხახვი - 1 ცალი","ბულიონი - 4 ჭიქა","პიტნა, ლიმონი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხახვი მოშუშეთ და სტაფილო დაუმატეთ","დაუმატეთ ოსპი და კარტოფილი","ჩაასხით ბულიონი და მოხარშეთ","დააბლენდერეთ","დაუმატეთ პიტნა და ლიმონი"]'::jsonb) WHERE id = '290acd87-550a-458c-a7f4-69cb997009e4';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ღუმელში გამომცხვარი ორაგული ლიმონით'), description_ka = COALESCE(description_ka, 'ომეგა-3-ის წყარო ბავშვის ტვინის განვითარებისთვის'), category_ka = COALESCE(category_ka, 'ვახშამი'), ingredients_ka = COALESCE(ingredients_ka, '["თევზის ფილე - 200 qr","ლიმონი - 2 ნაჭერი","ბროკოლი - 100 qr","ზეითუნის ზეთი, ქონდარი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თევზს სანელებლები წაუსვით","ფოლგაზე მოათავსეთ თევზი და ბოსტნეული","დააწყვეთ ლიმონის ნაჭრები","გამოაცხვეთ 180°C-ზე 25 წუთის განმავლობაში"]'::jsonb) WHERE id = '497f352b-6f6a-4450-a0eb-ddccc2332776';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბრწყინვალების სალათი'), description_ka = COALESCE(description_ka, 'დეტოქს-ეფექტის მქონე საუზმე მათთვის, ვისაც სურს, ბოსტნეულის ჭამა დილიდან დაიწყოს.

სარგებელი: ისპანახი და ზეითუნის ზეთი ააქტიურებს ნაწლავების მუშაობას და აჩქარებს ორგანიზმიდან ტოქსინების გამოდევნას.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ახალგაზრდა ისპანახი ან სალათის ფოთლები: 1-2 მუჭა","მაგრად მოხარშული კვერცხი: 1 ცალი","ნიგოზი: 2-3 ცალი","ზეითუნის ზეთი და ლიმონის წვენი.","ხაჭო: 2 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ისპანახი მოათავსეთ ჯამში. ზემოდან დაამატეთ დაჭრილი კვერცხი, ხაჭო და ნიგოზი. მოასხით ზეითუნის ზეთისა და ლიმონის სოუსი და მიირთვით."]'::jsonb) WHERE id = 'b7b9eff5-fed2-499e-b5d9-5c57fb32426f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროს მარცვლები — ბულგურის ფლავი'), description_ka = COALESCE(description_ka, 'ბულგურისა და ოსპის კომბინაცია. მდიდარია B ჯგუფის ვიტამინებით და ხელს უწყობს სარძევე ჯირკვლის ქსოვილების კვებას.'), category_ka = COALESCE(category_ka, 'სადილი'), ingredients_ka = COALESCE(ingredients_ka, '["ბულგური: 1 ჭიქა","მწვანე ოსპი: ნახევარი ჭიქა (მოხარშული)","ხახვი: 1 ცალი","კარაქი: 1 სუფრის კოვზი","წყალი: 2 ჭიქა"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხახვი კარაქში ოქროსფრის მიღებამდე მოშუშეთ","დაამატეთ გარეცხილი ბულგური და 1-2 წუთის განმავლობაში მოშუშეთ","დაამატეთ წინასწარ მოხარშული ოსპი","დაასხით 2 ჭიქა წყალი და მიიყვანეთ ადუღებამდე","დაბალ ცეცხლზე გააჩერეთ წყლის სრულად შეწოვამდე (15-20 წთ)"]'::jsonb) WHERE id = 'dcd85da7-ccb3-4272-a895-942bd99de63b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ძენ-ბალანსის სმუზი'), description_ka = COALESCE(description_ka, 'დამამშვიდებელი სასმელი მათთვის, ვისაც გულძმარვა აწუხებს'), category_ka = COALESCE(category_ka, 'ჯანსაღი_სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["შვრია - 2 სუფრის კოვზი","ბანანი - 1 ცალი","რძე - 1 ჭიქა","თაფლი - 1 ჩაის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["შვრია რძეში დაალბეთ და ოდნავ მოხარშეთ","ბანანსა და თაფლთან ერთად ბლენდერში აურიეთ"]'::jsonb) WHERE id = 'db9dd331-557e-46cd-9d2b-a47d4771ad41';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კუმინის კომფორტი - ოსპის სუპი'), description_ka = COALESCE(description_ka, 'სუპი, რომელიც როგორც დედას, ისე ბავშვს გაზების პრობლემის შემსუბუქებაში ეხმარება. ძირა რძის გამომუშავებას უწყობს ხელს და კოლიკას ამცირებს.'), category_ka = COALESCE(category_ka, 'ძუძუთი_კვება'), tags_ka = COALESCE(tags_ka, ARRAY['მშობიარობის_შემდგომი', 'რძის_მომატება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["წითელი ოსპი: 1 ჭიქა","ხახვი: 1 ცალი","კარტოფილი: 1 ცალი","ძირა (კუმინი): 1 ჩაის კოვზი (უხვად)","კარაქი: 1 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ოსპი, ხახვი და კარტოფილი დაჭერით და წყალში მოხარშეთ","დარბილების შემდეგ დააბლენდერეთ","ცალკე, კარაქში მოხალეთ ძირა (კუმინი), სანამ არომატს არ გამოუშვებს","სუპს ზემოდან მოასხით ძირიანი ცხელი კარაქი","მიირთვით ცხლად — ხელს უწყობს რძის გამომუშავებას და ამცირებს კოლიკას"]'::jsonb) WHERE id = '56b6eb44-1b68-4703-8191-5abf175ce6b4';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'პრობიოტიკური პარფე'), description_ka = COALESCE(description_ka, 'ნაწლავების ჯანმრთელობისთვის (მეორე ტვინისთვის) კალციუმისა და პრობიოტიკების ნამდვილი წყარო.

სარგებელი: ნაწლავის ჯანსაღი მიკროფლორა ქალებში პირდაპირ უკავშირდება როგორც ძლიერ იმუნიტეტს, ისე ფსიქოლოგიურ კეთილდღეობას.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["გაწურული იოგურტი (ან ბერძნული იოგურტი): 1 ჭიქა","უშაქრო გრანოლა (ან მოხალული შვრიის/თხილეულის ნარევი): 3 სუფრის კოვზი","ახალი ხილი (კივი, ატამი ან მარწყვი): დაჭრილი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მაღალ ჭიქაში ფენებად მოათავსეთ ჯერ იოგურტის ნახევარი, შემდეგ ხილი და ბოლოს გრანოლა. ზედა ფენა კვლავ იოგურტით დაფარეთ და სულ ზემოდან ცოტაოდენი გრანოლა მოაყარეთ."]'::jsonb) WHERE id = '06ed0fa8-cbd9-44a6-9ddc-7e7b1fe1e84d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროს კრემი - ჰუმუსი'), description_ka = COALESCE(description_ka, 'ნიგვზის მუხუდოსა და ტაჰინის რძის გამომუშავების ხელშემწყობი ძალის უგემრიელესი კომბინაცია. მცენარეული ცილისა და კალციუმის ნამდვილი წყარო.'), category_ka = COALESCE(category_ka, 'სადილი'), ingredients_ka = COALESCE(ingredients_ka, '["მუხუდო: 1 ჭიქა (მოხარშული)","ტაჰინი (სეზამის პასტა): 2 სუფრის კოვზი","ლიმონის წვენი: 1 სუფრის კოვზი","ნიორი: 1 კბილი","ზეითუნის ზეთი: 2 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მუხუდო წინასწარ დაალბეთ და დარბილებამდე მოხარშეთ","ბლენდერში მოათავსეთ მუხუდო, ტაჰინი, ლიმონის წვენი და ნიორი","დააბლენდერეთ ერთგვაროვანი კრემის მიღებამდე","საჭიროების შემთხვევაში დაამატეთ ნახარში წყალი","ზემოდან მოასხით ზეითუნის ზეთი და პურთან ერთად მიირთვით"]'::jsonb) WHERE id = '9448c07e-1f48-40e0-a861-ab4dcd62db5b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოს ტოსტი კვერცხით (1 წლიდან)'), description_ka = COALESCE(description_ka, '1 წლის ბავშვების საყვარელი კერძი, რომლებსაც ხელით ჭამა მოსწონთ.

სარგებელი: ავოკადო ჯანსაღი ცხიმებითაა მდიდარი, კვერცხი კი შეუცვლელი ამინომჟავებით უზრუნველყოფს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მთლიანი ხორბლის პური: 1 ნაჭერი (კიდებმოჭრილი, დატოსტილი)","ავოკადო: მეოთხედი (კარგად დაჭყლეტილი)","კვერცხი: 1 ცალი (მაგრად მოხარშული და გახეხილი)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["დატოსტილ პურზე დაჭყლეტილი ავოკადო წაუსვით. ზემოდან გახეხილი კვერცხი მოაყარეთ. დაჭერაში რომ გაუადვილდეს, გრძელ ზოლებად დაჭერით."]'::jsonb) WHERE id = '3d1a500a-b203-4052-b1f2-91a4407a4e3c';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მაკარონი ისპანახით (4 წლიდან)'), description_ka = COALESCE(description_ka, 'ყველით მომზადებული, რკინით მდიდარი ჯადოსნური სოუსი, რომელიც ბავშვებს მწვანე ფერით იზიდავს.

სარგებელი: ისპანახი და ნიგოზი ხელს უწყობს ბავშვის ტვინის განვითარებას და ენერგიით უზრუნველყოფს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქატოს ან ფერადი უგლუტენო მაკარონი: 1 ჭიქა","ისპანახი: 1 დიდი მუჭა","ნიგვზის ლებანი: 2 ცალი","კრემ-ყველი ან ზეითუნის ზეთი: 1 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მაკარონი მოხარშეთ. ისპანახი, ნიგოზი და ყველი (ან ზეთი) ბლენდერში ათქვიფეთ, სანამ სრულიად ერთგვაროვან, კაშკაშა მწვანე კრემს არ მიიღებთ. ცხელი მაკარონი ამ სოუსში აურიეთ და სუფრასთან მიიტანეთ."]'::jsonb) WHERE id = 'c842f7bd-4741-487b-b42c-981f40c245be';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სუპერძალის ხორცის ბურთულები (2 წლიდან)'), description_ka = COALESCE(description_ka, 'ღუმელში გამომცხვარი, სიურპრიზით სავსე ხორცის ბურთულები, რომლებსაც ხორცის არმოყვარული ბავშვებიც კი სიამოვნებით შეჭამენ.

სარგებელი: ქათმის სუფთა ცილა და ბროკოლიში შემავალი რკინა ერთ კერძში. რადგან შემწვარი არ არის, კუჭს არ ამძიმებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის ფარში: 200 გრ","ბროკოლი: 3-4 ყვავილედი (ბლენდერში ძალიან წვრილად, ფხვნილის მსგავსად დაფქული)","ხახვი: ძალიან პატარა ნაჭერი (გახეხილი)","დაფქული ორცხობილა: 1 სუფრის კოვზი","ზეითუნის ზეთი და ცოტა მარილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ერთ ჯამში კარგად მოზილეთ.","გააკეთეთ ნიგოზზე ოდნავ პატარა ზომის ბურთულები, რომ ბავშვს ხელით დაჭერა და ჭამა გაუადვილდეს.","საცხობი ქაღალდით დაფარულ ლანგარზე, 180 გრადუსზე 20-25 წუთის განმავლობაში გამოაცხვეთ."]'::jsonb) WHERE id = 'ce232b23-613e-4e89-87ba-f0def071b9bc';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ციტრუსის არომატიანი თეთრი თევზი'), description_ka = COALESCE(description_ka, 'არომატული და ნაზი ზღვის დელიკატესი, რომელიც კუჭს ოდნავადაც არ ამძიმებს.

სარგებელი: თეთრი თევზი (ლავრაკი, სიფი) ადვილად მოსანელებელი სუფთა ცილისა და ფარისებრი ჯირკვლის ჯანმრთელობისთვის საჭირო იოდის წყაროა. ლიმონი კი რკინის ათვისებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["თეთრი თევზის ფილე: 150-200 qr","ლიმონი და ფორთოხალი: თითოეულის 2 ნაჭერი","ახალი ბეგქონდარა (თიმიანი) ან როზმარინი: 1-2 ტოტი","ზეითუნის ზეთი, მარილი, შავი პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["გასუფთავებული თევზი საცხობ ქაღალდზე მოათავსეთ. მოაყარეთ მარილი და პილპილი, შემდეგ ზეთი მოასხით. ზემოდან ციტრუსის ნაჭრები და მწვანილი დაალაგეთ. ქაღალდი შეკვრის მსგავსად გადაკეცეთ და 180 გრადუსზე 20 წუთის განმავლობაში გამოაცხვეთ. მიირთვით უხვ მწვანე სალათთან ერთად."]'::jsonb) WHERE id = '69335e75-4e74-4b38-bb31-495c4674ceb3';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტროპიკული ოაზისი'), description_ka = COALESCE(description_ka, 'ყველაზე სუფთა სასმელი, რომელიც ორგანიზმში წყლისა და ელექტროლიტების ბალანსს აღადგენს და შეშუპების შემცირებას უწყობს ხელს.

სარგებელი: ქოქოსის წყალი ბუნებრივი სპორტული სასმელია (მდიდარია კალიუმით). კიტრი კი კანისა და ორგანიზმის შიგნიდან გაწმენდას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), ingredients_ka = COALESCE(ingredients_ka, '["ქოქოსის წყალი (ნატურალური): 1 ჭიქა","კიტრი: თხელ ლენტებად დაჭრილი ნაჭრები","ახალი პიტნა და ლაიმის წვენი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი გრაფინში ან დიდ ჭიქაში მოათავსეთ და მაცივარში 30 წუთით გააჩერეთ, რათა გემოები ერთმანეთს შეერწყას. მიირთვით გრილად."]'::jsonb) WHERE id = '59177852-56ab-4ae0-9965-367e9142cf8e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოსა და ქათმის სალათი'), description_ka = COALESCE(description_ka, 'დაბალნახშირწყლოვანი კერძი, რომელიც დიდხანს გინარჩუნებთ დანაყრების შეგრძნებას და კუნთებს კვებავს.

სარგებელი: ნოყიერი ცილისა (ქათამი) და ჯანსაღი ცხიმების (ავოკადო) კომბინაცია ტკბილეულისადმი ძლიერი ლტოლვის თავიდან აცილებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ფილე: 150 qr (გრილზე ან ტაფაზე შემწვარი)","ავოკადო: ნახევარი (ნაჭრებად დაჭრილი)","ნორჩი ისპანახი ან სალათის ფოთლები: 2 მუჭა","ჩერი პომიდორი: 5-6 ცალი","ლიმონის წვენი, ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქათმის ხორცი გრძელ ნაჭრებად დაჭერით. მწვანილი, პომიდორი და ავოკადო დიდ თეფშზე დაალაგეთ, ზემოდან კი ქათმის ნაჭრები მოათავსეთ. გემო ლიმონისა და ზეთის სოუსით შეჰმატეთ."]'::jsonb) WHERE id = '0ad5770d-c00e-4aaf-a326-ab7ca620f797';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კენკრისა და ჩიას მაგია'), description_ka = COALESCE(description_ka, 'ანტიოქსიდანტებით მდიდარი, გამაგრილებელი წასახემსებელი, რომელიც კანს შიგნიდან ატენიანებს.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ჩიას თესლი: 3 სუფრის კოვზი","ნუშის რძე (ან ქოქოსის რძე): 1 ჭიქა","ახალი ჟოლო ან მოცვი: 1 მუჭა","თაფლი ან ნეკერჩხლის სიროფი: 1 ჩაის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["საღამოს ჩიას თესლი, რძე და თაფლი ჯამში კარგად აურიეთ (10 წუთის შემდეგ კვლავ მოურიეთ, რომ კოშტები არ წარმოიქმნას). მაცივარში დილამდე დატოვეთ. დილით ზემოდან ახალი კენკრა მოაწყვეთ და მიირთვით."]'::jsonb) WHERE id = '76ceddd0-3762-4c0e-938c-757205264083';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჭარხლისა და ყველის სალათი'), description_ka = COALESCE(description_ka, 'მსუბუქი სადილი, რომელიც ხელს უწყობს სისხლის მიმოქცევას და თვალს სასიამოვნო ფერით იზიდავს.

სარგებელი: ჭარხალი ღვიძლის გაწმენდის ხელშემწყობ ერთ-ერთ საუკეთესო ბოსტნეულად მიიჩნევა, თხის ან ხაჭოს ყველი კი ადვილად მოსანელებელი კალციუმის წყაროა.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ჭარხალი: 1 საშუალო ზომის (ღუმელში შემწვარი ან მოხარშული, კუბებად დაჭრილი)","თხის ყველი (ან ხაჭოს ყველი): 2 სუფრის კოვზი","ნიგოზი: 1 მუჭა","რუკოლას (Arugula) ფოთლები.","ბალზამიკური ძმარი და ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["რუკოლას ფოთლებს დაუმატეთ დაჭრილი ჭარხალი, ყველი და ნიგოზი. ზემოდან ბალზამიკური ძმრისა და ზეითუნის ზეთის ნარევი მოასხით."]'::jsonb) WHERE id = 'db6223cf-fd40-4b31-9334-3aa607532faa';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოს ტოსტი'), description_ka = COALESCE(description_ka, 'ჯანსაღი ცხიმებისა და ხარისხიანი ცილის უგემრიელესი კომბინაცია.

სარგებელი: ავოკადო შეიცავს ქალის ჰორმონებისთვის მნიშვნელოვან ჯანსაღ ცხიმებს, კვერცხი კი კუნთების შენარჩუნებისთვის საჭირო სუფთა ცილის წყაროა.'), category_ka = COALESCE(category_ka, 'საუზმე'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მთელი მარცვლის ხორბლის ან ჭვავის პური: 1-2 დიდი ნაჭერი","ავოკადო: ნახევარი (მწიფე)","კვერცხი: 1-2 ცალი (წყალში მოხარშული — პაშოტი ან მსუბუქად მოხარშული)","ლიმონის წვენი, მარილი, წითელი წიწაკის ფანტელები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["პური დაბრაწეთ. ავოკადო ჩანგლით დაჭყლიტეთ, ლიმონის წვენსა და მარილში აურიეთ და პურზე წაუსვით. ზემოდან მოხარშული კვერცხი მოათავსეთ და წითელი წიწაკის ფანტელები მოაყარეთ."]'::jsonb) WHERE id = 'be15d84a-f891-40e8-bcea-25a7ea3f5e77';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ისპანახის ბლინები (1 წლიდან)'), description_ka = COALESCE(description_ka, 'საუზმისთვის განსხვავებული ფერის, უშაქრო, რბილი და გემრიელი ღრუბლები.

სარგებელი: ისპანახისა და ბანანის შესანიშნავი შეხამება. მდიდარია რკინითა და კალიუმით.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ახალგაზრდა ისპანახი: 1 მუჭა","ბანანი: 1 ცალი (მწიფე)","კვერცხი: 1 ცალი","ფქვილი (მთლიანი ხორბლის ან შვრიის): 2 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ისპანახი, ბანანი და კვერცხი ბლენდერში ათქვიფეთ, სანამ სრულიად ერთგვაროვან მწვანე მასას არ მიიღებთ. დაუმატეთ ფქვილი და აურიეთ. უცხიმო ტაფაზე კოვზით ნაწილ-ნაწილ დაასხით და ორივე მხრიდან გამოაცხვეთ."]'::jsonb) WHERE id = 'e3b32abb-4f90-4796-9370-d8e31b9a5d8e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტკბილი კარტოფილის ნავები (4 წლიდან)'), description_ka = COALESCE(description_ka, 'გემის ფორმით მირთმეული ფერადი, ვიტამინებით სავსე ნავები.

სარგებელი: ტკბილ კარტოფილში შემავალი A ვიტამინი მხედველობის დაცვას უწყობს ხელს. სიმინდი და ბარდა კი კერძს სახალისო ტექსტურას სძენს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი (ბატატი): 2 ცალი (შუაზე გაჭრილი და ღუმელში გამომცხვარი)","მწვანე ბარდა და სიმინდი: თითოეული 1 სუფრის კოვზი (მოხარშული)","დაქუცმაცებული ქათმის ხორცი ან ფარში: 2 სუფრის კოვზი","ყველი (იალქნისთვის)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["გამომცხვარ კარტოფილს შიგთავსი ოდნავ ამოუღეთ და პიურედ აქციეთ, შეურიეთ ბარდა, სიმინდი და ხორცი, შემდეგ კი კვლავ კარტოფილში მოათავსეთ. ზემოდან კბილის ჩხირით დაამაგრეთ სამკუთხედად დაჭრილი ყველი (იალქანი)."]'::jsonb) WHERE id = 'd55a1489-0c64-4fd1-9c95-61ccad0e27bf';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კაკაო ფორთოხლით'), description_ka = COALESCE(description_ka, 'ფორთოხალში შემავალი C ვიტამინი კაკაოში არსებული რკინის ათვისებას უწყობს ხელს. კანს ბზინვარებას მატებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 სუფრის კოვზი კაკაო, 1 ჭიქა ნუშის რძე, 1 სუფრის კოვზი ახალგამოწურული ფორთოხლის წვენი (ან გახეხილი ფორთოხლის ცედრა), 1 ჩაის კოვზი ბექმეზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კაკაო თბილ ნუშის რძეში გახსენით, ცეცხლიდან გადმოდგმის შემდეგ კი ფორთოხლის წვენი და ბექმეზი დაუმატეთ."]'::jsonb) WHERE id = 'c4928087-d44e-49b9-b047-6872459c8c34';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყაბაყი ინდაურით'), description_ka = COALESCE(description_ka, 'ცომისა და პურის გარეშე მომზადებული, ცილით მდიდარი და მადისაღმძვრელი „ნავები“.

სარგებელი: შეიცავს ძალიან ცოტა ნახშირწყალს. ინდაურის ხორცში არსებული ამინომჟავა „ტრიპტოფანი“ ხელს უწყობს მელატონინის (ძილის ჰორმონის) გამოყოფას და ღრმა, მშვიდ ძილს.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყაბაყი: 2 საშუალო ზომის (სიგრძეზე გაჭრილი, გულამოღებული)","ინდაურის ფარში (ან უცხიმო საქონლის ხორცი): 150 qr","პომიდორი: 1 ცალი (გახეხილი)","მოცარელა ან ჰოლანდიური ყველი: 30 qr (გახეხილი)","ხახვი, ნიორი, ბეგქონდარა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ფარში ხახვთან, ნიორთან და პომიდორთან ერთად ტაფაზე ნახევრად მოამზადეთ. მიღებული მასით ყაბაყის ნავები შეავსეთ და 180 გრადუსზე გახურებულ ღუმელში ყაბაყის დარბილებამდე (დაახლოებით 25 წუთი) გამოაცხვეთ. გამოღებამდე 5 წუთით ადრე ზემოდან ყველი მოაყარეთ."]'::jsonb) WHERE id = 'f34874ad-c7fb-4bad-9d1d-814135cad038';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ორაგული და ბროკოლი
(9 თვე+)'), description_ka = COALESCE(description_ka, 'ტვინის უჯრედების ჩამოყალიბებისთვის საჭირო ომეგა-3 ცხიმოვანი მჟავებით მდიდარი პირველი ზღვის ნადიმი.

სარგებელი: ორაგული აუცილებელია ტვინისა და ნერვული სისტემის განვითარებისთვის. ბროკოლი კი ბავშვს კალციუმითა და C ვიტამინით ამარაგებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ორაგულის ფილე: 30 qr (ძვლების გარეშე)","ბროკოლი: 2-3 ყვავილედი","ზეითუნის ზეთი: რამდენიმე წვეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თევზი და ბროკოლი ორთქლზე (ან მცირე რაოდენობის წყალში) კარგად მოამზადეთ. თევზის ჩანგლით დაქუცმაცებისას კიდევ ერთხელ შეამოწმეთ, რომ მასში ძვალი არ იყოს დარჩენილი. ბროკოლთან ერთად დაჭყლიტეთ და ზეითუნის ზეთი მოასხით."]'::jsonb) WHERE id = 'd3ad67eb-6c19-4eee-9f9a-b784483c1a16';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბრინჯი ბოსტნეულით (4 წელი+)'), description_ka = COALESCE(description_ka, 'სადღესასწაულო განწყობის შემქმნელი, ფერადი ბოსტნეულით სავსე ბრინჯი.

სარგებელი: ნოყიერი სადილი, რომელშიც ნახშირწყლები, ვიტამინები და ბოჭკო ერთ ქვაბშია გაერთიანებული.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბასმატი ან გრძელმარცვლოვანი ბრინჯი: 1 ჭიქა","სტაფილო, მწვანე ბარდა, ტკბილი წითელი წიწაკა, სიმინდი: თითოეული 2 სუფრის კოვზი (წვრილ კუბებად დაჭრილი)","კარაქი და ქათმის ბულიონი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბოსტნეული მცირე რაოდენობის კარაქში ოდნავ მოშუშეთ. გარეცხილი ბრინჯი და ბულიონი დაამატეთ და სითხის შეწოვამდე, ბრინჯის მარცვლების განცალკევებამდე მოხარშეთ."]'::jsonb) WHERE id = 'f04550c5-0fdb-4ab9-8b7b-831a4d2f5e5a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყვავილოვანი კომბოსტოს სტეიკი ღუმელში'), description_ka = COALESCE(description_ka, 'ვეგანური და ჯანსაღი კვების სამყაროში ერთ-ერთი ყველაზე პოპულარული „ხორცის შემცვლელი“. გარეგნულად სტეიკს ჰგავს.

სარგებელი: ძალიან დაბალკალორიული და ბოჭკოთი მდიდარია. ღუმელში მომზადებისას კომბოსტოში არსებული ბუნებრივი შაქარი კარამელიზდება და შესანიშნავ გემოს ქმნის.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყვავილოვანი კომბოსტო: 1 მთლიანი თავი (ძალიან დიდი)","ზეითუნის ზეთი: 2 სუფრის კოვზი","ნივრის ფხვნილი, ტკბილი წითელი წიწაკის ფხვნილი (პაპრიკა), ზღვის მარილი, შავი პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყვავილოვანი კომბოსტო მთლიანად გარეცხეთ და შუა ნაწილიდან 2 სანტიმეტრის სისქის მთლიანი „სტეიკის“ ნაჭრები დაჭერით. საცხობ ლანგარზე დააწყვეთ და ორივე მხარეს ფუნჯით წაუსვით ზეითუნის ზეთისა და სანელებლების ნარევი. გამოაცხვეთ 200 გრადუსზე, სანამ ორივე მხარე არ დაიბრაწება (დაახლოებით 25-30 წუთი)."]'::jsonb) WHERE id = 'dbb5731f-3844-4a55-a0b0-63c083018f90';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კვერცხის ნავები (3 წლის ასაკიდან)'), description_ka = COALESCE(description_ka, 'სახალისო, „გემის“ ფორმის წასახემსებელი ბავშვებისთვის, რომლებსაც კვერცხის გული არ უყვართ.

სარგებელი: კვერცხის გულში შემავალი ქოლინი ერთ-ერთი უმნიშვნელოვანესი ნივთიერებაა 3 წლის ბავშვის სწრაფად განვითარებადი ტვინისა და მეხსიერებისთვის.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მაგრად მოხარშული კვერცხი: 2 ცალი","იოგურტი: 1 ჩაის კოვზი","ძალიან წვრილად დაჭრილი ფერადი ბულგარული წიწაკა („განძისთვის“)","ყველი: თხელი სამკუთხა ნაჭრები (იალქნისთვის) და კბილის ჩხირი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["კვერცხები სიგრძეზე შუაზე გაჭერით. გულები ამოიღეთ, იოგურტთან ერთად დასრისეთ, შეურიეთ ფერადი ბულგარული წიწაკის ნაჭრები („განძი“) და მიღებული მასა კვლავ ცილებში მოათავსეთ. ყველის სამკუთხა ნაჭერი კბილის ჩხირზე წამოაცვით და კვერცხში „იალქანივით“ ჩაარჭეთ (ჭამის წინ ჩხირის ამოღება არ დაგავიწყდეთ!)."]'::jsonb) WHERE id = '38175de9-042b-4fc9-8a58-cdff56307d6d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'შიგთავსიანი პორტობელოს სოკო'), description_ka = COALESCE(description_ka, 'შესანიშნავი „ქუდები“, რომლებიც წითელი ხორცის გარეშე გაძლევთ ხორცის ტექსტურასა და გემოს.

სარგებელი: პორტობელოს სოკო მდიდარია სელენით — მინერალით, რომელიც კანს ნაადრევი დაბერებისგან იცავს. ადვილად მოსანელებელია და კუჭს არ ტვირთავს.'), category_ka = COALESCE(category_ka, 'ვახშამი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["პორტობელოს სოკო: 2 დიდი ცალი (ფეხების გარეშე, შიგნიდან გასუფთავებული)","ისპანახი: 1 მუჭა (დაჭრილი)","ქინოა (ან ბულგური): 2 სუფრის კოვზი (მოხარშული)","ფეტა (ან თეთრი ყველი): 1 სუფრის კოვზი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["სოკოები ქინოას, ისპანახისა და ყველის ნარევით გაავსეთ. საცხობ ფორმაში მოათავსეთ და ზემოდან ცოტაოდენი ზეითუნის ზეთი მოასხით. გამოაცხვეთ 180 გრადუსზე, სანამ სოკოები არ დარბილდება."]'::jsonb) WHERE id = 'fef93b73-64a7-48d4-94bf-fe08f3ed1adc';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ლალის ორცხობილები'), description_ka = COALESCE(description_ka, 'ჩაისთვის განკუთვნილი უფქვილო, უგლუტენო „თითის ანაბეჭდის“ ორცხობილები ჯემით.

სარგებელი: ნუშის ფქვილი კანს E ვიტამინით კვებავს, სახლში მომზადებული ჩიას „ჯემი“ კი ომეგა-3-ის საჭიროების დაკმაყოფილებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ნუშის ფქვილი: 1.5 ჭიქა","თაფლი ან აგავის სიროფი: 3 სუფრის კოვზი","ქოქოსის ზეთი: 2 სუფრის კოვზი (გამდნარი)","ახალი ჟოლო და 1 სუფრის კოვზი ჩიას თესლი (ჯემისთვის)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჟოლო ჩანგლით დაჭყლიტეთ და ჩიას შეურიეთ (15 წუთით გააჩერეთ, რომ შესქელდეს). ნუშის ფქვილი, ზეთი და თაფლი მოზილეთ და პატარა ბურთულები გააკეთეთ. შუაში თითით ჩაღრმავება გაუკეთეთ და ღუმელში 160 გრადუსზე 10 წუთის განმავლობაში გამოაცხვეთ. შემდეგ გამოიღეთ და ჩაღრმავებები ჟოლოსა და ჩიას ჯემით შეავსეთ."]'::jsonb) WHERE id = '6b9ff319-0e3b-432c-ae21-5efca3c9d50d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ჭარხლისა და ვაშლის პიურე
(7 თვიდან)'), description_ka = COALESCE(description_ka, 'ტკბილი, იმუნიტეტის გამაძლიერებელი პიურე, რომელიც თქვენს ბავშვს ლოყებს აუწითლებს.

სარგებელი: ჭარხალი ანემიის წინააღმდეგ ერთ-ერთ ყველაზე ძლიერ ბუნებრივ საშუალებად მიიჩნევა. ვაშლი კი ჭარხლის მიწისებურ გემოს არბილებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ჭარხალი: 1 პატარა ცალი","ვაშლი: ნახევარი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჭარხალი კანიანად მოხარშეთ ან ღუმელში გამოაცხვეთ (ვიტამინების შესანარჩუნებლად). შემდეგ გაფცქვენით და ვაშლთან ერთად ბლენდერში ერთგვაროვან პიურედ აქციეთ. ყურადღება მიაქციეთ, რომ ბავშვს ტანსაცმელზე არ დაეღვაროს!"]'::jsonb) WHERE id = '55df2691-7b63-4f38-bfb6-d946010b6903';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მარილიანი ცისარტყელას კექსი(2 წლიდან)'), description_ka = COALESCE(description_ka, 'დესერტს ჰგავს, მაგრამ სინამდვილეში ბოსტნეულისა და ყველისგან მომზადებული მარილიანი კექსია.

სარგებელი: პრაქტიკული საშუალებაა, რომ პრეტენზიულ ბავშვს სხვადასხვა ბოსტნეული (ფერადი წიწაკა, მწვანილი) შეაყვაროთ. ასევე იდეალურია პარკში გასვლისას თან წასაღებად.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კვერცხი: 2 ცალი","მაწონი: 2 სუფრის კოვზი","ზეითუნის ზეთი: 1 სუფრის კოვზი","წითელი წიწაკა და ისპანახი: ძალიან წვრილად დაჭრილი (1-2 სუფრის კოვზი)","ყველი (გახეხილი): 2 სუფრის კოვზი","ფქვილი და გამაფხვიერებელი (სქელი კექსის ცომის მიღებამდე)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თხევადი ინგრედიენტები (კვერცხი, მაწონი, ზეთი) ათქვიფეთ. დაამატეთ ბოსტნეული და ყველი.","ბოლოს დაუმატეთ ფქვილი და გამაფხვიერებელი და აურიეთ.","მაფინის (კექსის) ფორმებში გადაანაწილეთ და 180 გრადუსზე 20 წუთის განმავლობაში, აფუებამდე და შეწითლებამდე გამოაცხვეთ."]'::jsonb) WHERE id = '03922c9b-57cd-4e60-9084-3b45e0d48642';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ავოკადოს ტოსტი ჩიას თესლით'), description_ka = COALESCE(description_ka, 'კლასიკური ავოკადოს ტოსტის უფრო ნოყიერი ვერსია, რომელიც მეტ ომეგა-3-ს შეიცავს და სასიამოვნოდ ხრაშუნაა.

სარგებელი: ჩიას თესლისა და ავოკადოს კომბინაცია სასარგებლო ცხიმების შესანიშნავი წყაროა, რომელიც კანის შიგნიდან დატენიანებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["შავი ან მთლიანი მარცვლეულის პური: 1 ნაჭერი (მოხალული)","ავოკადო: ნახევარი (მწიფე)","ჩიას თესლი: 1 ჩაის კოვზი","ლიმონის წვენი, ზღვის მარილი, წითელი წიწაკის ფანტელები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ავოკადო ჩანგლით დაჭყლიტეთ და ლიმონის წვენსა და მარილს შეურიეთ. მიღებული მასა უხვად წაუსვით მოხალულ პურს. ბოლოს, ხრაშუნა ტექსტურისა და დამატებითი სარგებლისთვის, მოაყარეთ ჩიას თესლი და წითელი წიწაკის ფანტელები."]'::jsonb) WHERE id = '87d23e0f-a0db-4aa1-b0fb-794cb2b35b28';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'Rose & Berry Spritz'), description_ka = COALESCE(description_ka, 'თხევადი კოლაგენისა და ანტიოქსიდანტების მხარდაჭერა თქვენი კანისთვის. ძალიან მსუბუქი და გამაგრილებელი.

სარგებელი: კენკრა ხელს უწყობს უჯრედების დაბერების პროცესის შენელებას, ვარდის წყალი კი კანს შიგნიდან ატენიანებს და ბუნებრივ "glow"-ს (ბზინვარებას) სძენს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ახალი ჟოლო ან მარწყვი: 1 მუჭა","ვარდის წყალი (სასმელი, დანამატების გარეშე): 1 სუფრის კოვზი","გაზიანი წყალი (მინერალური წყალი): 1 ჭიქა","ლაიმი: 1 ნაჭერი","ყინულის კუბები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჭიქის ძირში კენკრა ჩანგლით დაჭყლიტეთ. დაამატეთ ყინული, ვარდის წყალი და ლაიმის წვენი. ბოლოს ჩაასხით გაზიანი წყალი და აურიეთ"]'::jsonb) WHERE id = 'f84c1bc3-0bf2-4206-b695-21d5ec9708da';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'დესერტი კურკუმით'), description_ka = COALESCE(description_ka, 'იტალიური კლასიკა ანთების საწინააღმდეგო თვისებებით, რომელიც კანს ბზინვარებას მატებს.

სარგებელი: კურკუმა და ქოქოსის რძე ხელს უწყობს აკნესთან დაკავშირებული ანთების შემცირებას, ჟელატინი კი კოლაგენის ბუნებრივი წყაროა, რომელიც ფრჩხილებისა და თმის გაძლიერებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი დესერტები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქოქოსის რძე (ქილაში, სქელი): 1 ჭიქა","კურკუმის ფხვნილი: 1 ჩაის კოვზი","თაფლი: 2 სუფრის კოვზი","ჟელატინის ფირფიტა: 2 ცალი (ან 1 ჩაის კოვზი აგარ-აგარი)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჟელატინი ცივ წყალში დაალბეთ. რძე ქვაბში გააცხელეთ (არ აადუღოთ), დაამატეთ კურკუმა, თაფლი და დარბილებული ჟელატინი, შემდეგ კარგად აურიეთ. გადაანაწილეთ პატარა მინის ჭურჭლებში და მაცივარში 3-4 საათით გააჩერეთ."]'::jsonb) WHERE id = '792abbe5-dddc-4848-8d97-bdcb84318aee';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ვარდისფერი ფლამინგოს ბლინები(3 წლის+)'), description_ka = COALESCE(description_ka, 'საკვები საღებავის გარეშე მომზადებული საუზმე, რომელიც ბავშვებს თავისი ბუნებრივი ვარდისფერი შეფერილობით ხიბლავს.

სარგებელი: ჭარხალი აუმჯობესებს სისხლის მიმოქცევას და ხელს უწყობს იმუნიტეტის გაძლიერებას. შვრია კი ბავშვს დიდხანს ანაყრებს და ენერგიით უზრუნველყოფს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ჭარხლის პიურე: 1 სუფრის კოვზი (მოხარშული ჭარხლისგან)","კვერცხი: 1 ცალი","შვრიის ფქვილი: 3 სუფრის კოვზი","რძე: ნახევარი ჩაის ჭიქა","თაფლი: ძალიან ცოტა (სიტკბოსთვის)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი დააბლენდერეთ, სანამ სრულიად ერთგვაროვან ვარდისფერ ცომს არ მიიღებთ. უცხიმო ტაფაზე პატარა წრეების ფორმით ორივე მხრიდან გამოაცხვეთ."]'::jsonb) WHERE id = '3c637a80-dd91-4c2f-bf85-45f21dbc4610';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მეტეორიტის ენერგეტიკული ბურთულები(5 წლის+)'), description_ka = COALESCE(description_ka, 'საბავშვო ბაღში ან პარკში წასაღები, უშაქრო „შოკოლადის“ ენერგეტიკული წასახემსებელი.

სარგებელი: ფინიკი და კაკაო სწრაფად მატებს ენერგიას, ხოლო ნიგოზი/თხილი ომეგა-3 ცხიმებით კანსა და თმას კვებავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["რბილი ფინიკი: 8-10 ცალი (კურკის გარეშე)","შვრია: ნახევარი ჭიქა","კაკაო (უშაქრო): 1 სუფრის კოვზი","თხილი ან მზესუმზირის გული: 2 სუფრის კოვზი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი დააბლენდერეთ, სანამ წებოვან მასას არ მიიღებთ. ხელით პატარა „მეტეორიტები“ გააკეთეთ. სურვილისამებრ, შეგიძლიათ ქოქოსის ფანტელებიც მოაყაროთ. მაცივარში 30 წუთით გააჩერეთ და შემდეგ მიართვით."]'::jsonb) WHERE id = '13882a92-abb0-49d4-b8c0-e8f4f9c2ea1b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სელისა და ჩიას პუდინგი'), description_ka = COALESCE(description_ka, 'საჭმლის მომნელებელი სისტემისთვის სასარგებლო და ნოყიერი პუდინგი, რომლის მომზადებასაც 2 წუთი სჭირდება და რომელიც შეგიძლიათ საუზმეზე ან წასახემსებლად მიირთვათ.

სარგებელი: ჩიასა და სელის თესლი საკუთარ წონაზე რამდენჯერმე მეტ წყალს იწოვს და იბერება, კუჭში დანაყრების შეგრძნებას ქმნის და სისხლში შაქრის დონეს არეგულირებს.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ჩიას თესლი: 2 სუფრის კოვზი","სელის თესლი (დაფქული): 1 სუფრის კოვზი","ნუშის რძე (ან ქოქოსის რძე): 1 ჭიქა","ვანილის ბუნებრივი ექსტრაქტი და 1 ჩაის კოვზი თაფლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ქილაში კარგად აურიეთ. 10 წუთის შემდეგ, კოშტების წარმოქმნის თავიდან ასაცილებლად, კვლავ აურიეთ და მაცივარში შედგით (მინიმუმ 2 საათით ან მთელი ღამით). მორთეთ ხილით და მიირთვით."]'::jsonb) WHERE id = '9a57e53c-6cc6-4002-bebc-5ba8dd87a146';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მატჩასა და ფისტის ტრიუფელი'), description_ka = COALESCE(description_ka, 'მეტაბოლიზმის დამაჩქარებელი და კანის გამაახალგაზრდავებელი "premium" მისაყოლებელი ყავისთვის.

სარგებელი: მატჩას ჩაი ძლიერი ანტიოქსიდანტია, რომელიც უჯრედების განახლებას აჩქარებს. კეშიუ და ფისტა სასარგებლო ცხიმებით კანს ატენიანებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კეშიუ (უმი, დამბალი): 1 ჭიქა","ფინიკი: 5-6 ცალი","მატჩას ფხვნილი: 1 სუფრის კოვზი (და დამატებით ამოსავლებად)","ფისტა: ნახევარი ჭიქა (დაქუცმაცებული)"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი (ფისტის ნახევრის გარდა) ბლენდერში ათქვიფეთ, სანამ წებოვან ცომს არ მიიღებთ. ხელით გააკეთეთ ბურთულები, ნახევარი მატჩას ფხვნილში, ნახევარი კი დაქუცმაცებულ ფისტაში ამოავლეთ."]'::jsonb) WHERE id = 'ceb5db8c-58a7-4fde-a771-d2ed012eb9df';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მაროკოული ბოსტნეულის ტაჟინი'), description_ka = COALESCE(description_ka, 'ჩრდილოაფრიკული კერძი, რომელიც სპეციალურ ჭურჭელში ნელა მზადდება და ბოსტნეულისა და ხილის ტკბილ-მარილიან ჰარმონიას აერთიანებს.

სარგებელი: მუხუდო და ბოსტნეული ორგანიზმს სისხლში შაქრის დონის მარეგულირებელი რთული ნახშირწყლებით ამარაგებს. კერძს შაქრის დამატების გარეშე, ჩირით ენიჭება ბუნებრივი სიტკბო.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მუხუდო (მოხარშული): 1 ჭიქა","სტაფილო, ყაბაყი, ტკბილი კარტოფილი (მსხვილად დაჭრილი).","გარგარის ჩირი ან ქიშმიში: ნახევარი ჭიქა","დარიჩინი, ძირა (კუმინი), ჯანჯაფილის ფხვნილი, ზეითუნის ზეთი, ბოსტნეულის ბულიონი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ღრმა ქვაბში (ან ტრადიციულ ტაჟინის ჭურჭელში) სანელებლები ზეთში გააცხელეთ. დაამატეთ ბოსტნეული, მუხუდო და ჩირი. დაასხით ბულიონი, დაახურეთ თავსახური და დაბალ ცეცხლზე ბოსტნეულის სრულ დარბილებამდე (40-45 წუთი) მოამზადეთ. მიირთვით ქინოასთან ან კუსკუსთან ერთად."]'::jsonb) WHERE id = '71967587-de0b-4a79-8b91-69af7cbe3013';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სმუზის თასი (4 წლის ასაკიდან)'), description_ka = COALESCE(description_ka, 'სახალისო დესერტი, რომელიც ბავშვს თხევადი სახით ბოსტნეულსა და ხილს შეაყვარებს და კოვზით მიირთმევა.

სარგებელი: იმუნიტეტის გამაძლიერებელი ვიტამინების ნამდვილი ბომბია. იდეალურია ბავშვის შუადღის წასახემსებლად.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ისპანახი: 1 მუჭა","გაყინული ბანანი: 1 ცალი","კივი: 1 ცალი","იოგურტი ან რძე: ნახევარი ჭიქა","გასაფორმებლად: კივის ნაჭრებისგან გამოჭრილი დინოზავრის \"ეკლები\" ან ძვლები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ისპანახი, ბანანი, კივი და რძე ბლენდერში სქელი კრემის მიღებამდე ათქვიფეთ. ჩაასხით თასში და ზემოდან კივის ნაჭრებით ისე გააფორმეთ, რომ დინოზავრის ზურგს დაემსგავსოს."]'::jsonb) WHERE id = '989c089a-7705-4f4f-aa06-64d202a23310';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტოსკანის მზე'), description_ka = COALESCE(description_ka, 'ცნობილი იტალიური კერძის, „Melanzane alla Parmigiana“-ს მსუბუქი, ჯანსაღი და ზეთში შეუწვავი ვერსია.

სარგებელი: ბადრიჯანი ანტიოქსიდანტების წყაროა. ტრადიციულად ზეთში შეწვის ნაცვლად ღუმელში მომზადების გამო კერძი გაცილებით დაბალკალორიულია, თუმცა იტალიურ ყველში შემავალი ცილა მას ნოყიერს ხდის.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბადრიჯანი: 2 დიდი ცალი (სიგრძეზე დაჭრილი)","ნატურალური ტომატის (პომიდვრის) პასტა: 2 ჭიქა (შეზავებული ნიორითა და ბაზილიკით)","მოცარელა და პარმეზანი: გახეხილი","ახალი ბაზილიკი (რეჰანი), ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბადრიჯნის ნაჭრებს ფუნჯით ზეითუნის ზეთი წაუსვით და ღუმელში დარბილებამდე (15 წუთი) გამოაცხვეთ. ღრმა საცხობ ფორმაში ლაზანიას მსგავსად ფენებად მოათავსეთ: პომიდვრის სოუსი, ბადრიჯანი, ყველი და ბაზილიკი. ზედა ფენაზე ყველი მოაყარეთ და 190 გრადუსზე 20 წუთის განმავლობაში, შეწითლებამდე გამოაცხვეთ."]'::jsonb) WHERE id = '9e271ac6-efc7-4123-9cc8-b60e93936503';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'იოგურტის ფილა ბროწეულით'), description_ka = COALESCE(description_ka, 'თვალისმომჭრელი ალტერნატივა ნაყინისთვის — გრილი და ამავდროულად ხრაშუნა.

სარგებელი: ბროწეულის მარცვლები მდიდარია ფიტოესტროგენებით, რომლებიც ქალებში ესტროგენის ბალანსის შენარჩუნებას უწყობს ხელს, და ანტიოქსიდანტებით. იოგურტი კი პრობიოტიკია.'), category_ka = COALESCE(category_ka, 'ჯანსაღი დესერტები'), ingredients_ka = COALESCE(ingredients_ka, '["იოგურტი (ბერძნული ან გაწურული): 1.5 ჭიქა","თაფლი: 1 სუფრის კოვზი","ბროწეულის მარცვლები: ნახევარი ჭიქა","ფისტა: 2 სუფრის კოვზი (დაქუცმაცებული)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["იოგურტი თაფლს შეურიეთ და საცხობი ქაღალდით დაფარულ ბრტყელ ჭურჭელში 0.5 სმ სისქეზე გადაანაწილეთ. ზემოდან ბროწეულის მარცვლები და ფისტა მოაყარეთ, შემდეგ საყინულეში 3 საათით მოათავსეთ. გაყინვის შემდეგ ხელით შოკოლადის ფილასავით დაამტვრიეთ."]'::jsonb) WHERE id = '80d2e83c-c415-4e59-854e-3c904d65b0ff';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქათმისა და ქინოას ცილოვანი თასი
(9 თვე+)'), description_ka = COALESCE(description_ka, 'ხანგრძლივი ენერგიის წყარო უფრო აქტიური და მცოცავი ბავშვებისთვის.

სარგებელი: ქათამი სუფთა ცილის წყაროა, ქინოა კი მარცვლეულთა შორის ერთ-ერთი ყველაზე მაღალი კვებითი ღირებულების მქონე, გლუტენისგან თავისუფალი სუპერპროდუქტია.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_საკვები']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ხორცი: 30 გრ","ყაბაყი: ნახევარზე ნაკლები","ქინოა: 1 სუფრის კოვზი (წინასწარ დამბალი და გარეცხილი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ქათამი მოხარშეთ (პირველი ნახარში გადაღვარეთ). მეორე წყალში ქინოა და დაჭრილი ყაბაყი დაამატეთ და ყველაფერი სრულ დარბილებამდე ხარშეთ. შემდეგ დააბლენდერეთ ან ჩანგლით ისე დასრისეთ, რომ მცირე ნაჭრები დარჩეს."]'::jsonb) WHERE id = '45628e71-5b41-431f-b26f-8283c2b308a2';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ხრაშუნა თევზის ჩხირები (2 წლიდან)'), description_ka = COALESCE(description_ka, 'მაღაზიაში გაყიდული გაყინული თევზის ჩხირების შეუწვავი, 100% ნატურალური ვერსია.

სარგებელი: თევზი ბავშვს აწვდის ომეგა-3 ცხიმოვან მჟავებს, რომლებიც აუცილებელია ტვინისა და მხედველობის განვითარებისთვის.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["თეთრი თევზის ფილე (მაგალითად, ლავრაკი — ძვლის გარეშე): 100 qr (მოგრძო ნაჭრებად დაჭრილი)","კვერცხი: 1 ცალი (ათქვეფილი)","შვრიის ფქვილი (ამოსავლებად)","ზეითუნის ზეთი, ცოტაოდენი მარილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თევზის ნაჭრები ჯერ კვერცხში, შემდეგ კი შვრიის ფქვილში ამოავლეთ.","დაალაგეთ საცხობ ქაღალდდაფენილ ლანგარზე და ზემოდან ფუნჯით ძალიან ცოტა ზეითუნის ზეთი გადაუსვით.","გამოაცხვეთ 190 გრადუსზე 15 წუთის განმავლობაში, სანამ ხრაშუნა არ გახდება."]'::jsonb) WHERE id = 'cf74a166-77b4-4cd9-978f-5f84fbaf4d6d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სუპერმენის კესადილია (5 წლიდან)'), description_ka = COALESCE(description_ka, 'ბოსტნეულით სავსე მექსიკური კერძი, რომლის ხელით ჭამაც ბავშვებს ძალიან უყვართ.

სარგებელი: შავი ლობიო და ქათამი ცილის კარგი წყაროა, ყველი კი მდიდარია ძვლების გასამაგრებელი კალციუმით.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მთლიანი ხორბლის ფქვილის ლავაში (ტორტილია): 1 ცალი","ჰოლანდიური ყველი (გახეხილი): 2 სუფრის კოვზი","შავი ლობიო (მოხარშული) და სიმინდი: 1 სუფრის კოვზი","დაძენძილი ქათმის ხორცი: 1 სუფრის კოვზი","ისპანახი (ძალიან წვრილად დაჭრილი): რამდენიმე ფოთოლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ლავაშის ერთ ნახევარზე გაანაწილეთ ყველი, ქათამი, ლობიო, სიმინდი და ისპანახი. მეორე ნახევარი ზემოდან გადააფარეთ (ნახევარმთვარის ფორმით). ცხელ ტაფაზე ორივე მხრიდან შეწვით, სანამ ყველი არ გადნება და ლავაში ხრაშუნა არ გახდება. დაჭერით სამკუთხედებად და მიირთვით."]'::jsonb) WHERE id = '495abf5b-aca7-4840-8cc2-c8a7f267da78';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბატატისა და ოსპის კარი'), description_ka = COALESCE(description_ka, 'ანთების საწინააღმდეგო სანელებლებით მდიდარი, ვეგანური და გლუტენის გარეშე მომზადებული ინდური სამზარეულოს კლასიკა.

სარგებელი: კარი და კურკუმა აძლიერებს იმუნიტეტს, ბატატი კი კერძს ბუნებრივ, აბრეშუმივით ნაზ სიტკბოს მატებს.'), category_ka = COALESCE(category_ka, 'general'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ბატატი (ტკბილი კარტოფილი): 1 დიდი ცალი (კუბებად დაჭრილი)","წითელი ოსპი: 1 ჭიქა","ქოქოსის რძე (ქილაში მოთავსებული, სქელი): 1 ჭიქა","კარის ფხვნილი: 1 სუფრის კოვზი","ისპანახი: 1 მუჭა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხახვი, ნიორი და კარის ფხვნილი ზეთში მოშუშეთ. დაამატეთ ბატატი, ოსპი, ქოქოსის რძე და 2 ჭიქა წყალი. დაბალ ცეცხლზე ხარშეთ, სანამ ბოსტნეული ბოლომდე არ მომზადდება. ცეცხლიდან გადმოდგმისას დაუმატეთ ისპანახი და მოურიეთ."]'::jsonb) WHERE id = '405b0576-a236-4ed8-8698-3423fb1d2ff0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბოსტნეულის გუფთები (1 წლიდან)'), description_ka = COALESCE(description_ka, 'რბილი გუფთები, რომლებშიც ბოსტნეულია „დამალული“ — იმ ბავშვებისთვის, რომლებიც ბოსტნეულის ჭამაზე უარს ამბობენ.

სარგებელი: წითელი ხორცი რკინის საჭიროების დაკმაყოფილებას უწყობს ხელს, დამალული ბოსტნეული კი უჯრედისითა და ვიტამინებით ამდიდრებს. იდეალურია, რომ ბავშვმა ხელით დაიჭიროს და დამოუკიდებლად მიირთვას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["საქონლის უცხიმო ფარში: 150 გ","ყაბაყი და სტაფილო: თითოეულის მეოთხედი (ძალიან წვრილად გახეხილი და გაწურული)","ხახვი: ძალიან პატარა ნაჭერი (გახეხილი)","ზეითუნის ზეთი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი კარგად მოზილეთ. გააკეთეთ ნიგვზის ზომის პატარა გუფთები. საცხობ ქაღალდდაფენილ ღუმელის ლანგარზე 180 გრადუსზე 20-25 წუთის განმავლობაში გამოაცხვეთ ისე, რომ არ გამოშრეს."]'::jsonb) WHERE id = '2369413b-697e-4e19-93a2-ff9c61cde8f7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბოსტნეულის ფრი (5 წლიდან)'), description_ka = COALESCE(description_ka, 'ღუმელში გამომცხვარი ფერადი და ხრაშუნა ბოსტნეულის ჩხირები — მავნე კარტოფილი ფრის ჯანსაღი ალტერნატივა.

სარგებელი: სტაფილო და ტკბილი კარტოფილი მდიდარია A ვიტამინითა და ბეტა-კაროტინით, რომლებიც თვალებისა და კანის ჯანმრთელობას იცავს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი, სტაფილო, ყაბაყი: თითოეულის ნახევარი","ზეითუნის ზეთი: 1 სუფრის კოვზი","ხმელი პიტნა ან ქონდარი, ცოტაოდენი მარილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბოსტნეული თანაბარი ზომის მოგრძო ჩხირებად („ჯადოსნურ ჯოხებად“) დაჭერით. ზეთსა და სანელებლებში აურიეთ და ღუმელის ლანგარზე ერთმანეთის გვერდიგვერდ დააწყვეთ. გამოაცხვეთ 200 გრადუსზე 20-25 წუთის განმავლობაში, სანამ კიდეები არ შეიბრაწება."]'::jsonb) WHERE id = 'a67b3fb0-1d8c-4568-bbb8-eea9c5b74c3a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროს მატჩას ელექსირი'), description_ka = COALESCE(description_ka, 'ანთების საწინააღმდეგო კურკუმისა და ენერგიის მომცემი მატჩას შესანიშნავი დუეტი.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ჩაის კოვზი მატჩა, ნახევარი ჩაის კოვზი კურკუმა, ერთი მწიკვი შავი პილპილი, 1 ჭიქა თბილი ნუშის რძე, 1 ჩაის კოვზი თაფლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თბილ რძეს ყველა ინგრედიენტი დაუმატეთ, კარგად აურიეთ და ააქაფეთ."]'::jsonb) WHERE id = '244e5027-cbdf-4e83-8b58-62158b64f304';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყვავილოვანი კომბოსტო ბუფალოს სტილში'), description_ka = COALESCE(description_ka, 'ამერიკული ცნობილი კერძის, „Buffalo Wings“-ის (ქათმის ფრთების), 100%-ით ვეგეტარიანული და ჯანსაღი ალტერნატივა.

სარგებელი: სრულად აკმაყოფილებს ხრაშუნა სწრაფი კვების სურვილს, თუმცა ქათმის ნაცვლად ბოჭკოებით მდიდარი ყვავილოვანი კომბოსტო გამოიყენება, შეწვის ნაცვლად კი — ღუმელი.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყვავილოვანი კომბოსტო: 1 თავი (ყვავილედებად დაყოფილი)","მთლიანი ხორბლის ფქვილი და წყალი: ცომის მოსამზადებლად (ბლინების ცომის სისქის)","ცხარე Buffalo-ს სოუსი (ან ნებისმიერი ცხარე სოუსისა და კარაქის ნარევი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყვავილოვანი კომბოსტოს ყვავილედები ამოავლეთ ფქვილისა და წყლის ნარევში და საცხობ ლანგარზე დაალაგეთ. გამოაცხვეთ 200 გრადუსზე 20 წუთის განმავლობაში. გამოიღეთ, ზემოდან ცხარე სოუსი მოასხით და კვლავ შედგით ღუმელში 10 წუთით, სანამ კიდეები ხრაშუნა არ გახდება."]'::jsonb) WHERE id = '287fe4e5-acde-487e-8549-304293001ae7';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ანდალუსიური ნიავი — ესპანური გასპაჩო'), description_ka = COALESCE(description_ka, 'ესპანეთის სამხრეთიდან წარმოშობილი, მომზადების გარეშე გაკეთებული გრილი, უმი და ვიტამინებით სავსე პომიდვრის წვნიანი.

სარგებელი: ეს არის სუფთა „ყვავილებისა და ბოსტნეულის“ დეტოქსი. ლიკოპენისა (პომიდორი) და C ვიტამინის (წიწაკა) წყალობით კანს შიგნიდან იცავს მზის მავნე სხივებისგან.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ძალიან მწიფე წითელი პომიდორი: 4-5 ცალი","კიტრი: 1 ცალი (გაგრილებული)","მწვანე ბულგარული წიწაკა: ნახევარი","წითელი ხახვი და ნიორი (ძალიან ცოტა)","ექსტრა ვირჯინ ზეითუნის ზეთი (2 სუფრის კოვზი) და ვაშლის ძმარი (1 სუფრის კოვზი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ბლენდერში მოათავსეთ, დაუმატეთ ზეითუნის ზეთი, ძმარი და ცოტაოდენი მარილი, შემდეგ კი სრულად თხევადი (წვნიანის) კონსისტენციის მიღებამდე დააბლენდერეთ. მაცივარში სულ მცირე 2 საათით გააჩერეთ, სანამ ძალიან კარგად არ გაცივდება."]'::jsonb) WHERE id = '0732d705-b1b2-4b26-b8dc-748f80e0f06a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'Gold Mac & Cheese (2 წლის+)'), description_ka = COALESCE(description_ka, 'ბავშვების საყვარელი ყველიანი მაკარონის ძალიან ჯანსაღი ვერსია, რომელშიც ბოსტნეულია დამალული.

სარგებელი: კლასიკური ფქვილიანი და ცხიმიანი სოუსის ნაცვლად, სოუსის საფუძველს გოგრა და სტაფილო წარმოადგენს. A ვიტამინისა და კალციუმის მდიდარი წყაროა.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მთლიანი ხორბლის მაკარონი (რქის ან სპირალის ფორმის): 1 ჭიქა","გოგრა და სტაფილო (მოხარშული): თითოეული ნახევარი ჭიქა","რძე: ნახევარი ჭიქა","ჩედარი (Cheddar) ან ჰოლანდიური ყველი: 3 სუფრის კოვზი, გახეხილი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მაკარონი წყალში სრულ მომზადებამდე მოხარშეთ და გადაწურეთ.","მოხარშული გოგრა, სტაფილო და რძე ბლენდერში მოათავსეთ და სრულად ერთგვაროვანი, ნარინჯისფერი კრემის (სოუსის) მიღებამდე დააბლენდერეთ.","სოუსი ცხელ ტაფაზე დაასხით, დაუმატეთ გახეხილი ყველი და გაადნეთ. ბოლოს მაკარონი სოუსს შეურიეთ."]'::jsonb) WHERE id = '6a513f71-83a0-47b7-94eb-0de33be5ff6d';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ვარსკვლავებიანი ღამის სუპი (3 წლის ზემოთ)'), description_ka = COALESCE(description_ka, 'ძვლის ბულიონზე მომზადებული გემრიელი სუპი, რომელშიც ვარსკვლავები დაცურავენ — ბავშვებისთვის, რომლებსაც სუპის ჭამა არ უყვართ.

სარგებელი: ძვლის ბულიონი მდიდარია კოლაგენითა და კალციუმით, ხელს უწყობს ბავშვების ზრდასა და მათი ძვლების გამაგრებას.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["სუფთა ძვლის ან ქათმის ბულიონი: 2 ჭიქა","ვარსკვლავის ფორმის საბავშვო მაკარონი: 2 სუფრის კოვზი","სტაფილო: ნახევარი (დაჭრილი ძალიან პატარა ვარსკვლავების ფორმით)","ოხრახუში: ძალიან ცოტა (მოსართავად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ბულიონი აადუღეთ, დაამატეთ ვარსკვლავის ფორმის მაკარონი და სტაფილო. ხარშეთ, სანამ მაკარონი ბოლომდე არ დარბილდება (დაახლოებით 8-10 წუთი)."]'::jsonb) WHERE id = '60680ede-d11d-4b46-a277-695525f7d111';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მატჩასა და მარწყვის ღრუბელი'), description_ka = COALESCE(description_ka, 'სოციალურ ქსელებში ყველაზე ტრენდული სასმელი. კანის მკვებავი ანტიოქსიდანტების ნამდვილი ბომბი.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["1 ჩაის კოვზი მატჩას ფხვნილი (გახსნილი თბილ წყალში), 4-5 ცალი ახალი მარწყვი (დაჭყლეტილი პიურეს სახით), 1 ჭიქა ნუშის რძე, ყინული."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჭიქის ძირში მოათავსეთ მარწყვის პიურე, ზემოდან დაამატეთ ყინული და რძე. ბოლოს ნელა ჩაასხით გახსნილი მწვანე მატჩა, რათა ფერები ფენებად დარჩეს (ქვემოთ ვარდისფერი, ზემოთ კი მწვანე)."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ნუშის ფანქეიქები და ჩიას ჯემი'), description_ka = COALESCE(description_ka, 'ჩვეულებრივი ფქვილით მომზადებული ფანქეიქების უგლუტენო, უშაქრო, „ჯანსაღი ცხოვრების“ ალტერნატივა.

სარგებელი: ნუშის ფქვილი სისხლში შაქრის დონეს მკვეთრად არ ზრდის (დაბალი გლიკემიური ინდექსი). ჩიას ჯემი კი სამრეწველო მურაბებში არსებული შაქრისგან გათავისუფლებთ.'), category_ka = COALESCE(category_ka, 'general'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ნუშის ფქვილი: 1 ჭიქა","კვერცხი: 2 ცალი","ნუშის რძე: მეოთხედი ჭიქა","ჯემისთვის: 1 ჭიქა გაყინული ჟოლო და 2 სუფრის კოვზი ჩიას თესლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჟოლო გააცხელეთ და დაჭყლიტეთ, შეურიეთ ჩიას თესლი და დატოვეთ გასაგრილებლად (შესასქელებლად). ცალკე ათქვიფეთ ნუშის ფქვილი, კვერცხი და რძე, შემდეგ ტაფაზე პატარა ფანქეიქები გამოაცხვეთ. ზემოდან მოასხით თქვენ მიერ მომზადებული უშაქრო ჩიას ჯემი."]'::jsonb) WHERE id = '0d809ddc-e476-418c-9f34-67e7b608cf9f';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'პერუული სევიჩე'), description_ka = COALESCE(description_ka, 'ლათინური ამერიკის გამაგრილებელი და ცილებით მდიდარი კერძი, რომელშიც თევზი ცეცხლის გარეშე, მხოლოდ ციტრუსის მჟავით „იხარშება“.

სარგებელი: დამატებული ცხიმი — ნულოვანი, სუფთა ცილა — მაქსიმალური. ეს დიეტაზე მყოფთა ერთ-ერთი საყვარელი კერძია.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["თეთრი თევზის ფილე (ძალიან ახალი და უფხო): 200 qr (პატარა კუბებად დაჭრილი)","ლაიმის წვენი: ნახევარი ჭიქა (ახლად გამოწურული)","წითელი ხახვი: ნახევარი (თხელ ნახევარრგოლებად დაჭრილი)","ახალი ქინძი, ცხარე ხალაპენიოს წიწაკა (სურვილისამებრ), მარილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["უმი თევზის კუბები მინის ჭურჭელში მოათავსეთ, დაასხით ლაიმის წვენი და მოაყარეთ ცოტაოდენი მარილი. წვენი თევზს ფერს გაუღიავებს და „მოხარშავს“. მაცივარში 20-30 წუთით გააჩერეთ. სუფრასთან მიტანამდე ცოტა ხნით ადრე დაუმატეთ ხახვი და ქინძი და აურიეთ."]'::jsonb) WHERE id = '53cbba9d-f39f-4a00-950a-386243d164bd';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სკანდინავიური Smørrebrød'), description_ka = COALESCE(description_ka, 'დანიასა და ნორვეგიაში წარმოშობილი ღია სენდვიჩის ხელოვნება მუქი ჭვავის პურის ნაჭერზე.

სარგებელი: ჭვავის პური რთული ნახშირწყლების წყაროა (სისხლში შაქრის დონეს მკვეთრად არ ზრდის). ორაგული კი ომეგა-3-ის ნამდვილი საბადოა, რომელსაც სკანდინავიელთა დღეგრძელობის საიდუმლოდ მიიჩნევენ.'), category_ka = COALESCE(category_ka, 'ზოგადი'), ingredients_ka = COALESCE(ingredients_ka, '["მუქი, მარცვლოვანი ჭვავის პური: 1 დიდი ნაჭერი","კრემ-ყველი (ლაბნე): 1 სუფრის კოვზი","შებოლილი ან დამარილებული ორაგული (სალმონი): 2-3 ნაჭერი","წითელი ხახვის რგოლები, ახალი კამა, ბოლოკის ნაჭრები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["პურს კრემ-ყველი წაუსვით. თევზის ნაჭრები ტალღისებურად დაალაგეთ. ზემოდან ხახვის რგოლებით, თხლად დაჭრილი ბოლოკითა და უხვი კამით გააფორმეთ და ლამაზად მიიტანეთ სუფრასთან."]'::jsonb) WHERE id = 'dded217d-3179-4368-8e13-255ed13ea4cf';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ქინოას ტაბულე (ლიბანური სამზარეულო)'), description_ka = COALESCE(description_ka, 'ახლო აღმოსავლეთის ცნობილი სალათი, რომელშიც ტრადიციული ბულგური უგლუტენო და უფრო მეტი ცილის შემცველი ქინოათი არის ჩანაცვლებული.

სარგებელი: მსუბუქია, მდიდარია ბოჭკოებითა და C ვიტამინით (ოხრახუშის უხვი შემცველობის წყალობით). ხელს უწყობს სისხლში შაქრის დონის რეგულირებას.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქინოა (მოხარშული და გაგრილებული): 1 ჭიქა","ახალი ოხრახუში (ძალიან წვრილად დაჭრილი): 2 დიდი კონა","ახალი პიტნა: 1 პატარა კონა","პომიდორი: 2 ცალი (პატარა კუბებად დაჭრილი)","მწვანე ხახვი: 3-4 ღერი","ექსტრა ვირჯინ ზეითუნის ზეთი, უხვი ლიმონის წვენი და მარილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ღრმა ჯამში ყველა დაჭრილი მწვანილი და ბოსტნეული მოხარშულ ქინოას შეურიეთ. უხვად მოასხით ზეითუნის ზეთი და ლიმონის წვენი, შემდეგ კარგად აურიეთ. მაცივარში მინიმუმ 30 წუთით გააჩერეთ."]'::jsonb) WHERE id = '23f9812f-031f-4161-95cf-ce2d96da0985';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ინდური ოსპის პიურე'), description_ka = COALESCE(description_ka, 'ვეგეტარიანელების საყვარელი ოქროსფერი ინდური რაგუ, რომელიც სანელებლების ძალით ორგანიზმს შიგნიდან ათბობს.

სარგებელი: კურკუმასა და ჯანჯაფილს ანთების საწინააღმდეგო თვისებები აქვს. ოსპი კი მცენარეული ცილის წყალობით დიდხანს გინარჩუნებთ დანაყრების შეგრძნებას.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["წითელი ან ყვითელი ოსპი: 1 ჭიქა","ხახვი, ნიორი, ახალი ჯანჯაფილი.","კურკუმა და კარის ფხვნილი: თითოეული 1 ჩაის კოვზი.","პომიდორი: 1 ცალი","ქოქოსის რძე: ძალიან ცოტა (ზემოდან მოსასხმელად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხახვი, ნიორი, ჯანჯაფილი და სანელებლები ზეთში სურნელის გამოყოფამდე მოშუშეთ. დაუმატეთ დაჭრილი პომიდორი და ოსპი. ჩაასხით წყალი და ხარშეთ, სანამ ოსპი მთლიანად არ დარბილდება და პიურესმაგვარ მასად (რაგუდ) არ იქცევა. ზემოდან მოასხით ქოქოსის რძე და მოაყარეთ ქინძი."]'::jsonb) WHERE id = 'f1edbb7c-89ad-49b8-9c59-42461d445810';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'გერმანული კარტოფილის სალათი'), description_ka = COALESCE(description_ka, 'შესანიშნავი მსუბუქი გერმანული სალათი მდოგვითა და ძმრით, რომელიც მძიმე, მაიონეზიან სალათებს მარტივად ჩაანაცვლებს.

სარგებელი: გაცივებულ კარტოფილში წარმოიქმნება პრებიოტიკური თვისებების მქონე „რეზისტენტული სახამებელი“, რომელიც ნაწლავებისთვის სასარგებლოა. რადგან სალათი მაიონეზს არ შეიცავს, ის ნაკლებად ცხიმიანია.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["კარტოფილი: 3-4 ცალი (მოხარშული, გაცივებული, ნაჭრებად დაჭრილი)","წითელი ხახვი: 1 პატარა თავი (წვრილად დაჭრილი)","ახალი ოხრახუში ან კამა","სოუსისთვის: 1 სუფრის კოვზი მარცვლოვანი მდოგვი, 2 სუფრის კოვზი ვაშლის ძმარი, 3 სუფრის კოვზი ზეითუნის ზეთი, მარილი, შავი პილპილი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["თბილ ან მთლიანად გაცივებულ კარტოფილის ნაჭრებს ხახვი და მწვანილი დაუმატეთ. მდოგვი, ძმარი და ზეთი ქილაში შეანჯღრიეთ, მიღებული სოუსი სალათს მოასხით და აურიეთ."]'::jsonb) WHERE id = 'bfa226ee-4fae-4a95-b348-aee056cab96b';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'შრეკის Mac & Cheese (3 წლის+)'), description_ka = COALESCE(description_ka, 'ყველიანი მაკარონი, რომელიც ლამაზი მწვანე ფერით იქცევს ყურადღებას და მასში ისპანახია დამალული.

სარგებელი: 3 წლის ბავშვების უმეტესობა უმი ან მომზადებული ისპანახის ჭამაზე უარს ამბობს. ამ სოუსის წყალობით ისინი შეუმჩნევლად მიიღებენ რკინით მდიდარ საკვებს.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["მაკარონი: 1 ჭიქა","ისპანახი: 1 დიდი მუჭა","რძე: ნახევარი ჭიქა","მოცარელა ან გაუდა: 2 სუფრის კოვზი (გახეხილი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["მაკარონი მოხარშეთ და გადაწურეთ. ისპანახი და რძე ბლენდერში ათქვიფეთ, სანამ სრულიად მწვანე, ერთგვაროვან სითხეს არ მიიღებთ. ეს მწვანე რძე ცხელ ტაფაზე დაასხით, ყველი დაუმატეთ და გაადნეთ. ბოლოს მაკარონი ჩაყარეთ და კარგად აურიეთ."]'::jsonb) WHERE id = '82a7ccbd-e708-435c-afe7-61fd5589966e';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროსფერი ოსპისა და ჯანჯაფილის სუპი'), description_ka = COALESCE(description_ka, 'ზამთრის სადილი, რომელიც ნივთიერებათა ცვლას ააქტიურებს და ორგანიზმს შიგნიდან ათბობს.

სარგებელი: ჯანჯაფილი და კურკუმა ორგანიზმში ანთებას (შეშუპებას, აკნეს, სახსრების ტკივილს) ამცირებს, წითელი ოსპი კი დიდხანს უზრუნველყოფს დანაყრების შეგრძნებას.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["წითელი ოსპი: 1 ჭიქა","ახალი ჯანჯაფილი: თხილის ზომის (გახეხილი)","კურკუმა: ნახევარი ჩაის კოვზი","სტაფილო, ხახვი.","ქოქოსის რძე: 2 სუფრის კოვზი (სურვილისამებრ, მოსართავად)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ბოსტნეული და ოსპი წყალში დარბილებამდე მოხარშეთ და ბლენდერით დააბლენდერეთ. დაამატეთ კურკუმა და ჯანჯაფილი და კიდევ ცოტა ხანს ადუღეთ. ჯამში გადაღების შემდეგ ზემოდან ქოქოსის რძე მოასხით."]'::jsonb) WHERE id = '9dca9acb-e3bc-495a-9af1-62c75bc63dca';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ტკბილი კარტოფილი და ლობიო'), description_ka = COALESCE(description_ka, 'რეცეპტი, რომელიც PMS-ის (მენსტრუაციის წინა) პერიოდში ტკბილეულისადმი ლტოლვისა და განწყობის ცვლილებების დარეგულირებაში დაგეხმარებათ.

სარგებელი: ტკბილი კარტოფილი და შავი ლობიო მდიდარია მაგნიუმით, ამშვიდებს ნერვულ სისტემას, ამცირებს სპაზმებს და დიდხანს უზრუნველყოფს დანაყრების შეგრძნებას.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ტკბილი კარტოფილი (ბატატი): 1 ცალი (შუაზე გაჭრილი და ღუმელში სრულად გამომცხვარი)","შავი ლობიო (ან წითელი): 2 სუფრის კოვზი (მოხარშული)","სიმინდი: 1 სუფრის კოვზი","ავოკადოს პიურე (გუაკამოლე) და ლაიმის წვენი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["გამომცხვარი და შიგნიდან დარბილებული ტკბილი კარტოფილის შუაგულში შავი ლობიო და სიმინდი მოათავსეთ. ზემოდან ავოკადოს პიურე დაადეთ და ლაიმის წვენი მოასხით."]'::jsonb) WHERE id = '0298f702-76b2-4fe4-995b-506dab64f0f1';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'პატარა დათვის პიურე (1 წლის+)'), description_ka = COALESCE(description_ka, 'წვნიანი, პირში დნობადი ზამთრის კერძი ბავშვებისთვის, რომლებსაც ხორცის ღეჭვა უჭირთ.

სარგებელი: დიდხანს მომზადებული ხორცი ადვილად მოსანელებელია, მისი ბულიონი კი სასარგებლოა ძვლების განვითარებისთვის.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['ბავშვის_კვება']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["საქონლის ხორცი: 50 გრ (ძალიან პატარა, ბარდის მარცვლის ზომის კუბებად დაჭრილი)","სტაფილო და კარტოფილი: ნახევარი ცალი (კუბებად დაჭრილი)","პომიდორი: მეოთხედი (გახეხილი)","ზეითუნის ზეთი და წყალი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ხორცი ზეითუნის ზეთში ფერის შეცვლამდე მოშუშეთ, შემდეგ პომიდორი და წყალი დაამატეთ და დარბილებამდე მოამზადეთ (უმჯობესია წნევის ქვაბში). შემდეგ სტაფილო და კარტოფილი დაუმატეთ და ხარშეთ, სანამ ბოსტნეულიც იმდენად არ დარბილდება, რომ ადვილად დაისრისოს."]'::jsonb) WHERE id = 'a7eb16f8-9a88-4ac0-92d3-fb7d3da355e0';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ოქროსფერი ბზინვარების ტონიკი'), description_ka = COALESCE(description_ka, 'დილის ტონიკი, რომელიც ორგანიზმში ანთებას ამცირებს და დაავადებებისგან დამცავ ფარად გვევლინება.

სარგებელი: კურკუმა ძლიერი ბუნებრივი ანთების საწინააღმდეგო საშუალებაა. ის ამცირებს კანის სიწითლესა და სახსრების ტკივილს და კანს ბუნებრივ ბზინვარებას უბრუნებს.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["თბილი წყალი: 1 ჭიქა","კურკუმის ფხვნილი: ნახევარი ჩაის კოვზი","შავი პილპილი: ერთი მწიკვი (აუცილებელია კურკუმის სისხლში შესაწოვად)","ლიმონის წვენი და 1 ჩაის კოვზი ნატურალური ვაშლის ძმარი"]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი კარგად აურიეთ და დილით, თბილ მდგომარეობაში (ისე, რომ ყელი და კუჭი არ დაგწვათ), ნელ-ნელა, ყლუპებით დალიეთ."]'::jsonb) WHERE id = '55d6317c-4bcb-4a93-943a-dda17af68226';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ფერადი შამფურები (5 წლის+)'), description_ka = COALESCE(description_ka, 'შამფურები, რომლებზეც ბოსტნეული და ხორცი ერთად, ფერადი თამაშის სახითაა წარმოდგენილი.

სარგებელი: ეს ყველაზე პრაქტიკული გზაა, რომ ბავშვებმა ცილებიცა და ვიტამინებიც ერთდროულად, სახალისო ფორმით მიიღონ.'), category_ka = COALESCE(category_ka, 'დამატებითი კვება'), tags_ka = COALESCE(tags_ka, ARRAY['baby_food']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ქათმის მკერდის ხორცი: 100 qr (შემწვარი ან მოხარშული, კუბებად დაჭრილი)","ფერადი ბულგარული წიწაკა (წითელი, ყვითელი), ჩერი პომიდორი და კიტრი (მსხვილად დაჭრილი).","ბლაგვწვერიანი ხის ჩხირები (შამფურები)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ჩხირებზე თანმიმდევრობით ააცვით: ჩერი პომიდორი, ქათმის კუბი, ყვითელი წიწაკა, კიტრი და კვლავ ქათამი. ყურადღება მიაქციეთ, რომ ფერები ცისარტყელასავით იყოს განლაგებული."]'::jsonb) WHERE id = 'd945cba8-c55e-4693-91cb-3385f3ce8b99';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ყაბაყის სპაგეტი პესტოს სოუსით'), description_ka = COALESCE(description_ka, 'საოცარი პასტა, რომელიც ცომეულის მირთმევის სიამოვნებას განიჭებთ, თუმცა წონაში მატებას არ იწვევს.

სარგებელი: ძალიან დაბალკალორიულია. პესტოს სოუსში შემავალი ზეითუნის ზეთი და რეჰანი ძლიერი ანტიოქსიდანტებია და უჯრედების ახალგაზრდობის შენარჩუნებას უწყობს ხელს.'), category_ka = COALESCE(category_ka, 'სადილი'), tags_ka = COALESCE(tags_ka, ARRAY['general']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ყაბაყი: 2 საშუალო ზომის (სპეციალური ხელსაწყოთი სპაგეტის ფორმად დაჭრილი)","პესტოს სოუსი: 2 სუფრის კოვზი (ახალი რეჰანის, ზეითუნის ზეთის, ნიგვზისა და დაჭყლეტილი ნივრის ნარევი)","ჩერი პომიდორი: 4-5 ცალი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყაბაყის სპაგეტი ტაფაზე, მცირე რაოდენობის ზეითუნის ზეთში, მხოლოდ 2-3 წუთის განმავლობაში მსუბუქად მოშუშეთ (ზედმეტად არ მოამზადოთ, ხრაშუნა უნდა დარჩეს). გადმოდგით ცეცხლიდან და შეურიეთ პესტოს სოუსი და შუაზე გაჭრილი პომიდორი."]'::jsonb) WHERE id = '4562e352-5778-4e1f-951e-cc27bf63469a';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'ბროკოლისა და საქონლის ხორცის სოტე'), description_ka = COALESCE(description_ka, 'პოპულარული აზიური (ჩინური) სამზარეულოს ერთ-ერთი ყველაზე ჯანსაღი კლასიკური კერძი, რომელიც მთელ მსოფლიოში უყვართ.

სარგებელი: ქმნის რკინის (ხორციდან) და კალციუმის/C ვიტამინის (ბროკოლიდან) შესანიშნავ ბალანსს. სწრაფად მზადდება.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["საქონლის ხორცი (სუკი, ძალიან თხლად დაჭრილი): 250 qr","ბროკოლი: 1 მთლიანი თავი (ყვავილედებად დაყოფილი)","სოიოს სოუსი (ნაკლებმარილიანი): 3 სუფრის კოვზი","ახალი ჯანჯაფილი და ნიორი (დაჭყლეტილი).","სეზამის ზეთი და სეზამის მარცვლები."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ტაფაზე (ვოკში) ხორცი მაღალ ცეცხლზე სწრაფად მოშუშეთ და ცალკე გადადეთ. იმავე ტაფაში მოათავსეთ ბროკოლი, ნიორი და ჯანჯაფილი და 3-4 წუთის განმავლობაში მოშუშეთ (ბროკოლი ხრაშუნა უნდა დარჩეს). ხორცი კვლავ ტაფაში ჩააბრუნეთ, დაამატეთ სოიოს სოუსი, 1 წუთის განმავლობაში ურიეთ, შემდეგ მოაყარეთ სეზამი და გადმოდგით ცეცხლიდან."]'::jsonb) WHERE id = 'cdafe114-fffe-4d67-b795-0770d33715ea';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'სელისა და ნუშის ფქვილის კრეკერი'), description_ka = COALESCE(description_ka, 'მაღაზიაში გაყიდული არაჯანსაღი ჩიფსების შემცვლელი, 100% გლუტენისა და ნახშირწყლების გარეშე მომზადებული სახლის კრეკერები (კეტო).

სარგებელი: ნუშის ფქვილი მდიდარია E ვიტამინით, სელის თესლი კი შესანიშნავად არეგულირებს ნაწლავების მუშაობას.'), category_ka = COALESCE(category_ka, 'ზოგადი'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["ნუშის ფქვილი: 1 ჭიქა","სელის თესლი (დაფქული): 3 სუფრის კოვზი","წყალი: 3 სუფრის კოვზი","ზეითუნის ზეთი: 1 სუფრის კოვზი","მარილი და ხმელი ბეგქონდარა."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი ერთ ჯამში მოზილეთ, რომ ცომი მიიღოთ. ცომი საცხობი ქაღალდის ორ ფურცელს შორის მოათავსეთ და გასაბრტყელებლით ძალიან თხლად (ჩიფსივით) გააბრტყელეთ. დანით კვადრატებად დაჭერით და 170 გრადუსზე გახურებულ ღუმელში 15-20 წუთის განმავლობაში, ხრაშუნა ტექსტურის მიღებამდე გამოაცხვეთ."]'::jsonb) WHERE id = 'd73926c7-3c66-41bd-88a6-1a28c3a2f959';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'კაკაოსა და მაკას მაგია'), description_ka = COALESCE(description_ka, 'თბილი და გემრიელი სასმელი, რომელიც ქალის ჰორმონების დაბალანსებასა და ბედნიერების ჰორმონის დონის ამაღლებას უწყობს ხელს.

სარგებელი: პერუული წარმოშობის "Maca"-ს (მაკას) ფესვის ფხვნილი ქალებში ჰორმონების რეგულირებას უწყობს ხელს (PMS-ისა და მენოპაუზის პერიოდში), ზრდის ენერგიასა და ლიბიდოს. კაკაო კი მაგნიუმის წყაროა.'), category_ka = COALESCE(category_ka, 'ჯანსაღი სასმელები'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["უშაქრო, სუფთა კაკაოს ფხვნილი: 1 სუფრის კოვზი","Maca-ს (მაკას) ფხვნილი: 1 ჩაის კოვზი","ნუშის ან თხილის რძე: 1 ჭიქა","დარიჩინი და თაფლი."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["ყველა ინგრედიენტი პატარა ქვაბში გააცხელეთ და კარგად ათქვიფეთ (აქაფებამდე). მიირთვით ცხელი შოკოლადივით, ნაშუადღევის სასიამოვნო განწყობისთვის."]'::jsonb) WHERE id = '9af7ce60-d92c-4cdf-bbaf-e2276dc4e407';
UPDATE public.admin_recipes SET title_ka = COALESCE(title_ka, 'მუხუდოს ბლონდი'), description_ka = COALESCE(description_ka, 'კარამელის გემოს მქონე, ფქვილის გარეშე მომზადებული კექსი, რომელშიც მუხუდოს არსებობას ვერავინ დაიჯერებს.

სარგებელი: ეს ტკბილეული სუფთა ცილისა და რთული ნახშირწყლების წყაროა. არ იწვევს გლუტენით გამოწვეულ შებერილობას და საღამოს ვარჯიშის შემდეგ (კუნთების აღსადგენად) შესანიშნავად უხდება ჩაის.'), category_ka = COALESCE(category_ka, 'ჯანსაღი ტკბილეული'), tags_ka = COALESCE(tags_ka, ARRAY['ზოგადი']::text[]), ingredients_ka = COALESCE(ingredients_ka, '["დაკონსერვებული მუხუდო: 1 ჭიქა (კარგად გარეცხილი და კანგაცლილი)","არაქისის კარაქი: 3 სუფრის კოვზი","თაფლი ან ნეკერჩხლის სიროფი: 3 სუფრის კოვზი","ვანილი, გამაფხვიერებელი.","შოკოლადის წვეთები (შავი)."]'::jsonb), instructions_ka = COALESCE(instructions_ka, '["შოკოლადის გარდა, ყველა ინგრედიენტი ბლენდერში სრულად ერთგვაროვანი მასის (ცომის) მიღებამდე დააბლენდერეთ. შეურიეთ შოკოლადის წვეთები და პატარა კვადრატულ კექსის ფორმაში ჩაასხით. გამოაცხვეთ 175 გრადუსზე 20 წუთის განმავლობაში. დაჭერით, სანამ ჯერ კიდევ თბილია."]'::jsonb) WHERE id = '4b5bc08b-15b1-4187-aa19-05b7b3bb4ae4';

