UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'თანმიმდევრობების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვს ესმის მოქმედებების თანმიმდევრობა და შეუძლია რამდენიმე ეტაპისგან შემდგარი დავალებების შესრულება'), symptoms_ka = COALESCE(symptoms_ka, '["იმედგაცრუება","მომთხოვნელობა","მოუთმენლობა","მშობელზე მიჯაჭვულობა"]'), tips_ka = COALESCE(tips_ka, '["თანმიმდევრული მოქმედებების შემცველი თამაშები","სათამაშოების ერთმანეთზე დაწყობა","ამბების მოყოლის რუტინა"]') WHERE id = '00332eb5-3642-4caa-aa0d-06c76e8858be';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'პროგრამების სამყარო'), description_ka = COALESCE(description_ka, 'პატარა ბავშვი იწყებს რთული მოქმედებების დაგეგმვასა და შესრულებას'), symptoms_ka = COALESCE(symptoms_ka, '["თავნებობა","ძალაუფლებისთვის ბრძოლა","დამოუკიდებლობისკენ სწრაფვა"]'), tips_ka = COALESCE(tips_ka, '["შესთავაზეთ არჩევანი განსაზღვრულ საზღვრებში","მიეცით დამოუკიდებლობის უსაფრთხოდ გამოვლენის საშუალება","შეაქეთ მისი ძალისხმევა"]') WHERE id = '368b778d-29bd-4c6e-a693-d14f3dbde8cb';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'პრინციპების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვს უვითარდება მორალური ღირებულებებისა და პრინციპების გაგება'), symptoms_ka = COALESCE(symptoms_ka, '["დაუმორჩილებლობა","საზღვრების გამოცდა","ემოციური აფეთქებები"]'), tips_ka = COALESCE(tips_ka, '["დააწესეთ თანმიმდევრული წესები","აუხსენით მიზეზი","მიეცით ქცევის კარგი მაგალითი"]') WHERE id = '68ec3d1f-0c2d-487a-b2b6-226b82a023c8';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'სისტემების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვს ესმის სისტემები და ის, თუ როგორ მოქმედებს სხვადასხვა რამ ურთიერთკავშირში'), symptoms_ka = COALESCE(symptoms_ka, '["ყველაფერზე კითხვების დასმა","სირთულით გამოწვეული იმედგაცრუება"]'), tips_ka = COALESCE(tips_ka, '["მოთმინებით უპასუხეთ კითხვებს","ერთად გამოიკვლიეთ","ერთად ააწყვეთ სხვადასხვა რამ"]') WHERE id = '6957aa52-d7bb-49bc-96d0-6c055983318b';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'ცვალებადი შეგრძნებების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვი სამყაროს განსხვავებულად აღქმას იწყებს და მისი შეგრძნებები უფრო მძაფრი ხდება'), symptoms_ka = COALESCE(symptoms_ka, '["უფრო ხშირი ტირილი","მშობელთან მუდმივად ყოფნის სურვილი","ცუდი ძილი","მადის დაკარგვა"]'), tips_ka = COALESCE(tips_ka, '["უფრო ხშირად ჩაეხუტეთ","კანით კანთან კონტაქტი","გამოიჩინეთ მოთმინება"]') WHERE id = '91076f7e-3fa0-4b65-b6c3-202f437732a4';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'კანონზომიერებების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვი კანონზომიერებებს აღმოაჩენს და სახეებისა და საგნების ამოცნობას იწყებს'), symptoms_ka = COALESCE(symptoms_ka, '["ჭირვეულობა","უფრო ხშირად ფხიზლად ყოფნა","მეტი ყურადღების საჭიროება","უფრო ხშირად შიმშილი"]'), tips_ka = COALESCE(tips_ka, '["შავ-თეთრი სათამაშოები","პირისპირ ურთიერთობა","მშვიდი გარემო"]') WHERE id = '6f91418c-7c6d-4189-804a-e00a07db94db';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'მდორე გადასვლების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვი თანმიმდევრულ მოძრაობებსა და ერთი მოქმედებიდან მეორეზე მდორედ გადასვლას სწავლობს'), symptoms_ka = COALESCE(symptoms_ka, '["უფრო ხშირი ტირილი","ძილის პრობლემები","მუდმივად ხელში ყოფნის სურვილი"]'), tips_ka = COALESCE(tips_ka, '["მოძრაობითი აქტივობები","ნაზი რწევა","მასაჟი"]') WHERE id = 'f8fc8a04-d9e6-4b79-b565-8cbc1c9ccb94';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'მოვლენების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვი მიზეზ-შედეგობრივ კავშირებსა და მოვლენათა თანმიმდევრობას აცნობიერებს'), symptoms_ka = COALESCE(symptoms_ka, '["მშობელთან მუდმივად ყოფნის ძლიერი სურვილი","განწყობის ცვალებადობა","ცუდი მადა","ღამით გაღვიძება"]'), tips_ka = COALESCE(tips_ka, '["„ჭიტას“ თამაში","სტაბილური დღის რეჟიმი","გამოიჩინეთ მეტი მოთმინება"]') WHERE id = '4f00fc01-ffca-4cb6-a186-c3cae46fe443';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'ურთიერთკავშირების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვი საგნებს შორის მანძილსა და ურთიერთკავშირებს აცნობიერებს'), symptoms_ka = COALESCE(symptoms_ka, '["განშორების შფოთვა","კოშმარები","უცხო ადამიანებთან მორცხვობა"]'), tips_ka = COALESCE(tips_ka, '["დარჩით ახლოს","დამამშვიდებელი საყვარელი ნივთები","თანდათანობითი განშორება"]') WHERE id = '5c97a8c2-5724-4bd6-97dd-fe1b7f05c200';
UPDATE public.baby_crisis_periods SET title_ka = COALESCE(title_ka, 'კატეგორიების სამყარო'), description_ka = COALESCE(description_ka, 'ბავშვი საგნების, ადამიანებისა და ემოციების კატეგორიებად დაყოფას იწყებს'), symptoms_ka = COALESCE(symptoms_ka, '["ისტერიკის შეტევები","მესაკუთრეობის ძლიერი განცდა","საზღვრების გამოცდა"]'), tips_ka = COALESCE(tips_ka, '["საგნების დასახელება","დახარისხების თამაშები","მკაფიო საზღვრები"]') WHERE id = 'f13911eb-137a-4fe7-be01-bccf1325e4e6';

-- ── baby_daily_info → ka (1457 sətir) ──
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ხანგრძლივი ორსულობის შემდეგ, როგორც იქნა, თქვენს პატარას შეხვდით. Anacan-ის ოჯახი თქვენ გვერდით იქნება თქვენს პატარასთან ერთად გატარებულ ყოველ ბედნიერ დღეს! 😊 ალბათ უკვე შეამჩნიეთ, რომ დაბადების მომენტიდან ბავშვი დღის თითქმის მთელ ნაწილს ძილში ატარებს. ამან შესაძლოა დროდადრო შეგაშფოთოთ კიდეც. უნდა იცოდეთ, რომ ძილი ახალშობილი ბავშვის ჯანმრთელობისთვის, ზრდისა და განვითარებისთვის შეუცვლელი საჭიროებაა. კვებისა და საფენის გამოცვლის გარდა, ბავშვი თითქმის მთელ დროს ძილს უთმობს. ძილის დროს ორგანიზმში გამოყოფილი ჰორმონი მელატონინი ხელს უწყობს ბავშვის იმუნური სისტემის გაძლიერებას და ჰიპოფიზის მიერ ზრდის ჰორმონის მეტი რაოდენობით გამოყოფას. თუმცა, ბავშვის ზრდასთან ერთად, ძილის ხანგრძლივობა შემცირდება. ამიტომ სასურველია, ეს დღეები შეძლებისდაგვარად დასვენებისთვის გამოიყენოთ.') WHERE id = '31cd50a4-c6f5-4862-b0ff-2fa89b11b67b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდეგ ბავშვის კანზე ალბათ შენიშნეთ კრემისებრი, თეთრი და ცხიმოვანი ფენა. ეს ფენა, რომელსაც ვერნიქს კაზეოზა ეწოდება, თხელი დამცავი ნივთიერებაა, რომლის 80%-ს წყალი შეადგენს და რომელიც დიდი რაოდენობით ლიპიდებსა და ცილებს შეიცავს. კანის ზედაპირზე ამ ცხიმოვანი ფენის განაწილება შესაძლოა განსხვავდებოდეს იმის მიხედვით, ორსულობის რომელ კვირაში და რა გზით მოხდა მშობიარობა. ჩვეულებრივ, გვიან დაბადებული ბავშვების კანში ამ ფენის ნაწილი უკვე შეწოვილია. 37 კვირამდე დაბადებული ბავშვების კანზე კი ეს ფენა უფრო სქლად გვხვდება. ვერნიქსი შეიცავს მიკრობების განადგურების უნარის მქონე დამცავ უჯრედებსა და დაახლოებით 40 სხვადასხვა ცილას, რომლებიც ბავშვის ორგანიზმის ბუნებრივ იმუნიტეტს აძლიერებს. ამიტომ ბავშვი დაბადებიდან სულ მცირე 24 საათის განმავლობაში არ უნდა დაბანოთ და უნდა დაელოდოთ, სანამ კანი ამ ფენას კარგად შეიწოვს.') WHERE id = '01b8c794-e427-40d5-a912-edbb2df87798';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს დაბადების მომენტიდანვე ძლიერი რეფლექსები აქვს. მათგან ყველაზე მნიშვნელოვანი, რა თქმა უნდა, წოვის რეფლექსია, რომელიც მის კვებას უზრუნველყოფს. როდესაც ბავშვს ლოყებზე ან პირის კუთხეებთან შეეხებით, ის მაშინვე შეხების მიმართულებით ბრუნდება და საკვების წყაროს ძებნას იწყებს. წოვის რეფლექსი მექანიკური მოქმედებაა, რომლის მეშვეობითაც ბავშვი კვებით და ემოციურ საჭიროებებს იკმაყოფილებს. ეს რეფლექსი ჯერ კიდევ მუცლად ყოფნისას, განვითარების მე-14 კვირიდან იწყებს ჩამოყალიბებას. პირის ღრუსა და სასის ჩამოყალიბების შემდეგ ის ხორციელდება ლოყების კუნთოვანი სტრუქტურის დახმარებით, რომელიც ვაკუუმს ქმნის. ორსულობის საკმაოდ ადრეულ ეტაპზე წარმოქმნილი ეს რეფლექსი ბავშვს საშუალებას აძლევს, ჯერ კიდევ თქვენს მუცელში ყოფნისას ივარჯიშოს. ამის წყალობით, ბავშვს დაბადების პირველივე წუთებიდან აქვს კვებისთვის საჭირო გამოცდილება და უნარი.') WHERE id = '4db7f0d9-f7be-435d-a305-5bea20ce135c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადების შემდეგ ბავშვი ინსტინქტურად გამოგარჩევთ მრავალი ადამიანისგან. მიიჩნევა, რომ ამ ინსტინქტის ჩამოყალიბებას თქვენი სუნი და ხმა უწყობს ხელს. ბავშვთან შეხვედრის ამ პირველ დღეებში ხშირად უნდა სცადოთ მისი ძუძუთი კვება, საუბრისას თვალით კონტაქტი დაამყაროთ და ნაზად შეეხოთ. ბავშვთან ყოველი შეხება თქვენს ორგანიზმში ჰორმონ ოქსიტოცინის გამოყოფას ასტიმულირებს. ოქსიტოცინი იწვევს იმ კუნთოვანი უჯრედების შეკუმშვას, რომლებიც რძეს სარძევე ჯირკვლის სადინრებიდან ძუძუსთავისკენ გადაადგილებს. ბავშვის კვებისთვის აუცილებელი კიდევ ერთი ჰორმონია პროლაქტინი, რომელსაც თავის ტვინში მდებარე ჰიპოფიზი გამოყოფს. ეს ორი ჰორმონი შეთანხმებულად მოქმედებს და ბავშვის წოვის საპასუხოდ უზრუნველყოფს როგორც რძის წარმოქმნას, ისე მის ძუძუსთავისკენ გადაადგილებას.') WHERE id = 'a25dea37-57a2-46fc-889c-23e73ad36d76';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადებისთანავე ექიმი ბავშვის ჯანმრთელობას ამოწმებს. ამასთანავე, დაბადებიდან რამდენიმე წუთში ექიმი ბავშვს ფეხში უკეთებს მის პირველ აცრას — ჰეპატიტი B-ის საწინააღმდეგო ვაქცინას. თუ თქვენ ჰეპატიტი B-ის მატარებელი ხართ, ვაქცინასთან ერთად ბავშვს იმუნოგლობულინიც უკეთდება. ამის გარდა, პირველი 1 თვის განმავლობაში ბავშვს ჰეპატიტი B-ის საწინააღმდეგო ვაქცინის გარდა სხვა აცრა არ უტარდება. საავადმყოფოდან გაწერამდე ბავშვს პედიატრი ჯანმრთელობის სრულყოფილ გამოკვლევას უტარებს. ასევე, საავადმყოფოს მიერ დანიშნული ექთანი აგიხსნით, როგორ მოუაროთ ბავშვს პირველ დღეებში და რას უნდა მიაქციოთ ყურადღება. მიღებული ინფორმაცია ძალიან მნიშვნელოვან მინიშნებებს მოგცემთ იმის შესახებ, თუ როგორ იზრუნოთ თქვენს ბავშვზე.') WHERE id = '0d9fa9e8-940a-4ec4-b501-2f30433e0030';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის სიგრძე და წონა მის ზოგად ჯანმრთელობაზე გვაწვდის ინფორმაციას. თავის გარშემოწერილობის გაზომვა კი ძალიან მნიშვნელოვანია ტვინის განვითარების შესაფასებლად. პირველი გაზომვისას ბავშვის თავის გარშემოწერილობა, ჩვეულებრივ, 32 sm-დან 37 sm-მდეა. ეს მაჩვენებლები ტვინის ჯანსაღ განვითარებაზე მიუთითებს. ვინაიდან თავის გარშემოწერილობის ზრდა ტვინის განვითარების მაჩვენებელია, მას ყურადღება უნდა მიაქციოთ. აუცილებელია ბავშვის სიგრძის, წონისა და თავის ზომების რეგულარულად კონტროლი. ამიტომ უნდა იპოვოთ კარგი პედიატრი და მასთან ერთად შეადგინოთ შემოწმებების გრაფიკი. განვითარების მონიტორინგისთვის რეკომენდებულია, დაბადებიდან საშუალოდ მე-5, მე-14 და მე-30 დღეებში ბავშვი ექიმთან გეგმურ შემოწმებაზე მიიყვანოთ.') WHERE id = '8c627179-a029-49ba-9226-4fa26ffce0a7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სარძევე ჯირკვლებში გამომუშავებული დედის რძე ყველაზე ძვირფასი რამაა, რაც შეგიძლიათ თქვენს ბავშვს მისცეთ. თქვენი რძე შეიცავს ორი სახის ცილას, ცხიმებს, ნახშირწყლებს, სხვადასხვა ვიტამინსა და ანტისხეულებს, რომლებიც ბავშვს ვირუსებთან და ბაქტერიებთან ბრძოლაში ეხმარება. რძეში შემავალი ცხიმები აუცილებელია ბავშვის ტვინის განვითარებისთვის, ენერგიით უზრუნველსაყოფად და ცხიმში ხსნადი ვიტამინების შეწოვისა და ათვისებისთვის. ყველა ამ თვისების წყალობით, დედის რძე საუკეთესო საკვებია, რომელსაც პირველი 6 თვის განმავლობაში სხვა საკვების დამატების გარეშე შეუძლია ბავშვისთვის საჭირო ყველა საკვები ნივთიერების მიწოდება. ხელოვნური საკვები, რომელსაც რძის ფორმულასაც უწოდებენ, ერთადერთი ალტერნატივაა ბავშვის გამოსაკვებად იმ შემთხვევებში, როდესაც დედის რძე საკმარისი არ არის. ამ ნარევების უმეტესობის ძირითადი ინგრედიენტი ძროხის რძეა და ისინი ბუნებრივ რძეში ზოგიერთი ნივთიერების დამატებით ან მისგან ზოგიერთი კომპონენტის ამოღებით მზადდება. თუმცა, რადგან დედის რძესთან შედარებით მეტ კაზეინის ცილას შეიცავს, ბავშვის ორგანიზმი მას უფრო ნელა ინელებს.') WHERE id = 'a9c4f35f-77e6-4302-9bda-fc0e36e3f3da';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პირველ დღეებში ბავშვის დაბადების წონა შესაძლოა 10%-ით შემცირდეს. ამ კლების შემდეგ მოსალოდნელია, რომ ბავშვი დაბადების წონას არაუგვიანეს მე-10 დღისა დაუბრუნდება. ახალშობილობის პერიოდი ბავშვის მთელი ცხოვრების განმავლობაში ყველაზე სწრაფი განვითარების ეტაპია. პირველ თვეებში ბავშვი შესაძლოა 2 სმ-დან 6 სმ-მდე გაიზარდოს და 700 გრამიდან 1500 გრამამდე მოიმატოს. უნდა გახსოვდეთ, რომ ეს მაჩვენებლები შეიძლება ბავშვის სქესის მიხედვით განსხვავდებოდეს, ხოლო დღენაკლულ ბავშვებში ზრდა გარკვეული პერიოდის განმავლობაში შედარებით ნელა მიმდინარეობდეს. გარდა ამისა, პირველ თვეებში სხეულის ზრდის პარალელურად ბავშვის კუნთები, რეფლექსები და ფიზიკური უნარებიც საკმაოდ სწრაფად ვითარდება. ამიტომ ამ პერიოდში ბავშვს განვითარებისთვის სათანადო სტიმულები უნდა შეუქმნათ და ექიმთან რეგულარულად გაიაროთ კონსულტაცია.') WHERE id = '379e34a9-be36-4930-a59c-af93a24eb449';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვისთვის საფენის გამოცვლა ახალბედა დედას თავდაპირველად შეიძლება საკმაოდ რთულ და შემაშინებელ საქმედ მოეჩვენოს. საფენის გამოცვლამდე დარწმუნდით, რომ ყველაფერი საჭირო ხელთ გაქვთ, და პროცესი ხელების დაბანით დაიწყეთ. სანამ ამას შეეჩვევით, შეგიძლიათ დახმარება ექთნებს, ახლობლებსა და ნათესავებს სთხოვოთ. დაბადებიდან პირველი რამდენიმე თვის განმავლობაში ბავშვს საფენის ხშირი გამოცვლა დასჭირდება. თუმცა, თუ ბავშვს სძინავს და საფენი ძალიან სველი არ არის, მხოლოდ მის გამოსაცვლელად გაღვიძება საჭირო არ არის. ამიტომ, თუ ღამით კვებისას ფიქრობთ, რომ ბავშვს დისკომფორტი არ აწუხებს, საფენის გამოსაცვლელად მისი შეწუხება არ ღირს. მძინარე ბავშვის შეწყვეტილი ძილის შემდეგ მას შესაძლოა კვლავ ჩაძინება გაუჭირდეს.') WHERE id = 'd0704bed-eb75-4a28-b892-e481bca3aba6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის დაბადების შემდეგ ჭიპლარის ნარჩენი დაახლოებით 10-14 დღის განმავლობაში მთლიანად შრება და ძვრება. თუმცა ზოგიერთ შემთხვევაში ამ პროცესს შეიძლება მეტი დრო დასჭირდეს. თუ ბავშვს ჭიპლარის ნარჩენი ჯერ კიდევ არ მოსძვრა, აუცილებლად უნდა მიმართოთ უახლოეს პედიატრს. თუ ჭიპლარის ნარჩენი 20 დღის შემდეგაც არ მოსძვრა, ეს შესაძლოა ბავშვის იმუნურ სისტემასთან დაკავშირებულ გარკვეულ პრობლემებზე მიუთითებდეს. ბავშვის დაბანისას ეცადეთ, ჭიპის მიდამო არ დაასველოთ, ხოლო თუ დასველდა, აუცილებლად კარგად გააშრეთ. ნესტიანი ჭიპლარის ნარჩენი შეიძლება დროულად არ მოსძვრეს და სხვადასხვა ინფექციაც გამოიწვიოს. გარდა ამისა, იმისთვის, რომ ჭიპლარის ნარჩენი სწრაფად და უსაფრთხოდ მოსძვრეს, არ გამოიყენოთ არავითარი წამალი ან ლოსიონი, თუ ექიმმა არ გირჩიათ.') WHERE id = '46a30d17-6906-4dd1-9f3a-fa10b39a15db';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დღის განმავლობაში ბავშვთან ხშირი კონტაქტი და ძუძუთი კვება მას ახალ სამყაროსთან შეგუებას მნიშვნელოვნად უადვილებს. დიდი ხანია ცნობილია, რომ ყველაზე თანამედროვე ინკუბატორიც კი ვერ უზრუნველყოფს ბავშვისთვის ისეთ ძლიერ მზრუნველობას, როგორსაც დედის ჩახუტება. შეხება, სითბო და სუნი ბავშვსა და თქვენ შორის ემოციურ კავშირს აძლიერებს. ამასთანავე, ეს კონტაქტი ძუძუთი წარმატებული კვების გასაგრძელებლად მნიშვნელოვან ფაქტორად მიიჩნევა. ამ ეტაპზე ბავშვთან ჩამოყალიბებული ძლიერი სენსორული კავშირი მის ფსიქიკურ და ფიზიკურ განვითარებას აჩქარებს. მოგვიანებით, ბავშვობის პერიოდში, ეს უსაფრთხოებისა და ნდობის განცდის ჩამოყალიბებისთვისაც ძალიან მნიშვნელოვანია. ამიტომ ყველა საქმე გადადეთ და ხშირად გქონდეთ ბავშვთან კანი-კანთან კონტაქტი! 😊') WHERE id = 'd3f6fa0e-5b44-4a86-8dac-648c5ea0fb9f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდგომი პერიოდი მოიცავს მშობიარობიდან დაახლოებით 6 კვირას. ამ პერიოდში, განსაკუთრებით მაშინ, როდესაც ბავშვთან და ახალ ცხოვრებასთან შეგუებას ცდილობთ, დროდადრო შეიძლება ემოციური აღმასვლა და დაღმასვლა განიცადოთ. ამ დროს ორსულობის განმავლობაში ნივთიერებათა ცვლასა და რეპროდუქციულ სისტემაში მომხდარი ცვლილებები თანდათან უკუვითარდება. ჰორმონების დონე და საშვილოსნოს ზომა სწრაფად უბრუნდება ორსულობამდელ მდგომარეობას. დაახლოებით 9 თვის განმავლობაში ნელ-ნელა განვითარებული ფიზიოლოგიური და ჰორმონული ცვლილებების ისეთ მოკლე დროში, როგორიც 6 კვირაა, უკუგანვითარებამ შესაძლოა თქვენს ფსიქოლოგიურ მდგომარეობაზე იმოქმედოს. თუ რთული მშობიარობა გადაიტანეთ, ეს პერიოდი შეიძლება ჩვეულებრივზე უფრო მძიმედ გაიაროთ. გახსოვდეთ, რომ ეს რთული ეტაპი დროებითია. თუ თავს კარგად არ გრძნობთ, ნუ მოგერიდებათ ახლობლებისთვის ან სპეციალისტისთვის დახმარების თხოვნა.') WHERE id = 'ee31cac0-139c-4b54-962e-0e0cfd50ac5a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის დაძინებისას ალბათ შეგიმჩნევიათ, რომ ის მუდმივად მოხრილ მდგომარეობაში რჩება. რადგან 9 თვის განმავლობაში საშვილოსნოში ემბრიონის პოზაში იყო, ეს ჩვევა კიდევ გარკვეული ხნით შეუნარჩუნდება. დაახლოებით მე-2 თვიდან ეს მდგომარეობა თანდათან შემცირდება, მე-3 თვეში კი მთლიანად გაივლის. საშვილოსნოში არსებული უსაფრთხო და დახურული გარემოს შემდეგ გარე სამყარო მას შეიძლება საშიშად და ქაოსურად მოეჩვენოს. ამიტომ მას მუდმივად თქვენთან სიახლოვე სურს. ამ პერიოდში დრო მიეცით — თანდათან შეეჩვევა. გახსოვდეთ, მისთვის ყველაზე უსაფრთხო ადგილი თქვენი მკლავებია, სადაც თქვენს სურნელს გრძნობს. დედასა და ბავშვს შორის მტკიცე კავშირი სწორედ პირველივე დღეებიდან ყალიბდება. როცა მოშივდება ან გამოცვლა და გასუფთავება დასჭირდება, ნუ ალოდინებთ — დაუყოვნებლივ დაუკმაყოფილეთ საჭიროება. ცოტა ხნით დაივიწყეთ გარე სამყარო და უბრალოდ თქვენს ბავშვს დაუთმეთ ყურადღება.') WHERE id = '990edf71-6742-4577-9d2f-dadba792cf8a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენ და თქვენმა ბავშვმა ერთად უკვე ერთი კვირა გაატარეთ. დრო მართლაც სწრაფად გადის, არა? 😊 ორსულობის განმავლობაში ბავშვის ნაწლავები სტერილურია და იქ მავნე მიკროორგანიზმები არ არის. თუ მშობიარობა საკეისრო კვეთით ჩატარდა, საჭმლის მონელების ხელშემწყობი ბაქტერიები ბავშვის ნაწლავურ ფლორაში სწორედ დღეიდან იწყებს ჩამოყალიბებას. ბუნებრივი მშობიარობის შემთხვევაში კი ეს პროცესი მე-4 დღიდან იწყება. ამ ბაქტერიების ნაწილი სასარგებლოა, ნაწილი კი — მავნე. ორივე სახეობის არსებობა საჭმლის მომნელებელ სისტემაში წონასწორობას ქმნის და ხელს უშლის მათ ჭარბ გამრავლებას. ანუ ეს მიკროორგანიზმები ბავშვის ნაწლავური ფლორის ბალანსისთვის მნიშვნელოვანია.') WHERE id = 'ea7ac5e6-2b68-47b7-9578-f87a52623334';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ნუ ინერვიულებთ იმის გამო, რომ რძე ცოტა გაქვთ, ძვირფასო დედიკო. დაბადებისას ბავშვის კუჭის მოცულობა მხოლოდ ერთი ბლის ზომისაა. ამიტომ ნუ შეშფოთდებით იმაზე ფიქრით, რომ თქვენი რძე საკმარისი არ არის. მშობიარობის შემდგომ დღეებში კუჭი იზრდება და ამ დროისთვის უკვე ერთი გარგრის ზომის, ანუ დაახლოებით 50 ml მოცულობისაა. ამიტომ რძის ის რაოდენობა, რომელიც თქვენ ცოტა გეჩვენებათ, სინამდვილეში სრულიად საკმარისია ბავშვის დასანაყრებლად. რადგან მისი კუჭი ჯერ კიდევ პატარაა, ბავშვს ცოტ-ცოტა, მაგრამ ხშირად მოუნდება ძუძუს წოვა. თუ ჭამის შემდეგ რძეს ამოაღებს, ეს, როგორც წესი, მაშინ ხდება, როცა კუჭის მოცულობაზე მეტი ჭამა. ხალხში გავრცელებული მოსაზრება, თითქოს თქვენი რძე ბავშვს არ უხდება, უბრალოდ მითია — ნუ დაიჯერებთ.') WHERE id = 'f7f368ac-9bca-4520-b0e3-f83cfbd455a4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რძეს, რომელიც მშობიარობისთანავე გამოიყოფა, ხსენი (კოლოსტრუმი) ეწოდება. ეს არის სქელი კონსისტენციის, მოყვითალო ფერის, ბავშვის ინფექციებისგან დამცავი ანტისხეულებითა და ცილებით მდიდარი, უაღრესად ღირებული საკვები. მშობიარობიდან დაახლოებით 5-7 დღის შემდეგ მას გარდამავალი რძე ცვლის. გარდამავალი რძე კოლოსტრუმთან შედარებით მეტ ცხიმსა და ლაქტოზას შეიცავს, ანუ უფრო კალორიულია. ამ ტიპის რძე დაახლოებით მე-14 დღემდე გამოიყოფა. მშობიარობიდან 2 კვირის შემდეგ კი უკვე მწიფე რძე იწყებს გამომუშავებას. ეს რძე მდიდარია როგორც წყლით, ისე ცილებითა და ცხიმებით.') WHERE id = '4794b2b1-e590-4e29-b9bf-54af8c8dcab5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის მოვლა, განსაკუთრებით მაშინ, თუ პირველად გახდით დედა, თავდაპირველად შეიძლება რთულად და შემაშინებლად მოგეჩვენოთ. თუ ფიქრობთ, რომ ამას ვერ შეძლებთ, ცდებით. 😊 შეიძლება ბანალურად ჟღერდეს, მაგრამ დროთა განმავლობაში ბავშვის მოვლას ძალიან მარტივად გაართმევთ თავს. მოვლის ერთ-ერთი ასეთი პროცედურაა ჭიპლარის ნარჩენის დამუშავება, რომელიც შრება და მალე უნდა მოძვრეს. ორსულობის განმავლობაში ჭიპლარის მეშვეობით ბავშვს ზრდისა და განვითარებისთვის საჭირო ჟანგბადი და საკვები ნივთიერებები მიეწოდება. დაახლოებით 50 cm სიგრძის ჭიპლარს მშობიარობის შემდეგ ექიმი ისე ჭრის, რომ 2 cm დარჩეს. ბავშვის ჭიპლარის ნარჩენი მე-5 და მე-15 დღეებს შორის ძვრება. თუ ჭიპის მიდამოს სათანადოდ არ მოუვლით როგორც ნარჩენის მოძრობამდე, ისე მის შემდეგ, ამ გზით ინფექციის განვითარების რისკი შეიძლება გაიზარდოს. ამ რისკის გამო აუცილებელია, ექიმის მიერ რეკომენდებული 70-პროცენტიანი სპირტის ხსნარით ჭიპის მიდამო დღეში ორჯერ ან სამჯერ გაწმინდოთ და გაანიავოთ.') WHERE id = '403ffca4-6096-4cf2-9210-17a6a3a59df5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სრულიად ნორმალურია, რომ ბავშვის თავი სხეულთან შედარებით უფრო დიდია და ეს ჯანმრთელობის პრობლემაზე არ მიუთითებს. ამასთანავე, თავის ფორმა შეიძლება ოდნავ არაპროპორციული ან ასიმეტრიული იყოს. ამის მიზეზი ისაა, რომ ბავშვის თავის ქალის ძვლები ჯერ არ გამაგრებულა, რაც აუცილებელია სამშობიარო გზების გასავლელად. ჯერ კიდევ რბილი თავის ქალის ძვლები უხვი ბოჭკოვანი ხრტილოვანი ქსოვილისგან შედგება. ამასთან, ბავშვის ტვინის განვითარების გასაგრძელებლად ეს ღია უბნები აუცილებელია. საშუალოდ, დაბადების თვის ბოლოსთვის ბავშვის თავი მისთვის დამახასიათებელ მომრგვალებულ ფორმას იღებს. ბავშვი 6 ყიფლიბანდით იბადება და მე-2 თვის ბოლოსთვის ყველა მათგანი იხურება, გარდა წინა ზედა ყიფლიბანდისა. წინა ზედა ნაწილში მდებარე დიდი ყიფლიბანდი ბავშვის მე-7 თვიდან იწყებს გამაგრებას და 2 წლის ასაკამდე იხურება.') WHERE id = '878511ba-a575-4d79-8fa5-80ca329e838e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდგომ პერიოდში გენიტალური მიდამოს სისუფთავეს განსაკუთრებული ყურადღება უნდა მიაქციოთ. გახსოვდეთ, რომ მშობიარობის შემდეგ ეს მიდამო ინფექციის გამომწვევი ბაქტერიების მიმართ საკმაოდ მგრძნობიარე ხდება. განსაკუთრებით, თუ ბუნებრივი მშობიარობის დროს ეპიზიოტომია (ჭრილობა) გაკეთდა, შესაძლოა ექიმის მიერ რეკომენდებული ანტისეპტიკური კრემებით მოვლა დაგჭირდეთ. საკეისრო კვეთის შემდეგ პირველ კვირებში კი განსაკუთრებული ყურადღება უნდა მიაქციოთ ნაკერის მიდამოს. უნდა გაითვალისწინოთ ოპერაციის ჩამტარებელი ექიმის რეკომენდაციები და არ გამოტოვოთ შემოწმებები. შხაპის მიღებისას დარწმუნდით, რომ წყალი მეტისმეტად ცხელი არ არის და აუცილებლად შედით შხაპში მხოლოდ იმ პირობით, რომ ვინმე თქვენ გვერდით იქნება. თუ საკეისრო კვეთით იმშობიარეთ, შხაპის მიღებისას ნაკერები უნდა დაიცვათ და ყურადღება მიაქციოთ, რომ ამ მიდამოში ინფექცია არ განვითარდეს.') WHERE id = '146cc0cd-e1d3-412a-82e1-01fb76131db8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი დღის განმავლობაში შეიძლება ხშირად ტიროდეს, ზოგჯერ კი ტირილი ხანგრძლივ შეტევებადაც გაგრძელდეს. ტირილის შეტევებმა, განსაკუთრებით მაშინ, როცა მის დამშვიდებას ვერ ახერხებთ, შეიძლება თავი სრულიად უმწეოდ გაგრძნობინოთ. შეინარჩუნეთ სიმშვიდე და გახსოვდეთ, რომ ტირილი ბავშვთან თქვენი ურთიერთობის ერთადერთი საშუალებაა. ბავშვის ტირილს ბევრი სხვადასხვა მიზეზი შეიძლება ჰქონდეს. მაგალითად, შესაძლოა ტანსაცმელი აწუხებდეს, სციოდეს ან სცხელოდეს. განსაკუთრებით ისინი, ვინც პირველად გახდნენ დედები, ავად გახდომის შიშით ბავშვს ხშირად საჭიროზე მეტად თბილად აცმევენ. სწორი ბალანსის შესანარჩუნებლად საკმარისია, ბავშვს თქვენზე მხოლოდ ერთი ფენით მეტი ტანსაცმელი ჩააცვათ.') WHERE id = '92bf1f12-3409-4d88-8829-221346b3ee91';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფიზიკური შეხება ძალიან მნიშვნელოვანია თქვენსა და ბავშვს შორის კავშირის ჩამოყალიბებისა და განმტკიცებისთვის. თქვენთან ფიზიკური კონტაქტისას ბავშვს თქვენი გულისცემა ამშვიდებს — ეს იყო პირველი ხმა, რომელიც მან ჯერ კიდევ საშვილოსნოში ყოფნისას გაიგონა. ამასთან, ეს მეთოდი მას უფრო ღრმად და მშვიდად დაძინებაში ეხმარება. მსოფლიოს მრავალ კულტურაში ბავშვს დაბადებისთანავე შიშველს აწვენენ დედის მკერდზე. სამეცნიერო კვლევების თანახმად, ეს პირველი ფიზიკური კონტაქტი ბავშვის ძირითადი ბიოლოგიური საჭიროებების დაკმაყოფილებას უწყობს ხელს. ეს კონტაქტი ბავშვის მომავალი ფსიქოლოგიისა და ქცევის ჩამოყალიბების განსაკუთრებით მნიშვნელოვან პერიოდს მოიცავს. კვლევები აჩვენებს, რომ ბავშვებში, რომლებსაც დედასთან ხშირი ფიზიკური კონტაქტი აქვთ, მე-3 და მე-6 თვეზე მხოლოდ დედის რძით კვების მაჩვენებელი 2-ჯერ უფრო მაღალია. ამავე კვლევაში აღნიშნულია, რომ ამ მეთოდის წყალობით ბავშვები 2 წლის ასაკამდე სხვა ბავშვებთან შედარებით 12-ჯერ ნაკლებად ტირიან.') WHERE id = 'c9ec86c3-ffa1-4c34-8c50-574a23ddec68';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდეგ პირველ დღეებში ნორმალურია ლოგინობის პერიოდისთვის დამახასიათებელი, მკვეთრი წითელი ფერის გამონადენი, რომლის რაოდენობაც მენსტრუაციის დროს სისხლდენისას გამოყოფილი სისხლის რაოდენობას უახლოვდება. ამ გამონადენს ლოქია ეწოდება და ის შეიძლება 1-2 კვირაში დასრულდეს ან 6 კვირამდე გაგრძელდეს. გამონადენის რაოდენობა დღითიდღე მცირდება და მისი ფერიც იცვლება. ლოგინობის პერიოდის ბოლოს ის მოთეთრო გამონადენად იქცევა. ამ პერიოდში გენიტალური მიდამოს მოსავლელად ჰიგიენური საფენი ხშირად უნდა გამოცვალოთ და ინტიმური ზონისთვის განკუთვნილი სპეციალური დასაბანი საშუალებები გამოიყენოთ. ლოგინობის პერიოდში ჭარბი და ხანგრძლივი სისხლდენა შეიძლება საშვილოსნოში პლაცენტის ქსოვილის ნარჩენზე ან ინფექციის განვითარებაზე მიუთითებდეს. მართალია, ეს იშვიათად ხდება, მაგრამ შესაბამისი ნიშნების არსებობისას უყურადღებოდ არ დატოვოთ და აუცილებლად მიმართეთ ექიმს.') WHERE id = '8438f645-667d-4bb4-ad8d-04104669e5fa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახალშობილებს დედა ძალიან სჭირდებათ, ხოლო მათი ყველაზე კარგად განვითარებული შეგრძნება სწორედ შეხებაა. ბავშვის შეხების მოთხოვნილება ყველაზე უკეთ ძუძუთი კვებისას კმაყოფილდება, როცა ის თქვენს სურნელს გრძნობს. სიცოცხლის პირველ თვეებში ბავშვს ძუძუს წოვა მხოლოდ მაშინ არ სურს, როცა შია. რადგან თავს უსაფრთხოდ მხოლოდ იქ გრძნობს, სადაც თქვენი სურნელი ესმის, მას შეიძლება ძუძუს წოვისას დაძინება უნდოდეს. ამიტომ წოვის სურვილი მნიშვნელოვანია არა მხოლოდ დანაყრებისთვის, არამედ ემოციური თვალსაზრისითაც. ბავშვები სოციალურ კონტაქტს მხოლოდ სამი თვის შემდეგ იწყებენ. ამიტომ არ უნდა მოერიდოთ ბავშვის ხელში აყვანას საზოგადოებაში გავრცელებული მცდარი მოსაზრების გამო, თითქოს ის ხელში ყოფნას მიეჩვევა. პირველ თვეებში ბავშვთან ხშირი ჩახუტება მას გარესამყაროსთან ადაპტაციაში ეხმარება და უსაფრთხოების განცდას უმტკიცებს.') WHERE id = 'a82a92d2-bea2-44d6-bcce-77b7bcd63519';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდეგ თქვენი საშვილოსნო ჯერ კიდევ მნიშვნელოვნად აღემატება ორსულობამდე არსებულ ნორმალურ ზომას. ახლა საშვილოსნოს, ჩვეულებრივ, ჭიპის დონეზე ან ოდნავ ზემოთ შეიგრძნობთ. დაახლოებით 1 თვის განმავლობაში საშვილოსნო სრულად დაუბრუნდება თავის ადრინდელ ზომას. საშვილოსნოს მასა, რომელიც მშობიარობის დროს დაახლოებით 1500 გრამია, ყოველდღიურად თანდათან მცირდება და ორსულობამდელი პერიოდის მსგავსად კვლავ 60 გრამამდე ჩამოდის. დროდადრო, განსაკუთრებით ძუძუთი კვებისას, ჰორმონ ოქსიტოცინის ზემოქმედებით საშვილოსნოს შეკუმშვასთან დაკავშირებული ტკივილი შეიძლება იგრძნოთ. მშობიარობის შემდეგ პირველ დღეებში შედარებით ძლიერი ეს ტკივილები თანდათან მსუბუქდება. მიიჩნევა, რომ ასეთი შეკუმშვები ნორმალურია და საშვილოსნოს შიდა შრის გაწმენდასაც კი უწყობს ხელს.') WHERE id = '79a8c317-465e-48a5-8158-982eb6d5f890';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პირველ ხანებში შეიძლება შეამჩნიოთ, რომ ბავშვი ძუძუთი კვების დროს იძინებს. ბევრი დედის მსგავსად, ეს შესაძლოა თქვენც მოგწონდეთ. თუმცა სიფრთხილე გმართებთ: თუ ეს ჩვევად ჩამოყალიბდება, ბავშვს ძუძუს წოვის გარეშე დაძინება შეიძლება გაუჭირდეს. როცა ბავშვი ამ რეჟიმს მიეჩვევა, ძუძუს წოვის გარეშე დაძინება აღარ მოუნდება. ამიტომ, როგორც კი შეამჩნევთ, რომ ეძინება და მოუსვენრადაა, საწოლში ჩააწვინეთ და დაძინების სხვადასხვა მეთოდი სცადეთ. ახალ მეთოდებთან შეჩვევისას ბავშვმა თავდაპირველად შეიძლება იტიროს. თუმცა, თუ არ დანებდებით და მცდელობას განაგრძობთ, დროთა განმავლობაში დაინახავთ, რომ მიეჩვია. თუ ამ მცდელობებისას ბავშვი დაძინებას ძლიერ ეწინააღმდეგება, ჯერ დაამშვიდეთ, შემდეგ კი კვლავ მიეცით დამოუკიდებლად დაძინების შესაძლებლობა.') WHERE id = '9210140f-4b86-4445-aa81-e541ebeace13';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '9 თვის განმავლობაში საშვილოსნო თქვენი ბავშვისთვის ძალიან თბილ და კომფორტულ გარემოს ქმნიდა. დაბადებისას ხმაურითა და სინათლით სავსე გარე სამყაროში უეცრად მოხვედრა ბავშვისთვის შეიძლება მცირე შოკი იყოს. ამიტომ ახალ გარემოსთან შესაგუებლად მას გარკვეული დრო დასჭირდება. თუ დაძინებისას ბავშვი კვლავ ისე მოკუნტული წევს, როგორც საშვილოსნოში იყო (ემბრიონის პოზა), ამის მიზეზი სწორედ ესაა. დაახლოებით 1 თვის განმავლობაში შეამჩნევთ, რომ ეს ჩვევა თანდათან მცირდება. ადაპტაციის ამ პერიოდში ბავშვს თქვენ ყველაზე მეტად სჭირდებით. მას ძალიან მოსწონს, როცა ხელში აგყავთ, კოცნით, ესაუბრებით და, მოკლედ, ყურადღებას აქცევთ — ეს მის ორგანიზმში ბედნიერების ჰორმონების გამომუშავებას უწყობს ხელს.') WHERE id = 'd3c1171d-ec50-4947-af33-82084d44686e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დღეები სწრაფად გადის და თქვენც ყოველდღიურად უფრო მეტად ეჩვევით დედობას. შესაძლოა, თქვენსა და ბავშვს შორის კავშირი უკვე ჩამოყალიბდა ენით აუწერელი სიყვარულისა და მისი დაცვის ძლიერი სურვილის სახით. თუმცა მოსაზრება, რომ ეს გრძნობა ყველა ქალს დაუყოვნებლივ და ერთნაირად უნდა გაუჩნდეს, მცდარია. ადამიანების ემოციები განსხვავებულია, ხოლო მშობიარობის სტრესისა და მშობიარობის შემდგომი პერიოდის გამო ზოგიერთ ქალს ბავშვთან ემოციური კავშირის ჩამოსაყალიბებლად დრო სჭირდება. თუ ხანდახან ბავშვის მიმართ გაუცხოებას გრძნობთ, თავს ნუ დაიდანაშაულებთ. ჰორმონების დონე, რომელიც 9 თვის განმავლობაში თქვენს სისხლში თანდათან იზრდებოდა, მშობიარობის შემდეგ მოკლე დროში მკვეთრად იცვლება, რამაც შესაძლოა თქვენს ფსიქოლოგიურ მდგომარეობაზე იმოქმედოს. თუ რამდენიმე კვირის გასვლის შემდეგაც ბავშვის მიმართ გაუცხოებას გრძნობთ, შესაძლოა მშობიარობის შემდგომი დეპრესია გქონდეთ. ასეთ შემთხვევაში აუცილებლად გირჩევთ, ექიმს მიმართოთ და ფსიქოლოგიური დახმარება მიიღოთ.') WHERE id = '08ca900e-fc32-45d6-bd75-a4633391d4f9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადების შემდეგ გარკვეულ კვირებში ბავშვებს სწრაფი ზრდისა და განვითარების პერიოდები, ანუ ზრდის ნახტომები აქვთ. მე-5 კვირა, რომელშიც ახლა იმყოფებით, ზრდის ასეთი ნახტომის პირველი პერიოდია. ამიტომ ამ დღეებში სრულიად ნორმალურია, თუ ბავშვი ჩვეულებრივზე მეტად ტირის, ჭირვეულობს, ძილი ერღვევა ან მადა ეცვლება. მადის მატება იმითაა განპირობებული, რომ ზრდისთვის მეტი ენერგია სჭირდება. ამასთან, უფრო ხშირი ძუძუს წოვით ის ააქტიურებს ჰორმონებს, რომლებიც რძის გამომუშავებას ზრდის და მის გაზრდილ მოთხოვნილებას აკმაყოფილებს. მე-5 კვირის ზრდის ნახტომის დროს ბავშვი გრძნობის ორგანოების აქტიურად გამოყენებას იწყებს და მის გარშემო არსებულ ყველაფერს თანდათან აღიქვამს. მოკლედ, ბავშვი აღმოაჩენს, რომ მისი სამყარო მხოლოდ კვებისა და ძილისგან არ შედგება. შედეგად, მეტი გამღიზიანებლის ზემოქმედების გამო, ზოგჯერ შეიძლება უფრო მოუსვენარი გახდეს. ეს პერიოდი სულ რამდენიმე დღეს გაგრძელდება, ამიტომ შეეცადეთ, რაც შეიძლება მეტი მოთმინებით შეხვდეთ და გახსოვდეთ, რომ ის დროებითია.') WHERE id = '3c3db532-5b9a-41a9-8a5e-67563130c5c0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახლა, როცა გარე სამყაროში ბავშვის პირველი თვე დასრულდა, ალბათ უკვე შეამჩნიეთ, რომ გარემოს მიმართ უფრო მეტ ინტერესს იჩენს. მას განსაკუთრებით იზიდავს გარშემო არსებული საინტერესო საგნები, დიდი ფორმები, მკვეთრი და კონტრასტული ფერები. დაბადებიდან პირველ დღეებში ბავშვი თვალებს მხოლოდ მცირე ხნით ახელდა, ახლა კი უფრო დიდხანს რჩება ფხიზლად. ეს ნიშნავს, რომ მან გარემოს შესასწავლად მნიშვნელოვანი გრძნობების გამოყენება დაიწყო. სიფხიზლის ხანმოკლე პერიოდებში შეგიძლიათ ბავშვს ფერადი ქსოვილები აჩვენოთ, შეახოთ და სხვადასხვა აქტივობა შესთავაზოთ. დაინახავთ, რომ ასეთი თამაშები ძალიან მოეწონება. ამასთან, რადგან მხედველობა ჯერ სრულად არ აქვს განვითარებული, სახე ახლოს მიუტანეთ და საშუალება მიეცით, ყურადღებით დაგაკვირდეთ და უკეთ გაგიცნოთ. 😊') WHERE id = '676e6646-3ff2-4bc0-82e0-4614c3d8096a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რძის ქერქი, რომელიც თავის კანზე ქერქოვან და აქერცლილ უბნებს წარმოქმნის, ბავშვის სიცოცხლის პირველ თვეებში გავრცელებული კანის მდგომარეობაა. ეს წითელი და აქერცლილი გამონაყარი შეიძლება გავრცელდეს შუბლზე, ყურების უკან, კისერსა და იღლიებშიც კი. თუ თქვენს ბავშვს რძის ქერქი გაუჩნდა, შეშფოთება საჭირო არ არის. ჩვეულებრივ, ის ქავილს არ იწვევს და ბავშვს არ აწუხებს. ზოგჯერ საფენის გამოცვლისას შეიძლება შეამჩნიოთ, რომ გამონაყარი საფენის მიდამოშიც გავრცელდა. იშვიათ შემთხვევებში ამ უბანში მდგომარეობას შეიძლება სოკოვანი ინფექციაც ახლდეს. რძის ქერქის ზუსტი მიზეზი უცნობია, თუმცა მის განვითარებას შეიძლება ხელს უწყობდეს გენეტიკური მიდრეკილება, კანზე ბუნებრივად არსებული საფუარა სოკოები, გამღიზიანებელი ნივთიერებები, მშრალი და ცივი ჰაერი.') WHERE id = 'dc08af3a-ac5d-4bd3-9ab0-537157d76301';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც ახალშობილებს შიათ, ტირილის ნაცვლად თავდაპირველად მოძრაობას იწყებენ. ამის შემდეგ შესაძლოა ნელ-ნელა მოუსვენრობა გამოავლინონ. თუ ამ რეაქციების შემდეგაც ვერ დანაყრდნენ, ტირილს იწყებენ და შიმშილის გახანგრძლივებასთან ერთად ტირილის ინტენსივობაც იმატებს. ამ ეტაპზე ბავშვის დაუყოვნებლივ გამოკვების მცდელობამ ზოგიერთ შემთხვევაში შეიძლება გამოიწვიოს ძუძუზე ან ბოთლზე უარის თქმა. ამიტომ მტირალი ბავშვი ჯერ ხელში უნდა აიყვანოთ და დაამშვიდოთ, შემდეგ კი გამოკვებოთ. თუ ხელში აყვანის მიუხედავად ბავშვი არ მშვიდდება, შეგიძლიათ ფეხზე დგომისას ძუძუთი კვება სცადოთ. რადგან თქვენ და თქვენი ბავშვი ჯერ კიდევ ერთმანეთთან შეგუების პროცესში ხართ, დააკვირდით მის რეაქციებს და შეეცადეთ გაიგოთ, რა სურს მას.') WHERE id = '9e7fdf66-075d-494d-b199-11e006ca39c4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდეგ თქვენი მკერდიდან იწყება დედის რძის გამოყოფა, რომელიც ბავშვის უმნიშვნელოვანესი საკვებია. ამიტომ პირველ კვირებში ბევრი სითხე უნდა მიიღოთ და შეძლებისდაგვარად მოერიდოთ სტრესს. ამ კვირიდან გაზებით გამოწვეული ჩივილები შეიძლება როგორც თქვენ, ისე ბავშვსაც გაგიჩნდეთ. ბავშვის გაზებით გამოწვეული ტკივილის შესამსუბუქებლად ექიმის მიერ რეკომენდებული წვეთები, როგორც წესი, 1-ლი თვის შემდეგ ინიშნება. ამიტომ შეეცადეთ მოერიდოთ აირების წარმოქმნის ხელშემწყობ საკვებს და კვების რაციონში შეიტანოთ უშაქრო კომპოტები, ახლად გამოწურული ხილის წვენები და ბოსტნეულის სუპები. რძემ და რძის პროდუქტებმა, პარკოსნებმა, ასევე ფორთოხლისა და მანდარინის მსგავსმა მჟავე ხილმა შეიძლება გაზებით გამოწვეული ტკივილი გამოიწვიოს. ამიტომ ეს პროდუქტები სათითაოდ მოსინჯეთ და ისე დაამატეთ თქვენს მენიუს. თუ რძის პროდუქტები გაზების წარმოქმნას იწვევს, შეგიძლიათ ულაქტოზო რძე გამოიყენოთ.') WHERE id = 'bbfc25e1-805a-4de5-a48e-49b8bc100ff1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ძილის რეჟიმის ჩამოყალიბებას შესაძლოა გარკვეული დრო დასჭირდეს. პირველ თვეებში ბავშვს, რომელსაც ჩვეულებრივ დღე-ღამის განმავლობაში მონაცვლეობით სძინავს და ღვიძავს, ჯერ არ შეუძლია დღისა და ღამის გარჩევა, რაც ძილის რეჟიმის მოწესრიგებასაც აფერხებს. გადაჭარბებული დაღლილობა და გამოუძინებლობა ბავშვის ტირილს იწვევს. პირველ თვეებში ბავშვმა, როგორც წესი, დღეში 15-16 საათამდე უნდა იძინოს, ხოლო როდესაც დაძინებას ვერ ახერხებს, ძალიან მოუსვენარი ხდება. გარდა ამისა, ზედმეტად ხმაურიან გარემოსა და ვიზუალურ გამღიზიანებლებთან შეხებამ შეიძლება ხელი შეუშალოს დაძინებაში და ტირილი გამოიწვიოს. ბავშვის ძილის რეჟიმი 8-12-ე კვირებს შორის თანდათან იწყებს ჩამოყალიბებას. ამ პროცესს ძუძუთი კვებებს შორის ინტერვალების გახანგრძლივებაც უწყობს ხელს. თუმცა ყველა ბავშვი განსხვავებულია, ამიტომ ზოგიერთის ძილის რეჟიმთან უფრო გვიან შეგუება ნორმალურად ითვლება.') WHERE id = 'a4331c8d-b2a0-435c-af06-870f5fad8fab';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი დაბადების პირველივე წუთებიდან ძალიან მგრძნობიარეა ადამიანის ხმების მიმართ. მიიჩნევა, რომ ამის მიზეზი ბგერების სიხშირის დიაპაზონს უკავშირდება. ამასთანავე, 9 თვის განმავლობაში საშვილოსნოში მას ყველაზე ხშირად თქვენი შინაგანი ორგანოების მუშაობისას წარმოქმნილი ხმები და საუბრის დროს თქვენი ხმა ესმოდა. ბავშვის დასამშვიდებლად ისარგებლეთ ამ შესაძლებლობით და ხშირად ესაუბრეთ. როდესაც ბავშვს ხელში იყვანთ და მას თქვენი ხმა და გულისცემა ესმის, თავს ძალიან მშვიდად და უსაფრთხოდ გრძნობს. შესაძლოა თქვენმა ბავშვმა საკუთარი გრძნობებისა და საჭიროებების გამოსახატავად გარკვეული ბგერების გამოცემაც დაიწყო. ბავშვთან ეფექტური კომუნიკაციისთვის მნიშვნელოვანია, მის მიერ გამოცემულ ბგერებს მსგავსი ბგერებით უპასუხოთ. ამგვარად, ბავშვი ურთიერთობის მიზნით საუბრისა და ბგერების გამოყენებას თანდათან სწავლობს.') WHERE id = '1ec6d652-1eca-417a-9067-3ad2a20a5f4b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვების დაახლოებით 20%-ს, მიუხედავად იმისა, რომ ჯანმრთელია, შესაძლოა განუწყვეტელი ტირილის შეტევები ჰქონდეს. ეს მდგომარეობა, რომელსაც კოლიკა ეწოდება, ჩვეულებრივ საღამოს საათებში იწყება და ბავშვის დამშვიდება საათების განმავლობაში ვერ ხერხდება. მიუხედავად იმისა, რომ კოლიკის მიზეზი ჯერ ბოლომდე ცნობილი არ არის, მიიჩნევა, რომ ის შესაძლოა საჭმლის მომნელებელი სისტემის არასრულ განვითარებას, ზოგიერთ ალერგიულ რეაქციას ან ნერვულ სისტემას უკავშირდებოდეს. თუ ექიმმა თქვენს ბავშვს კოლიკის დიაგნოზი დაუსვა, თქვენი წუხილი ბუნებრივია. უპირველეს ყოვლისა, უნდა იცოდეთ, რომ ეს მდგომარეობა დროებითია. ჩვეულებრივ, 3-ე თვის დასრულებისას ტირილის შეტევები თანდათან იკლებს და მალე გაივლის. ბავშვის ტირილის შეტევების დროს მის დასამშვიდებლად სხვადასხვა მეთოდი მოსინჯეთ და შეარჩიეთ ის, რომელიც ყველაზე მეტად ეხმარება. გავრცელებულ მეთოდებს შორისაა თბილი აბაზანა, მუცელზე თბილი პირსახოცის დადება ან განმეორებადი ხმის მქონე მოწყობილობის, მაგალითად, ფენის ჩართვა.') WHERE id = 'd6246f09-676f-479b-ac15-8f1e83a043b1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვთან ერთად კიდევ 1 თვე დატოვეთ უკან! ბავშვის ვაქცინაციის კალენდრის 1-ლ თვეში კეთდება B ჰეპატიტის ვაქცინის მეორე დოზა, რომლის პირველი დოზაც დაბადებისთანავე ჩაუტარდა. ფეხზე, სადაც ვაქცინა გაკეთდა, შესაძლოა სიწითლე და შეშუპება განვითარდეს. ასეთ შემთხვევაში არ უნდა ინერვიულოთ. ბავშვს შეიძლება ხანმოკლე სიცხე და ვაქცინაციის შემდგომი მოუსვენრობაც აღენიშნებოდეს. ეს ხშირი და უვნებელი გვერდითი მოვლენებია. განსაკუთრებით მოუსვენრობა ვაქცინირებული ბავშვების თითქმის უმრავლესობას აღენიშნება. ვაქცინაციის შემდეგ ტემპერატურა, როგორც წესი, 38 გრადუსს არ აღემატება. თუ სიცხე მალე არ იკლებს, ექიმის რეკომენდაციით შეგიძლიათ სიცხის დამწევი სიროფი ან სანთელი გამოიყენოთ. მართალია, ეს იშვიათად ხდება, მაგრამ თუ ფიქრობთ, რომ თქვენს ბავშვს უჩვეულო სიმპტომები აქვს, არ დაგავიწყდეთ ექიმთან დაკავშირება.') WHERE id = '418e11ce-7ef6-4382-bb9b-0ee9fe10e295';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძუძუთი კვების სწორი პოზის შერჩევა ძალიან მნიშვნელოვანია როგორც იმისთვის, რომ ბავშვმა დედის რძისგან მაქსიმალური სარგებელი მიიღოს, ისე თქვენი სხეულის ჯანმრთელობისთვის. ძუძუთი კვებისას კომფორტულად უნდა მოთავსდეთ და ზურგი და წელი ბალიშით დაიჭიროთ. ასევე, იმ მხარეს, რომელი ძუძუდანაც ბავშვს კვებავთ, მკლავის ქვეშ შემაღლებული საყრდენი მოათავსეთ, რათა მთელი პროცესის განმავლობაში მკლავის ჰაერში დაჭერა არ მოგიწიოთ. ძუძუთი კვების დროს ბავშვი რაც შეიძლება ახლოს, თქვენკენ სახით მობრუნებული უნდა გყავდეთ. საუკეთესოა, თუ ბავშვის სხეულს წინამხრის შიდა მხარეს მოათავსებთ, თავს კი იდაყვის მოხრილ ნაწილში ჩაუდებთ. სწორი პოზის შერჩევა ბავშვის განვითარებისთვისაც გადამწყვეტია. თუ ბავშვს არასწორ პოზაში დაიჭერთ და კვებას ასე გააგრძელებთ, კისერი მალე ასტკივდება და წოვას უფრო ადრე შეწყვეტს.') WHERE id = '4be7fa1f-7739-407d-aa85-d7577ebd4d3a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, ბავშვს აირებით გამოწვეული ტკივილი უკვე საკმაოდ შემაწუხებლად გამოუვლინდა. თუ მის სხეულის ენას დააკვირდებით და შენიშნავთ, რომ ფეხებს მუცლისკენ იზიდავს, წითლდება, ტირის და ფეხებს ისე ამოძრავებს, თითქოს ველოსიპედს ატარებს, დიდი ალბათობით, მას აირები აწუხებს. თუ ეს ნიშნები ძუძუთი კვების ან ჭამის შემდეგ ჩნდება და ბავშვი ვერ მშვიდდება, სავარაუდო მიზეზი აირებია. ამის ამოცნობა რთული არ არის: აირებით გამოწვეული ტკივილის დროს ბავშვი მოუსვენარია, წოვა სურს, მაგრამ ცოტა ხანში კვლავ ტირილს იწყებს. აირების დროს ბავშვის მუცელი შეიძლება გამაგრებული და შებერილიც ჩანდეს. მოძრაობა ნაწლავებში დაგროვილი ჰაერის გადაადგილებას უწყობს ხელს და ბავშვს შვებას ჰგვრის. აირებითა და კოლიკით გამოწვეული ტკივილი ძალიან შემაწუხებელია, თუმცა ეს დროებითი პერიოდია. ამიტომ სიმშვიდე შეინარჩუნეთ და გახსოვდეთ, რომ ეს გაივლის. ასეთ დროს ბავშვის დასამშვიდებლად ძალიან ეფექტურია წყნარ ოთახში გადასვლა, მასთან ნაზი ხმით საუბარი, განათების ჩაქრობა და მუცლის მასაჟი.') WHERE id = '16924675-e88b-458a-9fb7-e716fc169d02';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის რეგულარულად დაბანა ძალიან მნიშვნელოვანია როგორც მისი იმუნიტეტისთვის, ისე კანის ჯანმრთელობისთვის. თუმცა ბანაობისას რამდენიმე საკითხს განსაკუთრებული ყურადღება უნდა მიაქციოთ. მათგან ყველაზე მნიშვნელოვანია წყლის ტემპერატურა. ბავშვის აბაზანისთვის წყლის ტემპერატურა დაახლოებით 37 გრადუსი უნდა იყოს. უფრო ცივმა ან ცხელმა წყალმა შეიძლება ბავშვის კანი დააზიანოს და მისი ავად გახდომაც გამოიწვიოს. ოთახის ტემპერატურა კი 22-24 გრადუსის ფარგლებში უნდა შეინარჩუნოთ. კიდევ ერთი მნიშვნელოვანი საკითხია აბაზანაში წყლის დონე. ერთი წამით უყურადღებობის შემთხვევაშიც კი ბავშვი შეიძლება ხელიდან გაგისხლტეთ, ამიტომ წყლის სიღრმე 15 სმ-ზე მეტი არ უნდა იყოს. ბანაობისას ეცადეთ, ბავშვს თავი და სხეული ერთდროულად არ დაუსველოთ. თავის მიდამოდან სითბო ძალიან სწრაფად იკარგება. ბავშვი რომ არ გაცივდეს, ჯერ სხეული დაბანეთ, ხოლო სხეულის დაბანის დასრულების შემდეგ თავი დაბანეთ და ამით ბანაობა დაასრულეთ.') WHERE id = '9a3356cb-31bb-4c91-8c4b-755f5e18597d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ძირითადად დედის რძით იკვებება, მისი განავალი შესაძლოა საკმაოდ თხელი კონსისტენციის იყოს. თუმცა ზოგჯერ ბავშვს შეიძლება ყაბზობა ან დიარეაც ჰქონდეს. ჩვილებში საჭმლის მონელების პრობლემები ხშირია, რადგან მათი ნაწლავები ძალიან მგრძნობიარეა. ამიტომ ისეთი მდგომარეობები, როგორებიცაა ყაბზობა, დიარეა და აირები, ფიზიოლოგიურად ნორმალურად მიიჩნევა. განსაკუთრებით ხშირია ხელოვნური ნარევით კვებისას პერიოდული ყაბზობა, რადგან ნარევი შედარებით ძნელად მოსანელებელია და დედის რძესთან შედარებით საჭმლის მომნელებელ სისტემაში უფრო დიდხანს რჩება. როგორც ყველა ბავშვის შემთხვევაში, თქვენი ბავშვის ნაწლავების მუშაობა და დეფეკაციის სიხშირეც ინდივიდუალურია. ზოგი ბავშვი განავალზე დღეში რამდენჯერმე გადის, ზოგი კი — 5 დღეში ერთხელ. თუ განავალი რბილია, ბავშვი დეფეკაციისას არ იჭინთება, წონას სათანადოდ იმატებს და მისი ზოგადი მდგომარეობა კარგია, შეშფოთების მიზეზი არ გაქვთ.') WHERE id = '315efeec-966c-4318-a08f-5aee7f235a22';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კარგ ამინდში ბავშვის გარეთ გაყვანა თქვენც დაგამშვიდებთ და მის განვითარებასაც შეუწყობს ხელს. გარეთ ჰაერისა და ხმების ცვლილება და გარემოს ზემოქმედება შეიძლება ბავშვის დამშვიდების განსხვავებული საშუალება გახდეს. ბავშვთან ერთად გარეთ გასვლა ბევრ დედას რთულად ეჩვენება. სინამდვილეში ეს მხოლოდ ჩვევის საკითხია. რაც უფრო ხშირად გახვალთ ბავშვთან ერთად გარეთ, დროთა განმავლობაში მით უფრო თავდაჯერებულად და კომფორტულად იგრძნობთ თავს. გარეთ დროის სასიამოვნოდ და კომფორტულად გასატარებლად საჭირო ნივთების თან წაღება არ დაგავიწყდეთ. მათგან ყველაზე მნიშვნელოვანია ბავშვის მოვლისთვის მუდამ საჭირო საფენი, გამოსაცვლელი საფენი და სველი ხელსახოცები. ასევე ძალიან გამოგადგებათ სათადარიგო წინსაფარი და ტანსაცმლის ერთი კომპლექტი იმ შემთხვევისთვის, თუ ბავშვმა ამოიღო. ახლა კი ყველა საქმე გვერდზე გადადეთ და ბავშვთან ერთად სუფთა ჰაერით დატკბით! 😊') WHERE id = '1dffb4b0-c92d-41f6-b1a5-adde26593736';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დედის რძის კვებითი ღირებულებისა და რაოდენობის გასაზრდელად ყველაზე მნიშვნელოვანი ფაქტორი მიღებული წყლის რაოდენობაა. რძე რომ არ შეგიმცირდეთ და მისი გამომუშავება უწყვეტად გაგრძელდეს, დღეში სულ მცირე 2-3 ლიტრი სითხე უნდა მიიღოთ და ყოველი ძუძუთი კვების შემდეგ დაკარგული სითხე შეივსოთ. საკმარისი წყლის მიღება ასევე ძალიან ეფექტური გზაა ორსულობის დროს მომატებული წონის სწრაფად დასაკლებად. ორგანიზმისთვის საჭირო ყველა საკვები ნივთიერების საკმარისი რაოდენობით მიღება რძის რაოდენობასაც გაზრდის და ჭარბი წონის მოშორებაშიც დაგეხმარებათ. ცილის ყოველდღიური მოთხოვნილების დასაკმაყოფილებლად შეგიძლიათ როგორც მცენარეული, ისე ცხოველური წარმოშობის ცილის წყაროები გამოიყენოთ. თუმცა, რადგან ბავშვი ახლა იმ პერიოდშია, როდესაც აირები ხშირად აწუხებს, სასურველია, ყურადღება მიაქციოთ მიღებული საკვების შემადგენლობას. ასევე გახსოვდეთ: რაც უფრო ხშირად აჭმევთ ბავშვს ძუძუთი, მით მეტად გაიზრდება რძის რაოდენობა და მისი გამომუშავებაც სტაბილურად გაგრძელდება.') WHERE id = '8b7bb2b5-f77d-4347-879b-67f02bacb220';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე მნიშვნელოვნად განვითარებული სმენის წყალობით, თქვენმა ბავშვმა შესაძლოა თქვენს ხმასა და დამამშვიდებელ მუსიკას ღიმილით უპასუხოს. ამასთანავე, განსაკუთრებით მოულოდნელ ხმამაღალ ბგერებზე მან შეიძლება სახის გამომეტყველება შეიცვალოს, სხეული დაჭიმოს, ხელები გვერდებზე გაშალოს, შემდეგ კი მკერდთან მიიტანოს და ტირილით გამოხატოს დისკომფორტი. ჯერ კიდევ მუცლად ყოფნისას ბავშვი თქვენს გულისცემას, როგორც თქვენს, ისე მამის ხმას და გარემოდან შემოსულ სხვადასხვა ბგერას აღიქვამდა და იმახსოვრებდა. დაბადების შემდეგ მის მეხსიერებაში შენახული ხმების მოსმენამ შეიძლება დამამშვიდებლად იმოქმედოს. განსაკუთრებით მაშინ, როცა მოუსვენრადაა, მშვიდი მუსიკის ჩართვა და მასთან ნაზი ხმით საუბარი მოდუნებაში დაეხმარება. ამ დამამშვიდებელი ეფექტის გამოსაყენებლად, განსაკუთრებით დაძინებისას, იავნანის სიმღერა ბავშვის კოგნიტური განვითარებისთვისაც სასარგებლო იქნება. სხვათა შორის, გვინდა შეგახსენოთ, რომ ბავშვებს განსაკუთრებით მოსწონთ იავნანები, რომლებშიც სიტყვები მეორდება. 😊') WHERE id = '187e9ca9-650d-40db-aa1f-2e28314ee7e9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს აირების დაგროვებასთან დაკავშირებული პრობლემები შეიძლება მრავალი სხვადასხვა მიზეზით ჰქონდეს. ამ მიზეზების ცოდნა აირებით გამოწვეულ ჭვალთან გამკლავებაში ძალიან დაგეხმარებათ. მისი ყველაზე გავრცელებული მიზეზებია ზედმეტად ხშირი და არარეგულარული კვება. ბავშვისთვის, რომლის ნაწლავური ფლორაც ჯერ კიდევ ჩამოყალიბების პროცესშია, კვების რეჟიმის დაწესება ნაწლავებში არსებული ბაქტერიების ოპტიმალურ პირობებში მუშაობას უზრუნველყოფს. ეს ბავშვს აირებით გამოწვეული ჭვალის უფრო მსუბუქად გადატანაში დაეხმარება. პირველი 6 თვის განმავლობაში ბავშვის კუჭში მხოლოდ რძის მოსანელებელი ფერმენტები გამოიყოფა. ამიტომ მას მხოლოდ დედის რძე ან შემადგენლობით დედის რძესთან მაქსიმალურად მიახლოებული ხელოვნური საკვები უნდა მისცეთ. რძისა და რძის შემცველი საკვების გარდა მიცემული შაქრიანი წყალი, ბექმეზი, თაფლი და მურაბა ბავშვის საჭმლის მომნელებელ სისტემას მხოლოდ დამატებით დატვირთავს და სარგებელს არ მოუტანს. გარდა ამისა, ზოგიერთმა მედიკამენტმა შესაძლოა აირებით გამოწვეული ჭვალი გააძლიეროს, ამიტომ ექიმთან კონსულტაციის გარეშე ბავშვს წამალი არ უნდა მისცეთ.') WHERE id = 'a098a0a5-9cf9-4830-b539-70c7b71e29f4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რა სწრაფად გადის დღეები, არა? თქვენი ბავშვი ახალშობილობის საწყის ეტაპს უკვე გასცდა და გარემოს უკეთ აღქმას იწყებს. ამ პერიოდში მას ძალიან მოსწონს, როცა ეხებიან, ეფერებიან და ხელში აჰყავთ. ბავშვისთვის, რომელიც მთელი ორსულობის განმავლობაში თქვენს სხეულში ცხოვრობდა, თქვენი მკლავები ალბათ ყველაზე საყვარელი ადგილია. განსაკუთრებით მაშინ, როცა ეშინია ან მოუსვენრადაა, მას ყველაზე სწრაფად სწორედ თქვენს მკლავებში მოქცეული უსაფრთხო ნავსაყუდელი ამშვიდებს. თქვენს ან მამის მკლავებში ძილისას ბავშვი სხეულის ფორმას ერგება და თითქოს თავისთვის პატარა ბუდეს იკეთებს. მომდევნო 1-2 თვის განმავლობაში კი თავისუფლების ძიებას დაიწყებს და თქვენს მკლავებში მოკალათების ნაცვლად, საკუთარი სივრცის გაფართოებას შეეცდება. ამიტომ, მიუხედავად იმისა, რომ ზოგჯერ შეიძლება რთული იყოს, ეცადეთ, დატკბეთ ამ დღეებით, რომლებსაც ერთმანეთთან ჩახუტებულები ატარებთ. :)') WHERE id = '3ff154d9-4a5e-4705-b55a-c139a97509b8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, რომელიც დღისით უფრო ხშირად იღვიძებს, ღამით უკვე შედარებით დიდხანს იწყებს ძილს. ბავშვის ძილის ჯანსაღი რეჟიმის ჩამოსაყალიბებლად და დამოუკიდებლად დაძინებაში დასახმარებლად, როცა მოეძინება, ჯერ კიდევ ფხიზელი ფრთხილად უნდა ჩააწვინოთ საწოლში. ძილის მხრივ ეს დადებითი ცვლილებები იმითაა განპირობებული, რომ მას უკვე შეუძლია დღისა და ღამის გარჩევა. ამ ჩვევის გასამყარებლად რამდენიმე რჩევა გვაქვს. ყველაზე მნიშვნელოვანია, დღის განმავლობაში ოთახი, სადაც ბავშვია, ნათელი და აქტიური იყოს. საღამოს კი ოთახებსა და ბავშვის გარემოს მკრთალი სინათლით უნდა ანათებდეთ, უფრო მშვიდად იმოქმედოთ და ჩურჩულით ისაუბროთ. ეს მცირე ცვლილებები ბავშვის რეგულარული და ხარისხიანი ძილის უზრუნველსაყოფად უმნიშვნელოვანესი ფაქტორებია.') WHERE id = '854dcb61-ea42-4d37-9176-c3af87b58986';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან მშობიარობის შემდგომი აღდგენის საწყისი პერიოდი უკვე დასრულდა, ემოციური მერყეობა, შფოთვა და არასრულფასოვნების განცდა თანდათან უნდა შემცირდეს. მშობიარობით გამოწვეული დაღლილობა და გამოფიტულობის შეგრძნება იკლებს, თქვენ კი ოჯახში შემოსულ ბავშვს უფრო და უფრო ეჩვევით. თუ ფიზიოლოგიური მშობიარობა გქონდათ, ეპიზიოტომიის ნაკერების მიდამოში ან ტუალეტით სარგებლობისას შესაძლოა ჯერ კიდევ ზოგჯერ დისკომფორტს გრძნობდეთ, თუმცა შარდის ბუშტისა და ნაწლავების კონტროლი მნიშვნელოვნად უნდა იყოს გაუმჯობესებული. ამასთანავე, საშოს სიმშრალე და ჰორმონულ ცვლილებებთან დაკავშირებული სექსუალური სურვილის დაქვეითება შეიძლება კიდევ გარკვეული ხნით გაგრძელდეს. მიუხედავად იმისა, რომ ჰორმონები დიდწილად დაუბრუნდა ძველ მდგომარეობას, ახალბედა დედის როლთან და შეცვლილ ცხოვრებასთან სრულად შესაგუებლად ჯერ კიდევ დრო გჭირდებათ. თუ ფიქრობთ, რომ ამ ცვლილებებთან გამკლავება გიჭირთ, აუცილებლად მიმართეთ ექიმს დახმარებისთვის.') WHERE id = '56bf65a1-60b7-4dfd-848c-0b69df37fbad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახლა როგორც თქვენი ბავშვისთვის, ისე საკუთარი თავისთვის ჯანმრთელობაზე ზრუნვა ძალიან მნიშვნელოვანია. ინფექციებთან მებრძოლი ძლიერი იმუნური სისტემის შესანარჩუნებლად მთავარი პირობა დაბალანსებული კვებაა. მშობიარობის შემდეგ დარჩენილი ზედმეტი კილოგრამების მოსაშორებლად მკაცრ და სწრაფ დიეტებს არავითარ შემთხვევაში არ უნდა მიმართოთ. ექიმმა შესაძლოა გირჩიოთ, რომ ორსულობის დროს მიღებული ვიტამინები კიდევ გარკვეული ხნით გააგრძელოთ. ორგანიზმის A, C, D და E ვიტამინებზე მოთხოვნილების დაკმაყოფილებასთან ერთად, რძის ხარისხისთვის თუთიის, ომეგას და რკინის მიღებაც აუცილებელია. ამ საჭიროებების დასაკმაყოფილებლად ძალიან მნიშვნელოვანია სეზონური და ახალი ხილისა და ბოსტნეულის მიღება. განსაკუთრებით თუთიითა და სელენით მდიდარი საკვების კვების რაციონში შეტანით, იმუნური სისტემის გაძლიერებას წელიწადის ნებისმიერ დროს შეძლებთ.') WHERE id = '8b8bfabb-ad49-47f5-ad53-ea528bf3b3c1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან ბავშვის თვალის კუნთები ჯერ სრულად არ არის განვითარებული, სიელმე შესაძლოა კიდევ გარკვეული ხნით გაგრძელდეს. ზოგჯერ შეიძლება ერთი თვალი, ზოგჯერ კი ორივე თვალი ერთდროულად გარეთა მიმართულებით გაექცეს. როდესაც ბავშვი ცდილობს, რომელიმე საგანს თვალი გააყოლოს, მისი თვალები შეიძლება ერთმანეთის პარალელურად არ მოძრაობდეს. თვალების ასეთ გადახრას ცრუ სიელმე ეწოდება. ცრუ სიელმე შეიძლება ქუთუთოების ფიზიოლოგიური სიფართოვითაც იყოს გამოწვეული. გავრცელებული მოსაზრების საწინააღმდეგოდ, ბავშვის ეს მდგომარეობა მის მხედველობასა და თვალების განვითარებაზე გავლენას არ ახდენს. ზრდასთან ერთად, ცხვირის ძვლის ჩამოყალიბებისა და ქუთუთოების შესაბამის პოზიციაში დადგომის შემდეგ, ეს გარეგნული ნიშანი ქრება. ზოგიერთი ბავშვი სახის აგებულების გამო სიელმის მქონედ გამოიყურება, სინამდვილეში კი მისი თვალები ერთი მიმართულებით იყურება. თუ ეს მდგომარეობა გაწუხებთ, დასარწმუნებლად შეგიძლიათ ბავშვი პედიატრიულ ოფთალმოლოგთან გამოიკვლიოთ.') WHERE id = 'f12655d4-4f11-4cf4-949d-d3c74399a9bf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვებში გავრცელებულ საკვებ ალერგიებს შორის ყველაზე ხშირია რძის, ანუ ძროხის რძის ცილაზე ალერგია. ეს მდგომარეობა გამოწვეულია ბავშვის ორგანიზმის ალერგიული რეაქციით ძროხის რძეში შემავალ ბეტა-ლაქტალბუმინის ცილებზე. რადგან მზა საკვები ნარევების (ფორმულის) უმეტესობა ამ ცილას შეიცავს, ასეთი ალერგია ხშირად გვხვდება ხელოვნურ კვებაზე მყოფ ბავშვებში. თუმცა ეს პრობლემა მხოლოდ ხელოვნურ კვებას არ უკავშირდება; ძუძუთი კვებაზე მყოფ ბავშვს ალერგენი შესაძლოა დედის მიერ მიღებული რძის პროდუქტებიდან, დედის რძის საშუალებითაც გადაეცეს. ამასთან, ამ ალერგიის მქონე ბევრ ბავშვს შესაძლოა თხის რძისა და სოიის შემცველი რძის მიმართაც განუვითარდეს მგრძნობელობა. ძროხის რძის ცილაზე ალერგიის ყველაზე მკაფიო ნიშნებია: პირველ თვეებში გადაჭარბებული ტირილი და ძლიერი ნაწლავური კოლიკა, კვების შემდეგ ღებინება, წონის ვერმატება, განავალში სისხლის კოლტები და ყაბზობა. თუ თქვენს ბავშვს ამ ნიშნებს ამჩნევთ და ძროხის რძის ცილაზე ალერგია გაქვთ ეჭვმიტანილი, აუცილებლად უნდა მიმართოთ ექიმს.') WHERE id = '06a7caf5-4128-4600-83b6-7c3d296c2485';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვში აირებით გამოწვეული კოლიკის თავიდან ასაცილებლად ან ტკივილის შესამსუბუქებლად რამდენიმე მეთოდი არსებობს. შეძლებისდაგვარად ძუძუთი კვება ხელს უწყობს საჭმლის მონელების კომფორტულ პროცესს, რადგან დედის რძე ბავშვის საჭმლის მომნელებელი სისტემისთვის ყველაზე შესაფერისი საკვებია. ამის წყალობით ბავშვის ნაწლავებში აირების მინიმალური რაოდენობა გროვდება და მათ დაშლაში მონაწილე ბაქტერიები უკეთ მუშაობენ. ძუძუთი კვებებს შორის ინტერვალი სულ მცირე 2 საათი უნდა იყოს. ეს ხელს უწყობს რძის ცხიმიანობის ზრდას და ბავშვის განვითარებას, ამასთან კი მიღებული რძის უფრო მარტივად მონელებასაც უწყობს ხელს. ეცადეთ, ბავშვი ზედმეტად ცხელ ან ცივ გარემოში არ გყავდეთ და რამდენიმე ფენა მჭიდრო ტანსაცმელი არ ჩააცვათ. ამ პირობებმა შეიძლება უარყოფითად იმოქმედოს ბავშვის საჭმლის მომნელებელი და სისხლის მიმოქცევის სისტემების ფუნქციონირებაზე და ნაწლავებში აირების დაგროვება გამოიწვიოს. ასევე ყოველი კვების შემდეგ ბავშვს ბოყინში უნდა დაეხმაროთ, რათა დარწმუნდეთ, რომ კუჭში ჰაერი არ დარჩა.') WHERE id = '37fe650b-ff02-444b-9514-314d6f5df25d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, რომლის ძილის რეჟიმიც თანდათან წესრიგდება, უკვე გაცილებით მოძრავი გახდა და თქვენზე რეაგირებაც დაიწყო. შესაძლოა ისეთი ქცევებით, რომლებიც ამოცნობაზე მიანიშნებს, რეაგირება მოახდინოს როგორც თქვენზე, ისე მამასა და იმ ადამიანებზე, რომლებსაც ხშირად ხედავს. ამის ერთ-ერთი მთავარი მიზეზი ისაა, რომ ახლა უკვე უკეთ ხედავს; ამის წყალობით ბავშვი გარემოს აკვირდება და ნანახზე რეაგირებას იწყებს. მე-2 თვის დასრულებასთან და წონის მატებასთან ერთად, ბავშვის ლოყები, მკლავები და ფეხები თანდათან უფრო სავსე ხდება. მოკლედ, ის უკვე აღარ ჰგავს ახალშობილს. თუმცა უნდა იცოდეთ, რომ ყველა ჯანმრთელი ბავშვი შეიძლება განსხვავებული ტემპით იზრდებოდეს და სხვადასხვა სიმაღლე და წონა ჰქონდეს. ძილის რეჟიმის ჩამოსაყალიბებლად და ხარისხიანი ძილის უზრუნველსაყოფად ღამით მისი ძალით გაღვიძება და ძუძუთი კვება უკვე აღარ არის საჭირო. თუ ბავშვს არ შია, კვებისთვის ან, როცა დისკომფორტი არ აწუხებს, საფენის გამოსაცვლელად გაღვიძებამ შეიძლება მისი ძილის ხარისხი შეამციროს.') WHERE id = '6bb455df-6ea4-41c3-8194-cb7bda47e257';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვს სწორ პოზიციაში არ აწოვებთ ძუძუს, გარკვეული პრობლემები შეიძლება წარმოიშვას არა მხოლოდ ბავშვში, არამედ თქვენს ორგანიზმშიც. ამ პრობლემებს შორის ყველაზე ხშირია მასტიტი. მასტიტი ჯანმრთელობის პრობლემაა, რომელიც რძის სადინარების დახშობით არის გამოწვეული და ახასიათებს ისეთი სიმპტომები, როგორებიცაა სიცხე, სისუსტე, დაღლილობა, ძუძუს ტკივილი და სიწითლე. ამ მდგომარეობას, ჩვეულებრივ, ინფექციაც ახლავს თან; დახშობა მაშინ ვითარდება, როცა გადავსებული რძის სადინარები არ იცლება. ასეთ შემთხვევაში, ექიმის რეკომენდაციით, შეგიძლიათ ძუძუთი კვებასთან თავსებადი ტკივილგამაყუჩებელი გამოიყენოთ. ამასთან, ტკივილის მიუხედავად, ძალიან მნიშვნელოვანია მასტიტის მქონე ძუძუს დაცლა. სათანადო მკურნალობისას მასტიტი მოკლე დროში გაივლის და შეძლებთ, ბავშვის ძუძუთი კვება უსაფრთხოდ განაგრძოთ. თუმცა აუცილებელი მკურნალობის გარეშე ძუძუში წარმოქმნილმა დახშობამ შესაძლოა ორგანიზმში რძის გამომუშავების შეწყვეტა გამოიწვიოს.') WHERE id = '68a7f9bc-02a4-47e7-80eb-cfc071e562a7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვთან ერთად უკვე ორი თვე გაიარეთ. შეგიძლიათ დარწმუნებული იყოთ, რომ მე-3 თვე წინა თვეებთან შედარებით უფრო მშვიდად ჩაივლის და თქვენც მეტი გამოცდილება გექნებათ. გარე სამყაროში ცხოვრების პირველ თვეებში ბავშვი ძალიან სწრაფად ვითარდება და შესაძლოა თვეში 700 გრამიდან 1500 გრამამდე მოიმატოს. სხვა სიტყვებით რომ ვთქვათ, მოსალოდნელია, რომ ბავშვმა კვირაში სულ მცირე 150-200 გრამი მოიმატოს. ამ გამოთვლების მიხედვით, მიმდინარე კვირის ბოლოს ბავშვის საშუალო წონა 4-დან 6 კგ-მდეა. თუ ბავშვი დღეში საშუალოდ 5-ჯერ ასველებს საფენს, ეს მიანიშნებს, რომ ის საკმარისად იკვებება და დამატებითი საკვები არ სჭირდება. ამასთან, თუ გავითვალისწინებთ, რომ მისი სიმაღლე ყოველთვიურად საშუალოდ 1.5-2 სმ-ით იზრდება, ამჟამად შესაძლოა 57-62 სმ იყოს. არ უნდა დაგავიწყდეთ, რომ ეს მონაცემები საშუალო მაჩვენებლებია და ყველა ბავშვის შემთხვევაში შეიძლება განსხვავდებოდეს; ამ საკითხში ერთადერთი სანდო კრიტერიუმი თქვენი ექიმის შეფასებაა.') WHERE id = 'c4b87e12-4678-4aea-8944-a0c3b90a105f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ხელისა და თვალის კოორდინაციისა და განვითარების ხელშესაწყობად დროა, ხელთათმანები გვერდზე გადადოთ. ხელთათმანების ხანგრძლივმა გამოყენებამ შესაძლოა უარყოფითად იმოქმედოს ბავშვის გარესამყაროსთან ურთიერთობასა და განვითარებაზე. ბავშვმა, რომელმაც უკვე დაიწყო საკუთარი ხელების აქტიურად შესწავლა და დაკვირვება, შესაძლოა თქვენ მიერ მიწოდებული ნივთი დაიჭიროს და პირში ჩაიდოს. მუშტების შეკვრითა და ხელში მოხვედრილი ყველაფრის პირში ჩადების მცდელობით ბავშვი საგნების გაცნობას ცდილობს. ეს გამოცდილება ძალიან მნიშვნელოვან როლს ასრულებს მისი ინტელექტის განვითარებაში. ინტელექტი დიდწილად ყალიბდება იმ გამოცდილების საფუძველზე, რომელსაც ბავშვი აქტიური მოძრაობებითა და ქცევებით იძენს. ხელები პირველი საშუალებაა, რომლითაც ბავშვი გარემოს შეისწავლის და გონების განვითარებისთვის საჭირო ინფორმაციას აგროვებს. ამიტომ ძალიან მნიშვნელოვანია, ამ მხრივ ხელი შეუწყოთ და წაახალისოთ. ბავშვის განვითარებას შეგიძლიათ ხელი შეუწყოთ ისეთი საგნებით, რომლებიც მის ყურადღებას მიიპყრობს და რომელთა დაჭერასაც შეძლებს — მაგალითად, სათამაშოებით, ფერადი ქსოვილებითა და ხმოვანი ჟღარუნებით.') WHERE id = '42c11358-bbe1-48ad-b54d-e26f562016b7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვის ტვინი უკვე იმდენად არის განვითარებული, რომ შეუძლია რეაგირება იავნანაზე, სიმღერაზე, მუსიკასა და გარედან შემოსულ ხმებზეც კი. ბავშვის ტვინის ჯანსაღი და სწორი განვითარებისთვის მუსიკას თქვენს ყოველდღიურ ცხოვრებაშიც უნდა დაუთმოთ ადგილი. გარდა ამისა, ბავშვისთვის სიმღერის ან იავნანას შესრულება თქვენ შორის კავშირსაც გააძლიერებს. კვლევების თანახმად, ბავშვებში, რომლებიც ადრეული ასაკიდან უსმენენ მუსიკას, ტვინისა და მეტყველების განვითარება სხვა ბავშვებთან შედარებით უფრო სწრაფად მიმდინარეობს. ასევე აღინიშნა, რომ მომავალში ამ ბავშვების მუსიკალური ინსტრუმენტებით დაინტერესების ალბათობაც იზრდება. ვინაიდან ბავშვს ჯერ კიდევ საშვილოსნოში ყოფნისას შეეძლო თქვენი ხმის სხვა ადამიანების ხმებისგან გარჩევა, მისთვის სიმღერებისა და იავნანების შესრულება საშუალებას მოგცემთ, ერთად სასიამოვნოდ და მხიარულად გაატაროთ დრო, ამასთან კი ხელს შეუწყობს მისი ლექსიკური მარაგისა და მეტყველების უნარის ჩამოყალიბებას. განსაკუთრებით მაშინ, თუ ბავშვს ჩაძინება უჭირს, კლასიკური ან მშვიდი ტემპის მუსიკა დაამშვიდებს და დაძინებას გაუადვილებს.') WHERE id = '161206e9-2801-48d5-bf23-ba2c2a393a9f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უმიზეზოდ ტირის და ბოლო დღეებში უფრო მოუსვენარი გახდა? კეთილი იყოს თქვენი მობრძანება ბავშვის განვითარების მეორე ნახტომის პერიოდში. 😊 მე-8 კვირის ნახტომი საინტერესო ეტაპია, რომლის დასრულების შემდეგაც ბავშვი ახალ უნარებს შეიძენს. განვითარების ამ ნახტომის დროს ბავშვი საკუთარი სხეულის უკეთ გაცნობას და ხელებისა და ფეხების შესწავლას დაიწყებს. უკვე შეიძლება შეამჩნიოთ, რომ ის ხელებისა და თითების წოვას ცდილობს, ხოლო როცა რაიმე საგანს მიაწვდით, მის დასაჭერად თითებს თავისუფლად იყენებს. 😊 ახალშობილობის პერიოდთან შედარებით ბავშვი უფრო მოძრავი ხდება და შესაძლოა, ხელიდან დაწვენის შემდეგ, დამოუკიდებლად გართობაც დაიწყოს. მიუხედავად იმისა, რომ ბავშვი ჯერ კიდევ ვერ ხედავს შორს მკაფიოდ, მკვეთრი ფერის საგნები, ფორმებიანი სათამაშოები და სინათლე უკვე იწყებს მისი ყურადღების მიპყრობას. რადგან ბავშვისთვის გარესამყაროს უფრო აქტიურად შესწავლის პერიოდი იწყება, შესაძლოა მისი ყურადღება მცირე ხნით ადვილად გაიფანტოს და ამის გამო ძუძუს წოვაც ნაკლებად მოუნდეს. ასეთ შემთხვევაში მისთვის უფრო სასარგებლო იქნება მშვიდ და ჩაბნელებულ ოთახში ან ჩაძინებისას ძუძუთი კვება.') WHERE id = 'ba812bc8-8097-4c97-a28f-220a769e0dd9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე იწყებს თქვენთვის გაცნობიერებული, ნამდვილი სოციალური ღიმილით პასუხის გაცემას. ამ პერიოდში მისი კისრის კუნთები სწრაფად ვითარდება, ამიტომ ხერხემლის სწორად ჩამოყალიბებისთვის ძალიან მნიშვნელოვანია, ყოველდღიურად, თქვენი მეთვალყურეობით, მცირე ხნით მუცელზე დააწვინოთ. ამავდროულად, ბავშვს აღქმის უნარიც უუმჯობესდება: მას უკვე შეუძლია თვალით გააყოლოს ფერად საგნებს და გამოცემული მცირე ბგერებით თქვენთან ურთიერთობის პირველი მცდელობები ჰქონდეს. ამ პერიოდში დაგეგმილი 2 თვის რუტინული აცრების შემდეგ გამოვლენილი მსუბუქი დისკომფორტისა და მადის დაქვეითების დროს შეგიძლიათ ბავშვი ხშირი ძუძუთი კვებითა და ჩახუტებით დაამშვიდოთ.') WHERE id = '3c33ef6c-ad69-4a43-8495-e0ff0a641f32';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის თმის გარეშე ან თმით დაბადება ნორმალურია. თუ თქვენი ბავშვი თმით დაიბადა, განსაკუთრებით ამ პერიოდში თმის ღერების სწრაფად ცვენამ შესაძლოა ოდნავ შეგაშფოთოთ. ბავშვის ამ მდგომარეობას „ტელოგენური ეფლუვიუმი“ ეწოდება და ის ჰორმონალურ ცვლილებებთან დაკავშირებული თმის ცვენაა. ორსულობის დროს ბავშვის თმის ფოლიკულები მუდმივად ზრდისა და განვითარების ფაზაშია. დაბადების შემდეგ კი ჰორმონების ზემოქმედებით თმის ფოლიკულები გარკვეული ხნით მოსვენების ფაზაში გადადის. ზოგიერთ ბავშვს შესაძლოა თმა იმდენად გასცვივდეს, რომ გამელოტებული უბნებიც კი გაუჩნდეს. თუ ბავშვს მუდმივად ერთსა და იმავე პოზაში აძინებთ, შეიძლება შეამჩნიოთ, რომ თმა უფრო მეტად სცვივა თავის იმ უბნებში, რომლებიც ბალიშს ეხება. ეს ფიზიოლოგიური თმის ცვენა საკვები ნივთიერებების დეფიციტთან დაკავშირებული არ არის. დაახლოებით 6 თვის ასაკში ცვენა თანდათან შემცირდება და გაცვენილი თმის ნაცვლად ახალი თმა დაიწყებს ამოსვლას.') WHERE id = '902d6d84-5a76-4be3-852e-11ae4442029d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში შეიძლება შეამჩნიოთ, რომ ბავშვი მუდმივად მოუსვენარია, დასამშვიდებლად ხშირად ითხოვს ძუძუს და ზოგჯერ ძუძუს მოშორებაც კი არ სურს. ეს ნიშნები შესაძლოა ბავშვის ნაწლავებში აირების დაგროვებაზე მიუთითებდეს. ეს ფიზიოლოგიური და ნორმალური მდგომარეობაა, რომელიც ზოგიერთ ბავშვში მსუბუქად მიმდინარეობს, ზოგიერთში კი კოლიკურ ტკივილს იწვევს. განსაკუთრებით მე-8 კვირის განვითარების ნახტომის დასრულებისა და ტვინის განვითარების დაჩქარების შემდეგ ბავშვის ტვინი იწყებს სხეულის კუნთების, სახსრებისა და ნერვების აღქმას. ამ პროცესამდე ბავშვი აირებს უნებლიეთ და მარტივად გამოყოფდა, ახლა კი ამ კუნთების გაცნობიერებულად მართვას ცდილობს. მას ცოტა დრო სჭირდება იმის სასწავლად, თუ როგორ დაჭიმოს და მოადუნოს აირების გამოსაყოფად საჭირო კუნთები. ვინაიდან პირველ თვეებში ბავშვი ამ კუნთებს სრულად ვერ აკონტროლებს და მუდმივად დაჭიმული აქვს, აირების მარტივად გამოყოფას ვერ ახერხებს, რის შედეგადაც ტკივილი უჩნდება. ასეთ რთულ მომენტებში უნდა დაამშვიდოთ ბავშვი და გახსოვდეთ, რომ ეს დროებითი პერიოდია. მომდევნო კვირებში, ტვინის განვითარებასთან ერთად, ბავშვი ამ კუნთების მართვას ისწავლის და აირების გამოყოფას უფრო მარტივად შეძლებს.') WHERE id = 'f2315e81-cb4e-4e16-ad43-3687f3cbaef0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, ისევე როგორც ყველა ბავშვი, სიცოცხლის პირველ თვეებში ძალიან მგრძნობიარეა. რადგან მისი იმუნური სისტემა ჯერ სრულად არ არის ჩამოყალიბებული, შესაძლოა ზოგიერთი დაავადებისგან სათანადოდ დაცული არ იყოს. მიუხედავად იმისა, რომ თვეების განმავლობაში ნანატრ პატარასთან შეხვედრის ბედნიერებას განიცდით, ბუნებრივია, მისი გაღიზიანებისა თუ დისკომფორტის დროს თქვენც განიცდიდეთ სევდასა და ემოციურ მგრძნობელობას. განსაკუთრებით მაშინ, თუ ბავშვს ჯანმრთელობის რაიმე პრობლემა შეექმნება, შესაძლოა უფრო მეტად ინერვიულოთ. თუმცა ამ ეტაპზე თავი დამნაშავედ არ უნდა იგრძნოთ და სირთულეების დასაძლევად მთელი ენერგია საკუთარ თავსა და ბავშვს უნდა მოახმაროთ. მოკლედ, ნუ ინერვიულებთ და ეცადეთ, ბედნიერი იყოთ. გახსოვდეთ, რომ თქვენი ბავშვი თქვენს ყველა ემოციას გრძნობს და მისი ემოციური მდგომარეობა პირდაპირ თქვენზეა დამოკიდებული.') WHERE id = '90453aab-3c85-45f7-a53b-d1654064425e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ძილის პოზიციის შერჩევისას ღებინებისა და დახრჩობის რისკი უნდა გაითვალისწინოთ. ბავშვისთვის ყველაზე უსაფრთხოა ზურგზე ძილი მყარ, ბრტყელ და სწორ ზედაპირზე; მუცელზე ან გვერდზე დაძინება უსაფრთხო არ არის, მაშინაც კი, თუ თავი გვერდზე აქვს მიბრუნებული. ერთსა და იმავე მდგომარეობაში დიდხანს ყოფნამ ჯერ კიდევ რბილი თავის ქალის ფორმის შეცვლა შეიძლება გამოიწვიოს. ამიტომ, როცა ბავშვს ღვიძავს და მეთვალყურეობის ქვეშაა, ხშირად შეუცვალეთ პოზა და ყოველდღიურად დააწვინეთ მუცელზე სათამაშოდ. ძილის დროს მის ზურგს უკან არ მოათავსოთ პატარა ბალიში და არ გამოიყენოთ პოზიციონერები, დახრილი საწოლი ან თავის გაბრტყელების საწინააღმდეგო ბალიში — მათ შეიძლება დახრჩობის რისკი გაზარდონ. თუ ბავშვის თავის უკანა ნაწილი ბრტყელდება ან მისი ფორმა გაწუხებთ, მიმართეთ პედიატრს.') WHERE id = '82ca4410-dc4b-42c9-8de1-8024396fe373';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვი დღის განმავლობაში სხვადასხვა მიზეზით და სხვადასხვაგვარად შეიძლება ტიროდეს. მაგრამ შეგიმჩნევიათ, რომ ტირილისას თვალებიდან ცრემლები არ მოსდის? მიუხედავად იმისა, რომ ბავშვის საცრემლე არხები და ჯირკვლები ფუნქციონირებს, ჯერჯერობით მხოლოდ იმდენ ცრემლს წარმოქმნის, რამდენიც თვალების დასაცავად და დასატენიანებლადაა საჭირო. ბავშვის საცრემლე ჯირკვლები დაბადებისთანავე სწრაფი განვითარების ეტაპზე გადადის და საშუალოდ 2-3 თვის ასაკში იმდენად ვითარდება, რომ ცრემლების გამოყოფა იწყება. ზოგიერთ შემთხვევაში, ბავშვების დაახლოებით 5-6%-ს შეიძლება საცრემლე არხების დახშობა ჰქონდეს. ეს მდგომარეობა შეიძლება გამოვლინდეს თვალებში გამონადენის დაგროვებით, ცრემლდენით, წამწამების შეწებებით, ჩირქოვანი გამონადენითა და თვალების ირგვლივ შეშუპებით. საცრემლე არხის დახშობის მიზეზი იმ გარსის გაუხსნელობაა, რომელიც საცრემლე პარკის ცხვირში გამავალ ნაწილს ფარავს. მკურნალობის გარეშე ბავშვის თვალები მიკრობების მიმართ უფრო მგრძნობიარე ხდება. ამიტომ, თუ ბავშვს ამ ნიშნებს შეამჩნევთ, დროის დაკარგვის გარეშე უნდა მიმართოთ ოფთალმოლოგს.') WHERE id = 'e03b8fab-73de-4cff-bd15-34280044bd83';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, გაინტერესებდეთ, უნდა მისცეთ თუ არა ბავშვს საწოვარა. ბავშვი ძლიერი წოვის რეფლექსით იბადება. ამას „ორალური პერიოდი“ ეწოდება და დაახლოებით 2 წლამდე გრძელდება. ამერიკის პედიატრიის აკადემია 1 წლამდე საწოვარას გამოყენებას რეკომენდაციას უწევს, რადგან მიიჩნევს, რომ ის ჩვილის უეცარი სიკვდილის სინდრომის პრევენციას უწყობს ხელს. ამ პერიოდში ბავშვის ძლიერი წოვის რეფლექსი როგორც კვების, ისე ემოციური მოთხოვნილებების დაკმაყოფილებას ემსახურება. საწოვარას გამოყენება შეიძლება დაგეხმაროთ ბავშვის წოვის ფიზიკური მოთხოვნილების დაკმაყოფილებაში, ემოციური უსაფრთხოების განცდის შექმნასა და დამშვიდებაში, ასევე დედის ძუძუს კვების გარდა სხვა მიზნით გამოყენების შეზღუდვაში. თუმცა საწოვარას ხანგრძლივი გამოყენება შეიძლება ჩვევად იქცეს. თუ გამოყენების ხანგრძლივობას არ შეზღუდავთ, ამან შეიძლება ბავშვის კვებაზე იმოქმედოს და შედეგად განვითარების შეფერხება გამოიწვიოს. გარდა ამისა, საწოვარას ხანგრძლივმა გამოყენებამ შესაძლოა კბილების წყობის დარღვევა და მეტყველების შეფერხება გამოიწვიოს.') WHERE id = '9bf80a49-be8d-491a-9e0b-6671644690ad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვს ძუძუთი კვებავთ, შესაძლოა, მენსტრუაცია ჯერ არ დაგწყებიათ. მეძუძურ დედებში მენსტრუაცია შეიძლება მშობიარობიდან დაახლოებით ექვსი-რვა კვირის შემდეგ აღდგეს, თუმცა ეს პერიოდი ზოგჯერ 24 თვემდეც გრძელდება. მენსტრუაციის განახლების დრო ყველა ქალისთვის განსხვავებულია. ამის მიზეზი თქვენს ორგანიზმში რძის წარმოქმნასა და გამოყოფაზე პასუხისმგებელი ჰორმონების — პროლაქტინისა და ოქსიტოცინის — არსებობაა. სისხლში მაღალი კონცენტრაციით არსებული პროლაქტინი, რომელიც რძის წარმოქმნას უზრუნველყოფს, თრგუნავს კვერცხუჯრედების განვითარებისთვის საჭირო რეპროდუქციული ჰორმონების გამოყოფას. თუ საკვერცხეებში კვერცხუჯრედი არ მწიფდება, მენსტრუაციაც ვერ დაიწყება. ამიტომ შეუძლებელია ზუსტად განისაზღვროს, როდის აღუდგებათ მენსტრუაცია დედებს, რომლებიც ბავშვს ძუძუთი კვებავენ.') WHERE id = 'ed5d9752-70a1-4d4a-938d-22777462f998';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'განსაკუთრებით ძუძუთი კვების პერიოდში შეიძლება მედიკამენტების მიღებასთან დაკავშირებით გარკვეული შეშფოთება გქონდეთ. ორსულობის მსგავსად, ძუძუთი კვების პერიოდშიც ორგანიზმს ბავშვის დასაცავად სხვადასხვა მექანიზმი აქვს. დედის რძე საოცარი საკვებია, რომელიც თქვენს ორგანიზმში ბავშვის ყველა საჭიროების შესაბამისად წარმოიქმნება. ორგანიზმში არსებობს დამცავი სისტემები, რომლებიც სისხლში არსებული ზოგიერთი მავნე ნივთიერების რძის სადინარებში გადასვლას ხელს უშლის. ამ ფიზიოლოგიურ მექანიზმს ჰემატო-მამარული ბარიერი ეწოდება. ზოგიერთი მედიკამენტი ამ ბარიერს გადის, ზოგი კი ვერ გადალახავს და რძეში არ ხვდება. ზოგი ექიმი ძუძუთი კვების პერიოდში მედიკამენტების გამოყენების საკითხს მკაცრად უდგება, სხვები კი სარგებლისა და რისკის თანაფარდობას აფასებენ. ამიტომ აუცილებლად უნდა გაიაროთ კონსულტაცია ექიმთან, ჰკითხოთ იმ მედიკამენტების შემადგენლობის შესახებ, რომელთა მიღებასაც აპირებთ, და გაარკვიოთ, თავსებადია თუ არა ისინი ძუძუთი კვებასთან.') WHERE id = '23d4091f-e3fa-4f6e-82ab-2f668868b04f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ტირილი ბავშვის კომუნიკაციის უმნიშვნელოვანესი საშუალებაა. ბავშვმა შეიძლება იტიროს გაზებით გამოწვეული ტკივილის, შიმშილის, ძილიანობის, სიცივის, ოფლიანობის, ხელში აყვანის სურვილისა და მრავალი სხვა მიზეზის გამო. ტირილის ხასიათიც ბავშვის საჭიროების მიხედვით განსხვავდება. ალბათ, დაკვირვების შედეგად უკვე იწყებთ იმის გაგებას, თუ რა საჭიროების გამო ტირის ბავშვი. თუ ბავშვი შიმშილის გამო ტირის, კვების შემდეგ დამშვიდდება. ძალიან მნიშვნელოვანია, კვება ბავშვის მოთხოვნის შესაბამისად დაარეგულიროთ. ბავშვი შეიძლება ძილში შეკრთეს, გაიღვიძოს და ატირდეს. ასეთ შემთხვევაში მის დასამშვიდებლად შეგიძლიათ ნაწილობრივი შეხვევის მეთოდი გამოიყენოთ — ხელები თხელი საბნით ისე შეუხვიოთ, რომ ზედმეტად მჭიდრო არ იყოს. ზოგჯერ, მიუხედავად იმისა, რომ ბავშვის ყველა საჭიროებას აკმაყოფილებთ, ის ხელში აყვანისთანავე მშვიდდება, ხოლო დაწვენისას კვლავ ტირის. ეს ფიზიკური კონტაქტის მოთხოვნილებითაა გამოწვეული. სრულიად ბუნებრივია, რომ ბავშვი, რომელმაც 9 თვე საშვილოსნოში გაატარა, დაბადებიდან პირველ თვეებში ფიზიკურ კონტაქტს ეძებდეს. ნუ იდარდებთ, რომ ბავშვი ხელში აყვანას მიეჩვევა. ერთადერთი ადგილი, სადაც ბავშვი თავს უსაფრთხოდ იგრძნობს და თქვენს სურნელსა და სითბოს შეიგრძნობს, თქვენი მკლავებია.') WHERE id = 'd2ed38a5-2867-473a-a048-a7488c8a0f81';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის საოფლე ჯირკვლები ჯერ სრულად არ არის განვითარებული, ამიტომ მას სხეულის ტემპერატურის დასარეგულირებლად სათანადოდ ოფლიანობა არ შეუძლია. ამის გამო მოერიდეთ ბავშვის ზედმეტად თბილ გარემოში ყოფნასა და საჭიროზე მეტად ჩაცმას. ბავშვისთვის ოთახის დაახლოებით 22-24 გრადუსი ტემპერატურა საკმარისია. სახლში არ არის საჭირო მისთვის ჟილეტის, ქურთუკის, წინდებზე ჩასაცმელი ჩუსტებისა და სხვა მრავალი ფენის ჩაცმა. საკმარისია, ბოდეზე ან თხელ საცვალზე კომბინეზონი ჩააცვათ და ფეხებზე ერთი წყვილი წინდა გაუკეთოთ. თუმცა, თუ ბავშვი ნაადრევად დაიბადა, სხეულის სითბოს სრულად შენარჩუნება შეიძლება ვერ შეძლოს, ამიტომ შესაძლოა, ერთი ფენით მეტი ტანსაცმელი დასჭირდეს. იმის გასაგებად, საკმარისად აცვია თუ არა, შეეხეთ კისრის უკანა მხარეს ან მუცელზე. ბავშვებს ხელები და ფეხები ხშირად ცივი აქვთ, ამიტომ ამ ნიშნით იმის განსაზღვრა, სცივათ თუ არა, შეიძლება შეცდომაში შეგიყვანოთ. ბავშვის სხეული სითბოს ძირითადად თავის არედან კარგავს. ამის თავიდან ასაცილებლად სახლში შეგიძლიათ თხელი ქუდი დაახუროთ. თუმცა გახსოვდეთ, რომ ღამით ძილისას ბავშვი აუცილებლად უქუდოდ უნდა დააწვინოთ, რადგან ქუდმა შეიძლება ჰაერის მიწოდება შეუზღუდოს და დახრჩობის საფრთხე შექმნას.') WHERE id = '48c1b6b4-184f-478a-85ac-ef677c12d146';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ყველაზე განვითარებული შეგრძნება ჯერ კიდევ შეხებაა. ამიტომ ბავშვთან მუდმივი კანით კანთან კონტაქტი თქვენს შორის კავშირს გააძლიერებს. შეხების შეგრძნება, რომელსაც ბავშვის სიცოცხლის პირველ თვეებში უდიდესი მნიშვნელობა აქვს, ერთ-ერთი უმნიშვნელოვანესი ფაქტორია, რომელიც მას გარემოსთან ურთიერთობასა და მის აღქმაში ეხმარება. ამ მხრივ, ბავშვისთვის მასაჟის გაკეთება, მოფერება და კანით კანთან კონტაქტის უზრუნველყოფა თქვენს შორის კავშირის გასავითარებლად ყველაზე ეფექტურ და ბუნებრივ მეთოდებად მიიჩნევა. ბავშვის ურთიერთობა გარემოსთან მაშინ იწყება, როდესაც მას ეხებიან, ეფერებიან და ხელში აჰყავთ, რაც მის ფსიქოსოციალურ განვითარებასაც უწყობს ხელს. ხალხში გავრცელებული შიშის გამო, თითქოს ბავშვი ხელში აყვანას მიეჩვევა, მის აყვანაზე უარის თქმა სრულიად მცდარია და დედასა და ბავშვს შორის ურთიერთობას აზიანებს. ბავშვის შეხების შეგრძნების სტიმულირება და სხეულებრივი კონტაქტის შენარჩუნება მას უსაფრთხოების განცდის ჩამოყალიბებაში ეხმარება, ამასთან, ზრდის რძის გამომუშავებას და ხელს უწყობს წარმატებულ ძუძუთი კვებას. გარდა ამისა, კვლევების მიხედვით, ბავშვებში, რომლებთანაც ხშირად აქვთ ფიზიკური კონტაქტი და რეგულარულად უკეთებენ მასაჟს, სხვებთან შედარებით წონისა და სიმაღლის უფრო მეტი მატება შეინიშნება.') WHERE id = 'aa7f3500-7164-43a7-9fa5-208e7d522806';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როტავირუსული ინფექცია, რომელიც ბავშვებში უსიამოვნო სუნის მქონე დიარეით, შეუჩერებელი ღებინებითა და ცხელებით ვლინდება, თქვენი ბავშვისთვის, განსაკუთრებით სიცოცხლის პირველ თვეებში, შეიძლება ძალიან საშიში იყოს. ამ ვირუსს მრგვალი ფორმის გამო „როტა“ ეწოდა და ის კუჭის მჟავის მიმართ მდგრადია. როტავირუსი კუჭს გაივლის, წვრილ ნაწლავამდე აღწევს, იქ არსებულ უჯრედებს აინფიცირებს და გამრავლებას იწყებს. ვირუსის შეტევაზე რეაგირებისას იმუნურმა სისტემამ სხეულის ტემპერატურა შეიძლება 39°C-მდე გაზარდოს. როტავირუსული ინფექციის ნიშნები ვირუსით ინფიცირებიდან 48 საათის განმავლობაში იწყება. ის შეიძლება გამოვლინდეს როგორც თავისით გამავალი წყლიანი დიარეა, ასევე ძლიერი ცხელებითა და ღებინებით მიმდინარე დიარეა, რომელიც ორგანიზმში სითხის სერიოზულ დანაკარგს იწვევს. ვინაიდან ამ ინფექციამ შეიძლება ორგანიზმში სითხის მნიშვნელოვანი დანაკარგი გამოიწვიოს, განსაკუთრებით ბავშვებში შესაძლოა საჭირო გახდეს ჰოსპიტალიზაცია და ინტრავენური მკურნალობა. მიუხედავად იმისა, რომ როტავირუსის საწინააღმდეგო ვაქცინა ბავშვს ამ ინფექციისგან 100%-ით ვერ იცავს, აცრა ძალიან მნიშვნელოვანია, რადგან ინფიცირების შემთხვევაში დაავადება გაცილებით მსუბუქად მიმდინარეობს. თითქმის ყველა ექიმი ამ ვაქცინის გაკეთებას დაჟინებით გირჩევთ.') WHERE id = '1b640d9c-64b4-46e3-adef-12469bcc8075';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის პერიოდულმა, უხვმა ღებინებამ შეიძლება შეგაშფოთოთ. ასეთი ღებინება, ჩვეულებრივ, სიცოცხლის პირველ თვეებში, კვებიდან მცირე ხნის შემდეგ ხდება. პრობლემა, რომელიც დაბადებიდან რამდენიმე დღეში იწყება, კუჭსა და საყლაპავს შორის არსებული სფინქტერის (სარქველის) ჯერ კიდევ არასრული მომწიფებითაა გამოწვეული. განვითარებასთან ერთად ღებინება შეიძლება 3-4 თვეში შეწყდეს, თუმცა ზოგჯერ ბავშვის ორი წლის ასაკამდე გრძელდება. კვებისას ჰაერთან შერეული რძე ან ხელოვნური ნარევი შეიძლება საყლაპავში უკან ამოვიდეს, რაც ღებინების ალბათობას ზრდის. თუ თქვენს ბავშვს მსგავსი რამ ემართება, სასურველია გადახედოთ, როგორ კვებავთ მას. ძუძუთი ან ხელოვნური ნარევით კვებისას ბავშვის სრულიად ჰორიზონტალურ მდგომარეობაში ყოფნამ, ჰაერის ყლაპვამ, ძალიან ნელა ან სწრაფად წოვამ შეიძლება ღებინება გააძლიეროს. ამასთანავე, კვების შემდეგ ბავშვისთვის ბოყინის ამოშვებაში დახმარება ღებინების შემთხვევებს მნიშვნელოვნად შეამცირებს.') WHERE id = '5fefb883-23f7-42f1-b985-be875f76a7d5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ინფექციებისგან ბავშვის ყველაზე ძლიერი დაცვა თქვენი რძე და ჩატარებული აცრებია. დაბადების მომენტიდანვე რძით მიღებული ანტისხეულები საფუძველს უყრის მის იმუნურ სისტემას და დაავადებებისგან იცავს. თუმცა გახსოვდეთ, რომ ეს ბუნებრივი დაცვა მცირე ხნის შემდეგ მოქმედებას კარგავს. თუ ამ ეტაპზე ბავშვს არ აცრით, მიკრობებსა და ვირუსებთან შეხვედრისას მისი ორგანიზმი შესაძლოა მათთან საბრძოლველად საკმარისად ძლიერი არ აღმოჩნდეს. მსოფლიოში ყოველწლიურად მილიონობით ადამიანი იღუპება იმ დაავადებების გამო, რომელთა თავიდან აცილებაც ვაქცინაციით არის შესაძლებელი. ბავშვობისა და ჩვილობის პერიოდში გავრცელებულ დაავადებათა დიდი ნაწილი სწორედ ინფექციურია. ზოგიერთმა მათგანმა შეიძლება სერიოზული ეპიდემიები და გართულებები გამოიწვიოს. ამიტომ, ძვირფასო დედა, ბავშვის აცრების კალენდრის ზუსტად დაცვა ძალიან მნიშვნელოვანია, რათა მას მთელი ცხოვრების განმავლობაში ძლიერი იმუნიტეტი ჰქონდეს.') WHERE id = '9a1ea20d-ced6-455d-9f64-c58e6cf75bea';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადების შემდეგ, განსაკუთრებით პირველი წლის განმავლობაში, ბავშვი წარმოუდგენელი სისწრაფით ვითარდება. ზოგჯერ შეიძლება მოგეჩვენოთ, რომ ის ერთ დღეში ან თუნდაც ერთ ღამეში გაიზარდა. თუმცა ზრდის ეს პროცესი ხშირად შეუმჩნევლად არ მიმდინარეობს. სწრაფი ზრდის ეტაპს გარკვეული ფიზიოლოგიური გავლენა ახლავს. დროდადრო ბავშვს შეიძლება შეატყოთ ძილის პრობლემები, ტირილის შეტევები ან კვების რეჟიმის დარღვევა; ასევე შეიძლება შეხვდეთ მდგომარეობებს, რომელთა მიზეზსაც ვერ ადგენთ. ამ მოვლენებს, რომელთა შესახებაც ბევრმა მშობლობამდე არაფერი იცის, თუმცა თითქმის ყველა ბავშვთან გვხვდება, ზრდის ნახტომები ეწოდება. როგორც ყველა ბავშვის შემთხვევაში, თქვენი პატარას ზრდის ნახტომებიც სრულიად ნორმალური და აუცილებელი პროცესია. ამ პერიოდებში ბავშვი არა მხოლოდ ფიზიკურად ვითარდება სწრაფად, არამედ გარესამყაროს შესახებ ახალ აღმოჩენებს აკეთებს და ახალ უნარებს იძენს.') WHERE id = 'bf8343fd-c467-4ff0-b59e-adf0ca316a49';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კანი ზრდასრულის კანთან შედარებით უფრო თხელი, ძალიან ნაზი და გარე ზემოქმედების მიმართ უფრო მგრძნობიარეა. ამასთანავე, ცხიმოვანი შრე ჩვენთან შედარებით ნაკლები აქვს, ამიტომ სიცივესაც უფრო რთულად იტანს. შესაბამისად, განსაკუთრებით სიცოცხლის პირველ თვეებში, მისი ჩაცმისას სიფრთხილე უნდა გამოიჩინოთ და ტანსაცმლის შემადგენლობას ყურადღება მიაქციოთ. რადგან ქსოვილი ბავშვის კანს უშუალოდ ეხება, უპირატესობა ბამბისგან დამზადებულ რბილ და ბუნებრივ ქსოვილებს უნდა მიანიჭოთ. შერჩეული ტანსაცმელი საკმარისად თავისუფალი უნდა იყოს, რომ ბავშვმა კომფორტულად იმოძრაოს და ხელებისა და ფეხების მოძრაობა არ შეეზღუდოს. სისხლის მიმოქცევა რომ არ დაირღვეს, წინდების შერჩევისასაც აირჩიეთ რბილი მოდელები, რომელთა რეზინი ზედმეტად არ უჭერს. საყიდლებისას გირჩევთ, აუცილებლად მიაქციოთ ყურადღება, რომ ტანსაცმლის სახელოები, საყელო და წელის ნაწილი უხეში არ იყოს, ასევე შეამოწმოთ ისეთი დეტალების ხარისხი, როგორებიცაა კნოპები და ღილები.') WHERE id = '03d19ce6-58a4-42e4-a4c9-562747272e51';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფერების გავლენა ბავშვის ფსიქოლოგიაზე, ენერგიასა და განვითარებაზე მეცნიერულად დადასტურებული ფაქტია. განსაკუთრებით ახლა, როცა თქვენი ბავშვი უკვე იწყებს ფერების გარჩევას, ის გარემოში არსებული ტონების მიმართ უფრო მგრძნობიარე ხდება. ფერების გავლენა მხოლოდ განწყობით არ შემოიფარგლება. ზოგიერთ ფერს, რომელსაც მის ოთახში, ტანსაცმელსა და სათამაშოებშიც კი გამოიყენებთ, შეუძლია ტვინის გააქტიურება, ძილის ჩვევებზე გავლენის მოხდენა და მეხსიერების გაძლიერება. ამიტომ ფერების ენის ცოდნა ძალიან მნიშვნელოვანია. მაგალითად, ლურჯის მუქმა ტონებმა შესაძლოა მძიმე და დამთრგუნველი გარემო შექმნას, ხოლო ღია ტონები ბავშვზე დამამშვიდებლად მოქმედებს და მის ნერვულ სისტემას ასვენებს. აგურისფერი და მიწისფერი ტონები ბავშვს სიმშვიდის განცდას უქმნის, მუქმა წითელმა კი შეიძლება დაძაბულობა გამოიწვიოს. ზოგადად, თბილი ფერები თქვენი ბავშვისთვის ენერგიულ გარემოს ქმნის, ცივი ფერები კი უფრო მეტად დამამშვიდებელი და მომადუნებელი ეფექტით გამოირჩევა.') WHERE id = '1a3eb5d8-5f3e-4a88-8c08-5b1025f3faf7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ მენსტრუაცია დაგეწყოთ, შესაძლოა შეამჩნიოთ გარკვეული ცვლილებები რძის რაოდენობასა და ბავშვის რეაქციაში დედის რძეზე. ამის მიზეზია ის, რომ მენსტრუალური ციკლის მარეგულირებელი ჰორმონული ცვლილებები მცირედ მოქმედებს რძის გამომუშავებასა და შემადგენლობაზე. თუმცა ამ ცვლილებების გამო ძუძუთი კვებაზე უარი არ უნდა თქვათ. მენსტრუაციის დაწყება არ ნიშნავს, რომ ბავშვი ძუძუს უნდა მოსწყვიტოთ — ამ პერიოდში ძუძუთი კვება სრულიად უსაფრთხოა. განსაკუთრებით ოვულაციის დღეებში რძეში ნატრიუმისა და ქლორიდის შემცველობა იზრდება, ხოლო კალიუმისა და ლაქტოზის რაოდენობა მცირდება. ამის გამო რძეს შესაძლოა ოდნავ უფრო მარილიანი ან ნაკლებად ტკბილი გემო ჰქონდეს. ამასთან, ოვულაციის პერიოდში და სისხლდენის დაწყებამდე ესტროგენისა და პროგესტერონის დონეების ცვლილების გამო შესაძლოა მკერდის სისავსე და მგრძნობელობა იგრძნოთ.') WHERE id = '94e7a1fa-9551-4f9b-be28-3651b7e35a86';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, როცა მთელი თქვენი ყურადღება ბავშვზეა გადატანილი, ახალი ორსულობის ფიქრი შესაძლოა შემაშინებელი მოგეჩვენოთ. მიუხედავად იმისა, რომ ძუძუთი კვების პერიოდში ნაყოფიერება მცირდება, ის სრულად არ ქრება. მშობიარობის შემდეგ პირველ თვეებში ოვულაციის პროცესი, ისევე როგორც ორსულობის დროს, გარკვეული ხნით ჩერდება. თუმცა გავრცელებულ მოსაზრებაზე, რომ „რძე ორსულობისგან იცავს“, სრულად დაყრდნობა და კონტრაცეფციაზე უარის თქმა არასწორია. თუ თქვენი ბავშვი მხოლოდ დედის რძით იკვებება, მენსტრუაცია შესაძლოა 6-8 თვით დაგიგვიანდეთ. მაგრამ თუ ბავშვი ხელოვნურ ნარევს იღებს, ოვულაცია და მენსტრუაცია შეიძლება მშობიარობიდან 3 კვირის შემდეგ აღდგეს. გახსოვდეთ, რომ მენსტრუაციის არქონის შემთხვევაშიც კი დაორსულების რისკი დაახლოებით 1-2%-ია და ოვულაცია შესაძლოა პირველ სისხლდენამდეც მოხდეს. ამიტომ, თუ ახალ ორსულობას არ გეგმავთ, ყოველი სქესობრივი კავშირის დროს კონტრაცეფციის მეთოდის გამოყენება მნიშვნელოვანია.') WHERE id = 'a67e120d-50f6-40f7-8148-f8a30d4ac88d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ზურგზე ხელის გადასმისას შეგრძნებულმა სიხისტემ ან თმიანობამ შესაძლოა შეგაშფოთოთ. ხალხში ამას „ეკალს“ უწოდებენ, თუმცა ის არ უნდა აგერიოთ ზრდასრულებში არსებულ ქუსლის დეზში და, როგორც წესი, საშიში არ არის. ბავშვებში საკმაოდ გავრცელებული, თუმცა ხშირად შეუმჩნეველი ეს თმიანობა უფრო მეტად გოგონებში გვხვდება და ჩვეულებრივ ბანაობისას შეიგრძნობა. მიუხედავად იმისა, რომ სამედიცინო თვალსაზრისით მისი მავნებლობა დადასტურებული არ არის, თუ ეს მდგომარეობა გაწუხებთ ან ფიქრობთ, რომ ბავშვს დისკომფორტს უქმნის, მის დასამშვიდებლად შეგიძლიათ მასაჟი გაუკეთოთ. მასაჟის დროს უნდა გამოიყენოთ ქიმიური დანამატებისგან თავისუფალი ბუნებრივი ზეთები, რომლებიც ბავშვის ნაზ კანს არ გააღიზიანებს. ასეთი ზეთებით მასაჟი ბავშვსაც დაამშვიდებს და ამ თმის მოცილებასაც შეუწყობს ხელს. შესაფერისი ზეთებისა და მოვლის შესახებ რჩევისთვის შეგიძლიათ ექიმსაც მიმართოთ.') WHERE id = 'd55543a0-5e2c-48fc-9829-ce7e9fdddd6c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როგორც ყველა ბავშვის შემთხვევაში, თქვენი ბავშვის ჩაცმაც შეიძლება ნამდვილ თავგადასავლად იქცეს. რადგან პატარა ერთ ადგილას არ ჩერდება და გამუდმებით ამოძრავებს ხელ-ფეხს, განსაკუთრებით ზამთრის თვეებში მისი ტანსაცმლის გამოცვლას შეიძლება საკმაოდ დიდი დრო დასჭირდეს. ამიტომ უმჯობესია, შეარჩიოთ პრაქტიკული, ადვილად ჩასაცმელი სამოსი, რომელიც დროს დაგიზოგავთ. საყიდლების დროს უპირატესობა მიანიჭეთ ფართოყელიან ტანსაცმელს, რომელშიც ბავშვის თავი თავისუფლად გაივლის. რადგან ბავშვის კანი ზრდასრულის კანზე გაცილებით მგრძნობიარეა, აუცილებლად უნდა აირჩიოთ ბამბის შემცველი და ჰიპოალერგიული ნაწარმი. უსაფრთხოებაც ძალიან მნიშვნელოვანია: მოერიდეთ ისეთ დიდ ღილებს, რომელთა გადაყლაპვაც ბავშვს შეუძლია, და უხეშ ელვაშესაკრავებს, რომელთა ბოლო ქსოვილით არ არის დაფარული. ცნობისმოყვარეობის გამო ბავშვებმა შეიძლება ეს ღილები მოაგლიჯონ და პირში ჩაიდონ. ამასთან, ზედმეტი ლენტები, ზონრები და მაქმანებიც ამ პერიოდისთვის არცთუ შესაფერისი არჩევანია.') WHERE id = 'b8aa2eab-ff56-4ab9-8b20-121fbd2d3ec4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ჩვენს ქვეყანაში ანემიის ყველაზე გავრცელებული სახეობა რკინადეფიციტური ანემიაა. რკინა ადამიანის ორგანიზმისთვის ძალიან მნიშვნელოვანი ელემენტია. განსაკუთრებით სწრაფი ზრდის პერიოდებში უჯრედებისა და ქსოვილების მოთხოვნილება რკინაზე იზრდება. ამიტომ რკინის დეფიციტი ხშირად გვხვდება 6-24 თვემდე პერიოდში, როცა ბავშვები ყველაზე სწრაფად იზრდებიან. სანამ თქვენი ბავშვი 6 თვის გახდება, თუ ის დედის რძით იკვებება, მნიშვნელოვანია, თქვენს რაციონში რკინის შემცველი საკვები შეიტანოთ. ხელოვნური ნარევით კვების შემთხვევაში ყურადღება უნდა მიაქციოთ ნარევში რკინის შემცველობას, რის შესახებაც შეგიძლიათ ექიმს რჩევა ჰკითხოთ. 6 თვის შემდეგ მხოლოდ დედის რძე საკმარისი აღარ არის, ამიტომ დამატებით კვებაზე გადასვლისას ბავშვს რკინით მდიდარი მენიუ უნდა შეუდგინოთ. საუზმეზე მიცემული კვერცხის გული რკინით ძალიან მდიდარია. ასევე არ დაგავიწყდეთ ბავშვისთვის მომზადებულ ბოსტნეულის სუპებში ცხვრის ან საქონლის ხორცის დამატება.') WHERE id = 'd050305e-c358-4c29-9151-2db694755a43';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თითოეული ბავშვისთვის საუკეთესო საკვები საკუთარი დედის რძეა, რადგან ის სწორედ ბავშვის საჭიროებების შესაბამისად წარმოიქმნება. თუმცა ზოგჯერ ჯანმრთელობასთან დაკავშირებული ან პირადი მიზეზების გამო დედები ძუძუთი კვებას ვერ ახერხებენ. ასეთ შემთხვევებში საუკეთესო ალტერნატივაა სპეციალურად ჩვილებისთვის შექმნილი ხელოვნური საკვები ნარევები. ეს ნარევები ძროხის ან თხის რძის შემადგენლობის თანამედროვე ტექნოლოგიებით შეცვლისა და დედის რძესთან მაქსიმალურად მიახლოების გზით მზადდება. მიუხედავად იმისა, რომ ნატურალური ძროხის რძე აგებულებით დედის რძეს ჰგავს, კვლევები აჩვენებს, რომ ის ძნელად მოსანელებელია და მისი შემადგენლობა ჩვილებისთვის შესაფერისი არ არის. ამიტომ ექიმები 1 წლამდე ასაკის ბავშვებისთვის ძროხის რძის მიცემას არ გვირჩევენ. ბაზარზე ბავშვის სიცოცხლის პირველი ერთი წლისთვის განკუთვნილი ხელოვნური საკვების სხვადასხვა სახეობა არსებობს, მათ შორის ძროხის რძეზე ან სოიაზე დამზადებული და ჰიდროლიზებული ცილის შემცველი ნარევები. ძროხის რძეზე დამზადებული ნარევები ბავშვისთვის საჭირო ნივთიერებებით არის გამდიდრებული, ხოლო სოიაზე დამზადებული ნარევები, როგორც წესი, ძროხის რძის ცილაზე ალერგიის მქონე ბავშვებისთვის არის რეკომენდებული.') WHERE id = '54371049-7cba-412e-931d-3ce67181ed5e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე უფრო მოძრავია! 😊 ამის ერთ-ერთი მთავარი მიზეზი, რა თქმა უნდა, მისი განვითარებადი კუნთებია. ალბათ უკვე შენიშნეთ, რომ 3 თვის ასაკთან მიახლოებისას თქვენი ბავშვი უფრო აქტიური გახდა. ამ ეტაპზე ის თავის სწორად დაჭერას იწყებს და დაწოლილ მდგომარეობაში დაახლოებით 45 გრადუსამდე წამოწევაც შეუძლია, რაც სწრაფი განვითარების პერიოდის დაწყებაზე მიუთითებს. გაზრდილი აქტიურობის კიდევ ერთი მიზეზი გარემოს შესწავლის სურვილია. ბავშვი უკვე უკეთ არჩევს ფერებს და განვითარებული მხედველობის დახმარებით გარემოს გაცნობა სურს. ამ პერიოდში, რომელსაც აღმოჩენების თვესაც უწოდებენ, მოსალოდნელია ისეთი უნარების გამოვლენა, როგორებიცაა საკუთარი ხელების თვალიერება, თქვენ მიერ ნაჩვენები საგნების დაჭერის მცდელობა და მზერით თქვენი მოძრაობის მიყოლა. ბავშვმა უკვე უკეთ დაიწყო თქვენი და მამის გარჩევა და შესაძლოა, თქვენთან უფრო ხშირად დაამყაროს თვალით კონტაქტი. სმენითი და მხედველობითი ყურადღების განვითარების გამო, ამ თვეში საუბრისას შეიძლება ისეთი მზერით შემოგხედოთ, თითქოს თქვენი ესმის. რა თქმა უნდა, ამ ყველაფერს თავისი შედეგებიც მოჰყვება. მაგალითად, რადგან ბავშვი გარემოს შესწავლას ანიჭებს უპირატესობას, შესაძლოა, უკვე ნაკლები ეძინოს. ასევე მოემზადეთ ბედნიერების დაუსრულებელი შეძახილებისთვის! 😊') WHERE id = '5ea89e0c-0d1c-402a-8337-a40bace39e26';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დედის რძე შესანიშნავი საკვებია. ეს საოცარი საკვები ბავშვის ზრდასთან ერთად მისი საჭიროებების შესაბამისად იმატებს და იცვლება. რძის წარმოსაქმნელად საჭირო სარძევე სადინარების ჩამოყალიბება ორსულობის პირველივე პერიოდიდან იწყება. პირველი ტრიმესტრის განმავლობაში განვითარებადი სარძევე ჯირკვლები განსაკუთრებით მშობიარობის მოახლოებისას ივსება რძით და ბავშვის დაბადებისთვის ემზადება. მშობიარობამდე რძის სადინარებში ჩასვლის შეფერხებასა და დამატებითი რძის წარმოქმნის შეჩერებას პლაცენტის მიერ გამოყოფილი ჰორმონები არეგულირებს. ძუძუთი კვების პერიოდში კი ორგანიზმში გამოყოფილი ჰორმონები — ოქსიტოცინი და პროლაქტინი — რძის უწყვეტ გამომუშავებასა და ძუძუთი კვების პროცესს უზრუნველყოფს. თქვენი რძე ბავშვის პირველი 6 თვის განმავლობაში ცილის, ცხიმის, რკინისა და ვიტამინების ჩათვლით ყველა საჭირო საკვები ნივთიერებით უზრუნველყოფს, ხოლო 6 თვის შემდეგ მისი განვითარებისთვის თანდათან დამატებითი კვების დაწყებაა საჭირო. ბავშვის კუჭის მოცულობისა და კალორიებზე მოთხოვნილების ზრდასთან ერთად იზრდება როგორც რძის რაოდენობა, ისე მასში საკვები ნივთიერებების კონცენტრაცია. ამგვარად, ძუძუთი კვების პერიოდის დასრულებამდე ბავშვი თქვენი რძისგან მაქსიმალურ სარგებელს იღებს.') WHERE id = 'e67478e1-350c-4cf1-9917-9b4bd3ed801c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თანამედროვე ტექნოლოგიებისა და სამედიცინო ცოდნის წყალობით, ქალებისთვის, რომლებიც ახალ ორსულობას არ გეგმავენ, კონტრაცეფციის მრავალი განსხვავებული მეთოდი არსებობს. მათ შორის ყველაზე ხშირად ირჩევენ ჩასახვის საწინააღმდეგო აბებს, თუმცა ესტროგენის შემცველი აბები ძუძუთი კვების დროს რეკომენდებული არ არის, რადგან შესაძლოა რძის რაოდენობა შეამციროს. ესტროგენის არმქონე აბების უსაფრთხოდ გამოყენება კი მშობიარობიდან 6 კვირის შემდეგ შეიძლება. კონტრაცეფციის მეთოდი, რომელიც სამთვიანი ინიექციის სახელით არის ცნობილი, პროგესტერონს შეიცავს და ძუძუთი კვების პერიოდში საფრთხეს არ წარმოადგენს. სამთვიანი ინიექციისგან განსხვავებით, ყოველთვიური ინიექციები ესტროგენს შეიცავს, ამიტომ ძუძუთი კვების დროს მათი გამოყენება რეკომენდებული არ არის. იმპლანტი კი კანის ქვეშ თავსდება, ჰორმონს შეიცავს და სამი წლის განმავლობაში უზრუნველყოფს კონტრაცეფციას. მიუხედავად იმისა, რომ იმპლანტში შემავალი ჰორმონი დედის რძეში გადადის, ის ბავშვს ზიანს არ აყენებს. ექიმების მიერ ყველაზე ხშირად რეკომენდებული მეთოდია დაცვის ძალიან მაღალი ეფექტიანობის მქონე საშვილოსნოსშიდა საშუალება, რომელსაც სპირალს უწოდებენ. სპირალი ჰორმონიანი და ჰორმონის გარეშე ვარიანტებით არსებობს და მისი ჩადგმა მშობიარობიდან 6 კვირის შემდეგ შეიძლება.') WHERE id = 'e001d0c5-46e0-40b1-82c7-a4a7f2a5f692';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის ტანსაცმლის შერჩევა, ისევე როგორც სხვა საკითხები, სიფრთხილესა და გარკვეული დეტალების გათვალისწინებას მოითხოვს. ტანსაცმლის არჩევისას ერთ-ერთი მთავარი საკითხი უსაფრთხოებაა. უსაფრთხოების თვალსაზრისით ძალიან მნიშვნელოვანია, რომ ღილებიანი ან გრძელი თასმების მქონე ტანსაცმლის ნაცვლად უპირატესობა კნოპებიან და სადა მოდელებს მიანიჭოთ. არჩევისას ასევე უნდა შეიძინოთ ხარისხიანი ნაწარმი, რომელიც საღებავს არ გამოყოფს, რადგან საღებავი შესაძლოა ორგანიზმში ტოქსიკური ნივთიერების სახით დაგროვდეს და კანცეროგენული ზემოქმედება გამოიწვიოს. ბავშვის ორგანიზმი ყველა იმ ნივთიერების წინააღმდეგ, რომელმაც შესაძლოა ზიანი მიაყენოს, დამცავ მექანიზმს ავითარებს. ალერგიებიც სწორედ ამ დამცავი მექანიზმის მოქმედების შედეგად წარმოიქმნება. ტანსაცმელში გამოყენებულმა საღებავებმა შესაძლოა თქვენს ბავშვში ალერგია გამოიწვიოს, ამიტომ უპირატესობა შესაბამისი სტანდარტის სერტიფიკატის მქონე ნაწარმს უნდა მიანიჭოთ. ასეთი სერტიფიკატის მქონე ნაწარმი შემოწმებულია საეჭვო ნივთიერებებზე, რომლებმაც შესაძლოა ბავშვის ორგანიზმს ზიანი მიაყენოს, და უსაფრთხოების ნორმების დაცვით იწარმოება. ამიტომ ამ სტანდარტების შესაბამისი ტანსაცმელი შეგიძლიათ ბავშვს მშვიდად ჩააცვათ.') WHERE id = '8bcfa34a-ab3b-47cd-8082-d8d412e4c0f8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი და თქვენი ბავშვის ერთად გატარებული მე-3 თვე! ამ თვეში ბავშვთან ერთად ახალ ეტაპზე გადადიხართ, ამიტომ მოემზადეთ სიურპრიზებისთვის, რომლებიც ძალიან გაგახარებთ. თქვენს ბავშვს უკვე იმდენად განუვითარდა მოტორული უნარები, რომ შეუძლია, ხელში მიცემული საგნები მცირე ხნით მაინც დაიჭიროს. უფრო მეტიც, ეს უკვე რეფლექსი აღარ არის და თანდათან ნებელობით ქცევად იქცევა. ხელებში ჩაჭიდების რეფლექსი ნელ-ნელა ქრება, თუმცა ბავშვის ფეხებში არსებული ჩაჭიდების რეფლექსის გაქრობას კიდევ რამდენიმე თვე დასჭირდება. რეფლექსიდან გააზრებულ ქცევაზე გადასვლისას კიდევ ერთი ცვლილება ბავშვის კვებას უკავშირდება. ახალშობილის რეფლექსი, რომლის დროსაც ბავშვი ლოყაზე შეხებისას პირს აღებს, ამ თვიდან თანდათან ნებელობით ქცევად გარდაიქმნება. ანუ თუ ბავშვს არ შია, ის პირს აღარ გააღებს. ქცევის ეს ცვლილებები, რა თქმა უნდა, ბავშვის სწრაფად განვითარებადი ტვინის დამსახურებაა.') WHERE id = '327fd5ec-447f-4d93-a81c-c3fdb4d5f652';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში ბავშვის რუტინული შემოწმებისას ექიმი მისი განვითარების რამდენიმე მაჩვენებელს შეაფასებს. მათგან პირველი და ყველაზე მნიშვნელოვანი თავის დაჭერის უნარია. 3 თვის ბავშვს ამ პერიოდში უკვე უნდა შეეძლოს თავის თავისუფლად კონტროლი, სწორად დაჭერა და 45 გრადუსამდე აწევა. ყიფლიბანდი კი ჯერ კიდევ რბილი და ღია უნდა იყოს. ეს აუცილებელია ბავშვის ტვინის სათანადო განვითარებისთვის. ტვინის განვითარების კიდევ ერთი მაჩვენებელი თავის გარშემოწერილობაა. ამ თვიდან ბავშვის თავის გარშემოწერილობა საშუალოდ 37-43 სმ-ის ფარგლებში უნდა იყოს. სხვა მაჩვენებლები, რომლებსაც ექიმი რეგულარულად გააკონტროლებს, სიმაღლე და წონაა. ამ თვეში ბავშვის წონა შეიძლება 4200-7500 გრამის, ხოლო სიმაღლე 55-65 სმ-ის ფარგლებში მერყეობდეს. გახსოვდეთ, რომ ეს საშუალო მაჩვენებლებია და თითოეული ბავშვის შემთხვევაში შეიძლება განსხვავდებოდეს. სანამ მონაცემები ქვედა და ზედა ზღვრის ფარგლებში რჩება, ბავშვის განვითარებაზე ნერვიულობის საჭიროება არ არსებობს.') WHERE id = '76c150ee-bf0f-46cc-b728-a8452683e29c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის მესამე ნახტომი, ანუ ინტენსიური ზრდის პერიოდი, ამ დღეებში უნდა დაწყებულიყო. ამიტომ, თუ შეამჩნევთ მოუსვენრობას, ძილის დარღვევას ან მადის ცვლილებას, ნუ შეშინდებით. მესამე ნახტომის პერიოდი საშუალოდ მე-12 კვირის მიდამოებში იწყება, თუმცა ეს ვადა შეიძლება ბავშვის დაბადების რეალურ და სავარაუდო თარიღებს შორის სხვაობის მიხედვით შეიცვალოს. ამ ნახტომის შემდეგ ბავშვი ბგერების მიმართ უფრო მეტ ინტერესს იჩენს და გამძაფრებული სმენის წყალობით ხმის ტონის ცვლილებებსაც კი ამჩნევს. გარდა ამისა, ბავშვის ტვინის ღეროში სმენაზე პასუხისმგებელი უჯრედები იწყებს შემომავალი ბგერის მიმართულების განსაზღვრას და მასზე რეაგირებას. ეს ნიშნავს, რომ ბავშვს უკვე შეუძლია ხმის წყაროს მიმართულების გარჩევა და მისკენ მიბრუნება. ამ პერიოდში კიდევ ერთი ცვლილება ისაა, რომ ბავშვი საკუთარი ხმის აღმოჩენას იწყებს. საკუთარი ხმის გაცნობისას მან შეიძლება სხვადასხვა ტიპისა და სიძლიერის ბგერების გამოცემით გაგაოცოთ. კარგად გაერთეთ! 😊') WHERE id = '7157ab6b-c70f-4177-b181-d8ea3a2d459e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვს ხელოვნური ნარევით კვებავთ ან დედის რძის უკმარისობის გამო დამატებით ნარევს იყენებთ, ერთ-ერთი ყველაზე მნიშვნელოვანი საკითხი ბოთლის შერჩევაა. ბავშვის ჯანმრთელობისთვის ბოთლის არჩევას უყურადღებოდ არავითარ შემთხვევაში არ უნდა მოეკიდოთ. სწორად შერჩეული ბოთლი ბავშვის კვებაში დიდ როლს ასრულებს და, ამასთანავე, მოხერხებული გამოყენების წყალობით თქვენს საქმეს მნიშვნელოვნად ამარტივებს. არჩევისას უპირატესობა მიანიჭეთ მოდელებს, რომლებიც ბავშვს კვების დროს, ისევე როგორც ძუძუთი წოვისას, პირის ფართოდ გაღების საშუალებას აძლევს. გარდა ამისა, შერჩეული ბოთლი არ უნდა ტვირთავდეს საჭმლის მომნელებელ სისტემას და კლინიკურად დადასტურებული უნდა იყოს, რომ კოლიკით გამოწვეულ აირებსა და ტკივილს ამცირებს. ბოთლის მასალა, ზომა, ფორმა, ანტიკოლიკური თვისება, საწოვარას ფორმა და ხვრელების რაოდენობა ის დეტალებია, რომლებსაც ყურადღება უნდა მიაქციოთ. ამ ეტაპზე ბავშვისთვის რეკომენდებულია 240-260 ml მოცულობის ბოთლი, რომელსაც საშუალო ნაკადის სიჩქარისა და ჰაერის გამტარი სისტემის მქონე საწოვარა აქვს.') WHERE id = '20a065b0-2b51-4884-b57e-e72acfd3836c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ზრდისა და განვითარების ტემპი ასაკის მიხედვით იცვლება. ზოგიერთ პერიოდში ის უფრო ნელა იზრდება, თუმცა განსაკუთრებით ზრდის ნახტომის, ანუ სწრაფი განვითარების პერიოდში ზრდის ტემპი იმატებს. როდესაც ზრდის ტემპი ნელდება, ბავშვის მადის დაქვეითება მეცნიერული თვალსაზრისით ნორმალურ მოვლენად მიიჩნევა. სიცოცხლის პირველ წელს ბავშვი საკმაოდ სწრაფად იზრდება, ამიტომ მადის დაქვეითების სერიოზული პრობლემა, რომელიც ჩარევას მოითხოვს, ჩვეულებრივ არ გვხვდება. მიუხედავად ამისა, კბილების ამოსვლისა და გარემოს შეცნობის დაწყების პერიოდში შეიძლება მადის ხანმოკლე დაქვეითება შეამჩნიოთ. კბილების ამოსვლა თითქმის ყველა ბავშვისთვის რთული პერიოდია. ამ დროს ბავშვს, რომელიც თავს ცუდად გრძნობს და ფიზიკურ ტკივილს განიცდის, შეიძლება არარეგულარულად და ნაკლები რაოდენობით ჭამოს, რაც ნორმალურია. თუმცა მნიშვნელოვანია, მცირე ულუფებით კვება უმადობაში არ აგერიოთ. მიუხედავად იმისა, რომ ახალბედა დედისთვის ეს მდგომარეობა შეიძლება შემაშფოთებელი იყოს, სინამდვილეში პანიკის საფუძველი არ არსებობს. გარდა ამისა, ბავშვებში, რომლებსაც დამატებითი კვება ნაადრევად დაუწყეს, საჭმლის მომნელებელი სისტემის მოუმზადებლობით გამოწვეულმა ალერგიულმა რეაქციებმაც შეიძლება მადის დაქვეითება გამოიწვიოს.') WHERE id = '87f56862-dda9-454a-a541-34481c8ca235';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვთან ერთად ბევრი სხვადასხვა აქტივობით შეგიძლიათ დაკავდეთ. ბავშვთან ურთიერთობა, რომელიც უკვე აქტიურად იწყებს გარემოსთან კომუნიკაციას, ერთ-ერთი საუკეთესო ინვესტიციაა, რომელიც მის მომავალში შეგიძლიათ ჩადოთ. ბავშვს, რომელსაც საკმაოდ განვითარებული ყნოსვა აქვს, შეგიძლიათ სხვადასხვა სურნელი შეაგრძნობინოთ, რათა მისი ტვინის უჯრედები უფრო ეფექტურად მუშაობდეს. მეტყველების განვითარებისთვის აუცილებელია, ბავშვს ხშირად ესაუბროთ და მასთან ურთიერთობა დაამყაროთ. მნიშვნელოვანია, რომ მან რაც შეიძლება მეტი განსხვავებული სიტყვა მოისმინოს. მუდმივად ესაუბრეთ ბავშვს, ხშირად მიმართეთ სახელით, რათა საკუთარი სახელის ამოცნობაში დაეხმაროთ, შეეხეთ და აკოცეთ. ბავშვი, რომელიც გრძნობს, რომ უყვართ და ყურადღების ცენტრშია, როგორც ფიზიკურად, ისე ემოციურად უფრო ჯანმრთელი გაიზრდება. იმის ნაცვლად, რომ ბავშვთან ერთად მხოლოდ სახლში დარჩეთ და მხოლოდ მისი ფიზიოლოგიური საჭიროებები დააკმაყოფილოთ, ახალი გამოცდილების მიღების შესაძლებლობებიც უნდა შეუქმნათ. გადით გარეთ და მიეცით საშუალება, სუფთა ჰაერზე მზე შეიგრძნოს. თუ გარეთ გასვლას ვერ ახერხებთ, შეგიძლიათ ერთად გაიხედოთ აივნიდან ან ფანჯრიდან. აქ მთავარი მიზანია, მოძრაობის საშუალებით ბავშვის აღქმა გაააქტიუროთ, ხელი შეუწყოთ გრძნობის ორგანოების აქტიურად გამოყენებას და მეხსიერება ავარჯიშოთ.') WHERE id = 'd229dd79-f389-4db8-9b5a-34c760b0f5c0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვის საფენის გამოცვლისას კანზე აქერცვლას, სიწითლესა და ანთებას შეამჩნევთ, შესაძლოა მას სოკოვანი ინფექცია ჰქონდეს. ამ რეაქციების გამომწვევი სოკოები მიკროსკოპული ორგანიზმებია, რომლებიც ნესტიან გარემოში სწრაფად მრავლდება. გამრავლებისთვის მათ სითბო და ტენიანობა სჭირდება. ხელსაყრელ გარემოში მოხვედრისთანავე ისინი ადვილად ვრცელდება. სოკოვანი ინფექციის განვითარების ალბათობა მაღალია ისეთ ადგილებში, რომლებიც წყალთან კონტაქტის შემდეგ ნესტიანი რჩება, მაგალითად, ბავშვის საფენის ქვეშ მოქცეულ ინტიმურ მიდამოში. ამიტომ ბავშვის დაბანისა და გაწმენდის შემდეგ კანი ნესტიანი არ უნდა დატოვოთ და კარგად უნდა გაამშრალოთ. ბავშვის კანზე სოკოვანი ინფექციისა და საფენისმიერი გამონაყარის ერთმანეთისგან გასარჩევად აუცილებელია ექიმის კონსულტაცია. გარეგნულად სოკოთი დაზიანებულ უბნებზე კანის აქერცვლა შეინიშნება. საფენისმიერი გამონაყარის მქონე ბავშვებში სოკოვანი ინფექციის განვითარების რისკი განსაკუთრებით მაღალია, თუ ანტიბიოტიკი ექიმის მეთვალყურეობის გარეშე გამოიყენება. ამიტომ ბავშვის კანზე გაჩენილ საფენისმიერ გამონაყარს დიდი ყურადღებით უნდა მოეკიდოთ.') WHERE id = 'b63be385-2a69-41af-ad23-38c2f405d961';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვის განმავლობაში ბავშვს უნდა დააწყებინოთ D ვიტამინის წვეთების მიღება, რომელთა უფასოდ მიღება პოლიკლინიკაში შეგიძლიათ, ან გამოიყენოთ თქვენი ექიმის მიერ რეკომენდებული პრეპარატი. D ვიტამინის ძირითადი წყარო მზის სხივებია და გარკვეული დროით მზეზე ყოფნა ორგანიზმის ამ საჭიროებას 90%-ით აკმაყოფილებს. თუმცა, სამეცნიერო კვლევების თანახმად, D ვიტამინის დეფიციტი ჯანმრთელობის ერთ-ერთი ფართოდ გავრცელებული პრობლემაა. D ვიტამინი ბავშვის ჩამოყალიბების პროცესში მყოფი იმუნური სისტემის რეგულატორია. ორგანიზმში D ვიტამინის მარაგი განსაკუთრებით მნიშვნელოვანია ავტოიმუნური დაავადებების დროს. სიცოცხლის პირველივე დღიდან დედის რძით ან ხელოვნური ნარევით კვებისას ბავშვი D ვიტამინის გარდა ყველა სხვა ვიტამინს საკმარისი რაოდენობით იღებს. თუმცა, საკვების მეშვეობით ბავშვის ორგანიზმში D ვიტამინი საკმარისი რაოდენობით ვერ ხვდება. ამიტომ ეს დეფიციტი აუცილებლად უნდა შეივსოს თქვენი ექიმის მიერ დანიშნული D ვიტამინის დანამატით.') WHERE id = '4c2feb95-7f80-4a6f-9d8b-18f61f673c70';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვების შემდეგ ბავშვის წამოქაფება ფიზიოლოგიურად უმეტესად ნორმალურ მოვლენად მიიჩნევა. თუმცა, დაკვირვება მაინც მნიშვნელოვანია. განსაკუთრებით სიცოცხლის პირველ თვეებში, კვებიდან მალევე ბავშვმა შეიძლება ყოველგვარი ძალდატანების გარეშე პირის სავსე რაოდენობით წამოაქაფოს. ასაკის მატებასთან ერთად ეს მდგომარეობა იკლებს და, ჩვეულებრივ, რვა თვისთვის კვების შემდგომი წამოქაფება ქრება. კვებისას ჰაერის ჩაყლაპვამ, ძალიან სწრაფად ან ძალიან ნელა წოვამ და კვების შემდეგ ბოყინის ამოუშვებლობამ შესაძლოა წამოქაფება გამოიწვიოს. თუ კვების ტექნიკასთან დაკავშირებულ ამ შეცდომებს გამოასწორებთ, ბავშვის წამოქაფებაც შეწყდება. ეს, ჩვეულებრივ, ჭამის შემდეგ ხდება, რადგან საყლაპავის ქვედა ნაწილში მდებარე კუნთი, რომელიც კუჭის შიგთავსის უკან დაბრუნებას უშლის ხელს, ფიზიოლოგიურად ჯერ ბოლომდე ჩამოყალიბებული არ არის. წამოქაფება შესაძლოა დაბადებიდანვე აღინიშნებოდეს, თუმცა დაახლოებით მე-4 თვეში ხშირდება და თითქმის ყოველი 4 ბავშვიდან 3-ს ეხება. მე-6 თვის შემდეგ ის, როგორც წესი, იკლებს, ხოლო მყარ საკვებზე გადასვლისას მთლიანად ქრება.') WHERE id = '94ce13b4-bc4e-480c-a364-11de1e4c0330';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის აირებით გამოწვეულ ჭვალს ორი ძირითადი მიზეზი აქვს. ერთ-ერთი მათგანია აირი, რომელსაც ბავშვის კუჭ-ნაწლავში არსებული სასარგებლო ბაქტერიები დედის რძეში ან ხელოვნურ საკვებში შემავალი მოუნელებელი საკვები ნივთიერებების დაშლისას წარმოქმნიან. მეორე მიზეზი კი ჰაერია, რომელსაც ბავშვი ტირილის, ყლაპვის, ძუძუს წოვის ან ბოთლით კვების დროს ყლაპავს. ამასთანავე, თუ ბავშვს ძუძუთი კვებავთ, თქვენ მიერ ისეთი საკვების მიღებამ, რომელიც საჭმლის მომნელებელ სისტემაში აირების წარმოქმნას იწვევს, შესაძლოა ბავშვსაც შეუქმნას ეს პრობლემა. ამიტომ სასარგებლო იქნება რაციონში ასეთი პროდუქტების შემცირება. ბავშვის აირებით გამოწვეული ჭვალის შესამსუბუქებლად მრავალი ზომის მიღება შეგიძლიათ. ერთ-ერთი მათგანია, არ დაელოდოთ, სანამ ბავშვი ზედმეტად მოშივდება. ძალიან მოშივებული ბავშვები რძეს სწრაფად სვამენ და ამის გამო დიდი რაოდენობით ჰაერს ყლაპავენ. თუ ბავშვს ბოთლით კვებავთ, დარწმუნდით, რომ საწოვარას ნახვრეტი არც მეტისმეტად პატარაა და არც მეტისმეტად დიდი — ასე აირებთან დაკავშირებულ ჩივილებს მინიმუმამდე შეამცირებთ.') WHERE id = '14cce317-1232-45b9-96bd-2281d87ef8be';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვებაში რამდენიმე ცვლილების შეტანა რეფლუქსის შემცირებასა და მომავალში პრობლემების განვითარების რისკის მინიმუმამდე დაყვანაში დაგეხმარებათ. ყველაზე მნიშვნელოვანია კვების სიხშირე და რეჟიმი. კვებისას ბავშვი შეძლებისდაგვარად ვერტიკალურ მდგომარეობაში უნდა გეჭიროთ. უფრო ხშირად, მაგრამ მცირე ულუფებით კვება რეფლუქსს ამცირებს და საჭმლის მონელებას აადვილებს. კვებებს შორის და კვების შემდეგ მოერიდეთ ბავშვის ისეთ მკვეთრ მოძრაობებს, როგორიცაა მაღლა აგდება ან გადაგორება; ამის ნაცვლად, ყოველი კვების შემდეგ დაახლოებით 20 წუთის განმავლობაში ვერტიკალურად გეჭიროთ. ასევე, საფენის გამოცვლისას ყურადღება მიაქციეთ, რომ ის ზედმეტად მჭიდროდ არ იყოს შეკრული. ძალიან მჭიდრო საფენი ბავშვის მუცელში წნევას ზრდის და შესაძლოა ღებინება გამოიწვიოს. ბავშვის ძილისას თავის ნაწილის ოდნავ ასამაღლებლად თხელი ბალიშის გამოყენება აირების გამოსვლას აადვილებს და შესაძლო გადაცდენის რისკს ამცირებს. სიგარეტის კვამლის ჩასუნთქვამ, სხვა მავნე ზემოქმედებებთან ერთად, შესაძლოა რეფლუქსიც გამოიწვიოს, ამიტომ ეს კიდევ ერთი მნიშვნელოვანი ფაქტორია, რომელსაც უნდა მოერიდოთ.') WHERE id = '4db7b0e8-8a13-4223-9f1c-396106b58bfc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ზრდისას, ბუნებრივია, ყველაზე მეტად მისი გონებრივი შესაძლებლობებისა და ტვინის განვითარება გსურთ. ამის ხელშეწყობის ერთ-ერთი ძალიან ეფექტიანი გზა ბავშვისთვის წიგნების კითხვაა. ამ ეტაპზე ბავშვის წიგნებთან გაცნობა და მათი შეყვარება საფუძველს ჩაუყრის მის მომავალ აკადემიურ წარმატებას, საბაზისო მეტყველების უნარებს, ენობრივ ცოდნასა და მსჯელობის უნარს. მეცნიერულად დადასტურებულია, რომ ბავშვებს, რომლებიც წიგნებით ჯერ კიდევ სკოლამდელ ასაკში ინტერესდებიან, უფრო მაღალი აკადემიური მოსწრება აქვთ. როდესაც ბავშვს წიგნს უკითხავთ, თქვენ მისი მეტყველების უნარის საფუძველს ქმნით, რადგან ის თქვენგან საუბრისთვის აუცილებელ ძირითად ბგერებს სწავლობს. გარდა ამისა, აქტიური ურთიერთობისას თქვენთან ჩამოყალიბებული კავშირის წყალობით ბავშვი სწორი კომუნიკაციის გზებს სასკოლო ასაკამდე ბევრად ადრე აითვისებს. წიგნებიდან გამართული წინადადებების აგებულების რეგულარულად და მუდმივად მოსმენით, მეტყველების დაწყების პერიოდში ბავშვს გრამატიკული წესებისადმი მიდრეკილება ჯერ კიდევ სკოლამდელი ასაკიდან განუვითარდება. ამიტომ ძალიან მნიშვნელოვანია, რომ ბავშვს წიგნები თავად კითხვის დაწყებამდე, უკვე ახლა უკითხოთ.') WHERE id = '847c3222-1e8f-4ee7-af36-660c53f7b72c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი თვალწინ საოცარი სისწრაფით იზრდება. ყოველდღე ახალ უნარებს იძენს და მათ თქვენც გაჩვენებთ. 😊 სათამაშოებს, რომლებსაც მისი ახალი უნარების შეძენისა და შემოქმედებითი თუ გონებრივი განვითარების ხელშესაწყობად შეარჩევთ, დიდი მნიშვნელობა აქვს. ამ პერიოდში ბავშვი გარემოთი სულ უფრო მეტად ინტერესდება, ამიტომ შეგიძლიათ ახალი და განსხვავებული სათამაშოები შეუძინოთ ან უკვე არსებული სათამაშოებით თამაშის ახალი გზები მოიფიქროთ. სათამაშოს არჩევისას ყურადღება უნდა მიაქციოთ, შეესაბამება თუ არა ის ბავშვის ასაკს და რა გავლენას მოახდენს მის პიროვნულ თვისებებზე. სამეცნიერო კვლევები აჩვენებს, რომ სათამაშოები ბავშვის განვითარებაში დიდ როლს ასრულებს. ყველა სათამაშო, რომლითაც ბავშვი სკოლამდელ ასაკამდე თამაშობს, მნიშვნელოვანია სამყაროსთან კავშირის დასამყარებლად და პიროვნული განვითარებისთვის. ამიტომ სათამაშოს არჩევისას ყურადღება მიაქციეთ, რომ ის ბავშვის ყველა გრძნობას ასტიმულირებდეს, მოტორულ უნარებს ავითარებდეს, წარმოსახვას აძლიერებდეს და სოციალური უნარების ჩამოყალიბებას უწყობდეს ხელს.') WHERE id = '86e946c1-ab86-4301-9ac4-7f795adc1bfa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან ბავშვს კარგად განვითარებული გრძნობის ორგანოები და მილიონობით ტვინის უჯრედი აქვს, რომლებიც გააქტიურებას ელოდება, ის დაბადების მომენტიდანვე იწყებს ყველა ინფორმაციის აღქმასა და დამახსოვრებას. დაბადებისას ბავშვს მხოლოდ რამდენიმე რეფლექსი აქვს, რომლებიც სიცოცხლის შენარჩუნებაში ეხმარება, თუმცა მცირე დროში ის მრავალ უნარს აითვისებს, მათ შორის ხოხვას, ლაპარაკსა და სიარულს. კვლევების თანახმად, ერთ-ერთი მთავარი მიზეზი, რის გამოც ბავშვი ამ საოცარ უნარებს ასე სწრაფად სწავლობს, დღის ძილია. დღის ძილი ბავშვს დასვენებისა და ახალი ინფორმაციის ათვისების საშუალებას აძლევს, ამავდროულად კი მიღებული გამოცდილების მეხსიერებაში განმტკიცებაში ეხმარება. ძილის მოწესრიგებული რეჟიმი ხელს უწყობს, რომ ბავშვმა ისეთი მნიშვნელოვანი უნარები, როგორიცაა სიარული და ლაპარაკი, დროულად შეიძინოს. დროთა განმავლობაში ძილის ხანგრძლივობა მცირდება და ბავშვმა, რომელიც გარემოს შესწავლას იწყებს, შესაძლოა ზოგჯერ დაძინებას წინააღმდეგობა გაუწიოს. ამ თვეებში ბავშვი ჩვევებს ადვილად იძენს, ამიტომ გირჩევთ, მისი ძილის რეჟიმის მოწესრიგება უკვე ახლა დაიწყოთ. 😊') WHERE id = '12adf52f-ce6e-45aa-88f8-a01f2005b356';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მშობიარობის შემდგომ პერიოდს, როდესაც ორსულობის დროს სხეულში მომხდარი ცვლილებები თანდათან უბრუნდება საწყის მდგომარეობას, ლოგინობის ხანა ეწოდება. თუმცა ლოგინობის ხანა მხოლოდ მშობიარობის შემდგომ 40 დღეს, ანუ 6 კვირას მოიცავს. მშობიარობის შემდგომი პერიოდი კი ყველა ქალისთვის განსხვავებულია და ლოგინობის ხანაზე უფრო დიდხანს გრძელდება. სასწაული, რომელზეც 9 თვის განმავლობაში ოცნებობდით, ახლა უკვე თქვენს მკლავებშია. თუმცა უძილობა, დაღლილობა, ფიზიკური ტკივილი, საკუთარი თავისა და საოჯახო საქმეებისთვის დროის ნაკლებობა შესაძლოა კვლავ გაგრძელდეს და გაგიჩინოთ განცდა, რომ ყველაფერს ვერ უმკლავდებით. ზოგჯერ შეიძლება უმიზეზოდ გაღიზიანდეთ და გარშემომყოფებს მკაცრად უპასუხოთ. მოკლედ, მშობიარობის შემდგომი ფსიქოლოგიური მდგომარეობა რთულია და მისი მხოლოდ 40 დღით შემოფარგვლა სწორი არ არის. აუხსენით ოჯახის წევრებს, რას გრძნობთ, და მათგან გაგებას მოელოდეთ. გახსოვდეთ, ეს ყველაფერი დროებითია. ყველა ქალი თავისი ბავშვისთვის საუკეთესო დედაა. ნებისმიერ სირთულეში თქვენს გვერდით ვიქნებით. 😊') WHERE id = 'bad42002-8275-46dc-b1ad-174066cad7e7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვის გადასაყვანად ან დასაძინებლად იყენებთ ისეთ დამხმარე საშუალებას, როგორიცაა ბავშვის სავარძელ-არწევანა, მის ზედა ნაწილზე შეგიძლიათ ბავშვისთვის უსაფრთხო, ყურადღების მიმქცევი სათამაშოები განათავსოთ. ეს ნივთები ბავშვის ყურადღებას იპყრობს, ხელს უწყობს მხედველობისა და აღქმის განვითარებას და აძლიერებს შემეცნებით უნარებს. ბავშვს ძალიან მოეწონება მანათობელი, ხმოვანი და მოძრავი სათამაშოები. ახალი რაღაცების აღმოჩენა მას აღაფრთოვანებს და ართობს. ამავდროულად, გარემოში არსებული ფერადი სტიმულები ბავშვს საკუთარი შესაძლებლობების აღმოჩენაში ეხმარება. თუმცა სათამაშოების შერჩევისას სიფრთხილე უნდა გამოიჩინოთ. ტელევიზორის მსგავსმა მოწყობილობებმა, რომლებიც სწრაფად ცვალებად გამოსახულებებს, მკვეთრ ფერებსა და ხმებს გამოსცემს, შესაძლოა ბავშვის ყურადღება მიიპყროს, თუმცა უდავოა, რომ ეს მის განვითარებაზე უარყოფითად აისახება.') WHERE id = '3ad7f64e-f78d-46bd-a402-26a3f15d1d22';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი საათობით სწევს ხელებს თავის დონეზე და აღტაცებით აკვირდება? თითქოს გვესმის, როგორ ამბობთ: „დიახ!“ 😊 ამ კვირებში თითქმის ყველა დედა ამჩნევს, რომ ბავშვი საკუთარი ხელების შესასწავლად აკვირდება მათ და პირში იდებს. განვითარების ამ ეტაპზე ასეთი ქცევა სრულიად ნორმალურია და არ უნდა შეუშალოთ ხელი. მიეცით საშუალება, ხელები იმდენჯერ ჩაიდოს პირში, რამდენჯერაც მოისურვებს. 😊 ბავშვი, რომელსაც ხელებისა და თითების მიმართ ინტერესი ეზრდება, განსაკუთრებით ზურგზე წოლისას სწევს და ამოძრავებს ხელებს, თან კი აკვირდება მათ. შესაძლოა, ხელები სწრაფადაც ამოძრაოს და საკუთარ მოძრაობებს თვალებითა და თავის მიბრუნებით მიადევნოს თვალი. ამ ეტაპების გავლისას ბავშვი ისწავლის ხელების სასარგებლო ინსტრუმენტად მართვას და მათ გარშემო არსებული საგნების შესასწავლად გამოიყენებს. მხოლოდ ის უნდა გაითვალისწინოთ, რომ ხელები სუფთა ჰქონდეს, ფრჩხილები კი სათანადო სიგრძეზე დაჭრილი, რათა პირის ღრუ არ დაიზიანოს. სასიამოვნო აღმოჩენებს გისურვებთ! 😊') WHERE id = 'caffa322-fe7d-4bfd-9362-04360cd00a6c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მე-3 თვეში ბავშვის ტვინში მოგონებები და გამოცდილებები უკვე დამკვიდრებას იწყებს. საწყის ეტაპზე ისინი მუდმივად განმეორებადი მოქმედებებით ყალიბდება. რადგან ბავშვი ადრე ნანახი ადამიანების, საგნებისა და გამომეტყველებების დამახსოვრებასა და ერთმანეთისგან გარჩევას იწყებს, მან უკვე იცის, რომ ტირილით ყურადღებას მიიქცევს. ამ თვეში ერთ-ერთი ყველაზე სასიამოვნო ცვლილება ის არის, რომ ბავშვი სწავლობს თქვენს ღიმილზე ღიმილით პასუხს. მოემზადეთ ღიმილისთვის. 😊 სინამდვილეში, მეხსიერების ჩამოყალიბება ჯერ კიდევ მაშინ იწყება, როდესაც ბავშვი თქვენს საშვილოსნოშია. სმენის განვითარების მომენტიდან ბავშვი აღიქვამს და იმახსოვრებს ხმებს, რის გამოც დაბადების შემდეგ თქვენს ხმას სხვების ხმებისგან ადვილად არჩევს. ახლა კი, სწრაფად განვითარებადი ტვინის წყალობით, მას შეუძლია მეხსიერებაში შენახული ინფორმაციის გააზრება და მასზე რეაგირება. მაგალითად, 3 თვის ბავშვს შეუძლია დედის მიერ ნაჩვენები საგნის გამოსახულება მეხსიერებაში 7 დღემდე შეინახოს და ხელახლა დანახვისას რეაქციით მიანიშნოს, რომ იცნო.') WHERE id = 'a7c25396-4991-4496-8a65-64211f7dd866';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სწრაფად განვითარებული ნერვული სისტემისა და გრძნობის ორგანოების წყალობით, ბავშვმა გარემოსთან უფრო აქტიური ურთიერთობა დაიწყო. ამიტომ ნორმალურია, თუ მას ერთ ადგილას გაჩერება არ სურს, მარტო დარჩენისას ტირის და მუდმივად ხელში აყვანილი ტარება უნდა. ამ მდგომარეობას, რომელმაც დროდადრო შეიძლება დაგღალოთ, შეძლებისდაგვარად გაგებით უნდა მოეკიდოთ და ბავშვს გარემოს შესწავლაში დაეხმაროთ. სეირნობისას ბავშვის სხვადასხვა პოზაში დაჭერა მის კუნთებს ავითარებს და მას ძალიან მოსწონს. ამგვარად, ის თქვენთან და გარემოსთან ჯანსაღი სოციალიზაციის პერიოდსაც გაივლის. ამ თვეში ბავშვის ძილი, თამაში და კვება უკვე გარკვეულ რეჟიმში მოექცა. ამიტომ მე-3 თვე როგორც თქვენთვის, ისე ბავშვისთვის გარდამტეხ პერიოდად მიიჩნევა. განაგრძეთ ბავშვთან თამაში, მასთან დროის გატარება და ხშირად გაუღიმეთ. მასთან ხარისხიანად გატარებული დრო აჩვენებს, რომ მისით დაინტერესებული ხართ და მისი ჯანსაღი ფსიქოემოციური განვითარებისთვის ძალიან მნიშვნელოვანია.') WHERE id = 'c7c7ac0c-0d6e-4513-8d30-65a89768a3af';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ, უკვე გარკვეული დროა ამჩნევთ, რომ ბავშვი განავალზე უფრო იშვიათად გადის. ბავშვებში დეფეკაციის სიხშირე და თავისებურებები შეიძლება მნიშვნელოვნად განსხვავდებოდეს და უმეტეს შემთხვევაში ეს ნორმად მიიჩნევა. თუ ბავშვი მხოლოდ დედის რძით იკვებება, ნორმალურია როგორც კვირაში ერთხელ, ისე დღეში 5-6-ჯერ დეფეკაცია. ამასთანავე, ძუძუთი კვებაზე მყოფი ბავშვის განავალი, როგორც წესი, ყვითელი, თხიერი და ოდნავ მარცვლოვანია. თუ ბავშვი ხელოვნური ნარევით იკვებება და შეკრულობა არ აქვს, ნორმალურია რბილი განავალი როგორც 3-4 დღეში ერთხელ, ისე დღეში 5-ჯერ. ხელოვნური ნარევით კვებისას ბავშვის განავალი შეიძლება იყოს როგორც ყვითელი, ისე მწვანე. კვების ტიპის გარდა, გამოყენებული ნარევის ბრენდის შეცვლისას ან ანტიბიოტიკების მიღების პერიოდში შესაძლოა დეფეკაციის სიხშირეც შეიცვალოს. მთავარი, რასაც ყურადღება უნდა მიაქციოთ, განავლის კონსისტენციაა. თუ განავალი მყარი, მშრალი და ცალკეულ ნაწილებადაა დაყოფილი, ბავშვს, დიდი ალბათობით, შეკრულობა აქვს. თუ შეამჩნევთ, რომ ეს მდგომარეობა ბავშვს აწუხებს და დისკომფორტს უქმნის, სასურველია, რაც შეიძლება მალე დაუკავშირდეთ ექიმს.') WHERE id = '0aa04f59-8956-4168-94d6-7cbf1b5d04b5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის ხელისა და თვალის კოორდინაცია მნიშვნელოვნად განვითარდა. ბავშვი, რომელმაც ჩაჭიდების უნარის წყალობით აღმოაჩინა, რომ სათამაშოებისა და საგნების ხელში დაჭერა შეუძლია, ყურადღების ამ მოქმედებებზე გამახვილებას დაიწყებს. მაგალითად, ბავშვი ხელში დაჭერილ ჩხარუნას ადვილად აღარ გაუშვებს, სანამ თავად არ მოისურვებს. თუ მიხვდება, რომ ის ხმას გამოსცემს, შეიძლება მისი შეჯანჯღარებაც სცადოს. ასეთი ქცევები მიზეზშედეგობრივი კავშირის ჩამოყალიბების თვალსაზრისით ბავშვის გონებრივი განვითარების ერთ-ერთი პირველი ნაბიჯია. ბავშვის მიერ აღმოჩენილი ყველა ეს კავშირი მალე უფრო ფუნქციური გახდება და მას გაუჩნდება სურვილი, ხელში დაჭერილი საგნები პირში ჩაიდოს. ამ ეტაპზე, რომელსაც „ორალური პერიოდი“ ეწოდება, ბავშვი ერთ-ერთი პირველი რეფლექსის — წოვის რეფლექსის — დახმარებით ყველაფერს, რაც აინტერესებს და რისი შესწავლაც სურს, პირში იდებს. ეს პერიოდი ბავშვის ერთ წლამდე ასაკს მოიცავს. ამ დროის განმავლობაში ბავშვი გარე სამყაროსთან კავშირს სხეულის მთელი ზედაპირით, განსაკუთრებით კი პირის მეშვეობით ამყარებს. ამიტომ ყველა წვრილი საგანი, რომლის გადაყლაპვაც ბავშვს შეუძლია, უნდა მოაშოროთ და ის დიდი ხნით მარტო არ დატოვოთ.') WHERE id = '60021b19-b43c-4324-8e67-4e9b5d399b4d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ძუძუთი ან ბოთლით კვებისას ბავშვი უკან იწევს და ტირის, დიდი ალბათობით, საქმე ძუძუს ან ზოგადად კვებაზე უარის თქმასთან გაქვთ. ასეთ შემთხვევაში, მიუხედავად შიმშილისა, ბავშვს სხვადასხვა მიზეზით შეიძლება წოვა არ სურდეს. ამის ერთ-ერთი ყველაზე გავრცელებული მიზეზი ცხვირის გაჭედვაა. რადგან გაჭედილი ცხვირის გამო ბავშვი პირით სუნთქვას ცდილობს, შიმშილის მიუხედავად, შესაძლოა ხშირად გაუშვას ძუძუს თავი ან საერთოდ უარი თქვას მასზე. თუ ბავშვს ცხვირი გაჭედილი აქვს, კვებამდე ასპირატორით უნდა გაუწმინდოთ ან ექიმის მიერ რეკომენდებული ცხვირის წვეთებით თავისუფლად სუნთქვაში დაეხმაროთ. გარდა ამისა, ბავშვისთვის ჩვეული რეჟიმის დარღვევამ და კვების დროის ცვლილებამ შეიძლება მოუსვენრობა და წოვის მიმართ უარყოფითი რეაქცია გამოიწვიოს. ძუძუთი კვების არასწორი ტექნიკის გამოყენებამაც შეიძლება ბავშვს ძუძუს სწორად ჩაჭიდება გაურთულოს. ძუძუთი კვების სწორი ტექნიკის შესახებ ინფორმაციის მიღებითა და სხვადასხვა პოზის მოსინჯვით, რომლებშიც ბავშვი ძუძუს კომფორტულად ჩაეჭიდება, შეგიძლიათ მას კვლავ დაიწყებინოთ წოვა.') WHERE id = '923618b2-185f-4d48-8595-207ec8b1f1d7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის თმის ფოლიკულების განვითარება ჯერ კიდევ დედის მუცლად ყოფნისას, დაახლოებით პირველ ტრიმესტრში იწყება. დაბადების დღემდე ლანუგოდ წოდებული ბუსუსები ბავშვის თავის არეში სქელდება, რათა სითბოს დაკარგვას შეუშალოს ხელი. ვინაიდან ამ ბუსუსების სიხშირე და ზრდის ხანგრძლივობა გენეტიკური ფაქტორების მიხედვით შეიძლება განსხვავდებოდეს, სრულიად ნორმალურია, რომ ბავშვი ხშირი ან თხელი თმით, ან საერთოდ უთმოდ დაიბადოს. სინამდვილეში, ბავშვის ცოტა ან ხშირი თმით დაბადება ჯანმრთელობის რაიმე პრობლემაზე არ მიუთითებს. განსაკუთრებით ამ თვეებში ბავშვს თმა შეიძლება ინტენსიურად სცვიოდეს. შესაძლოა, თავის უკანა, კეფის ნაწილში მცირე გამელოტებაც კი შეამჩნიოთ. ეს შეიძლება გამოწვეული იყოს როგორც ბავშვის მუდმივად ერთსა და იმავე პოზაში ძილით, ისე თმის ფოლიკულების მოსვენების ფაზაში გადასვლით, რაც დაბადებიდან მე-6 თვემდე შეიძლება გაგრძელდეს. მიუხედავად იმისა, რომ შესაძლოა ბავშვის თმის შეჭრა გენანებოდეთ, სპეციალისტები გირჩევენ, დროის დადგომისას ბავშვს თმა შეჭრათ — განურჩევლად იმისა, ხშირია ის თუ თხელი.') WHERE id = '1a637264-ed95-4fa6-842a-a26e3ce3729a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტვინი ჯერ კიდევ თქვენს მუცლად ყოფნისას უწყვეტად ვითარდება. დაბადების შემდეგ ეს განვითარება კიდევ უფრო ჩქარდება. ტვინის განვითარების ყველაზე სწრაფი პერიოდი 0-48 თვეა. ამ პერიოდში ბავშვს გარშემო არსებული სამყაროს აღსაქმელად გამოცდილება სჭირდება და სწორედ მისი მეშვეობით სწავლობს. ამ გამოცდილების ერთ-ერთი უმნიშვნელოვანესი ნაწილი ისეთი სათამაშოებია, რომლებიც ბავშვის ინტერესს იწვევს და მის განვითარებას ხელს უწყობს. ფერადი, სხვადასხვა ფორმისა და საინტერესო სათამაშოები ბავშვის ტვინში ნეირონებს ააქტიურებს, მათ შორის კავშირებს ქმნის და გარემოს გააზრებაში ეხმარება. ყოველდღიური ნივთებისგან განსხვავებით, სათამაშოები შემოქმედებით უნარებს ავითარებს და ახლად ჩამოყალიბებული წარმოსახვის განვითარებას მნიშვნელოვნად უწყობს ხელს. ამ ეტაპზე ბავშვის სმენა მხედველობაზე უფრო მეტადაა განვითარებული. ამიტომ პირველი 6 თვის განმავლობაში ბავშვისთვის ხმოვანი დეტალების მქონე სათამაშოები უფრო სასარგებლოა. ასეთებია, მაგალითად, მსუბუქი სათამაშოები, რომლებიც სხვადასხვა ხმას გამოსცემს, საწოლსა და სათამაშო ხალიჩაზე ჩამოსაკიდი მუსიკალური სათამაშოები და ჩხარუნები, რომელთა დაჭერაც ბავშვს შეუძლია.') WHERE id = '341dbb77-f89b-4786-ae5e-27fe6c263105';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შეგიმჩნევიათ, რომ პირველი 1-2 თვის განმავლობაში ბავშვს ხელები, ჩვეულებრივ, მუშტებად ჰქონდა შეკრული, ახლა კი შლის? მე-3 თვიდან ბავშვი საკუთარი ხელებით ინტერესდება. ის ხელებს უფრო ხშირად ამოძრავებს, ხოლო მათი ყურება და მოძრაობა მის ერთ-ერთ საყვარელ საქმიანობად იქცევა. ხელების აღმოჩენასთან ერთად მხედველობაც უვითარდება. შეგიძლიათ, ეს პერიოდი კიდევ უფრო საინტერესო გახადოთ! მაჯაზე დასამაგრებელი ხმოვანი სათამაშოებით შეგიძლიათ მის აღმოჩენებით სავსე მოგზაურობას შეუწყოთ ხელი. თუმცა ეს აუცილებლად თქვენი მეთვალყურეობის ქვეშ უნდა მოხდეს — პატარა ხელებს ძალიან სწრაფად მოძრაობა შეუძლია.') WHERE id = 'ad6180ec-951a-4399-9c9f-0798090c6244';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვი შესაძლოა ჯერ კიდევ იყენებდეს ბევრ თანდაყოლილ რეფლექსს. ეს რეფლექსები, რომლებსაც ინსტინქტურ მოძრაობებსაც უწოდებენ, ბავშვის ზრდასთან ერთად ქრება და მათ ადგილს უფრო რთული მოტორული უნარები და ნებაყოფლობითი მოძრაობები იკავებს. ბავშვისთვის მნიშვნელოვანი რეფლექსებია: წოვისა და ძებნის რეფლექსები, მოროს რეფლექსი, კისრის ტონური რეფლექსი, ნაბიჯის გადადგმის რეფლექსი, ჩაჭიდების რეფლექსი, ბაბინსკის რეფლექსი, მოხრის რეფლექსი, ყლაპვისა და პირღებინების რეფლექსები. ამ ეტაპზე ზოგიერთი მათგანი შესაძლოა უკვე გამქრალი იყოს, ზოგი კი თანდათან სუსტდებოდეს. მაგალითად, ძებნისა და წოვის რეფლექსები დაბადებისთანავე ვლინდება და გადარჩენისთვის აუცილებელი კვების ინსტინქტიდან გამომდინარეობს. განვითარების დაახლოებით მე-2 და მე-4 თვეებს შორის, განსაკუთრებით დღისით, ამ რეფლექსებს თანდათან ნებაყოფლობითი ქცევა ანაცვლებს. შესაბამისად, შეიძლება შეამჩნიოთ, რომ ლოყაზე შეხებისას ბავშვი პირს აღარ აღებს და ამას მხოლოდ მაშინ აკეთებს, როდესაც საკვებს მიუახლოებთ.') WHERE id = 'f9a31ada-1c4c-4cc8-a19f-e08982dace02';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვთან ხარისხიანი დროის გატარება ნიშნავს არა დროის ხანგრძლივობაზე, არამედ მასთან ინტერაქციული, ანუ ორმხრივი აქტივობების სარგებლიანობაზე ყურადღების გამახვილებას. ამ თვალსაზრისით, ბავშვთან ერთ ოთახში ყოფნაც კი შეიძლება ხარისხიან დროდ არ ჩაითვალოს, თუ აქტივობასა და ყურადღებას არ იჩენთ. ბავშვის განვითარებისთვის ხარისხიანი დროის ერთ-ერთი მთავარი პირობაა, დაბადებიდანვე მშვიდი, მზრუნველი და ნაზი ხმით, გარკვევით ესაუბროთ და აუხსნათ, რას აკეთებთ. მიუხედავად იმისა, რომ ბავშვს ჯერ არ მიუღწევია იმ ფიზიკური და გონებრივი განვითარების ეტაპისთვის, როდესაც ლაპარაკსა და თქვენი სიტყვების გაგებას შეძლებს, ის ამ ეტაპზევე იწყებს მოსმენილი სხვადასხვა სიტყვის დამახსოვრებას. ბავშვთან ხშირი საუბარი და მრავალფეროვანი სიტყვების გამოყენება ძალიან მნიშვნელოვანია მომავალში მისი ენობრივი განვითარების, მეტყველების უნარისა და გონებრივი განვითარებისთვის. მაგალითად, საფენის გამოცვლისას ჩუმად ყოფნის ნაცვლად, ეტაპობრივად უნდა მოუყვეთ, რას აკეთებთ. ამ მეთოდის ყოველდღიური ცხოვრების ყველა მომენტში გამოყენება ბავშვს მდიდარი ლექსიკური მარაგის ჩამოყალიბებაში დაეხმარება და მისი ინტელექტის განვითარების ხელშემწყობი ფაქტორი გახდება.') WHERE id = 'b5b55ba0-7239-4a48-97b0-39887b3f6198';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტვინის უჯრედები ახალი გამოცდილების მიღებისას ვითარდება. ამ განვითარების ხელშესაწყობად ბავშვს ხშირად უნდა შესთავაზოთ ახალი გამოცდილება. მაგალითად, მასთან ახალი თამაშების თამაში და თქვენს აქტივობებში განსხვავებული სათამაშოების ან მოძრაობების დამატება ტვინის უჯრედებს შორის კავშირების წარმოქმნას დააჩქარებს. განვითარებისთვის მეტად ეფექტიანი შეიძლება იყოს იმის ჩვენებაც კი, თუ როგორ ითამაშოს არსებული სათამაშოებით სხვაგვარად, ან მისთვის ისეთი ნივთების გაცნობა, რომლებსაც ჩვეულებრივ ნანახისგან განსხვავებული ფიზიკური აგებულება აქვს. ამ აქტივობების დროს ბავშვს საშუალება უნდა მისცეთ, ხშირად გაიმეოროს თქვენ მიერ შეთავაზებული ახალი გამოცდილება. რაც უფრო ხშირად გაიმეორებს ბავშვი მოქმედებას, მით უფრო მყარად დამკვიდრდება ეს ახლად მიღებული გამოცდილება მის მეხსიერებაში. რადგან ბავშვი აქტიური სწავლის ეტაპზე გადავიდა, მას პოზიტიურად უნდა მიუდგეთ და გარკვეული რეჟიმის ჩამოყალიბება სცადოთ. დაკვირვებების თანახმად, ბავშვები უფრო მეტად იმახსოვრებენ ბედნიერ მომენტებსა და ყველა იმ სტიმულს, რომელიც მათ ამ მომენტებს ახსენებს. ბავშვზე თქვენი ემოციური მდგომარეობა ძლიერ მოქმედებს, ამიტომ მასთან დროის მხიარულად და ბედნიერად გატარება მასზეც დადებითად იმოქმედებს.') WHERE id = '6974552e-5545-418f-9e3a-c5909451e194';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყველა ბავშვი მისთვის დამახასიათებელი ტემპით იზრდება და განვითარების ეტაპებს სხვადასხვა დროს გადის. ამიტომ ბავშვის განვითარების სხვა ბავშვებთან შედარებას აზრი არ აქვს. მართალია, თქვენს ბავშვს ჯერ არ შეუძლია მეტყველებისთვის საჭირო ორგანოების გონებრივად თუ ფიზიკურად მართვა, მაგრამ დროის დიდ ნაწილს თქვენი ხმის მოსმენაში ატარებს. თქვენი მოსმენისას ბავშვი ენასთან დაკავშირებულ ყველანაირ ინფორმაციას იმახსოვრებს. ამიტომ, მიუხედავად იმისა, რომ ალაპარაკებამდე ჯერ დრო სჭირდება, სხვადასხვა სურვილის გამოსახატავად შეიძლება განსხვავებული ტონით იტიროს, გაიცინოს ან ღუღუნის მსგავსი ხმები გამოსცეს. სიყვარულისა და მის მიმართ გამოჩენილი ყურადღების საპასუხოდ, კვებისას ან საფენის გამოცვლის დროს ბავშვმა შეიძლება ფეხების ქნევით ან სხვადასხვა ხმის გამოცემით მოახდინოს რეაგირება. ამ მხრივ ბავშვებს ინდივიდუალური თავისებურებები ახასიათებთ. ზოგი ბავშვი გამუდმებით ცდილობს აზრიანი ბგერების წარმოთქმას, ზოგი კი შეიძლება დაელოდოს, სანამ ამისთვის სრულად მზად იქნება. კვლევების თანახმად, ბავშვთან ურთიერთობის სტილი მისი მეტყველების განვითარებას უკავშირდება. ბავშვის განვითარების ხელშესაწყობად გირჩევთ, ხშირად ესაუბროთ, ეთამაშოთ, წიგნები წაუკითხოთ და საუბრისას უფრო მარტივი და გასაგები ენა გამოიყენოთ. 😊') WHERE id = '51f1030e-fc36-4b12-b1d7-a64348ea081b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე უამრავი სხვადასხვა აქტივობა არსებობს, რომლებიც საშუალებას მოგცემთ, ბავშვთან ერთად გაატაროთ დრო და ხელი შეუწყოთ მის განვითარებას. მაგალითად, შეგიძლიათ ისეთი გარემო შეუქმნათ, სადაც სხვადასხვა ხმას მოისმენს. ბავშვის მარჯვნივ და მარცხნივ ხმოვანი სათამაშოების ან ჩხრიალების შერხევით შეგიძლიათ წაახალისოთ, რომ ხმის წყაროსკენ გაიხედოს. განსაკუთრებით მაშინ, როცა კარგ ხასიათზეა, ბანაობის ან ძუძუთი კვების შემდეგ შეგიძლიათ სხვადასხვა ცხოველის ხმა მოასმენინოთ. თავდაპირველად მოასმენინეთ მისთვის შედარებით ნაცნობი ცხოველების, მაგალითად, კატისა და ძაღლის ხმები, შემდეგ კი — ცხენის, ფუტკრის, ვირისა და სხვა ცხოველების ხმები. ამისთვის შეგიძლიათ ინტერნეტი და შემეცნებითი წიგნები გამოიყენოთ. ამ ხმების მიბაძვა თავადაც შეგიძლიათ. დააკვირდით, როგორ რეაგირებს ბავშვი სხვადასხვა ხმაზე. დაინახავთ, რამდენად გაახალისებს მას ეს ერთობლივი აქტივობა. 😊') WHERE id = 'e2c4c53d-e6ae-41f3-83d4-6473c78c7fb7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა, ალბათ, უკვე დაიწყო გადაბრუნება. ზოგი ბავშვი ამას უფრო ადრეც ახერხებს. თუმცა, თუ თქვენი ბავშვი ჯერ არ ბრუნდება, ეს სანერვიულო არ არის. ყველა ბავშვი უნიკალურია და მათი განვითარებაც შეიძლება მნიშვნელოვნად განსხვავდებოდეს. ბავშვის თავისუფლად გადაბრუნების უნარი თავისა და კისრის კუნთების განვითარებაზეა დამოკიდებული. როდესაც ბავშვი თავისა და კისრის კონტროლს შეძლებს, ამით საფუძველი ეყრება ისეთ მოტორულ უნარებსაც, როგორებიცაა ჯდომა, ხოხვა და სიარული. გადაბრუნების წასახალისებლად შეგიძლიათ ბავშვი რბილ ზედაპირზე მუცლით დააწვინოთ და ვარჯიშის საშუალება მისცეთ. დღენაკლულ ბავშვებში კუნთოვანი და ნერვული სისტემები სხვაგვარად ვითარდება, ამიტომ მათ თავისა და კისრის კონტროლის ათვისება შეიძლება უფრო გვიან შეძლონ. თუ თქვენი ბავშვი ნაადრევად დაიბადა, გადაბრუნების დასაწყებად მას მე-9 თვემდე აქვს დრო. და ვინ იცის? იქნებ გადაბრუნების ეტაპი გამოტოვოს და პირდაპირ ჯდომა დაიწყოს? 😊') WHERE id = '4f657a4a-e832-4fda-9834-e8fa08bd9d44';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის პირიდან გადმოსული ნერწყვი, ყველაფრის პირში ჩადების მცდელობა... ალბათ, ამის მიზეზი თქვენც იცით. ამ თვიდან თქვენი ბავშვისთვის კბილების ამოჭრის პერიოდი იწყება. როცა იცინის, მის მხიარულ სიცილს კბილები კიდევ უფრო საყვარელს ხდის. თუმცა კბილების ამოჭრის პერიოდი ბავშვების უმეტესობისთვის მტკივნეულია. ღრძილების შეშუპებამ შეიძლება ბავშვში დისკომფორტი და ტკივილი გამოიწვიოს. კბილების ამოჭრის ყველაზე ცნობილი ნიშანი, რა თქმა უნდა, ჭარბი ნერწყვდენაა. სხვა ნიშნებია ხელში მოხვედრილი ყველაფრის კბენის მცდელობა, სხეულის ტემპერატურის უმნიშვნელო მომატება და ძუძუს ან საკვებზე უარის თქმა. ეს ნიშნები შეიძლება რამდენიმე თვით ადრეც გამოვლინდეს, ან მემკვიდრეობითი თავისებურებების მიხედვით, კბილები ამ თვეში ყოველგვარი სიმპტომების გარეშე გამოჩნდეს. კბილების ამოჭრის დროს ბავშვის სხეულის ტემპერატურის 37 გრადუსამდე მომატება ექიმების მიერ ნორმალურად ითვლება და ჩარევას არ საჭიროებს. თუმცა, თუ ბავშვის ტემპერატურა 38 გრადუსამდე ან უფრო მაღლა აიწევს, ეს კბილების ამოჭრის ნიშანი არ არის და ექიმთან კონსულტაციას საჭიროებს.') WHERE id = 'fd702e8d-6a0f-4f31-a1a0-b330e1d04288';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვისთვის თმის შეჭრას სახლში გადაწყვეტთ, რამდენიმე საკითხი უნდა გაითვალისწინოთ. პირველ რიგში, შეჭრის დაწყებამდე დარწმუნდით, რომ ბავშვი დანაყრებულია და არ აწუხებს აირების დაგროვებით გამოწვეული ტკივილი ან სხვა სახის დისკომფორტი. დისკომფორტის დროს ბავშვი შეიძლება მოუსვენარი იყოს და უეცარი მოძრაობები გააკეთოს, რამაც შესაძლოა სახიფათო დაზიანება ან თმის არასწორად შეჭრა გამოიწვიოს. თუ ბავშვს ჯდომა შეუძლია, შეგიძლიათ საბავშვო კვების სკამის მსგავს კომფორტულ ადგილას მოათავსოთ ან კალთაში დაისვათ და მყარად დაიჭიროთ. შესაჭრელად პატარა, ბლაგვწვერიანი მაკრატელი უნდა გამოიყენოთ. ყურადღების გადასატანად შეგიძლიათ საყვარელი სათამაშო მისცეთ და თმის შეჭრისას განუწყვეტლივ ესაუბროთ — ეს სიმშვიდის შენარჩუნებაში დაეხმარება. თმის შეჭრისას განსაკუთრებული სიფრთხილე გამოიჩინეთ ყურებთან, კისერსა და შუბლთან. საჭიროების შემთხვევაში, დამხმარე ადამიანს სთხოვეთ, ბავშვს თავი მყარად დაუჭიროს. პროცესის დასრულებამდე ბავშვი მაკრატელთან მარტო არ დატოვოთ და გვერდიდან არ მოშორდეთ. ამიტომ მუშაობის დაწყებამდე წინასწარ მოამზადეთ პირსახოცი, სავარცხელი და სხვა საჭირო ნივთები.') WHERE id = '4c05c1b9-816f-4b3a-9570-73a5e8523f06';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ, ის დღე, როცა ბავშვი პირველად ჩაიხუტეთ, გუშინდელივით გახსოვთ. დრო მართლაც სწრაფად გადის, არა? 😊 მე-4 თვეს მიღწეული ბავშვი უკვე გაგრძნობინებთ, რომ იზრდება. მას სურს, მუდმივად ყურადღება მიაქციოთ და ყოველ შესაძლებლობაზე გახსენებთ, რომ თამაში უყვარს. მუცელზე წოლისას ხელებსა და იდაყვებს დაყრდნობილი ბავშვი მკერდამდე წამოიწევა და პირქვე წოლისას თავის 90 გრადუსით აწევა შეუძლია. ამ პერიოდში საგრძნობლად მატულობს ხმამაღალი სიცილი და ყურადღების მისაპყრობად წამოძახილებიც. შეიძლება ისიც კი შეამჩნიოთ, რომ ბავშვი დასაჯდომად უკვე დიდ ძალისხმევას იჩენს. ზოგი სპეციალისტი ბავშვის მე-6 თვემდე დასმას არ ემხრობა, თუმცა ზოგი ექიმი მიიჩნევს, რომ ყველა ბავშვის განვითარება განსხვავებულია. ამიტომ ძალიან მნიშვნელოვანია, დააკვირდეთ ბავშვს და ეცადოთ, გაიგოთ, რა სურს. თუ ბავშვს ჯდომა ძალიან უნდა, საყრდენით ძალიან მცირე ხნით დასმამ შეიძლება იგი მეტად გაახაროს. მიუხედავად ამისა, რადგან ყველა ბავშვი თავისებურად ვითარდება, ამ საკითხზე უმჯობესია თქვენი ექიმის მოსაზრებაც მოისმინოთ. 😊') WHERE id = '2ec8f436-2faa-47d9-bf8d-3c7a85cda289';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მომდევნო კვირები შესაძლოა ცოტა რთული იყოს როგორც თქვენთვის, ისე თქვენი ბავშვისთვის. განვითარების მეოთხე ნახტომის პერიოდი, რომელიც 14-19-ე კვირებს მოიცავს, განვითარების ერთ-ერთი ყველაზე ხანგრძლივი ეტაპია. ამ ზრდის პერიოდის წინ ბევრმა ბავშვმა შეიძლება უარი თქვას ძუძუს ან ხელოვნური საკვების მიღებაზე. მაშინ, როცა იფიქრებთ, რომ ძილის რეჟიმი მოწესრიგდა, ბავშვს შესაძლოა დაძინების მიმართ წინააღმდეგობა გაუჩნდეს. ამასთანავე, ბავშვმა შეიძლება მუდმივად ხელში ყოფნა მოინდომოს და მოუსვენრობამ ცოტა დაგღალოთ. თუმცა ამ რთული პერიოდის დასრულების შემდეგ თქვენი ბავშვისთვის სრულიად ახალი ეტაპი დაიწყება. ის უკვე მოვლენათა თანმიმდევრობის აღმოჩენას იწყებს. მაგალითად, როდესაც ბავშვი რაიმე საგანს დაინახავს, შესაძლოა ის მის ყურადღებას მიიქცევს, მოუნდება მაგრად ჩაეჭიდოს და შეისწავლოს. ხელში ცოტა ხნით დაჭერის შემდეგ კი შეიძლება საგანი პირთან მიიტანოს, რათა ახლოდან გაიცნოს. ზრდის ამ ნახტომის ბოლოს შესაძლოა შეამჩნიოთ, რომ ბავშვი სარკეში საკუთარ თავს ცნობს და უღიმის. ბავშვი უკვე ხვდება, როდის დანაყრდა და საკმარისი რძის მიღების შემდეგ შესაძლოა ძუძუს ან ბოთლს მოშორდეს, რაც ამოქაფების პრობლემის მინიმუმამდე შემცირებას უწყობს ხელს.') WHERE id = '57457675-a7c5-476e-b444-66d0b8d0364f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მე-4 თვის ექიმის შემოწმებისას ბავშვის განვითარების შესაფასებლად ამოწმებენ მის სიმაღლეს, წონას, თავის გარშემოწერილობას, მხედველობას, ზურგისა და კისრის კუნთებს. ამ ეტაპზე ბავშვის წონა 4800-9100 გრამის, ხოლო სიმაღლე 58-69 სმ-ის ფარგლებში უნდა იყოს. ამ მაჩვენებლების ქვედა ან ზედა ზღვართან სიახლოვე არ ნიშნავს, რომ თქვენს ბავშვს განვითარების რაიმე პრობლემა აქვს. თავის გარშემოწერილობა კი ამ პერიოდში 39-45 სმ-ის ფარგლებშია. რადგან ეს ტვინის ჯანსაღი განვითარების მაჩვენებელია, ძალიან მნიშვნელოვანია, რომ თავის გარშემოწერილობა ამ დიაპაზონში იყოს. ვინაიდან მხედველობა უკვე სრულად ჩამოყალიბებულია, ბავშვს ამიერიდან საგნების ნამდვილი ფერებით დანახვა შეუძლია. ეს გარესამყაროს უფრო საინტერესოს ხდის; თქვენმა ბავშვმა შესაძლოა შეამციროს ძილისა და წოვისთვის განკუთვნილი დრო და გარემოთი უფრო მეტად დაინტერესდეს. ამასთანავე, რადგან მე-4 თვე ზრდის ხანგრძლივ ნახტომს მოიცავს, ყველა ამ ცვლილების ფონზე შესაძლოა ძილის რეგრესია განვითარდეს. ამიტომ შეიძლება საჭირო გახდეს, რომ თქვენს ბავშვს ჩვეულებრივზე მეტი ყურადღება დაუთმოთ. შეეცადეთ, ერთად გატარებული დროით დატკბეთ. სასიამოვნო დროის გატარებას გისურვებთ! 😊') WHERE id = '3e04c60c-ae8b-4665-9ca2-95ef5bdb8192';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის მე-4 თვის შემოწმებისას გასაკეთებელი აცრები, მე-2 თვეში ჩატარებული ტუბერკულოზის საწინააღმდეგო აცრის გარდა, დანარჩენი ორი ვაქცინის მეორე დოზებია. ესენია პნევმოკოკური (მენინგიტის საწინააღმდეგო) ვაქცინა და ხუთკომპონენტიანი კომბინირებული ვაქცინა დიფთერიის, ყივანახველის, ტეტანუსის, Hib ინფექციისა და პოლიომიელიტის წინააღმდეგ. თუ ბავშვს როტავირუსის საწინააღმდეგო ვაქცინა მე-2 თვეში ჩაუტარდა, მეორე დოზა ამ თვეში უნდა მიიღოს. თუ მე-4 თვის აცრების შემდეგ თქვენს ბავშვს სიცხე და მოუსვენრობა ექნება, შეგიძლიათ მისცეთ ექიმის მიერ რეკომენდებული სიცხის დამწევი საშუალება. მიუხედავად იმისა, რომ ყველა ბავშვის რეაქცია განსხვავებულია, ტემპერატურამ ჩვეულებრივ აცრიდან 2-4 საათის შემდეგ შეიძლება მოიმატოს. სიცხე ზოგჯერ 2-3 დღემდე გრძელდება. ამასთანავე, ყველა აცრის შემდეგ შესაძლოა ინიექციის ადგილას ტკივილი, შეშუპება და სიწითლე გამოვლინდეს. ბავშვის მოუსვენრობისა და ჩივილების შესამსუბუქებლად შეგიძლიათ ინიექციის ადგილას ცივი კომპრესი დაადოთ და ექიმის რეკომენდაციით ტკივილგამაყუჩებლად პარაცეტამოლის შემცველი პრეპარატები გამოიყენოთ.') WHERE id = 'ecec54a9-6b16-4860-9c1c-01c24cd2eac2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე აქტიური სწავლის ეტაპზეა და შეგიძლიათ შეამჩნიოთ, რომ ყველა ახალ გამოცდილებას ინტერესით ეხმაურება. განვითარების ერთ-ერთი ასეთი ეტაპი მეტყველების უნარის საფუძვლის ჩამოყალიბებაა. ის უკვე რეაგირებს თქვენს ხმაზე და მოსმენილი ბგერების გამეორება უყვარს. განსაკუთრებით მაშინ, როცა ბედნიერია, შეიძლება წვრილი ხმით წამოიყვიროს, ხმამაღლა გაიცინოს და „ა-ღუ“ მსგავსი ბგერები გამოსცეს. ბავშვის მეტყველების უნარის გასავითარებლად გირჩევთ, ხშირად ესაუბროთ. 😊 მეოთხე თვის ბავშვი გარეგანი სტიმულებით ძალიან ინტერესდება, ამიტომ ყურადღება შეიძლება ხშირად გაეფანტოს. მაგალითად, თუ ჭამისას მის ყურადღებას სხვა რამ მიიპყრობს, შესაძლოა წოვა შეწყვიტოს. დროდადრო ძილზე უარის თქმის მიზეზიც შეიძლება ეს იყოს. მოთმინება გმართებთ, რადგან მისთვის სამყარო ძალიან დიდია და ჯერ კიდევ უამრავი რამ აქვს აღმოსაჩენი! 😊') WHERE id = '0479afbe-b14f-457d-b226-70e3d4f9bf7b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში თქვენმა ბავშვმა შესაძლოა გაგაოცოთ და მუცელზე წოლისას გვერდზე ან ზურგზეც კი გადაბრუნდეს. ზურგისა და კისრის განვითარებული კუნთების წყალობით, გადაბრუნების ეს მცდელობები ხშირად წარმატებით სრულდება. ამ თვიდან ბავშვმა შესაძლოა დაჯდომაც კი დაიწყოს. მიუხედავად იმისა, რომ ზოგიერთი ექიმი ბავშვის 6 თვემდე დასმას არ გირჩევთ, უნდა გახსოვდეთ, რომ ყველა ბავშვის განვითარება განსხვავებულია. როდესაც ბავშვის ტვინი და სხეული მზად იქნება, ანუ კუნთებისა და წონასწორობის კონტროლი საკმარის დონეს მიაღწევს, ის თავად მიიღებს მჯდომარე პოზიციას. თუ თქვენი ბავშვი წამოწევას და დაჯდომას ცდილობს, შეგიძლიათ ამის ნება მისცეთ, ოღონდ არა ძალიან დიდი ხნით. იმის დანახვა, რომ ეს შეძლო, გაახარებს და წაახალისებს. მიუხედავად ამისა, არ დაგავიწყდეთ მისი ზურგის მხარდაჭერა. მართალია, ზოგიერთი ბავშვი ამ თვეში ჯდომას იწყებს, მაგრამ უნდა გახსოვდეთ, რომ მათი ზურგის კუნთები ჯერ არ არის საკმარისად ძლიერი დამოუკიდებლად ჯდომისთვის.') WHERE id = '3e15f79b-7870-4c1b-9ff8-0d7695190d48';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა დაბადების წონა უკვე საშუალოდ გააორმაგა და, თუ ძუძუთი კვებავთ, ზოგჯერ შეიძლება იფიქროთ, რომ რძე არ ჰყოფნის. რადგან მე-4 და მე-5 თვეები ბავშვის სწრაფი ფიზიკური განვითარების პერიოდია, მისი ენერგეტიკული მოთხოვნილება იზრდება. ამ გაზრდილი მოთხოვნილების დასაკმაყოფილებლად შესაძლოა დამატებითი კვების დაწყება გადაწყვიტოთ. თუმცა გახსოვდეთ, რომ ამ ეტაპზე ბავშვის ნაწლავური ფლორა ჯერ არ არის მზად მყარი საკვებისთვის. დამატებითი საკვები ძალიან მცირე რაოდენობით ეძლევა, რათა ბავშვი მყარ საკვებს მიეჩვიოს, ხოლო ნაწლავების ჯანსაღი განვითარებისთვის ეს პროცესი მე-6 თვის შემდეგ უნდა დაიწყოს. ჯანდაცვის მსოფლიო ორგანიზაცია (ჯანმო) გირჩევთ, პირველი 6 თვის დასრულებამდე ბავშვს მხოლოდ დედის რძე მისცეთ, ხოლო თუ ეს შეუძლებელია — ერთადერთი ალტერნატივა, ხელოვნური საკვები. ნებისმიერი დამატებითი საკვების 6 თვემდე დაწყებამ თქვენს ბავშვში შესაძლოა გამოიწვიოს ანემია, საჭმლის მონელების დარღვევა, აირებით გამოწვეული ჭვალი, კუჭისა და ნაწლავების პრობლემები. ამიტომ დამატებითი კვების დაწყებას ნუ იჩქარებთ, დედიკო.') WHERE id = '63dc3b2b-9b88-4480-8d80-226d9607b848';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან ბავშვის სანერწყვე ჯირკვლები უკვე უფრო აქტიურად მუშაობს, პირის სისველე და ნერწყვის დენა, რომლის კონტროლიც მას ჯერ არ შეუძლია, სრულიად ნორმალურია. ეს ნიშნები შესაძლოა კბილების ამოჭრის მოახლოებაზეც მიუთითებდეს; ღრძილების ქავილის გამო ბავშვმა შეიძლება ხელები ხშირად ჩაიდოს პირში. სპეციალისტები გვირჩევენ, ამ დროს ბავშვს ხელი არ შევუშალოთ და, პირიქით, საკუთარი ხელების შესწავლის საშუალება მივცეთ. თუმცა არ უნდა დაგავიწყდეთ, რომ ბავშვმა, რომელიც ყველაფრის პირში ჩადებას ცდილობს, შესაძლოა პატარა ნივთები გადაყლაპოს. განსაკუთრებით მოარიდეთ ადვილად მტვრევადი და ნაწილებად დაშლადი სათამაშოები და დარწმუნდით, რომ ყველა ნივთი, რომლითაც ის თამაშობს, სუფთა და სტერილურია. ღრძილების ქავილის გამო ბავშვს ყველაფრის ღეჭვა მოუნდება და შეიძლება, როცა ვერ ხედავთ, პირში სახიფათო ნივთი ჩაიდოს. დახრჩობის შესაძლო საფრთხის თავიდან ასაცილებლად ყურადღებით შეარჩიეთ სათამაშოები და გააძლიერეთ უსაფრთხოების ზომები.') WHERE id = 'ff292524-4cb1-4b4f-9235-43064f330adc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია გადაბრუნება, საკუთარი სხეულის გარშემო ტრიალი, წოლისას თავის 45 გრადუსამდე აწევა და თავისა და სხეულის მარჯვნივ-მარცხნივ მოძრაობა. ეს მოძრაობები განვითარების ნორმალური ნაწილია. შესაძლოა ისიც კი შეამჩნიოთ, რომ მუცელზე დაწოლისას წინ ხოხვის მსგავს მოძრაობებს აკეთებს. თქვენს ბავშვს, ისევე როგორც ყველა ბავშვს, ძალიან სურს ახალი უნარების ათვისება და ნასწავლის ხშირად გამეორება. თუმცა გახსოვდეთ, რომ თითოეული ბავშვის განვითარება ინდივიდუალურია; თუ თქვენს ბავშვს ამ უნარებიდან ზოგიერთი ჯერ არ აუთვისებია, ნუ ინერვიულებთ. ამასთან, მის განვითარებას სწორად რომ შეუწყოთ ხელი, რამდენიმე ნიუანსს უნდა მიაქციოთ ყურადღება. ერთ-ერთი მათგანია ჭოჭინას გამოყენება. მიუხედავად იმისა, რომ მუდმივად მოძრაობისა და გარემოს შესწავლის სურვილით ბავშვმა ზოგჯერ შეიძლება დაგღალოთ, გამოსავალი ჭოჭინაში არ უნდა ეძებოთ. 6 თვეზე ნაკლები ასაკის ბავშვის, რომელიც ჯერ დასაჯდომად მზად არ არის, იძულებით დასმა ან ჭოჭინაში ჩასმა შესაძლოა ხელს უშლიდეს იმ კუნთების განვითარებას, რომლებიც მომავალში ოთხზე ცოცვისა და ხოხვის მსგავსი მნიშვნელოვანი უნარებისთვის არის საჭირო.') WHERE id = 'ea44cd71-5051-4dfc-bbf3-dac92612f0a6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ, ერთ-ერთი საკითხი, რომელიც ყველაზე მეტად გაეჭვებთ, ის არის, თუ როგორ ჩააცვათ ბავშვს ღამის ძილის წინ. რადგან თქვენი ბავშვი უკვე საკმაოდ მოძრავია, შეიძლება ხშირად გადაიხადოს გადასაფარებელი ან საბანი. თითქმის ყველა ბავშვს არ უყვარს ზედმეტი სითბო და სიცხეში თავს არაკომფორტულად გრძნობს. იდეალურია, თუ ოთახში, სადაც ბავშვს აძინებთ, ტემპერატურას 22-24 გრადუსის, ხოლო ტენიანობას 40-60%-ის ფარგლებში შეინარჩუნებთ. ღამის ძილისთვის მომზადებისას შეგიძლიათ ჩააცვათ ბამბის საძილე ტომარა, შიგნით კი, სეზონის შესაბამისად, თხელი ბამბის პიჟამა. იმის გასაგებად, საკმარისად აცვია თუ არა, შეგიძლიათ სხეულის ტემპერატურა იღლიაში გაუზომოთ. თუ ტემპერატურა 36.2-დან 37.2 გრადუსამდეა, ეს ნიშნავს, რომ ბავშვს არ სცივა. ამ მაჩვენებლებზე დაბალი ტემპერატურა მიუთითებს, რომ მას სცივა; ასეთ შემთხვევაში შეგიძლიათ ტანსაცმლის კიდევ ერთი ფენა ჩააცვათ.') WHERE id = '3719fbec-0855-4e9e-bd59-1324c629c2ce';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია ნაცნობი სახეების გარჩევა და გარშემომყოფებისადმი ინტერესს იჩენს. ნუ გაგიკვირდებათ, თუ განსაკუთრებით ნაცნობ ადამიანებს ღიმილით გამოეხმაურება. 😊 4-ე თვეში ბავშვი ბევრ ახალ უნარს იძენს. ეს უნარები მოიცავს როგორც ფიზიკურ, ისე გონებრივ განვითარებას. ბავშვს, რომლის ხელისა და თვალის კოორდინაციაც საგრძნობლად გაუმჯობესდა, ახლა ურთიერთობა უფრო მეტად სიამოვნებს. სწორედ ამიტომ შეიძლება ის საკუთარ ხელებს წუთების განმავლობაში აღფრთოვანებით აკვირდებოდეს, თმაზე გქაჩავდეთ და ყველაფერს, რასაც იპოვის, პირში იდებდეს. ბავშვთან, რომელსაც თქვენი დახმარებით შეუძლია ნივთებისკენ ხელის გაწვდენა და სათამაშოების ჩაჭიდება, ბევრი მარტივი თამაში შეგიძლიათ ითამაშოთ. ამასთან, მისი ასაკობრივი განვითარებისთვის შესაფერისი აქტივობების სათამაშოების გამოყენება ხელს შეუწყობს როგორც ფიზიკურ, ისე გონებრივ განვითარებას. სათამაშოს არჩევისას გირჩევთ, უპირატესობა მიანიჭოთ ისეთ სათამაშოებს, რომლებიც ბავშვს მიზეზშედეგობრივი კავშირის აღქმაში დაეხმარება.') WHERE id = 'aeb00407-e412-4f78-961f-30f7b120bf0d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის გარე სამყარო უსასრულო აღმოჩენების სივრცეა და დროა, ამას გაგებით მოეკიდოთ. სრულიად ნორმალურია, თუ მას მუდმივად ხელში ყოფნა სურს, ძილზე ან ძუძუს წოვაზე უარს ამბობს, ერთ ადგილას არ ჩერდება და ხშირად თამაში უნდა. ამასთან, ვარჯიში და მოძრაობა ბავშვის ფიზიოლოგიური განვითარებისთვის ძალიან მნიშვნელოვანია. ბავშვის სავარჯიშებლად შეგიძლიათ კოჭებში მოკიდოთ ხელი, ფეხები ფრთხილად მოუხაროთ და ზევით-ქვევით ამოძრაოთ. ასევე შეგიძლიათ ორივე მკლავში მოკიდოთ ხელი, მკერდთან შეაერთოთ და ჯვარედინად გაშალოთ და შეკრათ. ამ მოძრაობების შესრულებისას, ბავშვმა თავი უფრო მშვიდად რომ იგრძნოს, არ დაგავიწყდეთ მასთან საუბარი და ხშირად გაღიმება. ერთად გატარებული ეს წუთები თქვენი ბავშვის სოციალიზაციის ერთ-ერთი ყველაზე ჯანსაღი გზაა.') WHERE id = '77bdf252-33eb-455c-b59d-8af7012e078c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დროულად დაბადებული ბევრი ბავშვი შესაძლოა მყარი საკვების მისაღებად ჯერ კიდევ სამი თვის ასაკში ჩანდეს მზად. თუმცა მყარ საკვებზე გადასვლაში ხელის შემშლელი „ენის გამოყოფის“ რეფლექსი, ჩვეულებრივ, მეოთხე თვიდან იწყებს გაქრობას. სინამდვილეში ეს რეფლექსი მნიშვნელოვან როლს ასრულებს წოვის პროცესში და ბავშვს თქვენ მიერ მიცემული საკვების ენით გარეთ გამოდევნას აიძულებს. ამ თვიდან ბავშვის საჭმლის მომნელებელ სისტემას უკვე შეუძლია ზოგიერთი საკვების მონელება. თუმცა ეს განვითარების ეტაპობრივი პროცესის ნაწილია და არ ნიშნავს, რომ ბავშვი მყარი საკვებისთვის სრულად მზადაა. ამ საკითხთან დაკავშირებით ჯანმოს რეკომენდაცია ასეთია: თუ ბავშვი წონას არ კარგავს და ჯანმრთელად იზრდება, 6-ე თვემდე მხოლოდ ძუძუთი კვება უნდა გაგრძელდეს. თუ 6-ე თვემდე დედის რძე არასაკმარისია და ბავშვი თვეში 500 გრამზე ნაკლებს იმატებს, უნდა გახსოვდეთ, რომ კვებაში ძირითადი ადგილი ადაპტირებულმა რძის ნარევმა უნდა დაიკავოს. 6 თვის შესრულების შემდეგაც კი, ძირითად საკვებად კვლავ დედის რძე უნდა დარჩეს. ჯანმო რეკომენდაციას უწევს, რომ 9 თვის ბავშვის კვების 70% დედის რძისგან შედგებოდეს.') WHERE id = '8360a204-f867-4fb6-bb2c-9a237526ca1c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში თქვენი ბავშვი შესაძლოა პირველად გადაბრუნდეს. ბავშვები ამ მოძრაობას, ჩვეულებრივ, დაახლოებით 4 თვის ასაკში ასრულებენ — მუცელზე წოლისას გვერდზე გადაბრუნებით. თითქმის ყველა ბავშვს, როგორც კი აღმოაჩენს, რომ ეს შეუძლია, მოძრაობის გამეორება სურს და ასე იწყება დაუსრულებელი გადაბრუნებები. თუმცა ზოგიერთი ბავშვი გადაბრუნების შემდეგ შესაძლოა შეშინდეს და გარკვეული ხნით ხელახლა ცდისგან თავი შეიკავოს. ბავშვის მუცლის მომრგვალებული და მოქნილი ფორმა ამ მოძრაობის მარტივად შესრულებაში მნიშვნელოვნად ეხმარება. გადაბრუნების წასახალისებლად და ზურგის კუნთების გასაძლიერებლად შეგიძლიათ ბავშვს გაწვდენის მოძრაობების შესრულებისკენ უბიძგოთ. მაგალითად, სათამაშოს ან რაიმე ნივთის აღების მცდელობამ შეიძლება მას გადაბრუნებაში შეუწყოს ხელი. თუმცა ძალიან ყურადღებით უნდა იყოთ, რომ გადაბრუნებისას ბავშვი პირქვე, სუნთქვისთვის სახიფათო მდგომარეობაში არ დარჩეს ან ისეთ ადგილას არ აღმოჩნდეს, საიდანაც შეიძლება ჩამოვარდეს. ამ ვარჯიშების დროს ბავშვი მარტო არ დატოვოთ.') WHERE id = '74e1e965-f81e-44cc-a407-7883c6451cc2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პირველ თვეებთან შედარებით, შესაძლოა მოგეჩვენოთ, რომ ბავშვი ნაკლებს ჭამს. მიუხედავად იმისა, რომ ამან შეიძლება შეგაშფოთოთ, სინამდვილეში ეს ბუნებრივი პროცესია. მთავარი მიზეზი ისაა, რომ ბავშვმა უკვე ისწავლა, როგორ იკვებოს უფრო ეფექტურად. ახლა მას ნაკლებ დროში უფრო მეტი რძის წოვა შეუძლია, რაც ნიშნავს, რომ უფრო სწრაფად ნაყრდება. ამიტომ თქვენმა ბავშვმა შეიძლება დღის განმავლობაში კვების რაოდენობა 4-5-მდე შეამციროს. ამასთანავე, ამ თვეში მოსალოდნელმა ზრდის ნახტომმა შესაძლოა კვებაში ხანმოკლე ცვლილებები გამოიწვიოს. რადგან ბავშვის მოძრაობებზე დაკვირვებით უკვე მარტივად შეგიძლიათ მიხვდეთ, რომ შია, კვების საათებიც შესაბამისად შეგიძლიათ დაარეგულიროთ. მაგალითად, 4 თვის ასაკიდან ბავშვის ძუძუთი კვებისთვის ძილიდან გაღვიძება აუცილებელი აღარ არის. გარდა ამისა, მომდევნო ძუძუთი კვებამდე დაახლოებით 4 საათიანი შუალედის დაცვა ბავშვს დაეხმარება, უკეთ ისარგებლოს რძეში არსებული საკვები ნივთიერებებით.') WHERE id = 'ea6d6e3a-c957-436f-ac9c-f0c52e449526';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი განაგრძობს თქვენზე, თქვენს სახეზე, მიმიკებსა და, მოკლედ, მასთან ურთიერთობის თითოეულ მომენტზე დაკვირვებას. ასეთი უწყვეტი დაკვირვება ეხმარება, სამყაროს შესახებ მისი აღმოჩენები უფრო მრავალფეროვანი და მდიდარი გახდეს. ბავშვის ყოველი ახალი აღმოჩენა მის ტვინში ნერვულ უჯრედებს შორის კავშირების ჩამოყალიბებას უწყობს ხელს, რის შედეგადაც ის ინფორმაციის აღქმასა და სწავლას უფრო სწრაფად იწყებს. ამ კავშირების შესაქმნელად საკმარისია, რომ მისთვის მიცემულმა ჩხარუნამ ხმა გამოსცეს, ბავშვმა სათამაშოების ფორმები შეისწავლოს ან თუნდაც თვალით გამოგაყოლოთ. თქვენი ბავშვი ცდილობს უფრო ყურადღებით დააკვირდეს თქვენს მიმიკებს, ხმის ტონსა და ქცევებსაც კი. ეს კი იმას ნიშნავს, რომ მას უკვე უკეთ ესმის თქვენი. ამიტომ მის მიმართ გამოჩენილი ყურადღების შედეგებს სწორედ ამ თვეებიდან შეამჩნევთ. ყოველი წუთი, როცა ერთმანეთს ეკონტაქტებით და ბავშვს ყურადღებას უთმობთ, თქვენს შორის არსებულ კავშირს კიდევ უფრო გააძლიერებს.') WHERE id = '170aa164-55dd-45ac-8848-491ec6187f44';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გაციების, სეზონის ცვლილების, გრიპის ან ალერგიის გამო თქვენს ბავშვს შესაძლოა ცხვირი ხშირად გაეჭედოს. ცხვირის გაჭედვა არა მხოლოდ სუნთქვას ურთულებს, არამედ კვებისა და ძილის რეჟიმზეც უარყოფითად მოქმედებს. ძუძუზე უარის თქმის ერთ-ერთი მთავარი მიზეზიც სწორედ ცხვირის გაჭედვაა: სუნთქვისთვის ბავშვს პირის გამოყენება უწევს და, ბუნებრივია, წოვა აღარ სურს. ბავშვისთვის საკმაოდ შემაწუხებელი ამ მდგომარეობის შესამსუბუქებლად შეგიძლიათ გამოიყენოთ ექიმის მიერ რეკომენდებული საბავშვო ცხვირის სპრეი, ფიზიოლოგიური ხსნარი და ოთახის დამატენიანებელი. ფიზიოლოგიური ხსნარი (იზოტონური ნატრიუმის ქლორიდი), რომელსაც მარილიანი წყლის სახელითაც იცნობენ და ქიმიურ დანამატებს არ შეიცავს, ბავშვს ცხვირს მოკლე დროში გაუხსნის. განსაკუთრებით თუ პირველად გახდით დედა, მისი გამოყენება შესაძლოა გაგიჭირდეთ. თუ ფიზიოლოგიური ხსნარი საკმარისი არ აღმოჩნდება, შეგიძლიათ სპეციალურად ბავშვებისთვის შექმნილი ცხვირის ასპირატორიც გამოიყენოთ.') WHERE id = '9c8572cd-a48b-4b37-a542-edfc74817a74';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ფიზიკური განვითარებისა და ხოხვისა და ცოცვის ეტაპისთვის მოსამზადებლად სპეციალისტები ერთ ვარჯიშს გირჩევენ. აქტივობა, რომელსაც Tummy time (მუცელზე წოლის დრო) ეწოდება, შეგიძლიათ ბავშვის მუცელზე დაწვენით შეასრულოთ. ის ავითარებს ზურგის კუნთებს, რომლებსაც ბავშვი, ჩვეულებრივ, ნაკლებად იყენებს და ამავდროულად აძლიერებს ფეხების, კისრის, მხრებისა და მუცლის კუნთებს. მოტორული უნარების განმავითარებელი ეს მოძრაობები ასევე ხელს უშლის ბავშვის თავის ფორმის შესაძლო დეფორმაციას (ბრტყელი თავის სინდრომს). ირგვლივ დალაგებული სათამაშოებით შეგიძლიათ ხელი შეუწყოთ ბავშვის ტვინში მრავალმხრივი კავშირების ჩამოყალიბებას. თქვენს ბავშვს შეიძლება მუცელზე ყოფნა მალე მობეზრდეს ან ყურადღება გაეფანტოს, ამიტომ მის გვერდით დარჩით და ეცადეთ, მისი ინტერესი სხვადასხვა მიმართულებით წარმართოთ. მასთან საუბარი, ლექსების თქმა, საყვარელი სათამაშოების ჩვენება და დამამშვიდებელი მუსიკის ჩართვა ამ პროცესს მნიშვნელოვნად გაგიმარტივებთ. სასიამოვნო გართობას გისურვებთ! 😊') WHERE id = '3d1db687-2705-4040-8e81-a914b3ab0052';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტვინში არსებული მილიარდობით ნერვული უჯრედის წყალობით, სწავლისთვის ყველაზე ხელსაყრელი პერიოდი დაბადებიდან 48 თვის ასაკამდე გრძელდება. ამიტომ ამ პერიოდში ბავშვთან ხარისხიანი და დაგეგმილი ურთიერთობა მის განვითარებას დიდ სტიმულს მისცემს. კვლევების თანახმად, ბავშვები, რომლებიც ჩვილობის პერიოდში სწორად ვითარდებიან, სასკოლო ასაკში უკეთეს საგანმანათლებლო შედეგებს აჩვენებენ, რაც მათ ცხოვრებაზე მნიშვნელოვან გავლენას ახდენს. დაბადებიდან ბავშვთან გატარებული დრო და ამ პერიოდში ხარისხიანი ურთიერთქმედება მის ტვინისა და ემოციურ განვითარებაზე მრავალმხრივ დადებით გავლენას ახდენს. ბავშვისთვის ყურადღების მიქცევა და ერთად ნაყოფიერად გატარებული დრო მისი ცენტრალური ნერვული სისტემის განვითარებას უწყობს ხელს. ეს აძლიერებს მის თვითაღქმას, ეხმარება სხვა ადამიანებთან უსაფრთხო კავშირის დამყარებაში, ზრდის თავდაჯერებას და აგრძნობინებს, რომ ძვირფასია. რას იტყვით, ცოტა ხნით გადადოთ საქმეები და დრო თქვენს ბავშვს დაუთმოთ? 😊') WHERE id = '4e220ec0-af8b-4430-ab5f-7ff3954ffb65';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ გოგონა გყავთ, შესაძლოა, გაინტერესებდეთ, როდის არის უმჯობესი მისთვის ყურების გახვრეტა. ჩვილებში ყურის გახვრეტისთვის ზუსტად განსაზღვრული ასაკობრივი შუალედი არ არსებობს. მართალია, ეს უმეტესად პირადი არჩევანია, თუმცა შეგიძლიათ ექიმსაც ჰკითხოთ რჩევა. ვინაიდან ბავშვის ხრტილი ჯერ ძალიან რბილია, ამ თვეებში საყურის გაკეთება ნაკლებად მტკივნეულია. თუმცა მსოფლიოში ცნობილი ზოგიერთი პედიატრიული ორგანიზაცია ვაქცინაციის კალენდრის დასრულებისა და შემდგომი მოვლის სირთულის გამო ამ თვეებში ყურების გახვრეტას არ გირჩევთ. მიუხედავად ამისა, თუ ყურის გახვრეტის პროცედურა და შემდგომი მოვლა სწორად ჩატარდება, ბავშვის ჯანმრთელობასთან დაკავშირებული პრობლემის განვითარების ალბათობა საკმაოდ დაბალია. თუ ბავშვისთვის ყურების გახვრეტას გადაწყვეტთ, ანთების თავიდან ასაცილებლად გირჩევთ, ყურადღება მიაქციოთ, რომ საყურეები უჟანგავი ფოლადისგან ან, თუ შესაძლებელია, ოქროსგან იყოს დამზადებული.') WHERE id = '622d780e-3a5e-48fd-b009-10a81d465be2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'უნდა გახსოვდეთ, რომ ბავშვს შესაძლოა მუდმივად სურდეს ძუძუს წოვა — ეს განსაკუთრებით ხშირად ახალშობილობის პერიოდში გვხვდება, თუმცა ნებისმიერ დროს შეიძლება გამოვლინდეს. სპეციალისტების აზრით, ძუძუთი კვება, რომლის გაგრძელებაც 2 წლამდეა რეკომენდებული, თქვენსა და ბავშვს შორის განსაკუთრებულ კავშირს აყალიბებს. ამიტომ ბავშვს თქვენთან სიახლოვის ინსტინქტური სურვილის გამო შეიძლება ხშირად უნდოდეს ძუძუს წოვა, წოვისას ჩაძინება და მთელი დღის განმავლობაში მკერდისგან მოშორებაზე უარის თქმა. მიუხედავად იმისა, რომ მე-4 თვიდან აირების პრობლემა მცირდება, ზოგიერთ ბავშვში ის მე-6 თვემდე შეიძლება გაგრძელდეს. აირებით გამოწვეული ტკივილის დროს ბავშვს შეიძლება თქვენთან ყველაზე ახლოს ყოფნა — თქვენს მკლავებში მოქცევა და ძუძუს წოვით დამშვიდება — სურდეს, რათა თავი უსაფრთხოდ იგრძნოს. ამასთანავე, ბავშვის გააქტიურების შედეგად ენერგიაზე მოთხოვნილების ზრდაც წოვის სურვილს აძლიერებს. ბავშვთან ხშირი ფიზიკური კონტაქტი, რომელიც დღის განმავლობაში ძუძუთი კვებისას გაქვთ, თქვენდამი მის მიჯაჭვულობას აძლიერებს. ანუ მაშინაც კი, თუ ბავშვს არანაირი პრობლემა არ აქვს, ძუძუს მუდმივად წოვის სურვილი შეიძლება ნიშნავდეს, რომ მას კანით კონტაქტი მეტად სჭირდება.') WHERE id = '15a9163c-c7da-40c2-a76c-38c778e04718';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვის კანზე სხვადასხვა ფორმის გამონაყარი ჩნდება, ეს შეიძლება ალერგიული ეგზემა იყოს. ალერგია არის ორგანიზმის რეაქცია, როდესაც ბავშვის სხეული რეალურად უვნებელ ნივთიერებას უცხოდ და სახიფათოდ აღიქვამს. გახსოვდეთ, რომ ალერგიის გამომწვევი ფაქტორი აუცილებლად საკვები არ არის. მაგიდაზე არსებული მტვერი, სეზონების ცვლილებისას გავრცელებული ყვავილის მტვერი და სიგარეტის კვამლიც კი შეიძლება ბავშვში ალერგიული რეაქციის მიზეზი გახდეს. თუ ბავშვს გამონაყარს, სიწითლეს ან განავალში სისხლის წერტილებს ამჩნევთ, სასურველია, ექიმს მიმართოთ. საკვებმა ან ნივთიერებამ, რომელიც ბავშვების უმეტესობისთვის უსაფრთხოა, ალერგიის მქონე ბავშვს შესაბამისი ზომების მიუღებლობის შემთხვევაში შესაძლოა სერიოზული პრობლემები შეუქმნას. ალერგია, ჩვეულებრივ, იმუნური სისტემის გარკვეული დარღვევების გამო ვითარდება და შეიძლება გენეტიკური ხასიათიც ჰქონდეს. ანუ არსებობს ალბათობა, რომ თქვენი ალერგია ბავშვსაც გამოუვლინდეს.') WHERE id = 'e82d9ae2-ed27-40cb-9366-8cbbd0962327';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ჯანსაღი ზრდისა და განვითარებისთვის კვება ძალიან მნიშვნელოვანია. თუმცა ზოგჯერ მან შეიძლება უარი თქვას ძუძუზე ან ხელოვნურ საკვებზე. განსაკუთრებით მაშინ, თუ ბავშვს ძუძუთი კვებავთ, გირჩევთ, მოთმინებით და ხშირად აწოვოთ. უარის მიზეზებს შორის შეიძლება იყოს კბილების ამოჭრა, განვითარების კრიზისული პერიოდი, ცხვირის გაჭედვა და მრავალი სხვა ფაქტორი. მომდევნო თვეებში ბავშვის საჭიროებების შესაბამისად კვებაში ცვლილებების შეტანას შეძლებთ, თუმცა ამ ეტაპზე მკაცრი რეჟიმის ჩამოსაყალიბებლად არ უნდა აიძულოთ. საკვებზე უარის თქმისას გახსოვდეთ, რომ გარკვეული დროის შემდეგ ეს პრობლემა მოგვარდება და ყველაფერი დალაგდება. ასეთ სიტუაციებში, იმის შიშით, რომ ბავშვი მშიერი დარჩება, მყარ საკვებზე ნაადრევად გადასვლას არ გირჩევთ. დამატებითი კვება ბავშვის 180 დღის შესრულების შემდეგ დაიწყეთ და აუცილებლად დააკვირდით მის სიგნალებს, რათა დარწმუნდეთ, რომ ის ამისთვის მზად არის. ამიტომ მთელი პროცესის განმავლობაში ბავშვს მოთმინებით უნდა მიუდგეთ, გაუგოთ და მის საჭიროებებს უპასუხოთ.') WHERE id = '63e83115-0a58-4fb8-af8e-8058860fc7f2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '0-12 თვის პერიოდი, რომელშიც თქვენი ბავშვი იმყოფება, ტვინის ჯანსაღი განვითარებისთვის განსაკუთრებით მნიშვნელოვანია. ამ პერიოდში გარემო, რომელშიც ის იზრდება, და გარშემო მყოფ ადამიანებთან, განსაკუთრებით კი თქვენთან ურთიერთობა მისი ტვინის ჩამოყალიბებას უყრის საფუძველს. ამ მხრივ ბავშვის მიერ მიღებული სტიმულების შესაბამისობა და მრავალფეროვნება მის კოგნიტიურ, ემოციურ, სოციალურ და ფიზიკურ განვითარებაზე მუდმივად ახდენს გავლენას. თქვენსა და ბავშვს შორის ურთიერთობას მისი გრძნობები სტიმულად აღიქვამს. რაც უფრო მეტ ასეთ სტიმულს მიიღებს ბავშვი, მით მეტად განვითარდება. მისი განვითარებისთვის მნიშვნელოვანია, არ მოაკლოთ ეს სტიმულები და მუდმივად გქონდეთ მასთან ინტერაქცია. ზოგიერთი სამეცნიერო კვლევის თანახმად, ბავშვის ტვინის განვითარების ყველაზე მნიშვნელოვანი ფაქტორი ადამიანის ხმაა. ამიტომ დღეს ჩართეთ მშვიდი მუსიკა, გაუკეთეთ ბავშვს მასაჟი და ამ დროს უამბეთ, როგორ ჩაიარა თქვენმა დღემ, რა გადაგხდათ და რამდენად ძლიერ გიყვართ ის. სასიამოვნო დროის გატარებას გისურვებთ! 😊') WHERE id = 'b51f395b-32bc-4a20-bb23-ec95e7590add';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ჩვილობისა და ბავშვობის ასაკში კანის ერთ-ერთი ყველაზე გავრცელებული დაავადებაა ატოპიური დერმატიტი — ეგზემა. კანის ამ პრობლემის მაპროვოცირებელი ფაქტორებია ბაქტერიები, სარეცხი საშუალებები, სეზონური ცვლილებები და სხვადასხვა ალერგენი. ბავშვში ამ მდგომარეობის განვითარების თავიდან ასაცილებლად გარკვეული ზომები უნდა მიიღოთ. ამ პერიოდში, როდესაც მისი კანი ძალიან მგრძნობიარეა, ბავშვი მოარიდეთ შალის ტანსაცმელს, მტვერსა და ქვიშას, საპონს, საეჭვო შემადგენლობის კოსმეტიკურ პროდუქტებსა და სარეცხ საშუალებებს. კანის ეს პრობლემა შეიძლება შეძენილი ტანსაცმლის გაურეცხავად ჩაცმამაც გამოიწვიოს. ამიტომ ბავშვის მგრძნობიარე კანისთვის უპირატესობა ბამბის ტანსაცმელს უნდა მიანიჭოთ, ხოლო დაბანისას კანი გამაღიზიანებელი ხახუნის მოძრაობებით არ დაუმუშაოთ. კანის ეს დაავადება ჩვილობის პერიოდში ეგზემის სახით ვლინდება, ხოლო თუ შესაბამის ზომებს არ მიიღებთ და წარმოქმნის შემთხვევაში არ უმკურნალებთ, მომავალში შესაძლოა სასუნთქი გზების ალერგიად, ასთმად და ხელის ეგზემად ჩამოყალიბდეს.') WHERE id = '31c813fe-83a6-475d-b451-c6545ed0cadd';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ხელოვნური ნარევი შეგიძლიათ გამოიყენოთ როგორც ბავშვის კვების ერთადერთი წყარო, ასევე, თუ თქვენი რძე საკმარისი არ არის, ექიმის რეკომენდაციით დამატებით მისცეთ. თუმცა, თუ ბავშვს რაიმე სახით ხელოვნურ ნარევს აძლევთ, რამდენიმე მნიშვნელოვან საკითხს უნდა მიაქციოთ ყურადღება. მათგან ყველაზე მთავარია, რა თქმა უნდა, შემადგენლობით დედის რძესთან მაქსიმალურად მიახლოებული ნარევის შერჩევა. ამ მხრივ ექიმის რჩევა უნდა გაითვალისწინოთ და პროდუქტების შემადგენლობა კარგად შეისწავლოთ. განსაკუთრებით უნდა მოერიდოთ ისეთი ბრენდების გამოყენებას, რომელთა შესახებაც აქამდე არ გსმენიათ ან რომლებიც ექიმს არ ურჩევია. ასევე მნიშვნელოვანია, რომ მწარმოებელი კომპანია ეთიკურ ნორმებს იცავდეს. ამ ეტაპზე ჯერ კიდევ შეგიძლიათ სხვადასხვა ბრენდის ნარევი მოსინჯოთ. დროთა განმავლობაში აუცილებლად იპოვით ისეთს, რომელიც ბავშვს ყველაზე მეტად მოსწონს და ნაწლავებთან დაკავშირებულ პრობლემებს არ იწვევს. იმუნური სისტემის განვითარებისა და ნაწლავის მიკროფლორის ჯანმრთელობისთვის დარწმუნდით, რომ შერჩეული ნარევი შეიცავს პრობიოტიკებს — ისეთ სასარგებლო მიკროორგანიზმებს, როგორებიცაა ლაქტობაცილები და ბიფიდობაქტერიები. გარდა ამისა, ბავშვისთვის განკუთვნილ ნარევში ცხიმოვანი მჟავის, LC-PUFA-ს, არსებობა ციტოკინების გამომუშავების გაზრდით ხელს შეუწყობს იმუნური სისტემის რეგულირებას.') WHERE id = '20390cc9-8cbc-4417-abec-6230f65f2f2f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის არსებობს აქტივობა, რომელიც ერთდროულად ძალიან სახალისოცაა და მისი განვითარებისთვისაც მეტად მნიშვნელოვანი: სარკეში ჩახედვა! 😊 მიუხედავად იმისა, რომ უფროსი თაობის წარმომადგენლები ხშირად ერიდებიან ბავშვისთვის სარკის ჩვენებას, ექიმები ამას დაჟინებით გვირჩევენ. სარკეში ჩახედვა ბავშვს საკუთარი თავის დანახვასა და აღმოჩენაში ეხმარება, რითაც მნიშვნელოვნად უწყობს ხელს ტვინის განვითარებას. ამ აქტივობის პირველად ჩასატარებლად დრო სწორად უნდა შეარჩიოთ. თუ ბავშვი მოუსვენრადაა ან ცუდ ხასიათზეა, შესაძლოა სარკის შეეშინდეს. ამიტომ ამ თამაშისთვის იდეალურია დრო, როცა კარგ ხასიათზეა და დანაყრებულია, თუმცა ზედმეტად მაძღარი არ არის. დადექით სარკის წინ; აჩვენეთ ბავშვს თვალები, ხელის მტევნები, ტერფები, მკლავები და პირი და გააცანით სხეულის ეს ნაწილები. შემდეგ მათ თანმიმდევრობით შეეხეთ და მოქმედება გაიმეორეთ. დარწმუნებული ვართ, ეს თამაში ბავშვისთვის ძალიან საინტერესო იქნება. კარგად გაერთეთ! 😊') WHERE id = 'b0d88192-6e24-4e64-b343-6477a77e7840';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფიქრობთ, რომ ძუძუთი კვებისას ბავშვი პირს სწორად ვერ იყენებს, კვება დიდხანს გრძელდება, ხშირად ისვენებს, მოუსვენრადაა და მოსალოდნელი ტემპით ვერ იმატებს წონას? თუ პასუხი დადებითია, შესაძლოა ბავშვს ენის მოკლე ლაგამი ჰქონდეს. გირჩევთ, შეამოწმებინოთ. ენის მოკლე ლაგმის გამო ბავშვები წოვისას ძუძუს სწორად და სრულად ვერ ეჭიდებიან, საკმარის საკვებს ვერ იღებენ და ამის შედეგად შესაძლოა წონაც დაკარგონ. ასევე, რადგან ენით უკან ვერ უბიძგებენ რძეს ან ბოთლიდან მიღებულ ნარევს, შეიძლება კვებასთან დაკავშირებული გარკვეული დარღვევებიც განვითარდეს. ენის ლაგამი ქსოვილის ნაწილია, რომელიც ენას პირის ღრუს ფსკერთან აკავშირებს. ენის თავისუფლად მოძრაობისთვის ეს ქსოვილი ენისგან გარკვეულწილად განცალკევებული უნდა იყოს. ზოგჯერ, განსაკუთრებით მემკვიდრეობითი მიზეზების გამო, ეს განცალკევება არ ხდება და ენის მოძრაობა იზღუდება. ექიმები ამას ყოველთვის არ ამოწმებენ და მისი შემჩნევაც ყოველთვის ადვილი არ არის. თუმცა, ბავშვის ექიმმა დიაგნოზი დაგვიანებითაც რომ დასვას, ეს მდგომარეობა მკურნალობას ექვემდებარება.') WHERE id = '2904fd26-1eca-4d37-8e98-2e316a3eec9b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვს კბილების ამოჭრამდე ძალიან ცოტა დრო დარჩა, თუმცა შესაძლოა წინ ჯერ კიდევ რამდენიმე თვე იყოს. კბილების ამოჭრის პერიოდში ბავშვს ღრძილები შეიძლება ძალიან ექავებოდეს, ნერწყვი სდიოდეს, ხელები მუდმივად პირში მიჰქონდეს და ყველაფრის დაღეჭვა სურდეს, რასაც იპოვის. ქავილის შესამსუბუქებლად შეგიძლიათ კბილების ამოსაჭრელი სათამაშო გამოიყენოთ, ტკივილისთვის — ექიმის რჩევით კბილების გელი, ხოლო ნერწყვისთვის — წინსაფარი. გარდა ამისა, ეს პერიოდი, რომელიც რთულია როგორც თქვენთვის, ისე ბავშვისთვის, სახლში არსებული ნივთებითაც შეგიძლიათ შეამსუბუქოთ. როგორ? სუფთა პატარა პირსახოცების გამოყენებით! პირსახოცი ოდნავ დაასველეთ და შემდეგ გასაგრილებლად ცოტა ხნით მაცივარში მოათავსეთ. ცივი და შედარებით მყარი პირსახოცი ბავშვს ტკივილს მნიშვნელოვნად შეუმსუბუქებს. როცა მას ბავშვს მისცემთ, აუცილებლად მუდმივი მეთვალყურეობის ქვეშ გყავდეთ.') WHERE id = '8cafc042-a915-4258-a3c2-d05a6d6f4956';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, ბავშვი დედის რძით იკვებება თუ ხელოვნური ნარევით, შესაძლოა გაგიჩნდეთ კითხვა: სჭირდება თუ არა მის ორგანიზმს წყალი? ზოგადი მოსაზრებით, დამატებით კვებაზე გადასვლამდე ბავშვს დამატებით წყალი არ სჭირდება. ამის მიზეზი ისაა, რომ თუ პირველ 6 თვეში ძირითად საკვებთან ერთად ბავშვს წყალსაც მისცემთ, წყურვილის შეგრძნება შეუმცირდება. წყურვილის შემცირების გამო ბავშვი ნაკლებ დედის რძეს ან ხელოვნურ ნარევს მიიღებს, რამაც შესაძლოა ენერგიის დეფიციტი და განვითარების შეფერხება გამოიწვიოს. ამიტომ ბავშვისთვის წყლის რეგულარულად მიცემა დამატებით კვებაზე გადასვლისას უნდა დაიწყოთ. საკვების რაოდენობისა და სისქის მატებასთან ერთად ბავშვის ორგანიზმს მეტი სითხე დასჭირდება. ამ ეტაპზე სითხის საჭიროების დაკმაყოფილების ყველაზე ჯანსაღი საშუალება წყალია. მისაცემი წყლის რაოდენობის შესახებ ექიმთან კონსულტაცია არ დაგავიწყდეთ.') WHERE id = '8768c9bb-7bc9-40eb-8d2e-760fead026b4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ერთად გატარებული, შთაბეჭდილებებით სავსე 5 თვე... დრო რა სწრაფად გადის, არა? 😊 ბავშვის მეხუთე თვეც, როცა ის ყოველდღიურად ვითარდება და გამუდმებით გაოცებთ, გამორჩეული და ძალიან საინტერესო იქნება. ამ ეტაპზე ბავშვის გრძნობები თითქმის ზრდასრული ადამიანის დონემდეა განვითარებული. ამის წყალობით მისი კომუნიკაციისა და საკუთარი თავის გამოხატვის უნარები სწრაფად ვითარდება. ეს ნიშნავს, რომ ახლა ბავშვის გრძნობების გაგება უწინდელთან შედარებით უფრო მარტივად შეგიძლიათ. 5-ი თვიდან ბავშვი იწყებს თქვენთვის ბედნიერების, მოწონებისა და არმოწონების, დისკომფორტის, სიყვარულისა და ყურადღების მოთხოვნის აშკარად გამოხატვას. მაგალითად, თქვენი ან, თუ ხელოვნურ ნარევს იღებს, თავისი ბოთლის დანახვისას შეიძლება მიხვდეს, რომ ჭამის დრო მოვიდა, აღელდეს და ყვირილით შეეცადოს სიხარულის გამოხატვას. გარდა ამისა, მეხსიერებისა და გრძნობების განვითარების შედეგად, შესაძლოა უკვე უცხო ადამიანების მიმართ შფოთვა იგრძნოს და მათ უფრო ფრთხილად მოეკიდოს.') WHERE id = '12aa96ec-7101-441e-a8b6-16b0a453ee5a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პირველ 4 თვესთან შედარებით, ამ თვეში თქვენი ბავშვი უფრო აქტიურია, ამიტომ ნაკლები წონის მომატება ნორმალურია. შესაბამისად, არ უნდა ელოდოთ, რომ პირველ თვეებში მსგავსად, თვეში 800-1200 გრამს მოიმატებს. 5 თვის ბავშვისთვის 450-750 გრამის მომატება საკმარისად ითვლება და, გამონაკლისი შემთხვევების გარდა, დამატებითი ჩარევის საჭიროება არ არსებობს. 5 თვიდან ბავშვის წონა შეიძლება 5100-9000 გრამის, ხოლო სიმაღლე 58-70 სმ-ის ფარგლებში მერყეობდეს. გახსოვდეთ, რომ ბიჭებისა და გოგოების სიმაღლისა და წონის მატებას შორის მცირე განსხვავებები არსებობს და თითოეული ბავშვის განვითარება ინდივიდუალურია. თუ ამ მაჩვენებლების მიხედვით ფიქრობთ, რომ თქვენს ბავშვს წონის ან სიმაღლის ნაკლებობა ან სიჭარბე აქვს, გირჩევთ, ექიმს მიმართოთ. ასევე გახსოვდეთ, რომ ამ მაჩვენებლებზე გავლენას ახდენს ორსულობის რომელ კვირაში დაიბადა ბავშვი, ასევე დაბადებისას მისი სიმაღლე და წონა.') WHERE id = '57b48e89-533e-4812-870a-767029538ffe';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ახლა უფრო მეტად ცდილობს, აიღოს ის ნივთები, რომლებიც მის ყურადღებას იპყრობს და მხედველობის არეში ხვდება. შესაძლოა, მისთვის საინტერესო ნივთის დანახვისას აღფრთოვანდეს, გაიღიმოს, მისწვდომა სცადოს ან ტაში შემოჰკრას. მხედველობისა და აღქმის უნარის მნიშვნელოვნად განვითარების შედეგად, სხვადასხვა ფერისა და ფორმის დანახვა ბავშვს აზრობრივი კავშირების დამყარებასა და გარემოს შეცნობაში ეხმარება. ამასთანავე, ამ თვეში შეამჩნევთ, რომ ბავშვი უფრო აქტიურად ურთიერთობს გარშემომყოფებთან. თუ წინა თვეებში მისი ხმამაღალი სიცილი არ მოგისმენიათ, დიდი ალბათობით, ამ თვეში გაიგონებთ. ბავშვმა შეიძლება ღუტუნისას გაიცინოს და შეჰყვიროს. ბედნიერების დროს კი თავისთვის მხიარული ბგერები გამოსცეს. ბავშვის გაცინების კიდევ ერთი გზაა, მის ღიმილს სიცილით უპასუხოთ. ამ ასაკში ბავშვებს ერთმანეთისთვის ღიმილითა და სიცილით პასუხი ძალიან მოსწონთ. ბოთლიდან წოვისას, როცა თქვენ სხვას ესაუბრებით, მუსიკას რთავთ ან ბავშვი რაიმე ხმას ისმენს, ეს მას ართობს. „აღუ“-ს მსგავსი ბგერები, შეძახილები და კისკისი თქვენი ბავშვისთვის მეტყველების დაწყების პირველი ნაბიჯებია. 😊') WHERE id = '57cd3a11-aa81-4f90-bfb2-f69a0e71ee24';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვი გარშემო მიმდინარე მოვლენების მიმართ უფრო ყურადღებიანი ხდება, იწყებს ხმების ერთმანეთისგან გარჩევასა და გარემოში არსებულ ბგერებზე რეაგირებას. ამ თვიდან ბავშვის ემოციური მდგომარეობა ერთ-ერთი საკითხია, რომელსაც განსაკუთრებული ყურადღება უნდა მიაქციოთ. როდესაც ბავშვს ყურადღება სჭირდება, მოწყენილია ან თქვენთან კონტაქტის დამყარება სურს, შეიძლება თქვენი ყურადღების მისაქცევად მოულოდნელად შეჰყვიროს ან ხმამაღლა ატირდეს. ყურადღების მისაქცევად ბავშვის ასეთი მცდელობები მიუთითებს, რომ მას მიზეზშედეგობრივი კავშირის დამყარება უკვე შეუძლია. ამიტომ, როდესაც ბავშვს მშვიდად ესაუბრებით და ყურადღებას აქცევთ, შეიძლება მან მოულოდნელად შეწყვიტოს ტირილი და გაგიღიმოთ. ეს ცუდი ჩვევა არ არის და სანერვიულო არაფერი გაქვთ. რადგან ბავშვს ჯერ მეტყველების უნარი სრულად არ აქვს ათვისებული, დისკომფორტის დროს ამ გზით ცდილობს ყურადღების მიქცევასა და თავისი პრობლემის გადმოცემას.') WHERE id = 'c9b55f11-f202-4070-8d6a-fc7359809c90';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის სიმაღლისა და წონის კონტროლის მსგავსად, მნიშვნელოვანია მისი თავის გარშემოწერილობის მონიტორინგიც. თავის გარშემოწერილობის გაზომვა რუტინული პროცედურაა, რომელიც ბავშვის ტვინის განვითარებაზე წარმოდგენას გვიქმნის. ამ თვიდან ბავშვის თავის გარშემოწერილობა 39 სმ-დან 45 სმ-მდე უნდა იყოს. თავის გარშემოწერილობის შესაბამის ფარგლებში ზრდა ტვინის ჯანსაღი განვითარების ერთ-ერთი მაჩვენებელია. ბავშვებში ტვინის განვითარებასთან დაკავშირებული ზოგიერთი პრობლემა ხშირად სწორედ თავის გარშემოწერილობის ნორმისგან განსხვავებული მაჩვენებლით ვლინდება. თუმცა, თუ თქვენი ბავშვის თავის გარშემოწერილობა მოსალოდნელზე ნაკლები ან მეტია, მაშინვე ნუ შეშფოთდებით. ეს მდგომარეობა კვებასთან დაკავშირებული არ არის, ხოლო მითითებული რიცხვები მკაცრ ნორმას არ წარმოადგენს. ყველა ბავშვის მსგავსად, თქვენს ბავშვსაც ზრდის ინდივიდუალური პოტენციალი აქვს. გენეტიკურად მცირე აღნაგობის ბავშვებში თავის ზომა, ჯანმრთელობის მიუხედავად, შეიძლება შედარებით მცირე იყოს, ხოლო მსხვილი აღნაგობის ბავშვებში, ძვლოვანი აგებულების გამო, — შედარებით დიდი.') WHERE id = '7475597a-0083-4ac8-af52-e9ec4b5f2395';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც თქვენი ბავშვი ზურგზე წევს, უკვე ჰაერში სწევს ფეხებს და აღფრთოვანებით აკვირდება მათ! ბავშვი, რომელიც ახლა თავის ფეხებს ეცნობა, ძალიან მალე მათ ხელით დაჭერასაც დაიწყებს. სულ მალე თავად დარწმუნდებით 😊 ამ ეტაპზე ბავშვის განვითარებისთვის ძალიან მნიშვნელოვანია ისეთი თამაშების შერჩევა, რომლებიც მის გრძნობათა ორგანოებს ასტიმულირებს. ამასთანავე, ამ პერიოდში განსაკუთრებით სასარგებლოა თამაშები, რომლებიც ბავშვს საკუთარი სხეულის გაცნობაში ეხმარება. გახადეთ ბავშვს წინდები და ტერფებზე ნაზად შეუღუტუნეთ. დაინახავთ, რომ ის ღიმილით გიპასუხებთ. 😊 ღუტუნი და ერთმანეთისთვის სიცილით პასუხი ქმნის სოციალური კავშირის მექანიზმს, რომელიც თქვენსა და ბავშვს შორის ურთიერთობასა და სითბოს აძლიერებს. ბავშვის ღუტუნისას მისი ხმამაღალი სიცილი თქვენს ემოციურ კავშირსაც გააღრმავებს. თუმცა შეგახსენებთ, რომ ზედმეტი არაფერი ვარგა! :)') WHERE id = '85434c2c-c541-44d1-bc15-24301977fe06';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ღამით კვება ახლაც ისეთივე მნიშვნელოვანია, როგორც პირველ თვეებში. თუ თქვენი ბავშვი ღამით იღვიძებს, მისი საჭიროების შესაბამისად, ყოველ 3-4 საათში ძუძუთი ან ბოთლით უნდა კვებოთ. თუმცა, თუ ბავშვს სძინავს და ჯანმრთელობის რაიმე პრობლემა არ აქვს, მხოლოდ კვებისთვის მის გაღვიძებას არ გირჩევთ. როცა მოშივდება, ის ამას თავად გაგრძნობინებთ. მომავალში ძილის ჯანსაღი რეჟიმის ჩამოსაყალიბებლად შესაძლოა საჭირო გახდეს, თავი აარიდოთ ბავშვის კვებას უშუალოდ დაძინებამდე ან გაღვიძებისთანავე. ამიტომ ხელი უნდა შეუწყოთ ბავშვს, რომ დამოუკიდებლად ჩაძინება ისწავლოს, და ამაში მხარი დაუჭიროთ. თუ ბავშვი ძუძუთი კვების დროს დაძინებას მიაჩვიეთ, მიეცით მას ცოტა დრო და მოთმინება გამოიჩინეთ. დარწმუნებული იყავით, რომ მალე ყველაფერი დალაგდება! :)') WHERE id = '25c161ab-8831-4065-a3ec-22240c22edb0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა უკვე სრულად აღმოაჩინა ბგერების გამოცემის შესაძლებლობა. მან შეიძლება ხელში მოხვედრილი ნებისმიერი ნივთი შეანჯღრიოს და მისგან ხმის გამოცემა სცადოს — ამ აღმოჩენაში თქვენც შეგიძლიათ დაეხმაროთ. ბავშვებს ხმის გამოსაცემად ყველაზე მეტად საჩხაკუნო სათამაშოები მოსწონთ. მაღაზიებში სხვადასხვა ფერისა და ფორმის საჩხაკუნოებს იპოვით. ამასთანავე, სახლის ნივთებითაც მარტივად შეგიძლიათ საკუთარი სათამაშოს დამზადება. ამისთვის ორი პლასტმასის ჭიქაც საკმარისია. ჭიქებში შეგიძლიათ სახლში არსებული მშრალი მარცვლეული (ბრინჯი, ოსპი და სხვ.) ჩაყაროთ. ჭიქების პირები გამჭვირვალე წებოვანი ლენტით მჭიდროდ შეკარით, რათა შიგთავსი არ გადმოიყაროს. განსხვავებული ხმების მისაღებად შეგიძლიათ მსხვილი და წვრილი მარცვლები გამოიყენოთ. მაგალითად, ბრინჯის მარცვლები უფრო წვრილ, ხოლო ლობიოს მარცვლები უფრო დაბალ და მკვეთრ ხმას გამოსცემს.') WHERE id = 'c96c4837-c392-4247-ae1b-3dcef1d0e562';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენც ხომ გეჩვენებათ, რომ ბოლო დღეებში თქვენი ბავშვი გაცილებით მოძრავი გახდა? ამ პერიოდში მისი ხელებისა და ფეხების კუნთები საგრძნობლად გაძლიერდა. ბავშვმა უკვე ისწავლა ხოხვა, გადაბრუნება და საგნებზე მოჭიდებით გადაადგილება, მოძრაობისას კი მისი კუნთები კიდევ უფრო განვითარდება. ახლა, როდესაც ის ძალიან მოძრავია, უსაფრთხოების მიზნით გარკვეულ საზღვრებში უნდა გყავდეთ. მაგალითად, მაღალ ზედაპირზე მარტო ნუ დატოვებთ და მის გარშემო არსებული წვეტიანი და მჭრელი საგნები მოაშორეთ. თქვენს ბავშვს შეუძლია მისთვის საინტერესო ნებისმიერი ნივთი ცერსა და დანარჩენ თითებს შორის, მარწუხივით მოიქციოს. საგნის შესასწავლად კი მის პირში ჩადებას მოინდომებს. ამიტომ გირჩევთ, ბავშვისთვის ხელმისაწვდომ ადგილას არ დატოვოთ პატარა სათამაშოები, მონეტები, მძივები და სხვა საგნები, რომლებმაც შეიძლება დახრჩობის საფრთხე შექმნას.') WHERE id = '5d03d27f-629c-43d8-acc3-6fa2f69ef287';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ძალიან მგრძნობიარეა თქვენი შეხებისა და მასთან დამყარებული ფიზიკური კონტაქტის მიმართ. მის კანში მილიონობით პატარა ნერვული დაბოლოებაა, რომლებიც შეხების შეგრძნებისას ტვინსა და ნერვულ სისტემას სიგნალს გადასცემს. ეს ნერვული დაბოლოებები განსაკუთრებით მრავლადაა ბავშვის უფრო მგრძნობიარე უბნებში, როგორიცაა იღლიები, ტერფები, მუცელი და კისერი. როდესაც ბავშვს სწორედ ამ ადგილებზე ეხებით, ნერვული დაბოლოებები აქტიურდება, რის შედეგადაც ტვინი ღიტინის, ჟრუანტელისა და სიცილის მსგავს რეაქციებს იწვევს. ამ დროს ბავშვის არტერიული წნევა იმატებს, გულისცემა ჩქარდება და ტვინი უფრო აქტიური ხდება. მაგალითად, ბავშვის ღიტინი არა მხოლოდ სახალისოა, არამედ მას შეხების შეგრძნების უკეთ აღქმაშიც ეხმარება. გახსოვდეთ, რომ სიცილი ბავშვის იუმორის გრძნობის განვითარების პირველი ნაბიჯია. 😊') WHERE id = '541bc5b2-12fd-4d41-9d69-7d5b93ee3f92';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ასაკში თქვენს ბავშვს, ჩვეულებრივ, მჯდომარე მდგომარეობაში ყოფნა მოსწონს. თუ ის ჯერ დაჯდომას არ ცდილობს, ეს მხოლოდ დროის საკითხია! 😊 ჯდომისას წონასწორობის შესანარჩუნებლად და საყრდენად ბავშვი ხელებს იყენებს, ხოლო ზურგის კუნთების არასრული განვითარების გამო შეიძლება ოდნავ მოხრილი იჯდეს. ზოგიერთი ექიმი 6 თვემდე ჯდომის ვარჯიშების დაწყებას არ გვირჩევს. თუმცა ზოგი სპეციალისტი ბავშვის სურვილისა და განვითარების გათვალისწინებით უფრო მოქნილ მიდგომას ირჩევს. მიუხედავად ამისა, ბავშვის უსაფრთხოებისთვის ჯდომის მცდელობები ხანმოკლე უნდა იყოს და უმჯობესია, ის კალთაში დაისვათ. მართალია, თქვენი ბავშვი დღითი დღე ძლიერდება, მაგრამ ამ ეტაპზე მისი საყრდენის გარეშე დასმის მცდელობამ შეიძლება გარკვეული გართულებები გამოიწვიოს. ბავშვის განვითარების შესახებ ყველაზე ზუსტ ინფორმაციას თქვენი ექიმი მოგაწვდით. ამიტომ ჯდომის, დამატებითი კვებისა და ვიტამინების მსგავს საკითხებზე გადაწყვეტილება ექიმთან კონსულტაციის საფუძველზე უნდა მიიღოთ. 😊') WHERE id = '3d5e88a5-68ba-47fd-b5a0-88c276587011';